.irantheme-404-not-found {
    display: flex;
    align-items: center;
    justify-content: center;

    &.irantheme-hero-fullscreen {
        min-height: 100vh;
    }

    .irantheme-container-inner {
        z-index: 9;
    }

    // Social media
    &-social-media {
        display: flex;
        justify-content: center;
        padding: 2rem 0 1rem;

        .irantheme-social-media {
            display: flex;
            align-items: center;
            gap: 1.25rem;
            margin: 0;
            padding: 0;
            list-style: none;

            li a {
                display: flex;
                align-items: center;
                justify-content: center;
                width: 2.5rem;
                height: 2.5rem;
                border-radius: 50%;
                text-decoration: none;
                @include transition(0.25s);

                svg {
                    width: 1.15rem;
                    height: 1.15rem;
                    fill: currentColor;
                    @include transition(0.25s);
                }

                &:hover {
                    transform: translateY(-3px);
                }
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white .irantheme-social-media li a {
        color: $color-gray-600;
        background: $color-gray-100;

        &:hover {
            color: $color-white;
            background: $color-primary;
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark .irantheme-social-media li a {
        color: $color-gray-300;
        background: rgba($color-white, 0.08);

        &:hover {
            color: $color-white;
            background: $color-primary;
        }
    }
}