// Global style for popup modals
.irantheme-popup-modal {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    backdrop-filter: blur(3px);
    -webkit-backdrop-filter: blur(3px);
    background-color: $color-dark-transparent-2;
    z-index: 9999999;

    .irantheme-divider {
        height: 1px;
        width: 100%;
        background: linear-gradient(90deg, rgba(230, 231, 232, 0), $color-gray-300 52.08%, rgba(230, 231, 232, 0));
        margin: 1.5rem 0;
    }

    &-wrapper {
        background: $color-white;
        border-radius: $border-radius-high;
        box-shadow: 0px 2px 35px $color-gray-600 !important;
        padding: 2rem;
        width: 40%;
        position: relative;
        overflow: hidden;
        max-height: 95vh;
        overflow-y: auto;
        display: flex;
        flex-direction: column;

        @media (max-width: 1399.98px) {
            width: 60%;
        }

        @media screen and (max-width: 1199.98px) {
            width: 70%;
        }

        @media screen and (max-width: 767.98px) {
            width: 85%;
            padding: 1.2rem;
        }

        .topbar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            line-height: 0;

            .close {
                font-size: 1.2rem;
                color: $color-gray-700;
                cursor: pointer;
                @include transition(0.2s);
                padding: 0.15rem 0.5rem;

                &:hover {
                    color: $color-red-shine;
                }
            }

            .heading {
                font-size: 0.8rem;
                font-weight: 700;
            }
        }
    }
}

// Single product Q&A modal
.product-qa-reply-modal,
.product-qa-question-modal {
    .text-color-white {
        color: $color-white;
    }

    .text-color-dark {
        color: $color-dark;
    }

    .qa-content {
        &-question-holder {
            display: flex;
            padding-bottom: 1rem;

            &-text {
                font-size: 0.85rem;
                font-weight: 600;
                display: flex;
                align-items: center;
                column-gap: 0.5rem;

                &::before {
                    content: '';
                    width: 0.47rem;
                    height: 0.5rem;
                    display: inline-block;
                    background-color: $color-gray-700;
                    border-radius: 100%;
                }
            }

        }

        &-reply,
        &-question {
            display: flex;
            flex-direction: column;
            gap: 0.25rem;

            &-form-label {
                font-size: 0.85rem;
                color: $color-gray-800;
            }

            &-form {
                &-submit {
                    width: 100%;
                    height: 3rem;
                    font-size: 0.8rem;
                    font-weight: 600;
                    background-color: $color-red-shine;
                    border-width: 1px;
                    border-style: solid;
                    border-color: $color-red-shine;
                    border-radius: $border-radius-medium;
                    color: $color-white;
                    transition: all 0.2s ease-in-out;

                    &:hover {
                        background-color: $color-white !important;
                        color: $color-red-shine;
                    }
                }
            }
        }

        &-attention {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.75rem;

            &-label {
                font-size: 0.8rem;
                font-weight: 600;
            }

            &-login-btn {
                width: 100%;
                height: 3rem;
                font-size: 0.8rem;
                font-weight: 600;
                background-color: $color-red-shine;
                border-width: 1px;
                border-style: solid;
                border-color: $color-red-shine;
                border-radius: $border-radius-medium;
                color: $color-white;
                transition: all 0.2s ease-in-out;
                display: flex;
                align-items: center;
                justify-content: center;

                &:hover {
                    background-color: $color-white !important;
                    color: $color-red-shine;
                }
            }
        }
    }
}