/*
=====================================
Navbar dropdown
=====================================
*/

.irantheme-navbar-dropdown {
    position: absolute;
    top: 100%;
    right: 0;
    width: 100%;
    border-top-width: 1px;
    border-style: solid;
    @extend %box-shadow-white;
    border-radius: $border-radius-high;
    display: none;

    // Accessories
    &-accessories {
        &-ul {
            display: flex;
            flex-wrap: nowrap;
            width: 100%;
            text-align: center;

            &-item {
                display: flex;
                align-items: center;
                justify-content: center;
                flex-grow: 1;
                border-width: 0 1px 1px 1px;
                border-style: solid;
                border-color: $color-gray-800;

                &-link {
                    padding: 1rem;
                    color: $color-white;
                    display: block;
                    width: 100%;
                    font-size: 1.2rem;
                    position: relative;
                    @include transition(all, 0.3s, ease-in-out);

                    &:hover {
                        background-color: $color-gray-800;
                    }

                    i {}

                    // Mini shopping cart count
                    .irantheme-mini-number-count {
                        @extend %mini-number-count;

                        & {
                            right: calc(50% + 0.1rem);
                            top: calc(50% - 0.2rem);
                        }
                    }
                }

                &:first-child {
                    border-right: 0;
                }

                &:last-child {
                    border-left: 0;
                }
            }
        }
    }

    // Menu
    &-menu {
        padding: 1rem;

        &-ul {

            // First li item
            &>li.menu-item {
                // background-color: $color-white;

                // First link item
                &>a {
                    font-size: 0.9rem !important;
                    padding: 1rem 0 !important;
                }
            }

            // All li items
            li.menu-item {

                a {
                    font-size: 0.8rem;
                    padding: 0.75rem 1rem;
                    border: 0;
                    line-height: 0.8rem;
                    display: flex;
                    flex-direction: row;
                    justify-content: space-between;
                    width: 100%;
                    // color: $color-gray-600;
                    position: relative;

                    // Link title
                    .irantheme-menu-item-link-title {

                        // Structure title
                        cite {
                            font-style: normal;

                            // Icon
                            .irantheme-menu-item-link-icon {
                                display: inline-block;
                                margin-left: 0.5rem;
                            }

                            // Image
                            .irantheme-menu-item-link-image {
                                width: 1.5rem;
                                height: 1.5rem;
                                object-fit: cover;
                                object-position: center;
                                margin-left: 0.5rem;
                                border-radius: $border-radius-medium;
                            }

                            // Mode
                            .irantheme-menu-item-link-mode {
                                font-weight: bold;
                                font-size: 0.5rem;
                                padding: 0.05rem 0.25rem;
                                line-height: 1rem;
                                display: inline-block;
                                margin-right: 0.25rem;
                                position: relative;
                                top: -1px;
                            }
                        }
                    }

                    // Hover link
                    &:hover {
                        // color: $color-dark;
                        background: transparent !important;
                    }

                    // Chevron link
                    .irantheme-menu-item-link-icon-chevron {
                        display: flex;
                        align-items: center;
                        @include transition(0.2s);
                        @include transform(rotate(0));
                    }

                    &.active {
                        // color: $color-dark;

                        .irantheme-menu-item-link-icon-chevron {
                            @include transform(rotate(180deg));
                        }
                    }
                }
            }

            // All sub menus
            .sub-menu {
                // background-color: $color-gray-100;
                display: none;
                padding-right: 0.5rem;
            }
        }

        @extend .irantheme-menu-item-link-mode;
    }

    // Social media
    .irantheme-social-media {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: center;
        text-align: center;
        line-height: 0 !important;
        padding-top: 1rem;
        padding-bottom: 1rem;

        li {
            a {
                padding: 0.5rem;
                display: block;

                i {
                    font-size: 1rem;
                    // color: $color-white;
                    line-height: 1rem;
                    @include transition(0.2s);
                }

                svg {
                    width: 1rem;
                    height: 1rem;
                    // color: $color-white;
                    // fill: $color-white;
                    line-height: 1rem;
                    @include transition(0.2s);

                    path {
                        // fill: $color-white;
                        @include transition(0.2s);
                    }
                }

                &:hover {
                    // color: $color-gray-400;

                    svg,
                    path,
                    i {
                        // color: $color-gray-400;
                        // fill: $color-gray-400;
                    }
                }
            }
        }
    }
}

/*
  =====================================
  White mode
  =====================================
  */
&.irantheme-header-white,
&.irantheme-header-white-important {
    background-color: $color-white;

    .irantheme-navbar-dropdown {
        background-color: $color-white;
        border-color: $color-gray-100;

        // Accessories
        &-accessories {
            &-ul {
                &-item {
                    border-color: $color-gray-100;

                    &-link {
                        color: $color-gray-700;

                        &:hover {
                            background-color: $color-gray-100;
                        }
                    }
                }
            }
        }

        // Menu
        .irantheme-navbar-dropdown-menu {
            &-ul {

                // First li item
                &>li.menu-item {
                    // background-color: $color-white;
                }

                // All li items
                li.menu-item {
                    a {
                        color: $color-gray-600 !important;
                        background: transparent !important;

                        &:hover {
                            color: $color-dark !important;
                        }

                        &.active {
                            color: $color-dark !important;
                        }
                    }
                }

                // All sub menus
                &>li.menu-item>.sub-menu {
                    background-color: $color-white-transparent-6;
                }
            }
        }

        // Social media
        .irantheme-social-media {
            li {
                a {
                    i {
                        color: $color-dark;
                    }

                    svg {
                        color: $color-dark;
                        fill: $color-dark;

                        path {
                            fill: $color-dark;
                        }
                    }

                    &:hover {
                        color: $color-gray-600;

                        svg,
                        path,
                        i {
                            color: $color-gray-600;
                            fill: $color-gray-600;
                        }
                    }
                }
            }
        }
    }
}

