// Single text - Modern & beautiful reading experience
.irantheme-single-text {
    font-size: 1.05rem;
    font-weight: 400;
    line-height: 1.7;
    color: $color-gray-800;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    hyphens: auto;
    word-wrap: break-word;
    overflow-wrap: break-word;
    direction: rtl;
    text-align: right;
    margin: 0 auto;

    p {
        margin-bottom: 1.5rem;
        margin-top: 0;
        text-align: justify;
        word-spacing: 0.03em;
        letter-spacing: -0.01em;

        em,
        i {
            font-style: italic;
            color: inherit;
        }
    }

    img {
        display: block;
        max-width: 100%;
        height: auto;
        margin: 2rem auto;
        transition: all 0.3s ease;
        object-fit: contain;
        border-radius: $border-radius-medium;
        box-shadow: 0 3px 10px rgba(0, 0, 0, 0.08);

        &:hover {
            opacity: 0.9;
            transform: translateY(-1px);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.12);
        }

        @media (min-width: 768px) {
            max-width: min(100%, 800px);
        }
    }

    b,
    strong {
        font-weight: 700;
        color: inherit;
        padding: 0.1em 0.2em;
    }

    a {
        color: $color-primary;
        text-decoration: none;
        position: relative;
        transition: all 0.2s ease;
        font-weight: 500;

        &::after {
            content: '';
            position: absolute;
            right: 0;
            bottom: -2px;
            width: 100%;
            height: 1px;
            background: $color-primary;
            transform: scaleX(0);
            transform-origin: right;
            transition: transform 0.3s ease;
        }

        &:hover,
        &:focus {
            color: $color-primary-hover;

            &::after {
                transform: scaleX(1);
            }
        }

        &:focus-visible {
            outline: 2px solid $color-primary;
            outline-offset: 2px;
            border-radius: $border-radius-little;
        }
    }

    ul,
    ol {
        margin: 1.75rem 1rem 1.75rem 0;
        padding-right: 1.5rem;

        li {
            margin-bottom: 0.5rem;
            line-height: 1.6;
            position: relative;
        }

        ul,
        ol {
            margin-top: 0.5rem;
            margin-bottom: 0.5rem;
        }
    }

    ul {
        list-style: none;

        li {
            padding: 0.5rem 1.75rem 0.5rem 0;
            border-bottom: 1px solid $color-gray-200;

            &::before {
                content: '';
                position: absolute;
                right: 0;
                top: 0.9rem;
                width: 6px;
                height: 6px;
                background-color: $color-primary;
                border-radius: 50%;
                transition: transform 0.2s ease;
            }

            &:hover::before {
                transform: scale(1.2);
            }

            &:last-child {
                border-bottom: none;
            }
        }
    }

    ol {
        list-style: none;
        counter-reset: item;

        li {
            padding: 0.5rem 2.25rem 0.5rem 0;
            border-bottom: 1px solid $color-gray-200;

            &::before {
                counter-increment: item;
                content: counter(item) ".";
                position: absolute;
                right: 0;
                top: 0.4rem;
                width: 1.8rem;
                height: 1.8rem;
                background: $color-primary;
                color: $color-white;
                font-weight: 600;
                font-size: 0.85rem;
                display: flex;
                align-items: center;
                justify-content: center;
                border-radius: 50%;
                transition: all 0.2s ease;
            }

            &:hover::before {
                background: $color-primary-hover;
                transform: translateY(-1px);
            }

            &:last-child {
                border-bottom: none;
            }
        }
    }

    blockquote {
        background: $color-gray-100;
        margin: 2.5rem 0;
        padding: 2rem 2.5rem 1.5rem 2rem;
        border-right: 3px solid $color-primary;
        position: relative;
        font-style: italic;
        font-size: 1.1rem;
        line-height: 1.6;
        border-radius: 0 $border-radius-medium $border-radius-medium 0;

        &::before {
            content: "❞";
            position: absolute;
            right: 1rem;
            top: 0.5rem;
            color: $color-primary-trans;
            font-size: 1.8rem;
            font-family: $font-family-icons;
            line-height: 1;
        }

        p {
            margin: 0;
            color: $color-gray-900;
            font-size: inherit;
            line-height: inherit;
        }

        cite {
            display: block;
            margin-top: 1rem;
            font-size: 0.9rem;
            font-style: normal;
            color: $color-gray-700;
            font-weight: 500;

            &::before {
                content: '— ';
                margin-left: 0.5rem;
                color: $color-primary;
                font-weight: bold;
            }
        }
    }

    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        margin: 2.5rem 0 1.25rem;
        font-weight: 700;
        line-height: 1.3;
        color: $color-dark;
        scroll-margin-top: 1.5rem;

        &[id] {
            position: relative;

            &::before {
                content: '';
                display: block;
                height: 5rem;
                margin-top: -5rem;
                visibility: hidden;
            }
        }
    }

    h1 {
        font-size: 2rem;
        margin-top: 0;
        padding-bottom: 0.75rem;
        border-bottom: 2px solid $color-gray-200;
    }

    h2 {
        font-size: 1.75rem;
        padding-right: 0.75rem;
        border-right: 3px solid $color-primary;
    }

    h3 {
        font-size: 1.5rem;
        color: $color-gray-800;
    }

    h4 {
        font-size: 1.3rem;
        color: $color-gray-700;
    }

    h5 {
        font-size: 1.15rem;
        color: $color-gray-600;
    }

    h6 {
        font-size: 1.05rem;
        color: $color-gray-600;
        text-transform: uppercase;
        letter-spacing: 0.3px;
        font-weight: 600;
    }

    pre {
        margin: 2.5rem 0;
        padding: 1.75rem;
        border: 1px solid $color-gray-200;
        background: $color-gray-100;
        border-radius: $border-radius-medium;
        overflow-x: auto;
        font-size: 0.9rem;
        line-height: 1.5;
        direction: ltr;
        text-align: left;

        &::-webkit-scrollbar {
            height: 6px;
        }

        &::-webkit-scrollbar-track {
            background: $color-gray-200;
            border-radius: $border-radius-low;
        }

        &::-webkit-scrollbar-thumb {
            background: $color-gray-400;
            border-radius: $border-radius-low;

            &:hover {
                background: $color-gray-500;
            }
        }
    }

    table {
        width: 100%;
        border-collapse: collapse;
        margin: 2rem 0;
        font-size: 0.95rem;

        th,
        td {
            border: 1px solid $color-gray-200;
            padding: 0.75rem 1rem;
            text-align: center;
            vertical-align: middle;
            overflow-wrap: break-word;
        }

        th {
            background-color: $color-primary;
            color: $color-white;
            font-weight: 600;
        }

        tr:nth-child(even) {
            background-color: $color-gray-100;
        }

        tr:hover {
            background-color: $color-gray-200;
        }

        caption {
            font-weight: bold;
            margin-bottom: 0.75rem;
            font-size: 1.1rem;
            color: inherit;
            caption-side: top;
        }

        @media (max-width: 768px) {
            display: block;
            width: 100%;
            max-width: 100%;
            overflow-x: auto;
            -webkit-overflow-scrolling: touch;

            // Preserve the table's natural column sizing.
            white-space: normal;

            thead,
            tbody,
            tfoot {
                display: table-row-group;
            }

            tr {
                display: table-row;
                width: auto;
            }

            th,
            td {
                white-space: normal;
                overflow-wrap: anywhere;
                min-width: 100px;
            }
        }
    }

    .gallery {
        display: grid;
        gap: 1.25rem;
        margin: 2.5rem 0;

        .gallery-item {
            display: block;
            width: 100%;

            .gallery-icon {
                a {
                    display: block;
                    transition: transform 0.3s ease;

                    &:hover {
                        transform: translateY(-3px);
                    }

                    img {
                        margin: 0;
                        width: 100%;
                        height: auto;
                        border-radius: $border-radius-medium;
                    }
                }
            }
        }

        @media (min-width: 768px) {
            grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
        }
    }

    &.white {
        color: $color-gray-800;

        a {
            color: $color-primary;

            &::after {
                background: $color-primary;
            }

            &:hover {
                color: $color-primary-hover;
            }
        }

        ul {
            li {
                border-bottom-color: $color-gray-200;

                &::before {
                    background-color: $color-primary;
                }
            }
        }

        ol {
            li {
                border-bottom-color: $color-gray-200;

                &::before {
                    background: $color-primary;
                    color: $color-white;
                }

                &:hover::before {
                    background: $color-primary-hover;
                }
            }
        }

        blockquote {
            background: $color-gray-100;
            border-right-color: $color-primary;

            p {
                color: $color-gray-900;
            }

            cite {
                color: $color-gray-700;

                &::before {
                    color: $color-primary;
                }
            }
        }

        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
            color: $color-dark;

            &[id] {
                &:hover {
                    &::after {
                        content: '#';
                        margin-right: 0.5rem;
                        color: $color-primary;
                        opacity: 0.6;
                        font-size: 0.9rem;
                    }
                }
            }
        }

        h1 {
            border-bottom-color: $color-gray-300;
        }

        h2 {
            border-right-color: $color-primary;
        }

        pre {
            border-color: $color-gray-300;
            background: $color-gray-100;
        }

        table {

            th,
            td {
                border-color: $color-gray-200;
            }

            th {
                background-color: $color-primary;
                color: $color-white;
            }

            tr:nth-child(even) {
                background-color: $color-gray-100;
            }

            tr:hover {
                background-color: $color-gray-200;
            }

            caption {
                color: $color-gray-700;
            }
        }
    }

    &.dark {
        color: $color-gray-300;
        background-color: transparent;

        a {
            color: $color-primary;

            &::after {
                background: $color-primary;
            }

            &:hover {
                color: $color-primary-hover;
            }
        }

        ul {
            li {
                border-bottom-color: $color-gray-800;

                &::before {
                    background-color: $color-primary;
                }
            }
        }

        ol {
            li {
                border-bottom-color: $color-gray-800;

                &::before {
                    background: $color-primary;
                    color: $color-white;
                }

                &:hover::before {
                    background: $color-primary-hover;
                }
            }
        }

        blockquote {
            background: $color-gray-900;
            border-right-color: $color-primary;

            p {
                color: $color-gray-300;
            }

            cite {
                color: $color-gray-400;

                &::before {
                    color: $color-primary;
                }
            }

            &::before {
                color: $color-primary-trans;
            }
        }

        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
            color: $color-gray-200;

            &[id] {
                &:hover {
                    &::after {
                        content: '#';
                        margin-right: 0.5rem;
                        color: $color-primary;
                        opacity: 0.6;
                        font-size: 0.9rem;
                    }
                }
            }
        }

        h1 {
            border-bottom-color: $color-gray-800;
        }

        h2 {
            border-right-color: $color-primary;
        }

        h6 {
            color: $color-gray-400;
        }

        pre {
            border-color: $color-gray-800;
            background: $color-gray-900;

            &::-webkit-scrollbar-track {
                background: $color-gray-800;
            }

            &::-webkit-scrollbar-thumb {
                background: $color-gray-600;

                &:hover {
                    background: $color-gray-500;
                }
            }
        }

        table {

            th,
            td {
                border-color: $color-gray-800;
            }

            th {
                background-color: $color-primary;
                color: $color-white;
            }

            tr:nth-child(even) {
                background-color: $color-gray-900;
            }

            tr:hover {
                background-color: $color-gray-800;
            }

            caption {
                color: $color-gray-300;
            }
        }

        img {
            box-shadow: 0 3px 10px rgba(0, 0, 0, 0.2);

            &:hover {
                box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
            }
        }
    }

    @media print {
        font-size: 11pt;
        line-height: 1.6;
        direction: rtl;
        text-align: right;
        max-width: none;

        * {
            color: $color-dark !important;
            background: transparent !important;
            box-shadow: none !important;
            text-shadow: none !important;
        }

        a {
            text-decoration: underline;

            &::after {
                display: none;
            }
        }

        img {
            max-width: 100% !important;
            box-shadow: none !important;
            margin: 1.5rem auto !important;
        }

        pre {
            background: $color-gray-100 !important;
            border: 1px solid $color-gray-300 !important;
            page-break-inside: avoid;
            direction: ltr;
            text-align: left;
        }

        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
            page-break-after: avoid;
            color: $color-dark !important;
        }

        blockquote {
            page-break-inside: avoid;
            border: 1px solid $color-gray-300 !important;
            border-right: 3px solid $color-primary !important;
        }

        ul li::before,
        ol li::before {
            background: $color-gray-700 !important;
            color: $color-white !important;
        }
    }
}