/*
=====================================
Woocommerce ajax categories products
=====================================
*/
.irantheme-woocommerce-ajax-categories-products-section {
    .irantheme-woocommerce-ajax-categories-products-swiper {
        @include transition(0.2s);
    }

    .irantheme-woocommerce-products-wrapper {
        @include transition(0.2s);
    }

    .irantheme-woocommerce-ajax-categories-products-result {
        @include transition(0.2s);
    }

    .irantheme-woocommerce-ajax-categories-products-filter {
        display: flex;
        flex-wrap: wrap;
        line-height: normal;
        column-gap: 1.5rem;
        margin-bottom: 1rem;

        &-item {
            display: flex;
            padding: 0.5rem 0;
            background: transparent;
            color: $color-gray-700;
            position: relative;
            font-size: 0.8rem;
            column-gap: 0.25rem;

            i {
                font-size: 0.7rem;
            }

            &::after {
                content: '';
                width: 0;
                height: 0.15rem;
                background: $color-gray-600;
                position: absolute;
                right: 0;
                bottom: 0;
                border-radius: $border-radius-medium;
                @include transition(0.2s, all, cubic-bezier(0.42, 0, 0.58, 1));
                // transition: cubic-bezier(0.455, 0.03, 0.515, 0.955)
                // @include transform(translateX(50%));
            }

            &:hover,
            &.active {
                color: $color-dark;

                i,
                i::before {
                    color: $color-dark !important;
                }

                &::after {
                    width: 100%;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            .irantheme-woocommerce-ajax-categories-products-filter-item {
                color: $color-gray-700;

                &::after {
                    background: $color-gray-600;
                }

                &:hover,
                &.active {
                    color: $color-dark;

                    i,
                    i::before {
                        color: $color-dark !important;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            .irantheme-woocommerce-ajax-categories-products-filter-item {
                color: $color-gray-300;

                &::after {
                    background: $color-gray-400;
                }

                &:hover,
                &.active {
                    color: $color-white;

                    i,
                    i::before {
                        color: $color-white !important;
                    }
                }
            }
        }
    }
}