/*
=====================================
Service Progress Section
=====================================
*/
.irantheme-service-semi-grid-image-section {
    .irantheme-service-semi-grid-image {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        .irantheme-service-semi-grid-image-images {
            position: relative;
            display: grid;
            grid-template-rows: 50% 50%;
            grid-template-columns: 1fr 1fr;
            gap: 1.5rem;

            &-img1 {
                height: 100%;
            }

            &-img2 {
                height: 100%;
            }

            &-img3 {
                height: 100%;
            }

            &-img4 {
                height: 100%;
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;
        }
    }
}