/*
=====================================
Service Progress Section
=====================================
*/
.irantheme-service-semi-number-section {
    .irantheme-service-semi-number {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        // Item
        .irantheme-service-item {
            position: relative;
            // overflow: hidden;
            height: 100%;
            padding: 2rem;
            @include transition(0.3s, all, ease-in-out);
            z-index: 1;

            &.irantheme-box-style-shadow:hover {
                box-shadow: none !important;
            }

            // Box style none
            &.irantheme-box-style-none {
                padding: 0 !important;
            }

            // Wrapper
            .irantheme-service-item-wrapper {
                position: relative;
                overflow: hidden;
            }

            // Content
            &-content {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                z-index: 9;

                // Title
                &-number {
                    font-size: 1rem;
                    display: flex;
                    line-height: normal;
                    // color: $color-dark;

                    &-char {}
                }

                // Description
                &-desc {
                    font-size: 0.8rem;
                    // color: $color-gray-700;

                    &-heading {
                        font-size: 1rem;
                        line-height: 1.8rem;
                        margin-top: 1rem;
                    }

                    &-small {
                        font-size: 0.8rem;
                        line-height: 1.4rem;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Item
            .irantheme-service-item {

                // Shadow
                &.irantheme-box-style-shadow {
                    @extend %box-shadow-white;
                }

                // Shadow
                &.irantheme-box-style-border {
                    border: 1px solid $color-gray-200;
                }

                // Content
                &-content {

                    // Title
                    &-number {
                        color: $color-dark;

                        &-char {}
                    }

                    // Description
                    &-desc {
                        &-heading {
                            color: $color-gray-700;
                        }

                        &-small {
                            color: $color-gray-500;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Item
            .irantheme-service-item {

                // Shadow
                &.irantheme-box-style-shadow {
                    @extend %box-shadow-dark;
                }

                // Shadow
                &.irantheme-box-style-border {
                    border: 1px solid $color-gray-800;
                }

                // Content
                &-content {

                    // Title
                    &-number {
                        color: $color-white;

                        &-char {}
                    }

                    // Description
                    &-desc {
                        &-heading {
                            color: $color-gray-300;
                        }

                        &-small {
                            color: $color-gray-500;
                        }
                    }
                }
            }
        }
    }
}