// Navigation
.irantheme-woocommerce-wishlist-navigation {
    position: fixed;
    top: 0;
    left: 0;
    width: 400px;
    max-width: 100%;
    height: 100vh;
    z-index: 99999999;
    background: $color-gray-100;
    display: flex;
    flex-direction: column;
    @include transition(0.4s, transform, cubic-bezier(0.215, 0.61, 0.355, 1));
    @include transform(translateX(-100%));
    @include box-shadow(rgba(0, 0, 0, 0.2) 0px 70px 140px);

    &.active {
        transition-delay: 0.6s;
        transform: translateX(0) !important;
    }

    // Header
    &-header {
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        justify-content: center;
        padding: 1rem;

        // Close nav
        &-close {
            color: $color-gray-700;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            @include transition(0.2s);
            width: 2.5rem;
            height: 2.5rem;
            margin-right: auto;
            background: $color-white;
            border-radius: 50%;

            &:hover {
                background: $color-dark;
                color: $color-white;
            }

            i {
                font-size: 1.2rem;
            }
        }
    }

    // Wrapper
    &-wrapper {
        width: 100%;
        height: 100%;
        overflow-y: auto;
        overflow-x: hidden;
        padding: 1rem;
        display: flex;
        flex-direction: column;
        position: relative;

        .irantheme-woocommerce-cart-navigation-list-item-content-info {
            justify-content: flex-start;
        }

        &-empty {
            font-size: 0.8rem;
            color: $color-gray-700;
            text-align: center;
        }
    }

    // Footer
    &-footer {
        margin-top: auto;
        display: flex;
        flex-direction: column;
    }
}