/*
=====================================
Woocommerce products and offers products
=====================================
*/
.irantheme-woocommerce-offers-products-section {

    .irantheme-woocommerce-offers-products {

        &-holder {}

        .irantheme-woocommerce-offers-products-side {
            border-width: 0.15rem;
            border-style: dashed;
            border-color: $color-gray-700;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            padding: 1.5rem;
            row-gap: 1.5rem;
            height: 100%;

            @media (max-width: 1750px) {
                row-gap: 1rem;
            }

            // Content mode
            &-mode-content {
                padding: 0 !important;
                border: 0 !important;
            }

            // Image mode
            &-image {
                display: flex;
                justify-content: center;
                align-items: center;

                &-link {
                    display: block;
                    max-width: 100%;
                }

                &-img {
                    display: block;
                    width: 100%;
                    height: auto;
                    max-width: 100%;
                    object-fit: contain;
                }
            }

            &-heading {
                font-size: 2.5rem;
                font-weight: 600;
                line-height: normal;
                color: $color-gray-900;

                @media (max-width: 1750px) {
                    font-size: 2rem;
                }

                @media (max-width: 575px) {
                    font-size: 1.5rem;
                }
            }

            &-icon {
                font-size: 6rem;
                color: $color-gray-900;

                @media (max-width: 1750px) {
                    font-size: 4.5rem;
                }

                @media (max-width: 575px) {
                    font-size: 3rem;
                }
            }

            &-link {
                a {
                    display: inline-flex;
                    align-items: center;
                    column-gap: 0.25rem;
                    font-size: 0.7rem;
                    font-weight: 500;
                    color: $color-gray-600;
                    opacity: 0.8;
                    padding: 0.5rem 1rem;
                    border-radius: $border-radius-medium;
                    line-height: normal;

                    @media (max-width: 1750px) {
                        padding: 0.25rem 0.5rem;
                        font-size: 0.6rem;
                    }

                    i {
                        @include transition(0.2s);
                        width: fit-content;
                    }

                    &:hover {
                        opacity: 1;

                        i {
                            transform: translateX(-5px);
                        }
                    }
                }
            }
        }

        .irantheme-tinymce-holder {
            &.irantheme-heading-mobile-mode {
                display: none;
                visibility: hidden;
                opacity: 0;
            }


            @media (max-width: 479.98px) {
                &.irantheme-heading-mobile-mode {
                    display: block;
                    visibility: visible;
                    opacity: 1;
                }

            }
        }

        .irantheme-woocommerce-products-col {
            &.irantheme-heading-desktop-mode {
                display: block;
                visibility: visible;
                opacity: 1;
            }

            @media (max-width: 479.98px) {
                &.irantheme-heading-desktop-mode {
                    display: none !important;
                    visibility: hidden !important;
                    opacity: 0 !important;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            .irantheme-woocommerce-offers-products-side {
                border-color: $color-gray-700;

                &-heading {
                    color: $color-gray-900;
                }

                &-icon {
                    color: $color-gray-900;
                }

                &-link {

                    a {
                        background: $color-gray-200;
                        color: $color-gray-600;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            .irantheme-woocommerce-offers-products-side {
                border-color: $color-gray-300;

                &-heading {
                    color: $color-gray-100;
                }

                &-icon {
                    color: $color-gray-100;
                }

                &-link {
                    background: $color-gray-800;

                    a {
                        color: $color-gray-400;
                    }
                }
            }
        }
    }
}