/*
=====================================
Blog content
=====================================
*/

#irantheme-single {
    padding: 3rem 0;

    // All posts, grid masonry (main)
    main.grid-masonry {

        // padding: 0 -15px;
        // Post holder
        .post-holder {
            margin-bottom: 30px;
        }
    }
}

.post-single-contemporary {
    border-radius: $border-radius-low;
    overflow: hidden;

    // Single thumbnail
    .single-thumbnail {

        @media only screen and (max-width:991px) {
            margin-bottom: 2rem;
        }

        img {
            width: 100%;
            border-radius: $border-radius-low;
        }
    }

    // Single next prev post
    .next-prev-post {
        margin-bottom: 2rem;
        display: flex;
        flex-direction: row-reverse;
        justify-content: flex-end;

        a {
            margin-left: 1rem;
            width: 3rem;
            height: 3rem;
            display: flex;
            justify-content: center;
            align-items: center;
            background: $color-gray-100;
            color: $color-gray-600;
            border-radius: 50%;

            &:hover {
                background: $color-gray-200;
            }

            &.disable {
                color: $color-gray-300;

                &.disable:hover {
                    background: $color-gray-100;
                    color: $color-gray-300;
                    cursor: default;
                }
            }
        }
    }


    // Single heading
    .single-heading {
        margin-bottom: 1rem;
        padding-bottom: 1rem;
        border-bottom: 1px solid $color-gray-200;

        span {
            font-size: 0.7rem;
            color: $color-gray-900;

            i {
                margin-left: 0.5rem;
            }
        }

        h2 {
            font-size: 1rem;
            color: $color-dark;
            line-height: 1.6rem;
            font-weight: 400;
            margin: 1rem 0 0;

            a {
                color: inherit;
            }
        }
    }

    // Single author
    .single-author {
        display: flex;
        align-items: center;
        margin-bottom: 1rem;

        .single-author-img {
            img {
                width: 2.75rem;
                height: 2.75rem;
                border-radius: 50%;
            }
        }

        .single-author-info {
            padding-right: 1rem;
            line-height: 1rem;

            h4 {
                margin-bottom: 0.25rem;

                a {
                    font-size: 0.8rem;
                    color: $color-gray-800;
                }
            }

            p {
                font-size: 0.7rem;
                color: $color-gray-600;
            }
        }
    }

    // Single categories
    .single-categories {
        display: flex;
        margin-bottom: 1rem;
        padding-bottom: 1rem;
        border-bottom: 1px solid $color-gray-200;

        // Icon
        .single-categories-icon {
            font-size: 0.9rem;

            i {
                position: relative;
                top: 2px;
            }
        }

        // Content
        .single-categories-content {
            padding-right: 0.5rem;

            // Title
            strong {
                display: block;
                font-size: 0.9rem;
                font-weight: normal;
                color: $color-gray-800;
            }

            // List item
            .single-categories-list {
                display: flex;
                flex-wrap: wrap;

                a {
                    color: $color-gray-700;
                    font-size: 0.7rem;
                    font-weight: 400;

                    &:not(:last-child) {
                        margin-left: 1rem;
                    }
                }
            }
        }
    }

    // Single like share
    .single-like-share {
        display: flex;
        height: 2rem;
        margin-bottom: 1rem;
        margin-top: 2rem;
        width: 100%;

        // Like
        .like-button {
            margin: 0;
            padding: 0 1rem;
            background: $color-gray-100;
            border: 0;
            outline: 0;
            color: $color-gray-900;
            line-height: inherit;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: $border-radius-low;
            cursor: pointer;
            transition: background 0.3s ease;

            &[data-exists="yes"] {
                background: $color-gray-100;

                i {
                    font-weight: bold;
                }

                .like-heart-no {
                    display: none !important;
                }

                .like-heart-yes {
                    display: flex !important;
                    color: $color-primary; // Add this for liked state
                }

                .text-heart-no {
                    display: none !important;
                }

                .text-heart-yes {
                    display: flex !important;
                }
            }

            .like-heart-no {
                display: flex;
            }

            .like-heart-yes {
                display: none;
            }

            .text-heart-no {
                display: flex !important;
            }

            .text-heart-yes {
                display: none !important;
            }

            &:hover {
                background: darken($color-gray-100, 5%);
            }

            i {
                margin-left: 0.5rem;
                margin-right: 0;
                transition: 0.3s;
                color: $color-gray-700;
                background: transparent;
                display: flex;
                align-items: center;
                align-self: stretch;
                font-size: 0.8rem;
            }

            span {
                font-size: 0.8rem;
                color: $color-dark;
                display: flex;

                cite {
                    font-style: normal;
                }
            }

            .like-count {
                font-style: normal;
                font-size: inherit;
                margin-right: 0.5rem;
            }
        }

        // Button share
        .single-share-button {
            margin: 0 0.5rem 0 0;
            padding: 0 1rem;
            background: $color-gray-100;
            font-size: 0.8rem;
            color: $color-gray-700;
            border-radius: $border-radius-low;
            @include transition(all, 0.4s);
            z-index: 2;

            i {
                margin-left: 0.5rem;
            }

            &:hover {
                box-shadow: inset -10rem 0 0 $color-gray-200;
            }
        }

        // List share
        .single-share-list {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            @include transition(all, 0.3s);
            @include transform(translate(5rem, 0));
            opacity: 0;
            z-index: 1;
            visibility: hidden;
            font-size: 0.8rem;

            &.active {
                padding-right: 0.25rem;
                @include transform(translate(0, 0));
                opacity: 1;
                visibility: visible;
            }

            a {
                margin: 0.25rem;
                color: $color-gray-600;

                &:hover {
                    color: $color-gray-900;
                }
            }
        }
    }

    // Single tags
    .single-tags {
        margin-bottom: 1rem;

        .single-tags-list {
            display: flex;
            flex-wrap: wrap;

            h3 {
                margin-bottom: 0.5rem;
                margin-left: 0.5rem;

                a {
                    font-size: 0.7rem;
                    background: $color-gray-100;
                    padding: 0.5rem;
                    color: $color-gray-600;
                    display: flex;
                    align-items: center;
                    border-radius: $border-radius-low;

                    i {
                        margin-left: 0.5rem;
                    }

                    &:hover {
                        color: $color-gray-900;
                    }

                    &:not(:last-child) {
                        margin-left: 0.5rem;
                    }
                }
            }
        }
    }

    // Post box
    .post-box {
        background: $color-white;
        margin-bottom: 30px;
    }


    /*
  =====================================
  Comments fixed
  =====================================
  */

    #comments-fixed-container {
        position: fixed;
        top: 0;
        right: 0;
        z-index: 4;
        width: 100%;
        height: 100%;
        background: $color-white-transparent-4;
        z-index: 999999;
        display: none;
    }

    #comments-fixed {
        position: fixed;
        top: 50%;
        right: 50%;
        width: 800px;
        height: 90vh;
        background: $color-white;
        border-right: 4px solid $color-dark;
        box-shadow: 20px 20px 40px 4px rgb(0 0 0 / 6%);
        z-index: 5;
        border-radius: $border-radius-low;
        overflow: auto;
        @include transform(translate(50%, -50%));

        @media screen and (max-width: 991px) {
            width: 90vw;
            height: 90vh;
        }

        // Comments title
        .comments-title {
            background: $color-white;
            display: flex;
            justify-content: space-between;
            align-items: center;
            width: 100%;
            height: 3rem;
            border-bottom: 1px solid $color-gray-200;
            position: sticky;
            top: 0;
            right: 0;
            z-index: 1;

            h4 {
                font-size: 0.9rem;
                color: $color-gray-800;
                padding: 0 1rem;
            }

            #close-comments-fixed {
                font-size: 1rem;
                color: $color-gray-800;
                width: 3rem;
                height: 3rem;
                display: flex;
                align-items: center;
                justify-content: center;
                text-align: center;
                @include transition(0.2s);

                &:hover {
                    background: $color-gray-100;
                }
            }
        }

        #comments-holder {
            padding: 2rem;
        }

        // Comments fixed list
        #comments-fixed-list {
            padding: 2rem;
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {

        // Single next prev post
        .next-prev-post {

            a {
                background: $color-gray-100;
                color: $color-gray-600;

                &:hover {
                    background: $color-gray-200;
                }

                &.disable {
                    color: $color-gray-300;

                    &.disable:hover {
                        background: $color-gray-100;
                        color: $color-gray-300;
                    }
                }
            }
        }


        // Single heading
        .single-heading {
            border-bottom: 1px solid $color-gray-200;

            span {
                color: $color-gray-900;
            }

            h2 {
                color: $color-dark;
            }
        }

        // Single author
        .single-author {
            .single-author-info {
                h4 {
                    a {
                        color: $color-gray-800;
                    }
                }

                p {
                    color: $color-gray-600;
                }
            }
        }

        // Single categories
        .single-categories {
            border-bottom: 1px solid $color-gray-200;

            // Content
            .single-categories-content {

                // Title
                strong {
                    color: $color-gray-800;
                }

                // List item
                .single-categories-list {

                    a {
                        color: $color-gray-700;
                    }
                }
            }
        }

        // Single like share
        .single-like-share {

            // Like
            .like-button {
                color: $color-gray-700;
                background: $color-gray-100;

                span {
                    color: $color-gray-700;
                }

                .like-count {
                    color: $color-gray-600;
                }
            }

            // Button share
            .single-share-button {
                background: $color-gray-100;
                color: $color-gray-700;

                &:hover {
                    box-shadow: inset -10rem 0 0 $color-gray-200;
                }
            }

            // List share
            .single-share-list {

                a {
                    color: $color-gray-600;

                    &:hover {
                        color: $color-gray-900;
                    }
                }
            }
        }

        // Single tags
        .single-tags {

            .single-tags-list {

                a {
                    background: $color-gray-100;
                    color: $color-gray-600;

                    &:hover {
                        color: $color-gray-900;
                    }
                }
            }
        }

        // Post box
        .post-box {
            background: $color-white;
        }

        /*
        =====================================
        Comments fixed
        =====================================
        */
        #comments-fixed-container {
            background: $color-white-transparent-4;
        }

        #comments-fixed {
            background: $color-white;
            border-right: 4px solid $color-dark;
            box-shadow: 20px 20px 40px 4px rgb(0 0 0 / 6%);

            // Comments title
            .comments-title {
                background: $color-white;
                border-bottom: 1px solid $color-gray-200;

                h4 {
                    color: $color-gray-800;
                }

                #close-comments-fixed {
                    color: $color-gray-800;

                    &:hover {
                        background: $color-gray-100;
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {

        // Single next prev post
        .next-prev-post {

            a {
                background: $color-gray-900;
                color: $color-gray-400;

                &:hover {
                    background: $color-gray-800;
                }

                &.disable {
                    color: $color-gray-700;

                    &.disable:hover {
                        background: $color-gray-900;
                        color: $color-gray-700;
                    }
                }
            }
        }


        // Single heading
        .single-heading {
            border-bottom: 1px solid $color-gray-800;

            span {
                color: $color-gray-100;
            }

            h2 {
                color: $color-white;
            }
        }

        // Single author
        .single-author {
            .single-author-info {
                h4 {
                    a {
                        color: $color-gray-200;
                    }
                }

                p {
                    color: $color-gray-400;
                }
            }
        }

        // Single categories
        .single-categories {
            border-bottom: 1px solid $color-gray-800;

            // Content
            .single-categories-content {

                // Title
                strong {
                    color: $color-gray-200;
                }

                // List item
                .single-categories-list {

                    a {
                        color: $color-gray-300;
                    }
                }
            }
        }

        // Single like share
        .single-like-share {

            // Like
            .like-button {
                color: $color-gray-300;
                background: $color-gray-900;

                span {
                    color: $color-gray-300;
                }

                .like-count {
                    color: $color-gray-400;
                }
            }

            // Button share
            .single-share-button {
                background: $color-gray-900;
                color: $color-gray-300;

                &:hover {
                    box-shadow: inset -10rem 0 0 $color-gray-800;
                }
            }

            // List share
            .single-share-list {

                a {
                    color: $color-gray-400;

                    &:hover {
                        color: $color-gray-100;
                    }
                }
            }
        }

        // Single tags
        .single-tags {

            .single-tags-list {

                a {
                    background: $color-gray-900;
                    color: $color-gray-400;

                    &:hover {
                        color: $color-gray-100;
                    }
                }
            }
        }

        // Post box
        .post-box {
            background: $color-dark;
        }

        /*
        =====================================
        Comments fixed
        =====================================
        */
        #comments-fixed-container {
            background: $color-dark-transparent-4;
        }

        #comments-fixed {
            background: $color-dark;
            border-right: 4px solid $color-white;
            box-shadow: 20px 20px 40px 4px rgb(255 255 255 / 6%);

            // Comments title
            .comments-title {
                background: $color-dark;
                border-bottom: 1px solid $color-gray-800;

                h4 {
                    color: $color-gray-200;
                }

                #close-comments-fixed {
                    color: $color-gray-200;

                    &:hover {
                        background: $color-gray-900;
                    }
                }
            }
        }
    }
}