.post-single-advanced {
    overflow: hidden;

    .single-post {
        margin-bottom: 30px !important;
    }

    /*
    =====================================
    Blog content
    =====================================
    */
    // Post box
    .post-box {
        background: $color-white;
        margin-bottom: 30px;
        border-radius: $border-radius-low;
        overflow: hidden;
        padding: 1rem;
    }

    .post-content {}

    // Post image
    .post-image {
        a.post-image-link {
            display: block;
        }
    }

    // Post thumbnail
    .post-thumbnail {
        position: relative;
        border-radius: $border-radius-low;
        overflow: hidden;

        &::before {
            content: '';
            width: 100%;
            height: 100%;
            position: absolute;
            top: 0;
            right: 0;
            background: transparent;
            transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
            z-index: 2;
        }

        // Post image link hover
        &:hover {
            img {
                transform: scale(1.2);
            }

            &::before {
                background: $color-dark-transparent-2;
            }
        }

        img {
            width: 100%;
            transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
        }
    }

    // Post slider
    .post-slider {
        .post-slider-link {
            display: block;
            position: relative;
        }

        .post-image-slider-buttons {
            position: absolute;
            bottom: 0;
            left: 0;
            display: -webkit-box;
            display: -ms-flexbox;
            display: flex;
            -webkit-box-orient: horizontal;
            -webkit-box-direction: normal;
            -ms-flex-direction: row;
            flex-direction: row;
            z-index: 3;

            &>div[class*='post-image'] {
                width: 3rem;
                height: 3rem;
                background: rgba(0, 0, 0, 0.6);
                color: $color-white;
                display: -webkit-box;
                display: -ms-flexbox;
                display: flex;
                -webkit-box-pack: center;
                -ms-flex-pack: center;
                justify-content: center;
                -webkit-box-align: center;
                -ms-flex-align: center;
                align-items: center;
                text-align: center;
                font-weight: bold;
                font-size: 0.8rem;

                &.swiper-button-disabled {
                    color: $color-gray-600;
                    cursor: default;
                }
            }
        }
    }

    // Post video
    .post-video {
        video {
            width: 100%;
            height: auto;
            -o-object-fit: cover;
            object-fit: cover;
        }
    }

    // Post topbar
    .post-topbar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        flex-wrap: wrap;
        margin-bottom: 1rem;

        .gradient {
            font-size: 0.7rem;
            color: $color-dark;
            padding: 0 0.5rem;
            display: flex;
            align-items: center;
            position: relative;

            em {
                position: absolute;
                right: 0;
                top: 0;
                width: 0.15rem;
                height: 100%;
            }

            i {
                margin-left: 0.5rem;
            }
        }

        &-more {
            font-size: 0.7rem;
            color: $color-dark;

            i {
                margin-right: 0.5rem;
            }
        }
    }

    // Post options
    .post-options {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        margin-bottom: 1rem;
        cursor: default;

        span {
            cursor: default;
            font-size: 0.7rem;
            color: $color-gray-600;
            display: flex;
            align-items: center;

            i {
                margin-left: 0.5rem;
                color: $color-gray-600;
                font-size: 0.8rem;
                position: relative;
                top: 2px;
            }

            em {
                margin-right: 0.5rem;
                font-style: normal;
            }

            &:not(:last-child) {
                &::after {
                    content: '.';
                    font-size: 1.4rem;
                    margin-right: 0.5rem;
                    margin-left: 0.5rem;
                    color: $color-gray-500;
                    position: relative;
                    top: -0.25rem;
                }
            }
        }
    }

    // Post category (Without thumbnail)
    .post-category-no-thumbnail {
        margin-bottom: 1rem;
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;

        a {
            font-size: 0.7rem;
            padding: 0;
            margin-bottom: 0.25rem;

            &:hover {
                opacity: 0.8;
            }

            &:not(:last-child) {
                margin-left: 1rem;
            }
        }
    }

    // Post heading
    .post-heading {
        margin-bottom: 1rem;

        h2 {
            font-size: 1.2rem;
            color: $color-gray-900;
            line-height: 1.6rem;
            margin-bottom: 0.5rem;

            a {
                color: inherit;
            }
        }
    }

    // Post author
    .post-author {
        &>div {
            display: flex;
            transition: 0.3s;

            &:hover {
                background: transparent;
            }

            img {
                width: 3.5rem;
                height: 3.5rem;
                border-radius: 50%;
            }

            &>div {
                margin-right: 1rem;
                display: flex;
                flex-direction: column;
                padding-top: 0.75rem;

                a {
                    font-size: 0.8rem;
                    font-style: normal;
                    color: $color-dark;
                    line-height: 1.2;
                }

                span {
                    font-size: 0.7rem;
                    color: $color-gray-600;
                }
            }
        }
    }

    // Post tags
    .post-tags {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        padding-top: 0.5rem;
        margin-bottom: 1rem;

        h3 {
            margin-left: 0.5rem;
            margin-bottom: 0.5rem;

            a {
                background: transparent;
                font-size: 0.7rem;
                display: flex;
                align-items: center;
                color: $color-gray-700;
                border-radius: $border-radius-low;
                padding-left: 1rem;

                &::before {
                    content: '\f02b';
                    font-family: $font-family-icons;
                    line-height: inherit;
                    background: $color-gray-200;
                    color: $color-gray-600;
                    border-radius: $border-radius-low;
                    padding: 0 0.5rem;
                    margin-left: 0.5rem;
                    padding: 0.5rem;
                }

                &:hover {
                    background: $color-gray-200;
                    opacity: 1;
                    color: $color-dark;
                }
            }
        }
    }

    // Share & like

    // Holder
    .post-like {
        display: flex;
        justify-content: space-between;
        margin-left: 1rem;

        // Like
        .like-button {
            margin: 0;
            padding: 0 1rem;
            background: $color-gray-100;
            border: 0;
            outline: 0;
            color: $color-gray-900;
            line-height: inherit;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: $border-radius-low;
            cursor: pointer;
            transition: background 0.3s ease;

            &[data-exists="yes"] {
                background: $color-gray-100;

                i {
                    font-weight: bold;
                }

                .like-heart-no {
                    display: none !important;
                }

                .like-heart-yes {
                    display: flex !important;
                    color: $color-primary; // Add this for liked state
                }

                .text-heart-no {
                    display: none !important;
                }

                .text-heart-yes {
                    display: flex !important;
                }
            }

            .like-heart-no {
                display: flex;
            }

            .like-heart-yes {
                display: none;
            }

            .text-heart-no {
                display: flex !important;
            }

            .text-heart-yes {
                display: none !important;
            }

            &:hover {
                background: darken($color-gray-100, 5%);
            }

            i {
                margin-left: 0.5rem;
                margin-right: 0;
                transition: 0.3s;
                color: $color-gray-700;
                background: transparent;
                display: flex;
                align-items: center;
                align-self: stretch;
                font-size: 0.8rem;
            }

            span {
                font-size: 0.8rem;
                color: $color-dark;
                display: flex;

                cite {
                    font-style: normal;
                }
            }

            .like-count {
                font-style: normal;
                font-size: inherit;
                margin-right: 0.5rem;
            }
        }
    }

    // Post share
    .post-share {
        display: flex;
        justify-content: center;
        overflow: hidden;
        height: 2.5rem;
        line-height: 2.5rem;
        align-items: center;
        padding: 0 1rem;

        a {
            line-height: 1rem;
            padding: 0 0.5rem;
            font-size: 0.8rem;
            display: flex;
            align-items: center;
            position: relative;
            overflow: hidden;
            transition: none;
            color: $color-gray-700;

            &:hover {
                opacity: 1;
                color: inherit;
            }

            span {
                position: absolute;
                right: 2rem;
                white-space: nowrap;
            }
        }
    }

    /*
    =====================================
    Post box space
    =====================================
    */

    // Related post

    .related-post {
        padding-bottom: 30px;

        .related-post-slider {
            position: relative;
        }

        .swiper-slide {
            height: 100%;
        }
    }

    // Post list options
    .post-list-options {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        // margin-bottom: 1rem;
        cursor: default;

        span {
            cursor: default;
            font-size: 0.7rem;
            color: $color-gray-600;

            &:not(:last-child) {
                margin-left: 1rem;
            }

            i {
                margin-left: 0.5rem;
                color: $color-gray-600;
                font-size: 0.8rem;
                position: relative;
                top: 2px;
            }

            em {
                margin-right: 0.5rem;
                font-style: normal;
            }
        }
    }


    .post-box-space {
        padding: 1rem;
        background: $color-white;
        border-radius: $border-radius-low;
        height: 100%;
        width: 100%;
    }

    .post-image-space {
        margin-bottom: 1rem;
    }

    .post-thumbnail-space {
        height: 14rem;
        overflow: hidden;
        border-radius: $border-radius-low;

        img {
            height: 100%;
            width: 100%;
            object-fit: cover;
            @include transition(all, 0.3s, ease-out);

            &:hover {
                @include transform(scale(1.1) rotate(-2.5deg));
                opacity: 0.9;
            }
        }
    }

    .post-content-space {
        padding: 0;
    }

    .post-heading-space {
        margin-bottom: 0.5rem;

        span {
            font-size: 0.7rem;
            display: none;

            i {
                margin-left: 0.5rem;
            }
        }

        h2 {
            font-size: 0.9rem;
            line-height: 1.4rem;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;

            a {
                color: $color-gray-900;
            }
        }
    }

    /*
    =====================================
    Post little box
    =====================================
    */

    .post-box-little {
        background: $color-gray-900;
        padding: 1rem;
        border-radius: $border-radius-low;
        height: 100%;
        display: block;

        &:hover {
            background: $color-gray-800;

            .post-thumbnail-little {
                img {
                    opacity: 0.75;
                }
            }
        }

        .post-thumbnail-little {
            width: 100%;
            height: 9rem;
            overflow: hidden;
            margin-bottom: 1rem;

            img {
                width: 100%;
                height: 100%;
                @include transition(all, 0.3s, ease-out);
            }
        }

        // Heading
        .post-heading-little {
            margin-bottom: 0.5rem;

            span {
                font-size: 0.7rem;
                color: $color-gray-300;

                i {
                    margin-left: 0.5rem;
                    color: $color-primary;
                }
            }

            h3 {
                font-size: 0.9rem;
                line-height: 1.4rem;
                color: $color-gray-200;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }
        }

        // Options
        .post-options-little {
            span {
                cursor: default;
                font-size: 0.7rem;
                color: $color-gray-500;

                &:not(:last-child) {
                    margin-left: 1rem;
                }

                i {
                    margin-left: 0.5rem;
                    color: $color-primary;
                    font-size: 0.8rem;
                    position: relative;
                    top: 2px;
                }

                em {
                    margin-right: 0.5rem;
                    font-style: normal;
                }
            }
        }
    }

    /*
    =====================================
    Author post single
    =====================================
    */

    .author-post-single {
        display: flex;
        flex-direction: row;

        // Avatar
        &-avatar {
            margin-left: 1rem;
            width: 4rem;

            img {
                border-radius: 50%;
                width: 100%;
                height: auto;
            }
        }

        // Info
        &-info {
            width: 100%;
            display: flex;
            flex-direction: column;

            b {
                font-size: 0.9rem;
                font-weight: normal;
                padding: 0;
                margin: 0;
                color: $color-gray-800;

                a {
                    color: $color-dark;
                }

                span {
                    font-size: 0.7rem;
                    color: $color-gray-700;
                    background: $color-gray-100;
                    border-radius: $border-radius-low;
                    padding: 0.25rem 0.5rem;
                    width: fit-content;
                    cursor: default;
                    margin-right: 0.25rem;
                }
            }

            p {
                padding-top: 0.5rem;
                font-size: 0.7rem;
                color: $color-gray-600;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
