            }

            // Options
            .post-options-little {
                span {
                    color: $color-gray-500;

                    i {
                        color: $color-primary;
                    }
                }
            }
        }

        /*
        =====================================
        Author post single
        =====================================
        */
        .author-post-single {

            // Info
            &-info {

                b {
                    color: $color-gray-800;

                    a {
                        color: $color-dark;
                    }

                    span {
                        color: $color-gray-700;
                        background: $color-gray-100;
                    }
                }

                p {
                    color: $color-gray-600;
                }
            }
        }

        .post-heading-space {

            h2 {
                a {
                    color: $color-gray-900;
                }
            }
        }
    }

