/*
=====================================
Communication section
=====================================
*/
.irantheme-communication-faq-section {
    .irantheme-communication-faq {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;

        // Contact wrapper
        .irantheme-communication-faq-post-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-communication-faq-list {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: center;
                row-gap: 1rem;

                &-item {
                    width: 100%;
                    // max-width: 60rem;
                    overflow: hidden;
                    // border-color: $color-gray-200;

                    &:last-child {
                        margin-bottom: 0;
                    }

                    &-question {
                        position: relative;
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        padding: 2rem;
                        cursor: pointer;
                        // background-color: $color-gray-200;
                        // color: $color-dark;
                        font-size: 1rem;
                        font-weight: normal;
                        @include transition(0.2s);

                        &-cite {
                            display: flex;
                            align-items: center;
                            font-style: normal;

                            i {
                                margin-left: 0.5rem;
                            }
                        }

                        &-icon {
                            display: flex;
                            align-items: center;

                            i {
                                font-size: 1.2rem;
                                @include transition(0.2s)
                            }
                        }

                    }

                    &-answer {
                        display: none;
                        font-size: 0.9rem;
                        padding: 2rem;
                        // background-color: $color-white;
                        // color: $color-gray-600;
                    }

                    &.active {
                        .irantheme-communication-faq-list-item-question {
                            .irantheme-communication-faq-list-item-question-icon {
                                i {
                                    @include transform(rotate(45deg));
                                }
                            }
                        }
                    }

                    // Transparent mode
                    &.irantheme-communication-faq-transparent-mode {
                        border-radius: 0 !important;
                        border-top: 0 !important;
                        border-right: 0 !important;
                        border-left: 0 !important;
                        box-shadow: none !important;

                        .irantheme-communication-faq-list-item-question {
                            background: transparent !important;
                            padding-right: 0 !important;
                            padding-left: 0 !important;
                        }

                        .irantheme-communication-faq-list-item-answer {
                            background: transparent !important;
                            padding-right: 0 !important;
                            padding-left: 0 !important;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Communication faq
            .irantheme-communication-faq-list {
                &-item {
                    @extend %box-shadow-white;

                    &-question {
                        color: $color-dark;
                    }

                    &-answer {
                        background-color: $color-white;
                        color: $color-gray-600;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Communication faq
            .irantheme-communication-faq-list {
                &-item {
                    @extend %box-shadow-dark;

                    &-question {
                        color: $color-white;
                    }

                    &-answer {
                        background-color: $color-dark;
                        color: $color-gray-400;
                    }
                }
            }
        }
    }
}