.irantheme-wc-checkout-order-result {
    .irantheme-myaccount-content-title {
        display: none;
    }

    .irantheme-wc-checkout-order-success-message {
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        padding: 2rem;
        gap: 1rem;

        &-icon {
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 3.5rem;
            color: #00A991;
        }

        &-title {
            font-size: 0.9rem;
            font-weight: 600;
        }

        &-desc {
            font-size: 0.9rem;
            color: $color-gray-700;
            display: flex;
            align-items: center;
            gap: 0.25rem;

            span {
                font-weight: 600;
                font-size: 0.85rem;
                color: #00A991;

                &.order-status.pending {
                    color: $color-quinary-hover;
                }

                &.order-status.cancelled {
                    color: $color-red-shine;
                }

                &.order-status.refunded {
                    color: $color-red-shine;
                }

                &.order-status.failed {
                    color: $color-red-shine;
                }
            }
        }

        &-meta {
            display: flex;
            align-items: center;
            justify-content: center;
            flex-wrap: wrap;
            width: 100%;
            gap: 4rem;
            padding: 0.5rem 0;

            .meta-item {
                display: flex;
                align-items: center;
                gap: 1.5rem;

                .meta-icon {
                    font-size: 1.1rem;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    width: 2.5rem;
                    aspect-ratio: 1/1;
                    background-color: $color-gray-200;
                    border-radius: $border-radius-medium;
                }

                .meta-text {
                    font-size: 0.7rem;
                    text-align: center;

                    &-value {
                        font-weight: 600;
                    }
                }
            }
        }

        &-btn {
            display: flex;
            align-items: center;
            justify-content: center;
            flex-wrap: wrap;
            gap: 1rem;
            padding: 1rem 0;

            .order-details {
                background-color: #00A991;
                border: 1px solid #00A991;
                color: $color-white;
                font-weight: 500;

                &:hover,
                &.active {
                    background-color: #008f79;
                    border: 1px solid #008f79;
                }
            }

            .invoice {
                background: transparent;
                border: 1px solid #00A991;
                color: #00A991;
                font-weight: 500;

                &:hover,
                &.active {
                    background-color: #00A991;
                    border-color: #00A991;
                    color: $color-white;
                }
            }
        }
    }

    .irantheme-wc-checkout-order-official-invoice-box {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 0 2rem 2rem;

        &-inner-wrapper {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            background: $color-gray-100;
            border-radius: $border-radius-medium;
            border: 1px dashed $color-gray-400;
            padding: 2rem;
            gap: 1rem;
            font-size: 0.8rem;
            text-align: center;
            min-width: 50%;
        }

        &-header {
            display: flex;
            flex-direction: column;
            justify-content: center;
            gap: 1rem;

            .invoice-title {
                font-size: 0.8rem;
                font-weight: 600;
                padding: 0;
                margin: 0;
                display: flex;
                align-items: center;
                justify-content: center;
                text-align: center;
                gap: 0.25rem;

                i {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    color: $color-quaternary-hover;
                    font-size: 1.2rem;
                    font-weight: 500;
                }
            }

            .invoice-status-wrapper {
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 0.5rem;
            }

            .invoice-status {
                padding: .4rem .8rem;
                border-radius: $border-radius-medium;
                font-size: .65rem;
                font-weight: 600;
                display: flex;
                align-items: center;
                gap: .25rem;
                width: fit-content;
                line-height: normal;
                background-color: rgba($color-gray-600, 0.1);
                color: $color-gray-600;

                &::before {
                    content: '';
                    width: 5px;
                    height: 5px;
                    display: inline-block;
                    border-radius: 50%;
                    background-color: $color-gray-600;
                }

                &.invoice-status-approved {
                    background-color: rgba($color-quaternary, 0.1);
                    color: $color-quaternary-hover;

                    &::before {
                        background-color: $color-quaternary-hover;

                    }
                }

                &.invoice-status-pending {
                    background-color: rgba($color-quinary, 0.1);
                    color: $color-quinary-hover;

                    &::before {
                        background-color: $color-quinary-hover;

                    }
                }

                &.invoice-status-rejected {
                    background-color: rgba($color-red-shine, 0.1);
                    color: $color-red-shine;

                    &::before {
                        background-color: $color-red-shine;

                    }
                }
            }

        }

        &-content {
            display: flex;
            align-items: center;
            justify-content: center;
            flex-direction: column;
            gap: .75rem;

            .invoice-desc {
                font-size: .8rem;
                color: $color-gray-700;
                text-align: center;
            }

            .invoice-actions {
                font-size: 1rem;

                .submit-request {
                    background-color: #00A991;
                    border: 1px solid #00A991;
                    color: $color-white;
                    font-weight: 500;

                    &:hover,
                    &.active {
                        background-color: #008f79;
                        border: 1px solid #008f79;
                    }
                }

                .invoice-official {
                    background-color: #00A991;
                    border: 1px solid #00A991;
                    color: $color-white;
                    font-weight: 500;

                    &:hover,
                    &.active {
                        background-color: #008f79;
                        border: 1px solid #008f79;
                    }
                }
            }

            .invoice-tip {
                display: flex;
                align-items: center;
                justify-content: center;
                text-align: center;
                gap: 0.25rem;
                background: $color-white;
                border-radius: $border-radius-medium;
                border: 1px solid $color-gray-200;
                padding: 0.5rem 1rem;
                font-size: .7rem;
                color: $color-gray-600;
                margin-top: 0.5rem;

                i {
                    font-size: .8rem;
                    color: $color-primary;
                }

                &.warning {
                    color: $color-quinary-hover;

                    i {
                        color: $color-quinary-hover;
                    }

                    a {
                        text-decoration: underline;
                        font-weight: 600;
                    }
                }
            }
        }
    }

    .irantheme-wc-checkout-order-failed-message {
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        padding: 2rem;

        &-icon {
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 3.5rem;
            color: $color-tertiary;
        }

        &-desc {
            padding: 1.5rem 0;
            font-size: 0.9rem;
            color: $color-gray-700;
        }

        &-actions {
            display: flex;
            align-items: center;

            .irantheme-btn {
                background-color: $color-gray-200;
                color: $color-gray-700;
                display: flex;
                align-items: center;

                &:hover {
                    background-color: $color-gray-300;
                }

                &.pay {
                    margin: 0 0.5rem;
                }

                &.account {
                    margin: 0 0.5rem;
                }
            }
        }
    }

    .irantheme-wc-order-overview {
        border-radius: $border-radius-low;
        background-color: $color-gray-100;
        color: $color-gray-700;
        font-size: 0.85rem;
        margin-bottom: 0.75rem !important;
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        padding-top: 1rem;
        padding-bottom: 0.5rem;

        &-item {

            &-text {
                width: 100%;
                display: flex;
                align-items: center;
                padding-top: 0.5rem;
                padding-bottom: 0.5rem;

                &-value {
                    flex-grow: 1;
                    flex-shrink: 1;
                    padding: 0 0.25rem;
                    line-height: normal;
                }
            }
        }
    }

    .irantheme-myaccount-order-details {
        // Title of inner sections

        .irantheme-myaccount-content-title {
            font-size: 1rem;
            color: $color-gray-700;
            padding-bottom: 1rem;
        }

        .wc-item-meta {
            li {
                display: flex;
                align-items: center;

                strong {
                    margin-left: 0.25rem;
                }
            }
        }
    }

    // Global style for all used table
    .irantheme-myaccount-orders-table {
        width: 100%;

        thead {
            background-color: $color-gray-100;
            border-radius: $border-radius-low;
            color: $color-gray-700;
            font-size: 0.9rem;

            &.irantheme-myaccount-orders-table-radius {
                th:first-child {
                    border-radius: 0 $border-radius-low $border-radius-low 0;
                }

                th:last-child {
                    border-radius: $border-radius-low 0 0 $border-radius-low;
                }

            }
        }

        tbody {
            color: $color-gray-600;
            font-size: 0.85rem;
        }

        tr {
            &:not(:last-child) {
                border-bottom: 1px solid $color-gray-200;
            }
        }

        td {
            padding: 0.75rem 1rem;

            .irantheme-myaccount-orders-action {
                display: flex;
                align-items: center;

                &-item {
                    padding: 0.15rem 0.6rem;
                    background-color: $color-gray-100;
                    border-radius: $border-radius-low;
                    margin-left: 0.5rem;
                    display: flex;
                    align-items: center;
                    flex-wrap: wrap;
                    color: $color-gray-600;
                    font-size: 0.85rem;
                    @include transition(0.2s);

                    &-download {
                        display: flex;

                        i {
                            margin-left: 0.25rem;
                        }
                    }

                    &:hover {
                        color: $color-dark;
                        background-color: $color-gray-200;
                    }

                    &::before {
                        font-size: 0.9rem;
                        font-weight: 300;
                        margin-left: 0.25rem;
                        font-family: $font-family-icons;
                        display: inline-block;
                    }

                    &.view {
                        &::before {
                            content: '\f07c';
                        }
                    }

                    &.pay {
                        &::before {
                            content: '\f09d';
                        }
                    }

                    &.cancel {
                        &::before {
                            content: '\e2ae';
                        }
                    }
                }
            }

            white-space: normal;
        }

        th {
            padding: 0.75rem 1rem;
            white-space: normal;
            font-weight: normal;
        }

        tfoot {
            font-size: 0.85rem;
            background-color: $color-gray-100;

            tr {
                border: none !important;
            }
        }

        .irantheme-woocommerce-order-status {
            padding: 0.15rem 0.6rem;
            display: flex;
            align-items: center;
            width: fit-content;
            white-space: nowrap;

            &::before {
                content: '';
                width: 5px;
                height: 5px;
                display: inline-block;
                border-radius: 50%;
                margin-left: 0.5rem;
            }

            &.order-failed {
                background-color: $color-tip-error-background;
                color: $color-tip-error-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-error-color;
                }
            }

            &.order-refunded {
                background-color: $color-tip-error-background;
                color: $color-tip-error-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-error-color;
                }
            }

            &.order-cancelled {
                background-color: $color-tip-error-background;
                color: $color-tip-error-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-error-color;
                }
            }

            &.order-on-hold {
                background-color: $color-tip-warning-background;
                color: $color-tip-warning-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-warning-color;

                }
            }

            &.order-pending {
                background-color: $color-tip-warning-background;
                color: $color-tip-warning-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-warning-color;

                }
            }

            &.order-processing {
                background-color: $color-tip-info-background;
                color: $color-tip-info-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-info-color;

                }
            }

            &.order-completed {
                background-color: $color-tip-success-background;
                color: $color-tip-success-color;
                border-radius: $border-radius-low;

                &::before {
                    background-color: $color-tip-success-color;

                }
            }
        }


    }
}