/*
=====================================
Slider Simple Section
=====================================
*/
.irantheme-slider-simple-section {
    background-color: transparent;

    .irantheme-slider-simple {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        // background-color: $color-gray-900;
        width: 100%;
        position: relative;
        text-align: center;
        overflow: hidden;

        &.irantheme-hero-fullscreen {
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;

            @media only screen and (max-width: 991px) {
                height: auto !important;
                // padding: 10rem 0;
            }
        }

        &.irantheme-bottom-edge-right {
            clip-path: polygon(0 0, 100% 0, 100% 90%, 0 100%);
        }

        &.irantheme-bottom-edge-left {
            clip-path: polygon(0 0, 100% 0, 100% 100%, 0 90%);
        }

        .irantheme-content-center {
            display: flex;
            justify-content: center;
            text-align: center;
            width: 100%;
        }

        .irantheme-content-right {
            display: flex;
            justify-content: flex-start;
            text-align: right;
        }

        .irantheme-content-left {
            display: flex;
            justify-content: flex-end;
            text-align: left;
        }

        .irantheme-showcase-typed-holder {
            display: block;

            .typed-cursor {
                display: inline-block;
                font-size: 2.4rem;
                margin-bottom: 1rem;
            }
        }

        // Small heading
        .irantheme-showcase-small-heading {
            font-weight: bold;
            font-size: 1rem;
            // color: $color-gray-100;
            margin-bottom: 0.5rem;
            display: block;
        }

        // Heading
        .irantheme-showcase-heading {
            font-size: 2.4rem;
            display: inline-block;
            // color: $color-white;
            margin-bottom: 1rem;
        }

        // Description
        .irantheme-showcase-description {
            font-size: 1.2rem;
            // color: $color-gray-200;
            margin-bottom: 1rem;
        }

        // Button scroll down
        .irantheme-showcase-button-scroll-down {
            position: absolute;
            right: 0;
            bottom: 0;
            width: 100%;
            padding: 2rem 1rem;
            z-index: 2;
            display: flex;
            justify-content: center;
            align-items: center;
            text-align: center;

            // Trigger
            &-trigger {
                width: 1.8rem;
                height: 2.6rem;
                background: transparent;
                // border: 2px solid $color-gray-300;
                border-radius: $border-radius-2;
                position: relative;

                // Spot
                &::after {
                    content: '';
                    width: 4px;
                    height: 4px;
                    border-radius: 50%;
                    // background: $color-gray-300;
                    position: absolute;
                    top: 50%;
                    right: 50%;
                    @include transform(translate(50%, calc(-50% - 0.5rem)));
                    @include transition(0.4s);
                }

                &:hover,
                &.active {
                    // border-color: $color-white;

                    &::after {
                        @include transform(translate(50%, calc(-50% + 0.5rem)));
                        // border-color: $color-white;
                    }
                }
            }
        }

        // Social media
        .irantheme-social-media {
            position: absolute;
            left: 0;
            bottom: 0;
            z-index: 3;

            .irantheme-social-media {
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: center;
                font-size: 0.9rem;
                padding: 1.5rem 0.5rem;

                li {
                    a {
                        // color: $color-gray-300;
                        display: block;
                        padding: 0 0.5rem;

                        svg {
                            width: 0.8rem;
                            height: 0.8rem;
                            // color: $color-gray-300;
                            // fill: $color-gray-300;
                            line-height: 0.8rem;
                            @include transition(0.2s);

                            path {
                                // fill: $color-gray-300;
                                @include transition(0.2s);
                            }
                        }

                        &:hover {
                            // color: $color-white;

                            svg,
                            path {
                                // fill: $color-white;
                            }
                        }
                    }
                }
            }
        }

        // Custom text link
        .irantheme-showcase-custom-text-link {
            position: absolute;
            right: 0;
            bottom: 0;
            z-index: 3;
            padding: 2rem 0 1rem;

            // Text link item
            &-item {
                // color: $color-gray-300;
                font-size: 0.8rem;
                text-orientation: mixed;
                writing-mode: vertical-rl;

                &:hover {
                    // color: $color-white;
                }
            }
        }

        .irantheme-swiper-section-slider-simple {
            width: 100%;
            height: inherit;
            position: relative;
            overflow: hidden;

            // Image
            &-image {
                overflow: hidden;

                &-link {
                    display: flex;
                    width: 100%;
                    height: 100%;
                }

                &-img {
                    width: 100%;
                    height: fit-content;
                    max-height: 100vh;
                    object-fit: cover;
                    object-position: center;
                }
            }

            // Content
            &-content {
                position: absolute;
                top: 0;
                right: 0;
                left: 0;
                height: 100%;
            }

            .irantheme-tinymce-content {
                *::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .irantheme-btn-group {
                *::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .irantheme-showcase-custom-text-link {
                *::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .swiper-wrapper {
                height: inherit;
            }

            .swiper-slide {
                text-align: center;
                font-size: 18px;
                background-color: #fff;
                width: 100% !important;
                height: inherit;
                display: flex;
                overflow: hidden;

                &::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .irantheme-showcase-simple-section {
                height: inherit;
                width: 100%;
                display: flex;

                .irantheme-showcase-simple {
                    height: inherit;
                    width: 100%;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Small heading
            .irantheme-showcase-small-heading {
                color: $color-dark;
            }

            // Heading
            .irantheme-showcase-heading {
                color: $color-gray-800;
            }

            // Description
            .irantheme-showcase-description {
                color: $color-gray-700;
            }

            // Button scroll down
            .irantheme-showcase-button-scroll-down {

                // Trigger
                &-trigger {
                    border: 2px solid $color-gray-700;

                    // Spot
                    &::after {
                        content: '';
                        background: $color-gray-700;
                    }

                    &:hover,
                    &.active {
                        border-color: $color-dark;

                        &::after {
                            border-color: $color-dark;
                        }
                    }
                }
            }

            // Social media
            .irantheme-showcase-social-media {

                .irantheme-social-media {

                    li {
                        a {
                            color: $color-gray-700;

                            svg {
                                color: $color-gray-700;
                                fill: $color-gray-700;

                                path {
                                    fill: $color-gray-700;
                                }
                            }

                            &:hover {
                                color: $color-dark;

                                svg,
                                path {
                                    fill: $color-dark;
                                }
                            }
                        }
                    }
                }
            }

            // Custom text link
            .irantheme-showcase-custom-text-link {

                // Text link item
                &-item {
                    color: $color-gray-700;

                    &:hover {
                        color: $color-dark;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Small heading
            .irantheme-showcase-small-heading {
                color: $color-white;
            }

            // Heading
            .irantheme-showcase-heading {
                color: $color-gray-200;
            }

            // Description
            .irantheme-showcase-description {
                color: $color-gray-300;
            }

            // Button scroll down
            .irantheme-showcase-button-scroll-down {

                // Trigger
                &-trigger {
                    border: 2px solid $color-gray-300;

                    // Spot
                    &::after {
                        content: '';
                        background: $color-gray-300;
                    }

                    &:hover,
                    &.active {
                        border-color: $color-white;

                        &::after {
                            border-color: $color-white;
                        }
                    }
                }
            }

            // Social media
            .irantheme-showcase-social-media {

                .irantheme-social-media {

                    li {
                        a {
                            color: $color-gray-300;

                            svg {
                                color: $color-gray-300;
                                fill: $color-gray-300;

                                path {
                                    fill: $color-gray-300;
                                }
                            }

                            &:hover {
                                color: $color-white;

                                svg,
                                path {
                                    fill: $color-white;
                                }
                            }
                        }
                    }
                }
            }

            // Custom text link
            .irantheme-showcase-custom-text-link {

                // Text link item
                &-item {
                    color: $color-gray-300;

                    &:hover {
                        color: $color-white;
                    }
                }
            }
        }
    }
}