/*
=====================================
Business Brands post
=====================================
*/
.irantheme-business-brands-section {
    .irantheme-business-brands {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Brands
        .irantheme-business-brands-post-wrapper {

            .irantheme-business-brands-post-item {
                padding: 1rem 0;
                text-align: center;

                &-anchor {
                    display: inline-block;
                }

                &-image-src {
                    max-width: 100%;
                    opacity: 0.75;
                    object-fit: contain;
                    @include transition(0.2s);

                    &:hover {
                        opacity: 1;
                    }
                }
            }
        }

        &.irantheme-gradient-animation {
            animation: gradient-animation ease infinite;
        }

        @keyframes gradient-animation {
            0% {
                background-position: 0% 50%;
            }

            50% {
                background-position: 100% 50%;
            }

            100% {
                background-position: 0% 50%;
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Brands
            .irantheme-business-brands-post-wrapper {
                .irantheme-business-brands-post-item {
                    &-image-src {
                        filter: invert(0);
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Brands
            .irantheme-business-brands-post-wrapper {
                .irantheme-business-brands-post-item {
                    &-image-src {
                        filter: invert(1);
                    }
                }
            }
        }
    }
}