/*
=====================================
Logo brand
=====================================
*/
// Logo brand
.irantheme-logo-brand {
    display: flex;
    align-items: center;

    // Logo text holder
    .irantheme-logo-text-holder {
        display: inline-block;

        // Logo text (Self)
        .irantheme-logo-text {
            position: relative;
            // color: inherit;

            // After
            &::after {
                content: '';
                position: absolute;
                top: 50%;
                left: -0.5rem;
                width: 5px;
                height: 5px;
                border-radius: 50%;
                // background: inherit;
            }

            &:hover {
                // color: inherit;
            }
        }
    }

    // Logo image holder
    .irantheme-logo-img-holder {
        display: flex;

        // Logo img
        .irantheme-logo-img {
            height: 100% !important;
            width: auto;
        }
    }

    // Logo svg holder
    .irantheme-logo-svg-holder {
        display: flex;

        svg {
            height: 100% !important;
            width: auto;
            // color: inherit;

            * {
                // fill: inherit;
            }
        }
    }

    .irantheme-logo-mobile {
        display: none;
    }

    @media only screen and (max-width: 1199px) {
        .irantheme-logo-svg-holder.irantheme-has-logo-mobile {
            display: none !important;
        }

        .irantheme-logo-mobile {
            display: flex;
        }
    }

    @media only screen and (max-width: 1199px) {
        .irantheme-logo-img-holder.irantheme-has-logo-mobile {
            display: none !important;
        }

        .irantheme-logo-mobile {
            display: flex;
        }
    }
}

.irantheme-header-main {

    // White mode ==========
    &.irantheme-header-white,
    &.irantheme-header-white-important {
        background-color: $color-white;

        // Logo
        .irantheme-logo-brand {

            // Text logo
            .irantheme-logo-text-holder {
                .irantheme-logo-text {
                    color: $color-dark;

                    // After logo text
                    &::after {
                        background-color: $color-primary;
                    }

                    &:hover {
                        color: $color-gray-700;
                    }
                }
            }

            // Svg logo
            .irantheme-logo-svg-holder,
            .irantheme-logo-mobile-svg-holder {
                svg {
                    color: $color-dark;

                    * {
                        fill: $color-dark;
                    }
                }
            }

            // For alt img
            .irantheme-logo-img-holder {
                color: $color-dark;
            }
        }
    }

    // Dark mode ==========
    &.irantheme-header-dark,
    &.irantheme-header-dark-important {

        // Logo
        .irantheme-logo-brand {

            // Text logo
            .irantheme-logo-text-holder {
                .irantheme-logo-text {
                    color: $color-white;

                    // After logo text
                    &::after {
                        background-color: $color-primary;
                    }

                    &:hover {
                        color: $color-gray-300;
                    }
                }
            }

            // Svg logo
            .irantheme-logo-svg-holder,
            .irantheme-logo-mobile-svg-holder {
                svg {
                    color: $color-white;

                    * {
                        fill: $color-white;
                    }
                }
            }

            // For alt img
            .irantheme-logo-img-holder {
                color: $color-white;
            }
        }
    }
}