.irantheme-woocommerce-box-categories-section {

    .irantheme-woocommerce-box-categories {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        &-wrapper {
            position: relative;
            padding: 1rem 0;
            z-index: 2;
        }

        .row {
            row-gap: 2rem;
        }

        // Columns
        .irantheme-woocommerce-box-categories-col {
            @include transition(0.2s);

            &:hover {
                box-shadow: none !important;
            }

            // Set box style
            &.irantheme-woocommerce-box-categories-box-style-border {
                padding: 0.75rem;
            }

            // Set box style
            &.irantheme-woocommerce-box-categories-box-style-shadow {
                padding: 0.75rem;
            }
        }

        // Item
        &-item {
            height: auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            column-gap: 1rem;
            width: 100%;

            &-image {
                position: relative;
                overflow: hidden;

                &-img {
                    width: 100%;
                    height: auto;
                    aspect-ratio: 1 / 1;
                    object-fit: cover;
                    max-width: 3.5rem;
                    max-height: 3.5rem;
                }

                &.irantheme-woocommerce-category-image-radius {
                    .irantheme-woocommerce-box-categories-item-image-img {
                        border-radius: 50%;
                    }
                }
            }

            // Heading
            &-heading {
                display: flex;
                flex-direction: column;
                justify-content: center;
                width: fit-content;

                // Title
                &-title {
                    font-size: 0.8rem;
                    // color: $color-gray-700;
                    margin-bottom: 0.25rem;
                    display: -webkit-box;
                    -webkit-line-clamp: 1;
                    -webkit-box-orient: vertical;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    font-weight: bold;

                    &-product-count {
                        // color: $color-gray-600;
                        margin-right: 0.25rem;
                        font-size: 0.6rem;
                    }
                }

                // Description
                &-desc {
                    font-size: 0.6rem;
                    display: -webkit-box;
                    -webkit-line-clamp: 1;
                    -webkit-box-orient: vertical;
                    overflow: hidden;
                    text-overflow: ellipsis;
                }

                // Product count
                &-product-count {
                    // color: $color-gray-600;
                    font-size: 0.6rem;
                    cursor: default;

                    &-number {
                        // color: $color-gray-600;
                    }

                    &-title {
                        font-style: normal;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            &-wrapper {}

            .irantheme-woocommerce-box-categories-col {
                background: $color-white;

                // Set box style
                &.irantheme-woocommerce-box-categories-box-style-border {
                    border: 1px solid $color-gray-100;
                }

                // Set box style
                &.irantheme-woocommerce-box-categories-box-style-shadow {
                    @extend %box-shadow-white;
                }
            }

            // Item
            .irantheme-woocommerce-box-categories-item {

                // Image
                &-image {
                    // background: $color-gray-200;
                    background: transparent;
                }

                // Heading
                &-heading {

                    // Title
                    &-title {
                        a {
                            color: $color-gray-900;
                        }

                        &-product-count {
                            color: $color-gray-500;
                        }
                    }

                    // Description
                    &-desc {
                        color: $color-gray-600;
                    }

                    // Product count
                    &-product-count {
                        color: $color-gray-500;

                        &-number {
                            color: $color-gray-500;
                        }

                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            &-wrapper {}

            .irantheme-woocommerce-box-categories-col {
                background: $color-dark;

                // Set box style
                &.irantheme-woocommerce-box-categories-box-style-border {
                    border: 1px solid $color-gray-900;
                }

                // Set box style
                &.irantheme-woocommerce-box-categories-box-style-shadow {
                    @extend %box-shadow-dark;
                }
            }

            // Item
            .irantheme-woocommerce-box-categories-item {

                // Image
                &-image {
                    // background: $color-gray-800;
                    background: transparent;
                }

                // Heading
                &-heading {

                    // Title
                    &-title {

                        a {
                            color: $color-gray-100;
                        }

                        &-product-count {
                            color: $color-gray-500;
                        }
                    }

                    // Description
                    &-desc {
                        color: $color-gray-400;
                    }

                    // Product count
                    &-product-count {
                        color: $color-gray-500;

                        &-number {
                            color: $color-gray-500;
                        }

                    }
                }
            }
        }
    }
}