.irantheme-wc-archive {
    padding: 1.5rem 0;

    .irantheme-pagination-holder {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 100%;

        .irantheme-wc-archive-ajax-pagination {
            .page-numbers {
                cursor: pointer;
            }

            .page-dots {
                background-color: transparent;
                background-color: transparent;
                font-size: 1.2rem;
                line-height: 0;
                padding-top: 0;
            }
        }
    }

    .irantheme-wc-archive-top-bar {
        display: flex;
        align-items: center;
        justify-content: flex-end;
        flex-wrap: wrap;
        width: 100%;
        padding-bottom: 0.75rem;
        line-height: normal;

        &-item {
            font-size: 0.8rem;

            &-title {
                display: flex;
                align-items: center;
                @include transition(0.2s);
                cursor: pointer;
                padding: 0.5rem 0.75rem;

                i {
                    line-height: normal;
                    margin-left: 0.3rem;
                }
            }


        }

        .irantheme-woocommerce-filter-clear {
            display: none;

            &.active {
                display: flex;
            }

            align-items: center;

            &::after {
                content: '';
                display: flex;
                width: 1px;
                height: 1rem;
                background-color: $color-gray-500;
            }
        }

        .irantheme-woocommerce-result-count-wrapper {
            // color: $color-gray-600;

            .irantheme-woocommerce-result-count {
                .result-count-presentable {
                    em {
                        font-style: normal;
                    }

                    &-from {
                        // padding-left: 0.25rem;
                        padding-right: 0.25rem;
                    }

                    &-to {
                        padding-left: 0.25rem;
                        // padding-right: 0.25rem;
                    }
                }

                .result-count-total {
                    padding-left: 0.25rem;
                    padding-right: 0.25rem;
                }
            }

            .irantheme-wc-archive-top-bar-item-title {
                cursor: default;
            }
        }

        .irantheme-woocommerce-ordering-wrapper {
            position: relative;

            &:hover {
                .irantheme-woocommerce-ordering-list {
                    display: block;
                }
            }

            &.active {
                .irantheme-woocommerce-ordering-title {
                    // color: $color-gray-600;
                }
            }

            .irantheme-woocommerce-ordering-list {
                min-width: 200px;
                // box-shadow: 0 70px 140px rgba(0, 0, 0, 0.2);
                position: absolute;
                z-index: 9999;
                display: none;
                font-size: 0.8rem;
                padding: 1rem 0;
                @include transition(0.2s);
                // background-color: $color-white;
                left: 0;

                &-item {
                    position: relative;
                    // color: $color-gray-600;
                    padding: 0.75rem 2rem;
                    white-space: nowrap;
                    cursor: pointer;
                    @include transition(0.2s);

                    &:hover {
                        // color: $color-gray-800;
                        // background-color: $color-gray-100;
                    }

                    &.active::before {
                        content: '\f00c';
                        font-family: $font-family-icons;
                        font-weight: 900;
                        position: absolute;
                        right: 16px;
                        top: 15px;
                    }
                }
            }

            .irantheme-woocommerce-ordering-form {
                .irantheme-woocommerce-ordering-select {
                    display: none;
                    visibility: hidden;
                    opacity: 0;
                }
            }
        }
    }

    &.irantheme-wc-archive-show-filtering {
        .irantheme-wc-archive-show-filter {
            display: none;
        }

        .irantheme-wc-archive-hide-filter {
            display: flex;
        }
    }

    &.irantheme-wc-archive-hide-filtering {
        .irantheme-wc-archive-show-filter {
            display: flex;
        }

        .irantheme-wc-archive-hide-filter {
            display: none;
        }

        .irantheme-wc-archive-filter-col {
            min-width: 0 !important;
            padding: 0 !important;
            opacity: 0;
            width: 0;
        }

        .irantheme-wc-archive-product-col {
            width: 100%;
        }
    }

    .irantheme-wc-archive-filter-col {
        transition: opacity 0.4s cubic-bezier(.35, .81, .41, 1), min-width 0.4s cubic-bezier(.35, .81, .41, 1), width 0.4s cubic-bezier(.35, .81, .41, 1),
            padding 0.4s cubic-bezier(.35, .81, .41, 1);

        .irantheme-wc-archive-filter {
            padding-top: 0.75rem;
            margin-left: 1rem;

            .irantheme-wc-archive-filter-box {
                margin-bottom: 1rem;

                &-label {
                    position: relative;
                    font-size: 0.9rem;
                    // padding: 0.5rem 0;
                }

                .irantheme-wc-archive-filter-category-wrapper {
                    &:not(:last-child) {
                        margin-bottom: 1rem;
                    }
                }

                &-content {
                    padding-top: 0.5rem;
                    padding-bottom: 0.5rem;
                    // color: $color-gray-800;

                    .irantheme-wc-archive-filter-category-children-wrapper {

                        padding-right: 0.5rem;
                        margin-right: 9px;
                        border-right: 1px solid $color-gray-200;
                        display: none;
                    }

                    &.irantheme-wc-archive-filter-box-content-checkbox {
                        .irantheme-wc-archive-filter-content-label {
                            display: flex;
                            align-items: center;
                            line-height: normal;
                            cursor: pointer;

                            &::selection {
                                background-color: transparent;
                                color: inherit
                            }

                            &:not(:last-child) {
                                margin-bottom: 1rem;
                            }

                            &:hover {
                                a.irantheme-wc-archive-filter-content-label-text {
                                    // color: $color-gray-600;

                                    em.irantheme-wc-archive-filter-content-label-count {
                                        // color: $color-gray-600;
                                    }
                                }
                            }

                            em.irantheme-wc-archive-filter-content-label-color {
                                margin-right: auto;
                                width: 15px;
                                height: 15px;
                                display: flex;
                                border-width: 1px;
                                border-style: solid;
                                border-radius: 50%;
                            }
                        }

                        a.irantheme-wc-archive-filter-content-label-text {
                            margin-right: 0.5rem;
                            font-size: 0.8rem;
                            @include transition(0.2s);
                            display: flex;
                            align-items: center;
                            justify-content: space-between;
                            width: calc(100% - 20px);

                            &::selection {
                                background-color: transparent;
                                color: inherit
                            }

                        }

                        em.irantheme-wc-archive-filter-content-label-count {
                            @include transition(0.2s);
                            font-size: 0.7rem;
                            margin-right: 0.5rem;
                            border-radius: $border-radius-low;

                            &::selection {
                                background-color: transparent;
                                color: inherit
                            }
                        }

                        em.irantheme-wc-archive-filter-content-label-toggler {
                            @include transition(0.2s);
                            font-size: 0.9rem;
                            margin: 0;
                            padding: 0;

                            i {
                                margin: 0;
                            }
                        }

                        em {
                            font-style: normal;
                            padding: 0 0.3rem;
                            // color: $color-gray-700;
                        }

                        input[type=checkbox] {
                            appearance: none;
                            // background-color: $color-white;
                            width: 20px;
                            height: 20px;
                            border-width: 1px;
                            border-style: solid;
                            border-radius: $border-radius-low;
                            display: inline-grid;
                            place-content: center;
                            cursor: pointer;
                        }

                        input[type=checkbox]::before {
                            content: "";
                            width: 10px;
                            height: 10px;
                            transform: scale(0);
                            transform-origin: bottom left;
                            // background-color: $color-gray-700;
                            clip-path: polygon(13% 50%, 34% 66%, 81% 2%, 100% 18%, 39% 100%, 0 71%);
                        }

                        input[type=checkbox]:checked::before {
                            transform: scale(1);
                        }

                        input[type=checkbox]:checked {
                            // background-color: $color-white;
                            border-radius: $border-radius-little;
                        }
                    }
                }
            }

            .irantheme-wc-archive-filter-search {
                margin-bottom: 1rem;

                .irantheme-wc-archive-search-wrapper {
                    display: flex;
                    align-items: center;
                    flex-wrap: nowrap;
                    border-width: 1px;
                    border-style: solid;
                    // border-color: $color-gray-300;
                    border-radius: $border-radius-low;
                    @include transition(0.2s);


                    input {
                        border: none !important;
                    }

                    span {
                        padding: 0.75rem 1rem;
                        font-size: 1rem;
                        color: $color-gray-500;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        @include transition(0.2s);
                        cursor: pointer;
                    }
                }
            }

            .irantheme-price-input-holder {
                display: flex;
                flex-direction: column;
                position: relative;

                .irantheme-price-filter-input-holder {
                    display: flex;
                    align-items: center;
                    font-size: 0.9rem;
                    padding-left: 0.6rem;
                    padding-right: 0.6rem;

                    .irantheme-price-filter-input {
                        margin: 0.5rem 0.65rem;
                        padding: 0.35rem;
                        font-size: 0.8rem;
                        text-align: left;
                        width: 100%;

                        /* Chrome, Safari, Edge, Opera */
                        &::-webkit-outer-spin-button,
                        &::-webkit-inner-spin-button {
                            -webkit-appearance: none;
                            margin: 0;
                        }

                        /* Firefox */
                        &[type=number] {
                            -moz-appearance: textfield;
                        }
                    }

                    svg {
                        width: 22px;
                        height: 22px;

                        &#currency-rial {
                            width: 25px;
                            height: 25px;
                            stroke-width: 0.8;
                        }
                    }
                }
            }

            .irantheme-price-range-holder {
                margin-top: 1.5rem;
                padding: 0 0.5rem;

                .irantheme-price-range {
                    --_marker-size: 12px;
                    --_track-heigt: 2px;
                    width: 100%;
                    max-width: 600px;
                    display: flex;
                    flex-direction: column;
                }

                .irantheme-price-range-sliders-control {
                    position: relative;
                    z-index: 999;
                }

                input[type=range]::-webkit-slider-thumb {
                    -webkit-appearance: none;
                    pointer-events: all;
                    width: var(--_marker-size);
                    height: var(--_marker-size);
                    // background-color: $color-gray-900;
                    border-radius: 50%;
                    // box-shadow: 0 0 0 1px $color-gray-900;
                    cursor: pointer;
                }

                input[type=range]::-moz-range-thumb {
                    -webkit-appearance: none;
                    pointer-events: all;
                    width: var(--_marker-size);
                    height: var(--_marker-size);
                    // background-color: $color-gray-900;
                    border-radius: 50%;
                    // box-shadow: 0 0 0 1px $color-gray-900;
                    cursor: pointer;
                }

                input[type=range]::-webkit-slider-thumb:hover {
                    // background: #f7f7f7;
                }

                input[type=range]::-webkit-slider-thumb:active {
                    // box-shadow: inset 0 0 3px #2a2e33, 0 0 9px #2a2e33;
                    // -webkit-box-shadow: inset 0 0 3px #2a2e33, 0 0 9px #2a2e33;
                }

                input[type="range"] {
                    -webkit-appearance: none;
                    appearance: none;
                    height: var(--_track-heigt);
                    width: 100%;
                    position: absolute;
                    // background-color: $color-gray-900;
                    pointer-events: none;
                    direction: ltr;
                }

                #fromSliderRangeInput {
                    height: 0;
                    z-index: 1;
                }

                .scale {
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    width: 100%;
                    position: relative;
                    padding-top: 1rem;
                    font-size: 0.8rem;
                    // color: $color-gray-600;

                    &::after {
                        position: absolute;
                        width: 2px;
                        height: 6px;
                        // background-color: $color-gray-400;
                        top: 0.6rem;
                        left: 6px;
                        z-index: 99;
                        content: '';
                    }

                    &::before {
                        position: absolute;
                        width: 2px;
                        height: 6px;
                        // background-color: $color-gray-400;
                        top: 0.7rem;
                        right: 6px;
                        z-index: 99;
                        content: '';
                    }

                    &-end {
                        display: flex;
                    }

                    &-start {
                        display: flex;
                    }
                }
            }
        }
    }

    .irantheme-wc-archive-product-col {
        position: relative;
        transition: width 0.4s cubic-bezier(.35, .81, .41, 1);
        min-height: 20rem;

        /*
        =====================================
        Ajax error
        =====================================
        */
        .irantheme-wc-archive-ajax-error {
            padding: 4rem .5rem;
            text-align: center;
            display: none;
            align-items: center;
            flex-direction: column;

            i {
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.6rem;
                border-radius: $border-radius-medium;
                width: 3.5rem;
                height: 3.5rem;
            }

            &-title {
                font-size: 1.1rem;
                margin-top: 2rem;
            }

            &-desc {
                font-size: .9rem;
                margin-top: 0.7rem;
                direction: ltr;
            }
        }

        .irantheme-wc-archive-products {


            .irantheme-woocommerce-products-section {
                .irantheme-woocommerce-products {
                    &.white {
                        background-color: transparent;
                    }

