                                grid-template-columns: repeat(3, 1fr);
                            }

                            &.irantheme-wc-archive-grid-five-col {
                                grid-template-columns: repeat(3, 1fr);
                            }

                            &.irantheme-wc-archive-grid-six-col {
                                grid-template-columns: repeat(3, 1fr);
                            }

                            &.irantheme-wc-archive-grid-seven-col {
                                grid-template-columns: repeat(3, 1fr);
                            }

                            &.irantheme-wc-archive-grid-eight-col {
                                grid-template-columns: repeat(3, 1fr);
                            }
