                        @media (max-width: 324.98px) {
                            &.irantheme-wc-archive-grid-two-col {
                                grid-template-columns: 1fr;
                            }

                            &.irantheme-wc-archive-grid-three-col {
                                grid-template-columns: 1fr;
                            }

                            &.irantheme-wc-archive-grid-four-col {
