                }

                /*
                =====================================
                Search result not found
                =====================================
                */

                .irantheme-search-results-not-found,
                .irantheme-product-not-found {
                    padding: 8rem .5rem;
                    text-align: center;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    flex-direction: column;

                    i {
                        display: flex;
