    /*
    =====================================
    Cart woocommerce
    =====================================
    */

    // Navigation
    .irantheme-woocommerce-filter-navigation {
        position: fixed;
        top: 0;
        left: 0;
        width: 400px;
        max-width: 100%;
        height: 100vh;
        max-height: 100vh;
        z-index: 99999999;
        background: $color-white;
        display: flex;
        flex-direction: column;
        @include transition(0.4s, transform, cubic-bezier(0.215, 0.61, 0.355, 1));
        @include transform(translateX(-100%));

        &.active {
            transition-delay: 0.6s;
            transform: translateX(0) !important;
        }

        // Header
        &-header {
            width: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;

            // Close nav
            &-close {
                color: $color-gray-600;
                display: flex;
                align-items: center;
                justify-content: center;
                text-align: center;
                @include transition(0.2s);
                padding: 2.5rem 0;

                i {
                    font-size: 1.2rem;
                }
            }

            hr {
                border-top: 1px solid $color-gray-200;
                width: 100%;
                margin: 0;
                opacity: 1;
            }
        }

        // Wrapper
        &-wrapper {
            width: 100%;
            height: 100%;
            overflow-y: auto;
            overflow-x: hidden;
            padding-bottom: 1rem;
            padding-top: 0.5rem;
            display: flex;
            flex-direction: column;
            position: relative;

            .irantheme-wc-archive-filter-search {
                margin-bottom: 1rem;

                .irantheme-wc-archive-search-wrapper {
                    display: flex;
                    align-items: center;
                    flex-wrap: nowrap;
                    border-width: 1px;
                    border-style: solid;
                    // border-color: $color-gray-300;
                    border-radius: $border-radius-low;
                    @include transition(0.2s);


                    input {
                        border: none !important;
                    }

                    span {
                        padding: 0.75rem 1rem;
                        font-size: 1rem;
                        color: $color-gray-500;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        @include transition(0.2s);
                        cursor: pointer;
                    }
                }
            }

            .irantheme-wc-archive-filter {

                &.irantheme-wc-archive-filter-navigation {
                    overflow-y: auto;
                }

                .irantheme-wc-archive-filter-box {
                    margin-bottom: 0 !important;

                    &-label {
                        position: relative;
                        font-size: 0.9rem;
                    }

                    &-content {
                        // color: $color-gray-800;

                        .irantheme-wc-archive-filter-category-children-wrapper {

                            padding-right: 0.5rem;
                            margin-right: 9px;
                            border-right: 1px solid $color-gray-200;
                            display: none;
                        }

                        &.irantheme-wc-archive-filter-box-content-checkbox {
                            .irantheme-wc-archive-filter-content-label {
                                display: flex;
                                align-items: center;
                                margin-bottom: 1rem;
                                line-height: normal;
                                cursor: pointer;

                                &:hover {
                                    a.irantheme-wc-archive-filter-content-label-text {
                                        // color: $color-gray-600;

                                        em.irantheme-wc-archive-filter-content-label-count {
                                            // color: $color-gray-600;
                                        }
                                    }
                                }

                                em.irantheme-wc-archive-filter-content-label-color {
                                    margin-right: auto;
                                    width: 15px;
                                    height: 15px;
                                    display: flex;
                                    border-width: 1px;
                                    border-style: solid;
                                    border-radius: 50%;
                                }

                                em.irantheme-wc-archive-filter-content-label-toggler {
                                    @include transition(0.2s);
                                    font-size: 0.9rem;
                                    margin: 0;
                                    padding: 0;

