                }

                .irantheme-price-input-holder {
                    display: flex;
                    flex-direction: column;
                    position: relative;

                    .irantheme-price-filter-input-holder {
                        display: flex;
                        align-items: center;
                        font-size: 0.9rem;
                        padding-left: 0.6rem;
                        padding-right: 0.6rem;

                        .irantheme-price-filter-input {
                            margin: 0.5rem 1rem;
                            padding: 0.35rem;
                            font-size: 0.8rem;
                            text-align: left;
                            width: 100%;

