                        --_track-heigt: 2px;
                        width: 100%;
                        max-width: 600px;
                        display: flex;
                        flex-direction: column;
                    }

                    .irantheme-price-range-sliders-control {
                        position: relative;
                        z-index: 999;
                    }

                    input[type=range]::-webkit-slider-thumb {
                        -webkit-appearance: none;
                        pointer-events: all;
                        width: var(--_marker-size);
                        height: var(--_marker-size);
                        // background-color: $color-gray-900;
                        border-radius: 50%;
                        // box-shadow: 0 0 0 1px $color-gray-900;
                        cursor: pointer;
                    }

                    input[type=range]::-moz-range-thumb {
                        -webkit-appearance: none;
                        pointer-events: all;
                        width: var(--_marker-size);
                        height: var(--_marker-size);
                        // background-color: $color-gray-900;
                        border-radius: 50%;
                        // box-shadow: 0 0 0 1px $color-gray-900;
                        cursor: pointer;
                    }

                    input[type=range]::-webkit-slider-thumb:hover {
                        // background: #f7f7f7;
                    }

                    input[type=range]::-webkit-slider-thumb:active {
                        // box-shadow: inset 0 0 3px #2a2e33, 0 0 9px #2a2e33;
                        // -webkit-box-shadow: inset 0 0 3px #2a2e33, 0 0 9px #2a2e33;
                    }

                    input[type="range"] {
                        -webkit-appearance: none;
                        appearance: none;
                        height: var(--_track-heigt);
                        width: 100%;
                        position: absolute;
                        // background-color: $color-gray-900;
                        pointer-events: none;
                        direction: ltr;
                    }

                    #fromSliderRangeInput {
                        height: 0;
                        z-index: 1;
                    }

                    .scale {
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        width: 100%;
                        position: relative;
                        padding-top: 1rem;
                        font-size: 0.8rem;
                        // color: $color-gray-600;

                        &::after {
                            position: absolute;
                            width: 2px;
                            height: 6px;
                            // background-color: $color-gray-400;
                            top: 0.6rem;
                            left: 6px;
                            z-index: 99;
                            content: '';
                        }

                        &::before {
                            position: absolute;
                            width: 2px;
                            height: 6px;
                            // background-color: $color-gray-400;
                            top: 0.7rem;
                            right: 6px;
                            z-index: 99;
                            content: '';
                        }

                        &-end {
                            display: flex;
                        }

                        &-start {
                            display: flex;
                        }
                    }
                }
            }
        }

        // Footer
        &-footer {
            margin-top: auto;
            padding: 1rem 1rem 0 1rem;
            display: flex;
            flex-direction: column;

            // View filter
            &-clear {
                display: flex;
                justify-content: center;
                align-items: center;
                font-weight: bold;
                font-size: 0.8rem;
