/*
=====================================
Footer copyright section
=====================================
*/
.irantheme-footer-copyright-section {
    // background: $color-dark;



    // Copyright
    .irantheme-footer-copyright {
        display: flex;
        // background: $color-gray-900;
        padding: 1rem 0;
        position: relative;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;

        .irantheme-footer-copyright-wrapper {
            display: flex;
            flex-direction: column;
            gap: 1rem;
            position: relative;
            z-index: 9;

            // Social media
            .irantheme-footer-copyright-social-media {
                display: flex;

                .irantheme-social-media {
                    display: flex;
                    flex-direction: row;
                    column-gap: 1rem;

                    li {
                        a {
                            font-size: 0.8rem;
                            display: flex;
                            column-gap: 0.5rem;
                            align-items: center;
                            justify-content: center;
                            padding: 0.5rem 1rem;
                            border-radius: $border-radius-medium;

                            svg,
                            path {
                                width: 1.2rem;
                                height: 1.2rem;
                                position: relative;
                                top: -2px;
                                transition: inherit;
                            }

                            i {
                                font-size: 1.2rem;
                            }
                        }
                    }
                }
            }

            .irantheme-footer-copyright-text {
                display: flex;
                flex-direction: column;
                // color: $color-gray-500;
                font-size: 0.8rem;
                margin-bottom: 0;
            }
        }
    }

    /*
        =====================================
        White
        =====================================
        */
    &.white {

        // Copyright
        .irantheme-footer-copyright {
            background-color: $color-gray-100;

            // Social media
            .irantheme-footer-copyright-social-media {
                .irantheme-social-media {
                    li {
                        a {
                            background: $color-gray-200;
                            color: $color-dark;

                            svg,
                            path {
                                color: $color-dark;
                                fill: $color-dark;
                            }

                            &:hover {
                                background: transparent;
                                color: $color-gray-800;

                                svg,
                                path {
                                    color: $color-gray-800;
                                    fill: $color-gray-800;
                                }
                            }
                        }
                    }
                }
            }

            .irantheme-footer-copyright-copyright-text {
                color: $color-gray-600;
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {

        // Copyright
        .irantheme-footer-copyright {
            background-color: $color-gray-900;

            // Social media
            .irantheme-footer-copyright-social-media {
                .irantheme-social-media {
                    li {
                        a {
                            color: $color-white;
                            background: $color-gray-800;

                            svg,
                            path {
                                color: $color-white;
                                fill: $color-white;
                            }

                            &:hover {
                                background: transparent;
                                color: $color-gray-200;

                                svg,
                                path {
                                    color: $color-gray-200;
                                    fill: $color-gray-200;
                                }
                            }
                        }
                    }
                }
            }

            .irantheme-footer-copyright-text {
                color: $color-gray-400;
            }
        }
    }
}