/* Header ###############################3 */

#header-luxurious {
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
    background-attachment: fixed;
    background-color: $color-dark;
    position: relative;
}

/* Hero */

#header-luxurious .hero {
    position: relative;
    z-index: 2;
}

/* Showcase */

#header-luxurious .showcase {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-orient: vertical;
    -webkit-box-direction: normal;
    -ms-flex-direction: column;
    flex-direction: column;
    -webkit-box-pack: center;
    -ms-flex-pack: center;
    justify-content: center;
    text-align: center;
    padding: 8rem 0 6rem;
}

/* Heading */

#header-luxurious .showcase .heading {
    margin-bottom: 1rem;
}

#header-luxurious .showcase .heading h1 {
    font-size: 2rem;
    color: $color-gray-300;
    margin-bottom: 1.6rem;
    line-height: 2.8rem;
}

#header-luxurious .showcase .heading p {
    color: $color-gray-400;
    font-size: 1rem;
    line-height: 1.4;
}

/* Social networks */

#header-luxurious .showcase .irantheme-social-media {
    margin-bottom: 1rem;
}

#header-luxurious .showcase .irantheme-social-media li {
    display: inline-block;
    margin: 0.5rem;
}

#header-luxurious .showcase .irantheme-social-media li a {
    color: $color-gray-300;
    font-size: 0.9rem;
    position: relative;
}

#header-luxurious .showcase .irantheme-social-media li a svg,
#header-luxurious .showcase .irantheme-social-media li a path {
    color: $color-gray-300;
    fill: $color-gray-300;
    width: 0.9rem;
    height: 0.9rem;
    position: relative;
    top: -2px;
    transition: inherit;
}

#header-luxurious .showcase .irantheme-social-media li a::after {
    content: '';
    position: absolute;
    top: 100%;
    right: 0;
    width: 100%;
    background: $color-quaternary;
    height: 3px;
    -webkit-transform: scaleX(0);
    -ms-transform: scaleX(0);
    transform: scaleX(0);
    -webkit-transition: 0.3s;
    -o-transition: 0.3s;
    transition: 0.3s;
}

#header-luxurious .showcase .irantheme-social-media li a:hover::after {
    -webkit-transform: scaleX(1);
    -ms-transform: scaleX(1);
    transform: scaleX(1);
}

#header-luxurious .showcase .irantheme-social-media li a:hover {
    color: $color-quaternary;
}

#header-luxurious .showcase .irantheme-social-media li a:hover svg,
#header-luxurious .showcase .irantheme-social-media li a:hover path {
    color: $color-quaternary;
    fill: $color-quaternary;
}

/* Mouse down */

#header-luxurious .showcase .mouse-down {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: center;
    -ms-flex-pack: center;
    justify-content: center;
}

#header-luxurious .showcase .mouse-down .irantheme-mouse-down-toggle {
    width: 2.25rem;
    height: 3rem;
    border: 2px solid $color-gray-500;
    border-radius: $border-radius-2;
    position: relative;
    -webkit-transform: translateY(3rem);
    -ms-transform: translateY(3rem);
    transform: translateY(3rem);
    cursor: pointer;
}

#header-luxurious .showcase .mouse-down .irantheme-mouse-down-toggle::before {
    content: '';
    position: absolute;
    right: 50%;
    top: 30%;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: $color-white;
    -webkit-transform: translate(50%, 50%);
    -ms-transform: translate(50%, 50%);
    transform: translate(50%, 50%);
    -webkit-transition: all 0.3s cubic-bezier(0.25, 0, 1, 1);
    -o-transition: all 0.3s cubic-bezier(0.25, 0, 1, 1);
    transition: all 0.3s cubic-bezier(0.25, 0, 1, 1);
}

#header-luxurious .showcase .mouse-down .irantheme-mouse-down-toggle:hover,
#header-luxurious .showcase .mouse-down .irantheme-mouse-down-toggle.active {
    border-color: $color-white;
    background-color: $color-white;
}

#header-luxurious .showcase .mouse-down .irantheme-mouse-down-toggle:hover::before,
#header-luxurious .showcase .mouse-down .irantheme-mouse-down-toggle.active::before {
    top: 55%;
    background: $color-quaternary;
}