/*
=====================================
Woocommerce products and offers products
=====================================
*/

// Product images
.irantheme-product-image-holder {
    aspect-ratio: 1/1;
    overflow: hidden;

    .irantheme-product-image {
        width: 100%;
        height: 100%;
        // object-fit: contain;
        object-position: center;
    }
}

// Gallery images
.irantheme-banner-image-holder {
    aspect-ratio: 4/3;
    overflow: hidden;

    .irantheme-banner-image {
        width: 100%;
        height: auto;
        object-fit: cover;
        object-position: center;
    }
}

// Gallery images
.irantheme-gallery-image-holder {
    aspect-ratio: 16/9;
    overflow: hidden;

    .irantheme-gallery-image {
        width: 100%;
        height: auto;
        object-fit: cover;
        object-position: center;
    }
}

.irantheme-set-padding {
    @media only screen and (max-width: 991px) {
        padding-top: 1rem !important;
        padding-bottom: 1rem !important;
    }
}

.irantheme-set-height {
    @media only screen and (max-width: 991px) {
        height: auto !important;
    }
}

.irantheme-set-heading {
    @media only screen and (max-width: 991px) {
        font-size: 1.5rem !important;
        line-height: 2rem !important;
    }
}

.irantheme-set-thumbnail-abs {
    position: absolute;
    top: 0;
    right: 0;
    width: 100%;
    height: 100%;
    z-index: 1;
    display: flex;

    &-img {
        width: 100%;
        height: 100%;
    }
}

.irantheme-semi-image-holder {
    overflow: hidden;

    .irantheme-semi-image {
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center;
    }
}