/*
=====================================
Communication Newsletter Section
=====================================
*/
.irantheme-communication-newsletter-section {
    .irantheme-communication-newsletter {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;

        // Newsletter wrapper
        .irantheme-communication-newsletter-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-communication-newsletter-form {
                display: flex;
                align-items: center;
                height: 100%;

                .irantheme-communication-newsletter-form-input-holder {
                    display: flex;
                    width: 100%;
                    max-width: 40rem;

                    .irantheme-communication-newsletter-form-email {
                        margin: 0;
                        display: inline-block;
                        border: unset;
                        background-color: unset;
                        padding: 0.9rem 1.2rem;
                        font-size: 0.8rem;
                        flex-grow: 2;
                        flex-basis: 75%;
                    }

                    .irantheme-communication-newsletter-form-submit {
                        display: inline-block;
                        align-self: stretch;
                        padding: 0 2rem;
                        border-radius: unset;
                        flex-grow: 1;
                        flex-basis: 25%;

                        i {
                            font-size: 1.3rem;
                            // margin: 0;
                        }
                    }

                    &.irantheme-communication-newsletter-input-bg-white {
                        // background-color: $color-white;

                        .irantheme-communication-newsletter-form-email {
                            background-color: $color-white;
                            color: $color-dark;

                            &::placeholder {
                                color: $color-gray-600;
                                opacity: 1;
                                /* Firefox */
                            }

                            &::-ms-input-placeholder {
                                /* Edge 12-18 */
                                color: $color-gray-600;
                            }
                        }

                    }

                    &.irantheme-communication-newsletter-input-bg-dark {
                        // background-color: $color-dark;

                        .irantheme-communication-newsletter-form-email {
                            background-color: $color-dark;
                            color: $color-white;

                            &::placeholder {
                                color: $color-gray-400;
                                opacity: 1;
                                /* Firefox */
                            }

                            &::-ms-input-placeholder {
                                /* Edge 12-18 */
                                color: $color-gray-400;
                            }
                        }
                    }

                    &.irantheme-communication-newsletter-no-space {
                        overflow: hidden;

                        &.irantheme-communication-newsletter-input-normal {
                            &.irantheme-communication-newsletter-input-bg-dark {
                                .irantheme-communication-newsletter-form-email {
                                    background-color: $color-dark;
                                }
                            }

                            &.irantheme-communication-newsletter-input-bg-white {
                                .irantheme-communication-newsletter-form-email {
                                    background-color: $color-white;
                                }
                            }
                        }

                        &.irantheme-communication-newsletter-input-border {
                            border-radius: 10rem;
                            overflow: hidden;

                            &.irantheme-communication-newsletter-input-bg-dark {
                                border: 1px solid $color-gray-700;
                                background-color: $color-dark;
                            }

                            &.irantheme-communication-newsletter-input-bg-white {
                                border: 1px solid $color-gray-300;
                                background-color: $color-white;
                            }
                        }

                        &.irantheme-communication-newsletter-input-shadow {
                            border-radius: 10rem;
                            overflow: hidden;

                            &.irantheme-communication-newsletter-input-bg-dark {
                                @extend %box-shadow-dark;
                                background-color: $color-dark;
                            }

                            &.irantheme-communication-newsletter-input-bg-white {
                                @extend %box-shadow-white;
                                background-color: $color-white;
                            }
                        }
                    }

                    &.irantheme-communication-newsletter-yes-space {
                        column-gap: 1rem;

                        &.irantheme-communication-newsletter-input-normal {
                            &.irantheme-communication-newsletter-input-bg-dark {
                                .irantheme-communication-newsletter-form-email {
                                    background-color: $color-dark;
                                }
                            }

                            &.irantheme-communication-newsletter-input-bg-white {
                                .irantheme-communication-newsletter-form-email {
                                    background-color: $color-white;
                                }
                            }
                        }

                        &.irantheme-communication-newsletter-input-border {
                            &.irantheme-communication-newsletter-input-bg-dark {
                                .irantheme-communication-newsletter-form-email {
                                    border: 1px solid $color-gray-700;
                                    background-color: $color-dark;
                                }

                                .irantheme-communication-newsletter-form-submit {
                                    border: 1px solid $color-gray-700;
                                    background-color: $color-dark;
                                }
                            }

                            &.irantheme-communication-newsletter-input-bg-white {
                                .irantheme-communication-newsletter-form-email {
                                    border: 1px solid $color-gray-300;
                                    background-color: $color-white;
                                }

                                .irantheme-communication-newsletter-form-submit {
                                    border: 1px solid $color-gray-300;
                                    background-color: $color-white;
                                }
                            }
                        }

                        &.irantheme-communication-newsletter-input-shadow {
                            &.irantheme-communication-newsletter-input-bg-dark {
                                .irantheme-communication-newsletter-form-email {
                                    @extend %box-shadow-dark;
                                    background-color: $color-dark;
                                }

                                .irantheme-communication-newsletter-form-submit {
                                    @extend %box-shadow-dark;
                                    background-color: $color-dark;
                                }
                            }

                            &.irantheme-communication-newsletter-input-bg-white {
                                .irantheme-communication-newsletter-form-email {
                                    @extend %box-shadow-white;
                                    background-color: $color-white;
                                }

                                .irantheme-communication-newsletter-form-submit {
                                    @extend %box-shadow-white;
                                    background-color: $color-white;
                                }
                            }
                        }
                    }
                }
            }


            .irantheme-communication-newsletter-social-media {
                margin-top: 0.5rem;
                display: flex;

                .irantheme-social-media {
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    font-size: 1.2rem;
                    padding: 1.5rem 0;

                    li {
                        overflow: hidden;
                        width: 2.5rem;
                        height: 2.5rem;
                        border-radius: 100%;
                        margin-left: 0.7rem;
                        display: flex;
                        justify-content: center;
                        align-items: center;

                        @include transition(0.2s);

                        a {
                            // color: $color-gray-300;
                            // display: block;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            // padding: 2.5rem;
                            width: 100%;
                            height: 100%;
                            @include transition(0.2s);

                            svg {
                                width: 1.2rem;
                                height: 1.2rem;
                                // color: $color-gray-300;
                                // fill: $color-gray-300;
                                line-height: 1;
                                @include transition(0.2s);

                                path {
                                    // fill: $color-gray-300;
                                    @include transition(0.2s);
                                }
                            }

                            &:hover {
                                // color: $color-white;

                                svg,
                                path {
                                    // fill: $color-white;
                                }
                            }
                        }

                        &:hover {
                            @include transition(0.2s);
                            border: unset;
                        }
                    }
                }
            }

        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // News letter social media
            .irantheme-communication-newsletter-social-media {

                .irantheme-social-media {

                    li {

                        // &:hover {
                        //     border-color: $color-white;
                        //     background-color: $color-white;

                        // }

                        a {
                            color: $color-dark;

                            svg {
                                color: $color-dark;
                                fill: $color-dark;

                                path {
                                    fill: $color-dark;
                                }
                            }

                            &:hover {
                                background-color: $color-dark !important;
                                color: $color-white;

                                svg {
                                    color: $color-white;
                                    fill: $color-white;

                                    path {
                                        fill: $color-white;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // News letter social media
            .irantheme-communication-newsletter-social-media {

                .irantheme-social-media {

                    li {

                        // &:hover {
                        //     border-color: $color-dark;
                        //     background-color: $color-dark;

                        // }

                        a {
                            color: $color-white;

                            svg {
                                color: $color-white;
                                fill: $color-white;

                                path {
                                    fill: $color-white;
                                }
                            }

                            &:hover {
                                background-color: $color-white !important;
                                color: $color-dark;

                                svg {
                                    color: $color-dark;
                                    fill: $color-dark;

                                    path {
                                        fill: $color-dark;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}