/*
=====================================
Footer nav section
=====================================
*/
.irantheme-footer-nav-section {
    // background: $color-dark;

    .irantheme-footer-nav {
        position: relative;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;

        .irantheme-footer-nav-title {
            font-weight: bold;
            font-size: 0.9rem;
            margin-bottom: 1rem;
            display: flex;
            column-gap: 0.5rem;
            align-items: center;
        }

        &-top {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 2rem;

            // Logo
            &-logo {

                // Logo image holder
                .irantheme-logo-img-holder {
                    width: fit-content;

                    // Logo img
                    .irantheme-logo-img {
                        height: 100% !important;
                        width: auto;
                    }
                }

                // Logo svg holder
                .irantheme-logo-svg-holder {
                    width: fit-content;

                    svg {
                        height: 100% !important;
                        width: auto;
                    }
                }
            }

            // Return to top
            &-return-to-top {
                margin-right: auto;

                &-button {
                    display: flex;
                    column-gap: 0.5rem;
                    padding: 0.75rem 1rem;
                    font-size: 0.8rem;
                }
            }
        }

        &-row {
            display: flex;
            gap: 1.5rem;

            @media only screen and (max-width:991px) {
                flex-direction: column;
            }

            .irantheme-footer-nav-col {
                flex-grow: 1;

                @media only screen and (max-width:991px) {
                    flex-grow: unset;
                    width: 100%;
                }

                @media only screen and (min-width:992px) {
                    max-width: 35%;
                }
            }
        }

        // Headline
        .irantheme-footer-nav-headline {
            position: relative;
            z-index: 9;

            // About
            .irantheme-footer-nav-text {
                padding-top: 2rem;
                padding-bottom: 1rem;

                p {
                    font-size: 0.8rem;
                    // color: $color-gray-400;
                    margin-bottom: 0.5rem;
                }

                a {
                    font-size: 0.7rem;
                    font-weight: bold;
                    // color: $color-white;

                    &:hover {
                        i {
                            transform: translateX(-0.25rem);
                        }
                    }

                    i {
                        margin-right: 0.5rem;
                        transition: 0.3s;
                        font-size: 0.5rem;
                        font-weight: bold;
                    }
                }
            }

            // Useful links
            .irantheme-footer-nav-useful-links {
                width: 100%;

                &-list {
                    display: flex;
                    flex-direction: column;
                    flex-wrap: wrap;
                    row-gap: 0.75rem;

                    &-item {
                        display: flex;

                        &-link {
                            font-size: 0.8rem;
                            // color: $color-gray-700;

                            &:hover {
                                // color: $color-gray-800;
                            }
                        }
                    }
                }
            }

            // Details
            .irantheme-footer-nav-details {
                font-size: 0.8rem;
                display: flex;
                flex-direction: column;
                row-gap: 1rem;
            }

            // Newsletter
            .irantheme-communication-newsletter-form {
                margin-bottom: 2rem;

                .irantheme-communication-newsletter-form-input-holder {
                    display: flex;
                    flex-wrap: nowrap;
                    column-gap: 0.5rem;

                    .irantheme-communication-newsletter-form-submit {
                        height: 2.5rem;
                        width: auto;
                        flex-grow: 1;
                        font-weight: bold;
                    }

                    .irantheme-communication-newsletter-form-email {
                        height: 2.5rem;
                        width: 100%;
                        flex-grow: 1;
                        margin-bottom: 0;
                        font-size: 0.8rem;
                    }
                }
            }
        }

        // Badge
        &-badge {
            .irantheme-holder-badges {
                display: flex;
                flex-direction: column;
                align-items: flex-end;

                @media only screen and (max-width:991px) {
                    flex-direction: row;
                    align-items: flex-start;
                }
            }
        }

        // Platform applications
        &-app {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 1.5rem;
            padding: 1rem;
            margin-top: 2rem;

            &-holder {
                display: flex;
                flex-wrap: wrap;
                gap: 1rem;
            }

            &-link {
                display: flex;
                width: 10.08rem;
                height: 3rem;

                img {
                    width: 100%;
                    height: 100%;
                    object-fit: fill;
                }
            }
        }


        // Social media
        .irantheme-social-media {
            display: flex;
            flex-direction: row;
            justify-content: flex-start;
            text-align: center;
            flex-wrap: wrap;
            column-gap: 2rem;

            li {
                a {
                    // color: $color-white;
                    font-size: 1.2rem;
                    display: block;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 50%;

                    svg,
                    path {
                        // color: $color-white;
                        // fill: $color-white;
                        width: 1.2rem;
                        height: 1.2rem;
                        position: relative;
                        top: -2px;
                        transition: inherit;
                    }

                    &:hover {
                        // background: $color-gray-200;
                        // color: $color-dark;

                        svg,
                        path {
                            // color: $color-dark;
                            // fill: $color-dark;
                        }
                    }
                }
            }
        }

        // Copyright
        .irantheme-footer-nav-copyright {
            // background: $color-gray-900;
            display: flex;
            flex-direction: column;
            justify-content: center;
            text-align: center;
            padding: 1rem 0;
            border-top-width: 1px;
            border-style: solid;
            position: relative;
            z-index: 9;

            .irantheme-footer-nav-copyright-text {
                font-size: 0.8rem;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .irantheme-footer-nav {
            background-color: $color-white;

            .irantheme-footer-nav-title {
                color: $color-gray-900;
            }

            // Headline
            .irantheme-footer-nav-headline {

                // Top
                .irantheme-footer-nav-top {
                    color: $color-dark;

                    // Return to top
                    &-return-to-top {

                        &-button {
                            background: $color-dark;
                            color: $color-white;
                        }
                    }
                }

                // About
                .irantheme-footer-nav-text {

                    p {
                        color: $color-gray-600;
                    }

                    a {
                        color: $color-dark;
                    }
                }

                // Useful links
                .irantheme-footer-nav-useful-links {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-700;

                                &:hover {
                                    color: $color-gray-900;
                                }
                            }
                        }
                    }
                }

                // Details
                .irantheme-footer-nav-details {
                    color: $color-gray-700;
                }

                // App
                .irantheme-footer-nav-app {
                    background: $color-gray-100;
                }
            }

            // Social media
            .irantheme-social-media {
                li {
                    a {
                        color: $color-gray-700;

                        svg,
                        path {
                            color: $color-gray-700;
                            fill: $color-gray-700;
                        }

                        &:hover {
                            color: $color-gray-900;

                            svg,
                            path {
                                color: $color-gray-900;
                                fill: $color-gray-900;
                            }
                        }
                    }
                }
            }

            // Copyright
            .irantheme-footer-nav-copyright {
                // background: $color-white;
                border-color: $color-gray-100;

                .irantheme-footer-nav-copyright-text {
                    color: $color-gray-600;
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .irantheme-footer-nav {
            background-color: $color-dark;

            .irantheme-footer-nav-title {
                color: $color-gray-100;
            }

            // Headline
            .irantheme-footer-nav-headline {

                // Top
                .irantheme-footer-nav-top {
                    color: $color-white;

                    // Return to top
                    &-return-to-top {

                        &-button {
                            background: $color-white;
                            color: $color-dark;
                        }
                    }
                }

                // About
                .irantheme-footer-nav-text {
                    p {
                        color: $color-gray-400;
                    }

                    a {
                        color: $color-white;
                    }
                }

                // Useful links
                .irantheme-footer-nav-useful-links {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-300;

                                &:hover {
                                    color: $color-gray-100;
                                }
                            }
                        }
                    }
                }

                // Details
                .irantheme-footer-nav-details {
                    color: $color-gray-300;
                }

                // App
                .irantheme-footer-nav-app {
                    background: $color-gray-900;
                }
            }

            // Social media
            .irantheme-social-media {
                li {
                    a {
                        color: $color-gray-300;

                        svg,
                        path {
                            color: $color-gray-300;
                            fill: $color-gray-300;
                        }

                        &:hover {
                            color: $color-gray-100;

                            svg,
                            path {
                                color: $color-gray-100;
                                fill: $color-gray-100;
                            }
                        }
                    }
                }
            }

            // Copyright
            .irantheme-footer-nav-copyright {
                // background: $color-dark;
                border-color: $color-gray-900;

                .irantheme-footer-nav-copyright-text {
                    color: $color-gray-400;
                }
            }
        }
    }
}

// Badge
.irantheme-badge-item {
    img {
        max-width: 4rem;
        object-fit: contain;
        height: auto;
        margin-bottom: 1rem;
    }
}