.irantheme-MyAccount-support {

    // Ticket register ============
    &-ticket-register {
        &-heading {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
            margin-bottom: 1.5rem;

            &-title {
                font-size: .9rem;
                font-weight: 600;
                color: $color-gray-700;
                display: flex;
                flex-direction: column;

                .desc {
                    font-size: 0.8rem;
                    font-weight: 500;
                    color: $color-gray-600;
                }
            }

        }
    }

    // Ticket content ============

    &-ticket-content {
        &-heading {
            background-color: $color-white;
            padding-bottom: 2rem;
            display: flex;
            flex-direction: column;
            width: 100%;
            gap: 1rem;

            @media (max-width: 767.98px) {
                gap: 2rem;
            }

            &-title {
                display: flex;
                align-items: center;
                gap: 0.5rem;
                width: 100%;

                @media (max-width: 767.98px) {
                    order: 1;
                    flex-direction: column;
                    flex-wrap: wrap;
                }

                &-wrapper {
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    gap: 1rem;
                    width: 100%;

                    @media (max-width: 767.98px) {
                        flex-direction: column;
                        gap: 2rem;
                    }
                }

                &-subject {
                    font-size: 0.9rem;

                    -webkit-line-clamp: 1;
                    line-clamp: 1;
                    display: -webkit-box;
                    -webkit-box-orient: vertical;
                    overflow: hidden;
                    max-width: 75%;

                    @media (max-width: 767.98px) {
                        max-width: none;
                        order: 1;
                        text-align: center;
                        -webkit-line-clamp: 3;
                        line-clamp: 3;
                    }
                }

                &-id {
                    padding: .3rem .6rem;
                    border-radius: $border-radius-high;
                    font-size: .6rem;
                    font-weight: 600;
                    width: fit-content;
                    line-height: normal;
                    background-color: $color-gray-100;
                    color: $color-gray-600;
                    display: flex;
                    align-items: center;
                    gap: .2rem;
                    border: 1px solid $color-gray-300;

                    cite {
                        font-style: normal !important;
                    }
                }
            }

            &-meta {
                display: flex;
                align-items: center;
                gap: 1.2rem;
                width: 100%;

                @media (max-width: 767.98px) {
                    flex-wrap: wrap;
                    justify-content: center;
                }

                // status style
                .ticket-status {
                    padding: .4rem .8rem;
                    border-radius: $border-radius-high;
                    font-size: .65rem;
                    font-weight: 600;
                    display: flex;
                    align-items: center;
                    gap: .25rem;
                    width: fit-content;
                    line-height: normal;
                    background-color: rgba($color-gray-600, 0.1);
                    color: $color-gray-600;

                    &::before {
                        content: '';
                        width: 5px;
                        height: 5px;
                        display: inline-block;
                        border-radius: 50%;
                        background-color: $color-gray-600;
                    }

                    &.status-open {
                        background-color: rgba($color-primary, 0.1);
                        color: $color-primary;

                        &::before {
                            background-color: $color-primary;

                        }
                    }

                    &.status-under-review {
                        background-color: rgba($color-quinary, 0.1);
                        color: $color-quinary-hover;

                        &::before {
                            background-color: $color-quinary-hover;

                        }
                    }

                    &.status-answered {
                        background-color: rgba($color-quaternary, 0.1);
                        color: $color-quaternary-hover;

                        &::before {
                            background-color: $color-quaternary-hover;

                        }
                    }

                    &.status-closed {
                        background-color: rgba($color-red-shine, 0.1);
                        color: $color-red-shine;

                        &::before {
                            background-color: $color-red-shine;

                        }
                    }

                }

                // Priority style
                .ticket-priority {
                    padding: calc(.4rem - 1px) calc(.8rem - 1px);
                    border-radius: $border-radius-high;
                    font-size: .65rem;
                    font-weight: 600;
                    display: flex;
                    align-items: center;
                    gap: .5rem;
                    width: fit-content;
                    line-height: normal;
                    border: 1px solid $color-gray-400;

                    &::before {
                        font-size: .7rem;
                        font-weight: 600;
                        font-family: $font-family-icons;
                        line-height: normal;
                    }

                    &.priority-normal {
                        border-color: rgba($color-quinary, 0.5);
                        color: $color-quinary;

                        &::before {
                            content: '\3d';
                        }
                    }

                    &.priority-low {
                        border-color: rgba($color-primary, 0.5);
                        color: $color-primary;

                        &::before {
                            content: '\f107';
                        }
                    }

                    &.priority-high {
                        border-color: rgba($color-tertiary, 0.5);
                        color: $color-tertiary;

                        &::before {
                            content: '\f106';
                        }
                    }

                    &.priority-urgent {
                        border-color: rgba($color-red-shine, 0.5);
                        color: $color-red-shine;

                        &::before {
                            content: '\f102';
                        }
                    }



                }

                // Ticket data create and modified
                .ticket-date {
                    font-size: 0.75rem;
                    display: flex;
                    align-items: center;
                    gap: 0.25rem;
                    line-height: normal;

                    i {
                        font-size: 0.8rem;
                        line-height: normal;
                    }

                    @media (max-width: 767.98px) {
                        width: 100%;
                        justify-content: center;
                    }
                }
            }
        }

        &-body {
            padding: 0.25rem;
            border-radius: $border-radius-high;
            min-height: 100%;

