            background-attachment: fixed;

            &-conversations {
                display: flex;
                flex-direction: column;
                max-height: 800px;
                overflow-y: auto;
                padding: .5rem .5rem 0 .5rem;
                margin-bottom: 0.25rem;

                &::-webkit-scrollbar {
                    width: 5px;
                }

                &::-webkit-scrollbar-track {
                    background: transparent;
                }

                &::-webkit-scrollbar-thumb {
                    background-color: $color-gray-300;
                    border-radius: 10px;
                    @include transition(0.2s);

                    &:hover {
                        background-color: $color-gray-400;
                    }
                }

                .chat-date-divider {
                    text-align: center;
                    margin: 20px 0;
                    position: relative;
                    clear: both;

                    &::before {
                        content: '';
                        position: absolute;
                        left: 0;
                        right: 0;
                        top: 50%;
                        height: 1px;
                        background: $color-gray-300;
                        z-index: 1;
                    }

                    &-text {
                        background: $color-gray-100;
                        line-height: normal;
                        font-size: 0.75rem;
                        font-weight: 500;
                        padding: .4rem .8rem;
                        border-radius: $border-radius-high;
                        color: $color-gray-500;
                        position: relative;
                        z-index: 2;
                        display: inline-block;

                        @media (max-width: 768px) {
                            font-size: 0.65rem;
                            padding: .3rem .7rem;
                        }
                    }

                    /* اولین جداکننده فاصله کمتری داره */
                    &:first-of-type {
                        margin-top: 5px;
                    }

                }



                &-message {
                    display: flex;
                    gap: 0.5rem;

                    &-group {
                        display: flex;
                        flex-direction: column;
                        gap: 0.5rem;
                        margin-bottom: 1.2rem;
                    }

                    .message-bubble {
                        display: flex;
                        flex-direction: column;
                        gap: 0.3rem;
                        box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
                        max-width: 70%;
                        padding: .7rem .9rem;
                        position: relative;

                        @media (max-width: 768px) {
                            max-width: 85%;
                        }
                    }

                    .message-avatar {
                        width: 36px;
                        height: 36px;
                        border-radius: 50%;
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        font-size: 1rem;
                        flex-shrink: 0;
                        align-self: flex-end;
                        color: $color-white;

                        &.user-avatar {
                            background-color: $color-primary;
                            box-shadow: 0 2px 5px rgba($color-primary, 0.3);
                            order: 0;
                        }

                        &.admin-avatar {
                            background-color: $color-tip-info-color;
                            box-shadow: 0 2px 5px rgba($color-tip-info-color, 0.3);
                            order: 1;
                        }

                        @media (max-width: 575.98px) {
                            display: none;
                        }
                    }

                    .message-heading {
                        line-height: normal;

                        &-username {
                            font-size: 0.7rem;
                        }
                    }

                    .message-text {
                        font-size: 0.8rem;
                    }

                    .message-time {
                        color: $color-gray-600;
                        display: flex;
                        gap: 0.15rem;
                        margin-top: 0.25rem;

                        .time {
                            font-size: 0.6rem;
                            line-height: normal;
                        }

                        .icon {
                            font-size: 0.65rem;
                            line-height: normal;
                        }
                    }

                    &.admin-message {
                        justify-content: flex-end;

                        &:not(.has-avatar) {
                            margin-left: calc(36px + 0.5rem);
                        }

                        .message-bubble {
                            background-color: $color-white;
                            border-radius: 12px 12px 12px 0;
                        }

                        &.first-in-group {
                            .message-bubble {
                                border-radius: 12px 12px 12px 6px;
                            }
                        }

                        &.middle-in-group {
                            .message-bubble {
                                border-radius: 6px 12px 12px 6px;
                            }
                        }

                        &.last-in-group {
                            .message-bubble {
                                border-radius: 6px 12px 12px 0;
                            }
                        }

                        &.alone-in-group {
                            .message-bubble {
                                border-radius: 12px 12px 12px 0;
                            }
                        }

                        .message-time {
                            text-align: right;
                        }

                        @media (max-width: 575.98px) {
                            &:not(.has-avatar) {
                                margin-left: 0;
                            }
                        }

                    }

                    &.user-message {
                        justify-content: flex-start;

                        &:not(.has-avatar) {
                            margin-right: calc(36px + 0.5rem);
                        }

                        .message-bubble {
                            background-color: $color-gray-200;
                        }

                        &.first-in-group {
                            .message-bubble {
                                border-radius: 12px 12px 4px 12px;
                            }
                        }

                        &.middle-in-group {
                            .message-bubble {
                                border-radius: 12px 4px 4px 12px;
                            }
                        }

                        &.last-in-group {
                            .message-bubble {
                                border-radius: 12px 4px 0 12px;
                            }
                        }

                        &.alone-in-group {
                            .message-bubble {
                                border-radius: 12px 12px 0 12px;
                            }
                        }

                        .message-time {
                            text-align: right;
                        }

                        @media (max-width: 575.98px) {
                            &:not(.has-avatar) {
                                margin-right: 0;
                            }
                        }
                    }

                    &.hide-name {
                        .message-heading {
                            display: none;
                        }
                    }
                }
            }

            &-reply {
                width: 100%;
                padding: 0 0.5rem 0.5rem 0.5rem;

                &-form {
                    background-color: $color-white;
                    border-radius: $border-radius-high;
                    overflow: hidden;
                    display: flex;
                    flex-direction: column;

                    &-input {
                        // Reset all input style
                        appearance: none;
                        -webkit-appearance: none;
                        -moz-appearance: none;

                        border: none;
                        outline: none;
                        background: none;
                        box-shadow: none;

                        width: 100%;
                        box-sizing: border-box;

                        -webkit-tap-highlight-color: transparent;

                        &:focus {
                            outline: none;
                            border: none;
                            box-shadow: none;
                        }

                        &:hover {
                            box-shadow: none;
                        }

                        // Custom style
                        resize: none;
                        overflow-y: auto;
                        font-size: 0.75rem;
                        padding: 0.75rem !important;
                        margin: 0 !important;
                    }

                    &-actions {
                        display: flex;
                        align-items: center;
                        padding: 0.75rem;

                        &-submit {
                            border-radius: $border-radius-high;
                        }
                    }
                }
            }

            &-ticket-closed {
                width: 100%;
                padding: 0 0.5rem 0.5rem 0.5rem;

                &-wrapper {
                    background-color: $color-white;
                    border-radius: $border-radius-high;
                    overflow: hidden;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    padding: 1rem;
                    min-height: 180px;

                    .icon {
                        font-size: 2.5rem;
                        color: $color-gray-600;
                        margin-bottom: 1rem;
                    }

                    .title {
                        text-align: center;
                        font-size: .9rem;
                        color: $color-gray-700;
                    }

                    .desc {
                        text-align: center;
                        font-size: .8rem;
                        color: $color-gray-600;
                    }
                }
            }
        }
    }

    &-ticket-not-found {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        width: 100%;

        &-wrapper {
            padding: 1rem 0;
            margin-top: 3rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 1rem;
        }

        .icon {
            font-size: 5rem;
            color: $color-gray-600;
            margin-bottom: 1rem;
        }

        .title {
            font-size: .8rem;
            font-weight: 600;
            color: $color-gray-800;
        }

        .add-ticket {
            font-size: .75rem;
            font-weight: normal;
            padding: .5rem 1rem;
            display: flex;
            align-items: center;
            gap: .25rem;
            color: $color-gray-700;
            transition: all .2s ease-in-out;

            i {
                font-size: .65rem;
            }
        }
    }

    // Ticket list style =========
    // Heading
    &-heading {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 1.5rem;
        flex-wrap: wrap;
        gap: 15px;

        &-btn {
            a {
                padding: 0.65rem 1rem !important;
                font-size: 0.7rem !important;
            }

            i {
                font-size: 1.25rem;
            }
        }
    }

    // Table
    &-table {

        // td tags
        &-td {

            // NumberID style
            &.ticket-subject {
                a {
                    color: $color-gray-700;
                }
            }

            // Subject style
            &.ticket-subject {
                max-width: 250px;

                p {
                    color: $color-gray-700;
                    -webkit-line-clamp: 1;
                    line-clamp: 1;
                    display: -webkit-box;
                    -webkit-box-orient: vertical;
                    overflow: hidden;
                    text-overflow: ellipsis;
                }
            }

            // status style
            &.ticket-status {
                .status-badge {
                    padding: .35rem .75rem;
                    border-radius: $border-radius-medium;
                    font-size: .65rem;
                    font-weight: 600;
                    display: flex;
                    align-items: center;
                    gap: .25rem;
                    width: fit-content;
                    line-height: normal;
                    background-color: rgba($color-gray-600, 0.1);
                    color: $color-gray-600;

                    &::before {
                        content: '';
                        width: 5px;
                        height: 5px;
                        display: inline-block;
                        border-radius: 50%;
                        background-color: $color-gray-600;
                    }

                    &.status-open {
                        background-color: rgba($color-primary, 0.1);
                        color: $color-primary;

                        &::before {
                            background-color: $color-primary;

                        }
                    }

                    &.status-under-review {
                        background-color: rgba($color-quinary, 0.1);
                        color: $color-quinary-hover;

                        &::before {
                            background-color: $color-quinary-hover;

                        }
                    }

                    &.status-answered {
                        background-color: rgba($color-quaternary, 0.1);
                        color: $color-quaternary-hover;

                        &::before {
                            background-color: $color-quaternary-hover;

                        }
                    }

                    &.status-closed {
                        background-color: rgba($color-red-shine, 0.1);
                        color: $color-red-shine;

                        &::before {
                            background-color: $color-red-shine;

                        }
                    }

                }
            }

            // Priority style
            &.ticket-priority {
                .priority-badge {
                    display: flex;
                    align-items: center;
                    gap: .5rem;
                    line-height: normal;

                    &::before {
                        font-size: .7rem;
                        font-weight: 600;
                        font-family: $font-family-icons;
                        line-height: normal;
                    }

                    &.priority-normal {
                        &::before {
                            content: '\3d';
                            color: $color-quinary;
                        }
                    }

                    &.priority-low {
                        &::before {
                            content: '\f107';
                            color: $color-primary;
                        }
                    }

                    &.priority-high {
                        &::before {
                            content: '\f106';
                            color: $color-tertiary;
                        }
                    }

                    &.priority-urgent {
                        &::before {
                            content: '\f102';
                            color: $color-red-shine;
                        }
                    }



                }
            }

            &.ticket-actions {
                a {
                    font-size: 0.7rem;
                    display: flex;
                    align-items: center;
                    gap: 0.25rem;
                    line-height: normal;

                    i {
                        font-size: 0.6rem;
                        line-height: normal;
                    }
                }
            }
        }
    }
}