.irantheme-business-ads-section {
    .irantheme-business-ads {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Viewpoints
        .irantheme-business-ads-post-swiper {}

        .irantheme-business-ads-post-wrapper {

            // Item
            .irantheme-business-ads-post-item {
                position: relative;
                overflow: hidden;
                display: flex;
                align-items: center;
                justify-content: center;
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Viewpoints
            .irantheme-business-ads-post-wrapper {

                // Item
                .irantheme-business-ads-post-item {}
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Viewpoints
            .irantheme-business-ads-post-wrapper {

                // Item
                .irantheme-business-ads-post-item {}
            }
        }
    }
}