/*
=====================================
Header universal
=====================================
*/

#header-technological {
    background: $color-dark;
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
    // background-attachment: fixed;
    position: relative;

    #wrapper-header {
        position: relative;
        z-index: 1;

        // Banner universal
        .banner-universal {
            padding: 8rem 0 6rem;
            text-align: center;

            // Heading
            &-heading {
                margin-bottom: 2rem;

                h1 {
                    font-size: 2rem;
                    line-height: 2.5rem;
                    color: $color-white;
                    margin: 0 0 1rem;
                    padding: 0;
                }

                p {
                    font-size: 1rem;
                    color: $color-gray-400;
                }
            }

            &__info {
                display: flex;
                flex-wrap: wrap;
                justify-content: center;
                width: 100%;

                li {
                    font-size: 0.8rem;
                    color: $color-gray-300;
                    font-weight: normal;

                    span {
                        margin-left: 0.25rem;
                    }

                    &:not(:last-child)::after {
                        content: '';
                        margin-left: 1rem;
                        margin-right: 1rem;
                        width: 4px;
                        height: 4px;
                        background: $color-primary;
                        border-radius: 50%;
                        display: inline-block;
                        position: relative;
                        top: -3px;
                    }

                    a {
                        color: $color-gray-300;
                    }
                }
            }
        }

        // Info universal
        .info-universal {
            padding: 0 2rem 2rem;

            .container-fluid {
                display: flex;
                justify-content: space-between;
            }

            // Author
            &-author {

                &::before,
                &::after {
                    content: '';
                    display: table;
                    clear: both;
                }

                // Img
                &-img {
                    float: right;

                    img {
                        width: 50px;
                        height: 50px;
                        border-radius: 50%;
                    }
                }

                // Content
                &-content {
                    display: flex;
                    flex-direction: column;
                    margin-right: calc(50px + 1rem);

                    strong {
                        padding-top: 0.5rem;
                        font-weight: normal;

                        a {
                            font-size: 0.8rem;
                            color: $color-white;
                            line-height: 1rem;
                            display: block;
                        }
                    }

                    span {
                        font-size: 0.6rem;
                        color: $color-gray-200;
                    }
                }
            }

            // Category
            &-category {
                display: flex;
                justify-content: flex-end;

                a {
                    border: 1px solid $color-dark-transparent-2;
                    color: $color-gray-200;
                    padding: 0.25rem 1rem;
                    font-size: 0.7rem;
                    margin: 0.5rem 0.25rem;
                    border-radius: $border-radius-2;

                    i {
                        margin-left: 0.5rem;
                    }

                    &:hover {
                        border-color: transparent;
                    }
                }
            }

            // Mouse toggle
            .mouse-toggle {
                display: -webkit-box;
                display: -ms-flexbox;
                display: flex;
                -webkit-box-pack: center;
                -ms-flex-pack: center;
                justify-content: flex-end;
                z-index: 999;
                position: relative;

                .irantheme-mouse-down-toggle {
                    width: 2rem;
                    height: 3rem;
                    border: 2px solid $color-gray-500;
                    border-radius: $border-radius-2;
                    position: relative;
                    // @include transform(translateY(3rem));
                    cursor: pointer;

                    &::before {
                        content: '';
                        position: absolute;
                        right: 50%;
                        top: 30%;
                        width: 5px;
                        height: 5px;
                        border-radius: 50%;
                        background: $color-white;
                        -webkit-transform: translate(50%, 50%);
                        -ms-transform: translate(50%, 50%);
                        transform: translate(50%, 50%);
                        -webkit-transition: all 0.3s cubic-bezier(0.25, 0, 1, 1);
                        -o-transition: all 0.3s cubic-bezier(0.25, 0, 1, 1);
                        transition: all 0.3s cubic-bezier(0.25, 0, 1, 1);
                    }

                    &:hover,
                    &.active {
                        border-color: $color-white;
                        background-color: $color-white;

                        &::before {
                            top: 55%;
                            background: $color-primary;
                        }
                    }
                }
            }
        }
    }
}

/*
=====================================
Header navbar
=====================================
*/
#header-navbar {
    background: transparent;
    width: 100%;
    height: 6rem;
    display: flex;
    align-items: center;
    padding: 0;
    position: relative;

    .container-padding {
        width: 100%;
    }

    .container-fluid {
        display: flex;
        justify-content: space-between;

        // Logo
        .logo {
            .custom-logo-link {
                display: flex;
                align-items: center;

                .custom-logo {
                    max-height: 20px;
                    width: auto;
                }
            }

            &.light {
                .custom-logo-link {
                    .custom-logo {
                        filter: invert(1);
                    }
                }
            }
        }

        // Main items
        .main-items {
            display: flex;
            align-items: center;
        }
    }
}

/*
=====================================
List post style
=====================================
*/

.list-post-style {
    display: flex;
    padding: 1rem 0;

    &.list-post-dark {
        .list-post-style-content {
            a {
                color: $color-gray-800;

                &:hover {
                    color: $color-dark;
                }
            }

            span {
                color: $color-gray-500;
            }
        }
    }

    .list-post-style-img {
        a {
            display: block;
            width: 5rem;
            margin-left: 1rem;

            img {
                width: 100%;
                height: 5rem;
                border-radius: 50%;
            }

            @media screen and (max-width(992px)) {
                width: 4rem;
            }
        }
    }

    .list-post-style-content {

        h3 {
            a {
                font-size: 0.8rem;
                color: $color-gray-300;

                &:hover {
                    color: $color-white;
                }
            }
        }

        span {
            font-size: 0.7rem;
            color: $color-gray-600;
        }
    }
}

.container-padding {
    padding: 0 calc(2rem + 10px);

    @media screen and (max-width: 991px) {
        padding: 0;
    }
}