/*
=====================================
Button styles
=====================================
*/

// Button no style
.irantheme-btn-void {
	margin: 0;
	padding: 0;
	border: 0;
	outline: 0;
	background: transparent;
	color: inherit;
	line-height: 1;
	box-shadow: none;
	border-radius: 0;

	&:hover,
	&:focus {
		color: inherit;
		text-decoration: none;
		background: inherit;
	}
}

// Default button
.irantheme-btn {
	background: transparent;
	display: flex;
	justify-content: center;
	align-items: center;
	column-gap: 0.5em;
	margin: 0;
	padding: 0;
	border: 0;
	outline: none;
	box-shadow: none;
	color: $color-gray-700;
	padding: 0.5em 1em;
	height: auto;
	line-height: normal;
	font-size: 0.8em;
	border-radius: $border-radius-high;
	position: relative;
	@include transition(0.2s);
	text-align: center;

	i {
		font-size: 0.9rem;
	}

	// Hover & focus
	&:hover,
	&:focus {
		color: inherit;
		text-decoration: none;
		background: inherit;
	}

	// Colors -----------------------------------

	&.irantheme-btn-default {
		background-color: $color-gray-100;
		border: 1px solid $color-gray-100;
		color: $color-gray-700;

		&:hover,
		&.active {
			background-color: $color-gray-200;
			border: 1px solid $color-gray-200;
		}
	}

	// Dark button
	&.irantheme-btn-dark {
		background-color: $color-gray-900;
		border: 1px solid $color-gray-900;
		color: $color-gray-200;

		&:hover,
		&.active {
			background-color: $color-gray-800;
			border: 1px solid $color-gray-800;
		}

		// Disable button
		&.disabled {
			background-color: $color-gray-600 !important;
			color: $color-gray-300 !important;
			cursor: default !important;
		}
	}

	// Dark button
	&.irantheme-btn-primary {
		background-color: $color-primary;
		border: 1px solid $color-primary;
		color: $color-white;

		&:hover,
		&.active {
			background-color: $color-primary-hover;
			border: 1px solid $color-primary-hover;
		}

		// Disable button
		&.disabled {
			background-color: $color-gray-600 !important;
			color: $color-gray-300 !important;
			cursor: default !important;
		}
	}

	// White button
	&.irantheme-btn-white {
		background-color: $color-gray-100;
		color: $color-gray-800;

		&:hover,
		&.active {
			background-color: $color-gray-200;
		}

		// Disable button
		&.disabled {
			background-color: $color-gray-300 !important;
			color: $color-gray-600 !important;
			cursor: default !important;
		}
	}

	// Dark outline button
	&.irantheme-btn-dark-outline {
		background: transparent;
		border: 1px solid $color-gray-900;
		color: $color-gray-900;

		&:hover,
		&.active {
			background-color: $color-gray-800;
			border-color: $color-gray-800;
			color: $color-gray-100;
		}
	}

	// White outline button
	&.irantheme-btn-white-outline {
		background: transparent;
		border: 1px solid $color-gray-100;
		color: $color-gray-100;

		&:hover,
		&.active {
			background-color: $color-white;
			border-color: $color-white;
			color: $color-gray-900;
		}
	}

	// Alignment -----------------------------------

	// Button inline (Self)
	&.irantheme-btn-inline {
		display: inline-block;
	}

	// Button block (Self)
	&.irantheme-btn-block {
		width: 100%;
	}

	// Radius styles -----------------------------------

	&.irantheme-btn-radius {
		border-radius: $border-radius-2 !important;
	}

	&.irantheme-btn-no-radius {
		border-radius: 0 !important;
	}

	&.irantheme-btn-low-radius {
		border-radius: $border-radius-low !important;
	}

	// Button sizes -----------------------------------
	&.irantheme-btn-small {
		padding: 1em 1.5em !important;
		column-gap: 0.55em;
		font-size: 0.6em !important;
		border-radius: $border-radius-low;

		i {
			font-size: 0.7rem;
		}
	}

	&.irantheme-btn-medium {
		padding: 1em 1.75em !important;
		column-gap: 0.65em;
		font-size: 0.7em !important;
		border-radius: $border-radius-medium;

		i {
			font-size: 0.8rem;
		}
	}

	&.irantheme-btn-large {
		padding: 1.25em 2em !important;
		column-gap: 0.75em;
		font-size: 0.8em !important;
		border-radius: $border-radius-high;

		i {
			font-size: 0.9rem;
		}
	}
}

// Grouping -----------------------------------

.irantheme-btn-group {

	// Buttons group inline ------------------------------------
	&.irantheme-btn-group-inline {
		display: flex;
		flex-wrap: wrap;
		column-gap: 0.5em;
		row-gap: 0.5em;

		.irantheme-btn {
			display: flex;
			align-items: center;
			width: fit-content;
		}
	}

	// Buttons group block ------------------------------------
	&.irantheme-btn-group-block {
		.irantheme-btn {
			display: block;
			margin-top: 0.5em;
			margin-bottom: 0.5em;
		}
	}

	// Buttons group block ------------------------------------
	&.irantheme-btn-group-padding-y {
		padding-top: 1.5rem;
		padding-bottom: 0.5rem;
	}

	// Buttons group no space
	&.irantheme-btn-group-no-space {
		display: flex;

		.irantheme-btn {
			border-radius: 0;

			&:not(:first-child) {
				border-right: 0;
			}

			&:first-child {
				border-top-right-radius: $border-radius-little;
				border-bottom-right-radius: $border-radius-little;
			}

			&:last-child {
				border-top-left-radius: $border-radius-little;
				border-bottom-left-radius: $border-radius-little;
			}
		}
	}

	@media only screen and (max-width:1199px) {
		font-size: 13pt;
	}

	@media only screen and (max-width:991px) {
		font-size: 12pt;
	}

	@media only screen and (max-width:767px) {
		font-size: 11pt;
	}

	@media only screen and (max-width:575px) {
		font-size: 10pt;
	}

	@media only screen and (max-width:399px) {
		font-size: 9pt;
	}
}

/*
=====================================
Notification
=====================================
*/

.irantheme-notification {
	height: fit-content;
	border-radius: var(--border-radius-medium);
	margin: 0.2rem 0.5rem;
	position: relative;
	padding: 0.75rem;
	display: none;
	flex-direction: row;
	align-items: center;

	&.irantheme-notification-success {
		color: #155724;
		background-color: #d4edda;
	}

	&.irantheme-notification-info {
		color: #004085;
		background-color: #cce5ff;

	}

	&.irantheme-notification-warning {
		color: #856404;
		background-color: #fff3cd;
	}

	&.irantheme-notification-error {
		color: #721c24;
		background-color: #f8d7da;
	}

	.irantheme-notification-message {
		font-size: 0.85rem;
		text-align: right;
	}

	.irantheme-notification-icon {
		font-size: 1.1rem;
		margin-left: 0.6rem;
	}
}