.irantheme-woocommerce-grid-products-section {

    .irantheme-woocommerce-grid-products {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        &-wrapper {
            position: relative;
            z-index: 2;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        &-group {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;

            // Padding
            &.irantheme-woocommerce-grid-products-group-padding {
                padding: 1rem;
            }

            // Border
            &.irantheme-woocommerce-grid-products-group-border {
                border-width: 1px;
                border-style: solid;
                padding: 1rem;
                // border-color: $color-gray-200;
            }

            // Shadow
            &.irantheme-woocommerce-grid-products-group-shadow {
                padding: 1rem;
                @include transition(0.2s);
            }

            // Caption
            &-caption {
                display: flex;
                flex-direction: column;
                align-items: center;
                text-align: center;
                justify-content: center;
                width: 100%;
                row-gap: 0.25rem;
                overflow: hidden;
                aspect-ratio: 1/1;
                cursor: default;

                &-img {
                    width: 3rem;
                    height: 3rem;
                    object-fit: contain;
                    @include transition(0.3s, transform, ease);
                }

                &-title {
                    font-size: 0.7rem;
                    font-weight: 600;
                    color: $color-gray-900;
                }

                &-link {
                    font-size: 0.6rem;
                    display: flex;
                    align-items: center;
                    column-gap: 0.25rem;
                    opacity: 0.8;
                    padding: 0.25rem 0.5rem;
                    line-height: normal;

                    &:hover {
                        opacity: 1;
                        transform: translateY(-1px);

                        i {
                            transform: translateX(-3px);
                        }
                    }

                    &:active {
                        transform: translateY(0);
                    }

                    i {
                        transition: 0.2s;
                        font-size: 0.6rem;
                    }
                }
            }
        }

        // Columns
        .irantheme-woocommerce-grid-products-col {
            flex-grow: 1;
            width: calc(50% - 0.5rem);
            height: auto;
        }

        // Hover shadow
        &-hover-shadow {
            @include transition(0.2s);
            overflow: hidden;

            &:hover {
                // background: $color-white;
                @include transform (translateY(-1rem));
                border-radius: $border-radius-low;
            }
        }

        // Hover scale
        &-hover-scale {
            overflow: hidden;

            .irantheme-woocommerce-grid-products-item {
                &-image {
                    img {
                        @include transition(3s, 'all', ease-in-out);
                    }
                }

                &-image:hover {
                    img {
                        animation-duration: 3s;
                        animation-name: scale;
                        animation-timing-function: cubic-bezier(0.47, 0, 0.745, 0.715);
                        animation-delay: 0.2s;
                        animation-direction: alternate;
                        animation-iteration-count: infinite;
                    }
                }
            }

            @keyframes scale {
                from {
                    @include transform(scale(1));
                }

                to {
                    @include transform(scale(1.25));
                }
            }
        }

        // Item
        &-item {
            position: relative;
            width: 100%;
            height: 100%;
            display: flex;

            &:hover {
                box-shadow: none !important;

                .irantheme-woocommerce-grid-products-item-content {
                    opacity: 1;
                    visibility: visible;
                }
            }

            // Remove extra spacing of last child
            &>*:last-child {
                margin-bottom: 0 !important;
            }

            // Images & gallery
            &-image {
                position: relative;
                width: 100%;
                overflow: hidden;

                &>a {
                    display: block;
                    position: relative;
                    width: 100%;
                    aspect-ratio: auto 1 / 1;

                    img {
                        width: 100%;
                        transition: all .2s linear;
                        -o-object-fit: contain;
                        object-fit: contain;
                        height: auto;
                    }
                }


                .irantheme-woocommerce-grid-products-item-gallery-img {
                    position: absolute;
                    top: 0;
                    right: 0;
                    width: 100%;
                    height: 100%;
                    z-index: 1;
                    opacity: 0;
                    visibility: hidden;
                    @include transition(0.2s, all, linear);
                    object-fit: contain;
                }

                &.irantheme-woocommerce-grid-products-item-image-changer {

                    // Hover image
                    &:hover {
                        .irantheme-woocommerce-grid-products-item-gallery-img {
                            opacity: 1;
                            visibility: visible;
                        }
                    }
                }
            }

            // Content
            &-content {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                gap: 0.25rem;
                position: absolute;
                top: 0;
                right: 0;
                @include transition(0.2s, all, ease-in-out);
                width: 100%;
                height: 100%;
                padding: 0.5rem;
                // background: $color-white;
                // @extend %box-shadow-dark;
                border-radius: $border-radius-medium;
                opacity: 0;
                visibility: hidden;
                z-index: 2;

                a {
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    width: 100%;
                    height: 100%;
                    gap: 0.25rem;
                }

                // Heading
                &-heading {
                    font-size: 0.65rem;
                    font-weight: 700;
                    line-height: 1.4;
                    overflow: hidden;
                    display: -webkit-box;
                    -webkit-line-clamp: 2;
                    line-clamp: 2;
                    -webkit-box-orient: vertical;
                    text-align: center;
                    @include transition(0.2s, color, ease);
                }

                // Price
                &-price {
                    font-size: 0.6rem;
                    line-height: normal;
                    font-weight: bold;
                    display: flex;
                    justify-content: flex-end;
                    align-items: center;
                    text-align: center;
                    // color: $color-gray-800;

                    .irantheme-woocommerce-products-holder {
                        display: flex;
                        align-items: center;
                        column-gap: 0.25rem;
                        justify-content: flex-end;
                    }

                    .irantheme-woocommerce-products-discount {
                        padding: 0.25rem;
                        font-size: 0.5rem;
                        border-radius: $border-radius-medium;
                    }

                    del {
                        font-size: 0.6rem;
                        // color: $color-gray-600;
                        display: block;
                        font-weight: normal;

                        .woocommerce-Price-currencySymbol {
                            display: none;
                        }
                    }

                    ins {
                        text-decoration: none;
                        display: block;
                    }

                    svg {
                        width: 1.1rem;
                        height: 1.1rem;

                        position: relative;
                        top: -2px;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            &-wrapper {}

            .irantheme-woocommerce-grid-products-group {

                // Border
                &.irantheme-woocommerce-grid-products-group-border {
                    border-color: $color-gray-100;
                }

                // Shadow
                &.irantheme-woocommerce-grid-products-group-shadow {
                    @extend %box-shadow-white;
                }

                // Caption
                &-caption {
                    background: $color-gray-100;

                    &-title {
                        color: $color-gray-900;
                    }

                    &-link {
                        color: $color-gray-600;

                        &:hover {
                            color: $color-gray-800;
                        }
                    }
                }
            }

            .irantheme-woocommerce-grid-products-col {}

            // Hover shadow
            .irantheme-woocommerce-grid-products-hover-shadow {

                &:hover {

                    .irantheme-woocommerce-grid-products-item {
                        background: $color-white;
                    }
                }
            }

            // Item
            .irantheme-woocommerce-grid-products-item {
                background: $color-white;

                // Images & gallery
                &-image {}

                // Content
                &-content {
                    background: $color-white-transparent-8;

                    &::after {
                        border-top: 10px solid $color-white;
                    }

                    // Heading
                    &-heading {
                        a {
                            color: $color-gray-900;
                        }
                    }

                    // Price
                    &-price {
                        color: $color-gray-800;

                        del {
                            color: $color-gray-600;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            &-wrapper {}

            .irantheme-woocommerce-grid-products-group {

                // Border
                &.irantheme-woocommerce-grid-products-group-border {
                    border-color: $color-gray-900;
                }

                // Shadow
                &.irantheme-woocommerce-grid-products-group-shadow {
                    @extend %box-shadow-dark;
                }

                // Caption
                &-caption {
                    background: $color-gray-900;

                    &-title {
                        color: $color-gray-100;
                    }

                    &-link {
                        color: $color-gray-400;

                        &:hover {
                            color: $color-gray-200;
                        }
                    }
                }
            }

            .irantheme-woocommerce-grid-products-col {}

            // Hover shadow
            .irantheme-woocommerce-grid-products-hover-shadow {

                &:hover {

                    .irantheme-woocommerce-grid-products-item {
                        background: $color-dark;
                    }
                }
            }

            // Item
            .irantheme-woocommerce-grid-products-item {
                background: $color-dark;

                // Images & gallery
                &-image {}

                // Content
                &-content {
                    background: $color-dark-transparent-8;

                    &::after {
                        border-top: 10px solid $color-dark;
                    }

                    // Heading
                    &-heading {
                        a {
                            color: $color-gray-100;
                        }
                    }

                    // Price
                    &-price {
                        color: $color-gray-200;

                        del {
                            color: $color-gray-400;
                        }
                    }
                }
            }
        }
    }
}