/*
=====================================
post section
=====================================
*/
.irantheme-post-box-section {
    background: transparent;
    overflow: hidden;

    .irantheme-post-box {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        .irantheme-post-box-post-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-blog-post-post-item-holder {
                // display: flex;

                .irantheme-post-box-item {
                    .irantheme-post-box-animation {
                        height: 100%;
                    }

                    .irantheme-post-box-item-inner-wrapper {
                        position: relative;
                        // background-color: $color-white;
                        height: 100%;
                        transition: 0.4s all cubic-bezier(0.785, 0.135, 0.15, 0.86);
                        overflow: hidden;

                        &.irantheme-post-box-item-border-little {
                            // border: 1px solid $color-gray-200;
                            border-style: solid;
                            border-width: 1px;
                        }

                        .irantheme-post-box-item-category {
                            position: absolute;
                            top: 0;
                            right: 0;
                            z-index: 999;

                            ul {
                                display: flex;
                                flex-wrap: wrap;
                                padding: 1rem 1rem 0;
                                font-size: 0.75rem;

                                li {
                                    // background-color: $color-white-transparent-6;
                                    margin-left: 10px;

                                    a {
                                        padding: 0.5rem;
                                    }
                                }
                            }
                        }

                        &.irantheme-post-box-without-image {
                            .irantheme-post-box-item-category {
                                position: relative;
                            }
                        }

                        .irantheme-post-box-item-img {
                            a {
                                display: block;

                                .irantheme-post-box-item-img-wrapper {
                                    overflow: hidden;
                                    position: relative;

                                    img {
                                        width: 100%;
                                        height: 100%;
                                        transform: scale(1.1);
                                        @include transition(0.2s);
                                    }

                                    &::before {
                                        content: " ";
                                        width: 100%;
                                        height: 100%;
                                        position: absolute;
                                        top: 0;
                                        right: 0;
                                        background: transparent;
                                        transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
                                        z-index: 2;
                                    }
                                }
                            }
                        }

                        .irantheme-post-box-item-content {
                            display: flex;
                            flex-direction: column;
                            padding: 2rem;

                            .irantheme-post-box-item-content-details {
                                display: flex;
                                flex-wrap: wrap;

                                &-date,
                                &-author,
                                &-comment {
                                    margin-left: 10px;
                                    font-size: 0.75rem;
                                    // color: $color-gray-600;

                                    i {
                                        margin-left: 5px;
                                    }
                                }

                            }

                            .irantheme-post-box-item-content-title {
                                font-size: 1rem;
                                padding: 0.8rem 0;
                            }

                            .irantheme-post-box-item-content-description {
                                font-size: 0.8rem;
                                // color: $color-gray-600;
                            }

                            .irantheme-post-box-item-content-read-more {
                                font-size: 0.8rem;
                                padding-top: 0.8rem;
                            }
                        }

                        &.irantheme-post-box-item-zoom-image-hover:hover {
                            .irantheme-post-box-item-img {
                                img {
                                    transform: rotate(2deg) scale(1.2);
                                }
                            }
                        }

                        &.irantheme-post-box-item-mask-hover:hover {
                            .irantheme-post-box-item-img {
                                .irantheme-post-box-item-img-wrapper {
                                    &::before {
                                        background: $color-dark-transparent-4;
                                    }
                                }
                            }
                        }

                        &.irantheme-post-box-item-transform-hover:hover {
                            transform: translateY(-15px);

                            &.irantheme-post-box-item-shadow-little {
                                box-shadow: none;
                            }

                            &:not(.irantheme-post-box-item-shadow-little) {
                                @extend %box-shadow-white;
                            }
                        }

                        &.irantheme-post-box-item-zoom-post-hover:hover {
                            transform: scale(1.03);

                            &.irantheme-post-box-item-shadow-little {
                                box-shadow: none;
                            }

                            &:not(.irantheme-post-box-item-shadow-little) {
                                @extend %box-shadow-white;
                            }
                        }

                        &.irantheme-post-box-item-shadow-hover:hover {
                            &.irantheme-post-box-item-shadow-little {
                                box-shadow: none;
                            }

                            &:not(.irantheme-post-box-item-shadow-little) {
                                @extend %box-shadow-white;
                            }
                        }
                    }

                }

            }
        }

        .irantheme-blog-post-carousel {
            padding-top: 1rem;
            padding-bottom: 2.5rem;
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            .irantheme-post-box-post-wrapper {
                .irantheme-blog-post-post-item-holder {
                    .irantheme-post-box-item {
                        .irantheme-post-box-item-inner-wrapper {
                            background-color: $color-white;

                            &.irantheme-post-box-item-border-little {
                                border-color: $color-gray-200;
                            }

                            &.irantheme-post-box-item-shadow-little {
                                @extend %box-shadow-white;
                            }

                            .irantheme-post-box-item-category {
                                ul {
                                    li {
                                        a {
                                            background-color: $color-white-transparent-6;
                                            color: $color-dark;
                                        }
                                    }
                                }
                            }

                            .irantheme-post-box-item-content {
                                .irantheme-post-box-item-content-details {

                                    &-date,
                                    &-author,
                                    &-comment {
                                        color: $color-gray-600;
                                    }
                                }

                                .irantheme-post-box-item-content-title {
                                    a {
                                        color: $color-dark;

                                        &:hover {
                                            color: $color-gray-600;
                                        }
                                    }
                                }

                                .irantheme-post-box-item-content-description {
                                    color: $color-gray-600;
                                }

                                .irantheme-post-box-item-content-read-more {
                                    color: $color-dark;
                                }
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            .irantheme-post-box-post-wrapper {
                .irantheme-blog-post-post-item-holder {
                    .irantheme-post-box-item {
                        .irantheme-post-box-item-inner-wrapper {
                            background-color: $color-dark;

                            &.irantheme-post-box-item-border-little {
                                border-color: $color-gray-800;
                            }

                            &.irantheme-post-box-item-shadow-little {
                                @extend %box-shadow-dark;
                            }

                            .irantheme-post-box-item-category {
                                ul {
                                    li {
                                        a {
                                            background-color: $color-dark-transparent-8;
                                            color: $color-white;
                                        }
                                    }
                                }
                            }

                            .irantheme-post-box-item-content {
                                .irantheme-post-box-item-content-details {

                                    &-date,
                                    &-author,
                                    &-comment {
                                        color: $color-gray-400;
                                    }
                                }

                                .irantheme-post-box-item-content-title {
                                    a {
                                        color: $color-white;

                                        &:hover {
                                            color: $color-gray-400;
                                        }
                                    }
                                }

                                .irantheme-post-box-item-content-description {
                                    color: $color-gray-400;
                                }

                                .irantheme-post-box-item-content-read-more {
                                    color: $color-white;
                                }
                            }

                        }
                    }
                }
            }
        }
    }
}