// Navbar mobile
.irantheme-single-product-navbar-mobile {
    border-radius: $border-radius-medium;
    position: fixed;
    right: 0.25rem;
    left: 0.25rem;
    bottom: 0.25rem;
    width: calc(100% - 0.5rem);
    // height: 9rem;
    height: fit-content;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    z-index: 999999;
    opacity: 0 !important;
    visibility: hidden !important;

    // Full width mode
    &.irantheme-navbar-mobile-full-width {
        right: 0;
        left: 0;
        bottom: 0;
        width: 100%;
        border-radius: 0;
    }

    &.irantheme-navbar-mobile-glass-bg {
        backdrop-filter: blur(18px) !important;
    }

    @media only screen and (max-width:992px) {
        opacity: 1 !important;
        visibility: visible !important;
    }

    // List
    &-content {
        width: 100%;

        .product-add-to-card {
            display: flex;
            flex-direction: column;
            gap: 1rem;
            width: 100%;

            &-price {
                display: flex;
                align-items: center;
                width: 100%;

                .irantheme-woocommerce-product-price {
                    padding: 0;
                    display: flex;
                    align-items: flex-end;
                    width: 100%;
                    color: $color-dark;

                    &.left_space {
                        .woocommerce-Price-currencySymbol {
                            margin-right: 0.1rem;
                        }
                    }

                    &.right_space {
                        .woocommerce-Price-currencySymbol {
                            margin-left: 0.15rem;
                        }
                    }

                    .price {
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        flex-wrap: wrap;
                        width: 100%;
                        line-height: normal;


                        .woocommerce-Price-amount {
                            font-size: 1.1rem;
                            font-weight: 600;
                            display: block;
                            margin-right: auto;
                            line-height: normal;


                            .woocommerce-Price-currencySymbol {
                                line-height: normal;

                                svg {
                                    color: $color-dark;
                                    width: 21px;
                                    height: 21px;

                                    &#currency-rial {
                                        width: 25px;
                                        height: 25px;
                                        stroke: $color-white;
                                        stroke-width: 0.8;
                                    }
                                }
                            }
                        }

                        &-label {
                            font-size: 0.8rem;
                            color: $color-gray-800;
                            margin-left: auto;
                            // margin-top: auto;
                        }

                        &.offer-percentage {
                            justify-content: flex-end;
                        }

                        .price-offer-percentage {
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            order: 2;
                            column-gap: 0.25rem;
                            padding: 0.15rem 0.5rem;
                            font-size: 0.7rem;
                            font-weight: 600;
                            text-align: center;
                            line-height: normal;
                            border-radius: $border-radius-high;
                            background-color: $color-red-shine;
                            color: $color-white;
                            box-shadow: -2px 3px 4px 0px $color-tip-error-background;
                            margin-right: 0.5rem;

                            i {
                                font-weight: 400;
                            }
                        }

                        del {
                            display: flex;
                            align-items: center;
                            order: 1;
                            color: $color-gray-500;

                            .woocommerce-Price-currencySymbol {
                                display: none;
                                opacity: 0;
                                visibility: hidden;
                                margin: 0;
                            }

                            .woocommerce-Price-amount {
                                color: $color-gray-500;
                                font-size: 0.85rem;
                                font-weight: normal;
                                margin: 0;
                            }
                        }

                        ins {
                            display: flex;
                            align-items: center;
                            margin-top: 0.5rem;
                            width: 100%;
                            text-decoration: none;
                            order: 3;
                        }
                    }

                }

                .free-product-price {
                    font-size: 1.3rem;
                    font-weight: 600;
                }
            }

            &-call-info {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                font-size: 0.8rem;
                font-weight: 600;
            }

            // External product type
            .irantheme-external-form {
                width: 100%;
            }

            &-button {
                display: flex;
                flex-direction: row;
                width: 100%;

                .irantheme-wc-single-add-to-cart-wrapper {
                    display: flex;
                    flex-direction: row;
                    align-items: center;
                    gap: 1rem;
                    width: 100%;

                    // External product type
                    &.irantheme-woocommerce-external-add-to-cart {
                        flex-direction: column;
                        justify-content: center;
                        gap: .5rem;

                        .irantheme-single-add-to-cart-button-external {
                            width: 100%;
                        }

                        .irantheme-single-add-to-cart-secoundary-button-external {
                            text-align: center;
                            font-size: .7rem;
                            color: $color-gray-700;
                            @include transition(0.2s);

                            &:hover {
                                color: $color-gray-800;
                                text-decoration: underline;
                            }
                        }
                    }
                }

                &.call-for-price-info {
                    margin-top: 0;
                    gap: 1rem;

                    .irantheme-single-add-to-cart-button {
                        width: 55%;
                    }

                    .product-add-to-card-call-info {
                        width: 45%;
                    }
                }

                .irantheme-single-product-quantity {
                    display: flex;
                    align-items: center;
                    position: relative;
                    border-radius: $border-radius-medium;
                    background-color: rgba($color-gray-500, 0.1);
                    overflow: hidden;
                    height: 45px;
                    width: 35%;
                    padding: 0.5rem;

                    .irantheme-input-text-quantity {
                        text-align: center;
                        border: none;
                        margin: 0;
                        padding: 0.5rem;
                        min-width: 3.5rem;
                        height: 100%;
                        font-size: 0.9rem;
                        font-weight: 600;
                        background-color: transparent;
                    }

                    .irantheme-quantity-btn {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        margin: 0;
                        font-size: 0.85rem;
                        height: 32px;
                        width: 80px;
                        transition: color 0.2s ease-in-out;
                        color: $color-dark;
                        background-color: $color-white;
                        border-radius: $border-radius-medium;

                        &:hover {
                            color: $color-gray-600;
                        }

                        i {
                            font-weight: 400;
                            line-height: normal;
                        }
                    }
                }

                .irantheme-single-add-to-cart-button {
                    position: relative;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    text-align: center;
                    font-size: 0.9rem;
                    font-weight: 600;
                    background-color: $color-red-shine;
                    border-width: 1px;
                    border-style: solid;
                    border-color: $color-red-shine;
                    border-radius: $border-radius-medium;
                    color: $color-white;
                    height: 45px;
                    // padding-left: 1.5rem;
                    // padding-right: 1.5rem;
                    // margin-top: 0.7rem;
                    transition: all 0.2s ease-in-out;
                    width: 65%;

                    &.outofstock {
                        cursor: default;
                        width: 100%;
                    }

                    &.contrast-light {
                        color: $color-white;
                    }

                    &.contrast-dark {
                        color: $color-dark;
                    }

                    &.text-color-white {
                        color: $color-white;
                    }

                    &.text-color-dark {
                        color: $color-dark;
                    }

                    i.icon {
                        margin-left: 0.5rem;
                        font-size: 1rem;
                    }

                    &:not(.outofstock):hover {
                        background-color: $color-white !important;
                        color: $color-red-shine;
                    }

                    span {
                        opacity: 1;
                        display: flex;
                        align-items: center;
                        line-height: normal;
                    }

                    .irantheme-animate-rotate {
                        position: absolute;
                        width: 1.5rem;
                        height: 1.5rem;
                        border-radius: 50%;
                        border-width: 2px;
                        border-style: solid;
                        border-color: $color-gray-400 $color-gray-400 $color-gray-700 $color-gray-400;
                        transition: 0.3s;
                        transition: all 0.5s linear;
                        display: none;
                    }

                    &.active {
                        span {
                            opacity: 0;
                        }

                        .irantheme-animate-rotate {
                            display: flex !important;
                        }
                    }
                }
            }
        }
    }

    // White mode
    &.white {
        background: $color-white;
        border: 1px solid $color-gray-200;
        @include box-shadow(0 -0.1rem 1rem 0.1rem rgba(31, 34, 41, 0.1));

        &.irantheme-navbar-mobile-glass-bg {
            background: rgba($color-white, 0.75);
        }

        // List
        .irantheme-navbar-mobile-list {

            // Item
            &-item {

                // Link
                &-link {
                    color: $color-gray-700;

                    &::before {
                        background: $color-primary-hover;
                    }

                    &.active,
                    &:hover {
                        color: $color-primary-hover;
                    }
                }
            }
        }
    }

    // Dark mode
    &.dark {
        background: $color-dark;
        border: 1px solid $color-gray-800;
        @include box-shadow(0 -0.1rem 1rem 0.1rem rgba(224, 221, 214, 0.1));

        &.irantheme-navbar-mobile-glass-bg {
            background: rgba($color-dark, 0.75);
        }

        // List
        .irantheme-navbar-mobile-list {

            // Item
            &-item {

                // Link
                &-link {
                    color: $color-gray-300;

                    &::before {
                        background: $color-primary-hover;
                    }

                    &.active,
                    &:hover {
                        color: $color-primary-hover;
                    }
                }
            }
        }
    }
}