// Transition
@mixin transition($time, $ele: all, $style: ease-in-out) {
  -webkit-transition: $ele $time $style;
  -moz-transition: $ele $time $style;
  -ms-transition: $ele $time $style;
  -o-transition: $ele $time $style;
  transition: $ele $time $style;
}

// Transform
@mixin transform($value) {
  -webkit-transform: $value;
  -moz-transform: $value;
  -ms-transform: $value;
  -o-transform: $value;
  transform: $value;
}

// Box shadow
@mixin box-shadow($param1, $param2: false) {
  @if $param2==false {
    -webkit-box-shadow: $param1;
    -moz-box-shadow: $param1;
    -ms-box-shadow: $param1;
    -o-box-shadow: $param1;
    box-shadow: $param1;
  }

  @else if $param2 !=false {
    -webkit-box-shadow: $param1, $param2;
    -moz-box-shadow: $param1, $param2;
    -ms-box-shadow: $param1, $param2;
    -o-box-shadow: $param1, $param2;
    box-shadow: $param1, $param2;
  }
}