.irantheme-single-product {
    &-wrapper {}

    .irantheme-physical-product {
        .irantheme-single-product-main-content {
            .product-offer-schedule {
                display: flex;
                align-items: center;
                justify-content: space-between;
                padding: 1rem 1.5rem;
                border-radius: $border-radius-medium;
                background-color: #FFEDF2;
                margin-bottom: 1rem;

                &-title {
                    display: flex;

                    &.title-svg {
                        svg {
                            width: 9rem;
                            height: 1.6rem;
                        }
                    }
                }

                &-time {
                    display: flex;
                    align-items: center;
                    color: $color-red-shine;
                    column-gap: 0.5rem;

                    .irantheme-woocommerce-products-schedule-list {
                        margin-top: 4px;

                        &-item {
                            padding: 0 !important;

                            &-count {
                                line-height: normal;
                                color: $color-red-shine !important;
                                margin-top: 0 !important;
                                margin-bottom: 0 !important;
                                font-size: 0.85rem;
                                font-weight: 700;
                            }

                            cite {
                                line-height: normal;
                                color: $color-red-shine !important;
                                margin-top: 0 !important;
                                margin-bottom: 0 !important;
                                font-size: 0.85rem;
                                font-weight: 700;
                            }
                        }
                    }
                }
            }

            .product-image {

                &-wrapper {
                    width: 100%;
                    display: flex;
                    flex-direction: column;
                    margin-bottom: 1rem;
                    position: relative;

                    &.irantheme-product-gallery-thumb-grid {
                        .product-image-thumb-slider {
                            &-wrapper {
                                display: grid;
                                gap: 0.5rem;
                                grid-template-columns: repeat(6, 1fr);
                            }

                            &-item {
                                max-width: 100% !important;
                                width: 100% !important;
                                margin: 0 !important;
                            }
                        }
                    }

                    &.irantheme-product-gallery-thumb-slider-vertical {
                        flex-direction: row;

                        @media (max-width: 767.98px) {
                            flex-direction: column;
                        }

                        .product-image-thumb-slider {
                            width: calc(15% - 0.5rem);
                            order: -1;
                            direction: ltr;

                            @media (max-width: 767.98px) {
                                direction: unset;
                                order: unset;
                                width: 100%;
                            }

                            &-wrapper {
                                margin-top: 0;

                                @media (max-width: 767.98px) {
                                    margin-top: 1rem;
                                }
                            }
                        }

                        .product-image-hero {
                            width: calc(85% - 0.5rem);

                            @media (max-width: 767.98px) {
                                width: 100%;
                            }
                        }

                        .product-image-thumb-slider-item:not(.swiper-slide-thumb-active) {
                            border: none !important;
                        }
                    }

                    &.irantheme-product-gallery-grid {

                        .product-image-hero {
                            width: 100%;
                            border: none !important;

                            &-wrapper {
                                display: grid;
                                gap: 0.5rem;
                                grid-template-columns: repeat(2, auto);
                            }
                        }
                    }
                }

                .new-product-ribbon {
                    position: absolute;
                    right: .5rem;
                    top: .5rem;
                    padding: .5rem;

                    background-color: $color-red-shine;
                    color: $color-white;
                    text-align: center;
                    line-height: normal;

                    display: flex;
                    align-items: center;
                    justify-content: center;

                    aspect-ratio: 1/1;

                    border-radius: 50%;
                    z-index: 999999;
                    font-size: 0.8rem;
                    font-weight: 600;
                    box-shadow: 2px 3px 4px 0px #e806452e;
                }

                &-hero {
                    width: 100%;
                    position: relative;
                    overflow: hidden;
                    border-width: 1px;
                    border-style: solid;
                    border-color: $color-gray-200;
                    border-radius: $border-radius-high;

                    &-wrapper {
                        align-items: center;
                    }

                    &-item {
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        border-radius: $border-radius-medium;
                        overflow: hidden;

                        &::selection {
                            background: transparent;
                        }

                        &:hover {
                            cursor: pointer;
                        }

                        img {
                            width: 100%;
                            max-width: 100%;
                            height: auto;

                            &::selection {
                                background: transparent;
                            }
                        }
                    }
                }

                &-thumb-slider {
                    width: 100%;

                    &-wrapper {
                        width: 100%;
                        margin-top: 1rem;
                    }

                    &-item {
                        // border-radius: $border-radius-medium;
                        height: auto;
                        align-self: stretch;
                        // min-height: 138px;
                        overflow: hidden;
                        border-width: 1px;
                        border-style: solid;
                        border-color: $color-gray-200;
                        border-radius: $border-radius-high;
                        position: relative;

                        &::after {
                            position: absolute;
                            content: '';
                            top: 0;
                            left: 0;
                            background: $color-white;
                            opacity: .5;
                            width: 100%;
                            height: 100%;
                        }

                        &::selection {
                            background: transparent;
                        }

                        &.swiper-slide-thumb-active {
                            border: 1px solid $color-gray-500;

                            &::after {
                                background: transparent;
                            }
                        }

                        &:hover {
                            cursor: pointer;
                        }

                        img {
                            border-radius: $border-radius-medium;
                            width: 100%;
                            max-width: 100%;
                            height: 100%;
                            object-fit: cover;
                            aspect-ratio: 1/1;

                            &::selection {
                                background: transparent;
                            }
                        }
                    }
                }
            }

            .product-info {

                padding-left: 1.5rem;

                // Hidden add to card btn and quantity input
                form.cart .quantity,
                form.cart .single_add_to_cart_button,
                .irantheme-wishlist-wrapper {
                    display: none !important;
                    opacity: 0 !important;
                    visibility: hidden !important;
                }

                &-main-desc {
                    .product-brand-category {
                        display: flex;
                        align-items: center;
                        justify-content: flex-start;

                        li {
                            display: flex;
                            align-items: center;
                            font-size: 0.75rem;
                            padding-left: 1rem;

                            span.label {
                                padding-left: 0.25rem;
                            }

                            span.value {
                                &:not(:last-child) {
                                    padding-left: 0.25rem;

                                    &::after {
                                        content: ',';
                                    }
                                }
                            }
                        }
                    }

                    .product-details-badge {
                        display: flex;
                        align-items: center;
                        justify-content: flex-start;
                        gap: 0.5rem;
                        margin-top: 1rem;
                        flex-wrap: wrap;

                        &-item {
                            display: flex;
                            line-height: normal;
                            padding: 0.32rem 0.55rem;
                            border-radius: $border-radius-high;
                            font-size: 0.67rem;
                            font-weight: 600;

                            &.has_original {
                                color: $color-quaternary;
                                background-color: #F0FAF5;
                            }

                            &.has_unoriginal {
                                color: $color-quinary-hover;
                                background-color: $color-quinary-trans;
                            }

                            &.has_warranty {
                                color: $color-red-shine;
                                background-color: #FFF5F5;
                            }

                            &.has_installments {
                                color: $color-primary;
                                background-color: #eef5ff;
                            }
                        }
                    }

                    .product-title {
                        font-size: 1.2rem;
                        font-weight: 700;
                        margin-top: 1rem;
                        margin-bottom: 0;
                        color: $color-gray-800;
                        line-height: 1.8;
                    }

                    .product-short-description {
                        padding: 0;
                        margin: 0.75rem 0 0 0;
                        font-size: 0.75rem;
                        color: $color-gray-700;
                    }

                    .product-review-summary {
                        display: flex;
                        align-items: center;
                        margin-top: 0.75rem;

                        .product-rating-star {
                            display: flex;
                            align-items: center;
                            justify-content: flex-start;
                            font-size: 0.8rem;
                            color: $color-gray-600;
                            line-height: normal;
                            margin-left: 1rem;

                            i {
                                color: $color-quinary;
                                padding-left: 0.25rem;
                                font-size: 0.8rem;
                                line-height: normal;
                                margin-bottom: 0.3rem;
                            }

                            .average {
                                padding-left: 0.5rem;
                                color: $color-dark;
                                font-weight: 600;
                            }

                        }

                        .product-review-count,
                        .product-question-count {

                            .woocommerce-review-link,
                            .woocommerce-question-link {
                                display: flex;
                                align-items: center;
                                column-gap: 0.25rem;
                                font-size: 0.7rem;
                                color: $color-gray-800;
                                line-height: normal;
                            }
                        }

                        .product-review-summary-box {
                            &:not(:last-child) {
                                margin-left: 1rem;
                            }

                            padding: 0.4rem 0.75rem;
                            border-radius: $border-radius-3;
                            background-color: rgba($color-gray-500, 0.1);
                        }
                    }

                    .product-tags {
                        display: flex;
                        gap: 0.5rem;
                        margin-top: 1.2rem;

                        &-label {
                            font-size: 0.8rem;
                            white-space: nowrap;
                            display: none;
                        }

                        &-list {
                            display: flex;
                            align-items: center;
                            gap: 0.5rem;
                            flex-wrap: wrap;
                            font-size: 0.7rem;

                            &-item {
                                background-color: $color-gray-100;
                                border-radius: $border-radius-high;
                                padding: 0.15rem 0.55rem;

                                h3 {
                                    font-size: 0.65rem;
                                    font-weight: 400;
                                    display: flex;
                                    align-items: center;
                                    column-gap: 0.5rem;
                                }
                            }
                        }
                    }

                    .stock {
                        display: none !important;
                        visibility: hidden !important;
                        opacity: 0 !important;
                    }

                    .irantheme-variations {
                        tr {
                            display: flex;
                            flex-direction: column;
                            padding: 0;

                            &:not(:first-child) {
                                margin-top: 1rem;
                            }
                        }

                        .irantheme-variation-label {
                            text-align: right;
                            // padding-left: 1rem; //For row style
                            // min-width: 4rem; //For row style
                            position: relative;
                            top: 1px;
                            margin-bottom: 0.5rem;
                            display: flex;
                            align-items: center;

                            label {
                                font-size: 0.8rem;
                                font-weight: normal;
                                color: $color-gray-800;
                                margin-bottom: 0;
                            }

                            .irantheme-variation-label-switch-selected {
                                font-size: 0.75rem;
                                font-weight: normal;
                                color: $color-gray-600;
                                display: flex;
                                align-items: center;

                                &::before {
                                    content: '';
                                    background-color: $color-gray-300;
                                    width: 6px;
                                    height: 6px;
                                    border-radius: 100%;
                                    display: block;
                                    margin: auto 0.75rem;
                                    position: relative;
                                    top: 20%;
                                    transform: translateY(-20%);
                                }
                            }
                        }

                        .irantheme-variation-value {
                            vertical-align: middle;

                            select {
                                margin: 0;
                                font-size: 0.8rem;
                                padding: 0.75rem;
                                height: auto;
                                width: auto;
                                min-width: 15rem;
                                position: relative;
                                top: -4px;
                                border-radius: $border-radius-medium;
                                border: none !important;
                                background-color: rgba($color-gray-500, 0.1);
                            }

                            .irantheme-custom-switch-var {
                                margin-bottom: 0.25rem;

                                &.disable {
                                    opacity: 0.5;
                                    cursor: not-allowed !important;
                                    background-color: $color-gray-200;
                                }

                                &.irantheme-switch-size-var.disable {
                                    background-color: $color-gray-200;
                                }

                                &.irantheme-switch-color-image-var.disable {
                                    filter: grayscale(100%) opacity(100%);
                                    -webkit-filter: grayscale(100%) opacity(100%);
                                    -moz-filter: grayscale(100%) opacity(100%);
                                }
                            }

                            .irantheme-variation-switch-color {
                                display: flex;
                                align-items: center;
                                column-gap: 0.6rem;
                                flex-wrap: wrap;

                                label {
                                    margin-left: 1rem;
                                    font-size: 0.9rem;
                                    display: none;
                                }


                                .irantheme-switch-color-var {
                                    display: flex;
                                    align-items: center;
                                    border: 1px solid $color-gray-300;
                                    border-radius: $border-radius-high;
                                    cursor: pointer;
                                    position: relative;
                                    padding: 0.25rem 0.65rem;
                                    column-gap: 0.5rem;
                                    @include transition(0.2s);

                                    .attr-color {
                                        width: 1.18rem;
                                        height: 1.18rem;
                                        border-radius: 100%;
                                        border: 1px solid $color-gray-400;
                                        display: flex;
                                        align-items: center;
                                        justify-content: center;

                                        &::after {
                                            line-height: normal;
                                            font-size: 0.6rem;
                                            font-weight: 900;
                                            content: '\f00c';
                                            font-family: $font-family-icons;
                                            display: none;
                                            @include transition(0.2s);
                                        }

                                        &.contrast-light {
                                            color: $color-white;
                                        }

                                        &.contrast-dark {
                                            color: $color-dark;
                                        }
                                    }

                                    .attr-label {
                                        font-size: 0.75rem;
                                        color: $color-gray-700;
                                    }

                                    &.active {
                                        .attr-color {
                                            &::after {
                                                display: flex;
                                            }
                                        }

                                        border-color:$color-gray-500;
                                        box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
                                        transform: scale(1.05);
                                    }
                                }

                                .irantheme-switch-color-image-var {
                                    display: flex;
                                    width: 4rem;
                                    height: auto;
                                    border: 1px solid $color-gray-300;
                                    border-radius: $border-radius-medium;
                                    margin-left: 0.55rem;
                                    cursor: pointer;
                                    position: relative;
                                    background-color: unset !important;
                                    @include transition(0.2s);

                                    img {
                                        width: 100%;
                                        max-width: 100%;
                                        height: auto;
                                        border-radius: $border-radius-medium;
                                        overflow: hidden;
                                    }

                                    &.active {
                                        border-color: $color-gray-500;
                                        box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
                                        transform: scale(1.05);
                                    }
                                }
                            }

                            .irantheme-variation-switch-size {
                                display: flex;
                                align-items: center;
                                flex-wrap: wrap;

                                label {
                                    margin-left: 1rem;
                                    font-size: 0.9rem;
                                    display: none;
                                }

                                .irantheme-switch-size-var {
                                    display: flex;
                                    align-items: center;
                                    justify-content: center;
                                    text-align: center;
                                    line-height: normal;
                                    font-size: 0.7rem;
                                    min-width: 3rem;
                                    height: 2.1rem;
                                    border: 1px solid $color-gray-400;
                                    margin-left: 0.5rem;
                                    padding: 0.15rem 0.5rem 0;
                                    cursor: pointer;
                                    position: relative;
                                    color: $color-gray-700;
                                    border-radius: $border-radius-low;

                                    &.active {
                                        border-color: $color-dark;
                                        background-color: $color-dark;
                                        color: $color-white;
                                    }
                                }
                            }

                            .irantheme-variation-select.irantheme-select-type-custom-var {
                                visibility: hidden;
                                opacity: 0;
                                display: none;
                            }
                        }

                        .irantheme-reset-variation {
                            font-size: 0.7rem;
                            font-weight: 600;
                            color: $color-gray-600;
                            display: flex;
                            align-items: center;
                            gap: 0.25rem;
                            width: fit-content;
                            padding: 0.4rem 0.8rem;
                            line-height: normal;
                            margin-top: 1rem;
                            background-color: $color-gray-200;
                            border-radius: $border-radius-medium;
                            transition: color 0.2s ease-in-out;

                            &::before {
                                content: '\f0e2';
                                font-family: $font-family-icons;
                                font-size: .8rem;
                            }

                            &:hover {
                                color: $color-dark;
                            }
                        }
                    }

                    .irantheme-single-variation-wrap {
                        display: none !important;
                        visibility: hidden !important;
                        opacity: 0 !important;
                    }

                    .product-attributes-summary {
                        &-heading {
                            display: flex;
                            align-items: center;
                            flex-wrap: nowrap;
                            margin-bottom: 1.25rem;
                            margin-top: 1.25rem;

                            &-title {
                                font-size: 0.75rem;
                                color: $color-gray-800;
                                display: flex;
                                align-items: center;
                                column-gap: 0.35rem;
                            }

                            &-line {
                                height: 1px;
                                flex-grow: 1;
                                background: linear-gradient(90deg, rgba(230, 231, 232, 0), $color-gray-300 52.08%, rgba(230, 231, 232, 0));
                                padding: 0 0.25rem;
                            }

                            &-more {
                                display: flex;
                                align-items: center;
                                column-gap: 0.35rem;
                                font-size: 0.75rem;
                                color: $color-gray-800;
                                line-height: normal;
                                padding: 0.35rem 0.45rem;
                                border-radius: $border-radius-medium;
                                // border: 1px solid $color-gray-300;

                                i {
                                    font-size: 0.65rem;
                                    font-weight: 500;
                                    line-height: normal;
                                }

                                &:hover {
                                    // background-color: #FFF5F5;
                                    color: $color-red-shine;
                                    // border-color: #FFF5F5;
                                }
                            }
                        }

                        &-list {
                            display: grid;
                            grid-template-columns: 1fr 1fr 1fr;
                            gap: 0.85rem;

                            @media (max-width: 991.98px) {
                                display: flex;
                                overflow-x: auto;
                                scroll-snap-type: x mandatory;
                                -webkit-overflow-scrolling: touch;
                                scrollbar-width: none;
                            }

                            &-item {
                                display: flex;
                                flex-direction: column;
                                justify-content: center;
                                align-items: flex-start;
                                padding: 0.75rem;
                                border: 1px solid $color-gray-300;
                                border-radius: $border-radius-medium;
                                overflow: hidden;
                                row-gap: 0.65rem;

                                @media (max-width: 991.98px) {
                                    min-width: 9rem;
                                    width: 9rem !important;
                                }

                                .attribute-label {
                                    font-size: 0.7rem;
                                    font-weight: 500;
                                    color: $color-gray-600;
                                    line-height: normal;
                                }

                                .attribute-value {
                                    font-size: 0.65rem;
                                    color: $color-gray-800;
                                    font-weight: 600;
                                    text-overflow: ellipsis;
                                    overflow: hidden;
                                    display: -webkit-box;
                                    line-clamp: 1;
                                    -webkit-line-clamp: 1;
                                    -webkit-box-orient: vertical;
                                    line-height: normal;
                                    max-width: 100%;
                                }
                            }
                        }
                    }

                    .product-details-tip {
                        display: flex;
                        column-gap: 0.6rem;
                        padding: 1rem;
                        background-image: url("data:image/svg+xml,%3csvg width='100%25' height='100%25' xmlns='http://www.w3.org/2000/svg'%3e%3crect width='100%25' height='100%25' fill='none' rx='11' ry='11' stroke='%23adb5bd' stroke-width='1' stroke-dasharray='8' stroke-dashoffset='15' stroke-linecap='square'/%3e%3c/svg%3e");
                        margin-top: 1.5rem;

                        @media (max-width: 991.98px) {
                            margin-bottom: 1rem;
                        }

                        .icon {
                            color: $color-gray-400;
                            margin-top: 4px;
                        }

                        .text {
                            font-size: 0.7rem;
                            color: $color-gray-600;
                            text-align: justify;
                        }
                    }
                }
            }
        }

        .irantheme-single-product-shopping-summary {
            &:not(.shopping-summary-mobile-mode) {
                @media (max-width: 991.98px) {
                    display: none !important;
                    opacity: 0 !important;
                    visibility: hidden !important;
                }
            }

            position: relative;

            // Hidden add to card btn and quantity input
            form.cart .quantity,
            form.cart:not(.irantheme-external-form) .single_add_to_cart_button,
            .irantheme-wishlist-wrapper,
            .irantheme-single-variation-wrap {
                display: none !important;
                opacity: 0 !important;
                visibility: hidden !important;
            }

            .irantheme-variations {
                width: 100%;
                margin-bottom: 1rem;

                tr {
                    display: flex;
                    flex-direction: column;
                    padding: 0;
                }

                .irantheme-variation-label {
                    text-align: right;
                    // padding-left: 1rem; //For row style
                    // min-width: 4rem; //For row style
                    position: relative;
                    top: 1px;
                    margin-bottom: 0.5rem;
                    display: flex;
                    align-items: center;

                    label {
                        font-size: 0.8rem;
                        font-weight: normal;
                        color: $color-gray-800;
                    }

                    .irantheme-variation-label-switch-selected {
                        font-size: 0.75rem;
                        font-weight: normal;
                        color: $color-gray-600;
                        display: flex;
                        align-items: center;

                        &::before {
                            content: '';
                            background-color: $color-gray-300;
                            width: 6px;
                            height: 6px;
                            border-radius: 100%;
                            display: block;
                            margin: auto 0.75rem;
                            position: relative;
                            top: 20%;
                            transform: translateY(-20%);
                        }
                    }
                }

                .irantheme-variation-value {
                    vertical-align: middle;

                    select {
                        margin: 0;
                        font-size: 0.8rem;
                        padding: 0.75rem;
                        height: 55px;
                        width: auto;
                        // min-width: 15rem;
                        position: relative;
                        top: -4px;
                        border-radius: $border-radius-medium;
                        border: none !important;
                        background-color: $color-gray-200;
                        width: 100%;
                    }

                    .irantheme-custom-switch-var {
                        margin-bottom: 0.25rem;

                        &.disable {
                            opacity: 0.5;
                            cursor: not-allowed !important;
                            background-color: $color-gray-200;
                        }

                        &.irantheme-switch-size-var.disable {
                            background-color: $color-gray-200;
                        }

                        &.irantheme-switch-color-image-var.disable {
                            filter: grayscale(100%) opacity(100%);
                            -webkit-filter: grayscale(100%) opacity(100%);
                            -moz-filter: grayscale(100%) opacity(100%);
                        }
                    }

                    .irantheme-variation-switch-color {
                        display: flex;
                        align-items: center;
                        column-gap: 0.6rem;
                        flex-wrap: wrap;

                        label {
                            margin-left: 1rem;
                            font-size: 0.9rem;
                            display: none;
                        }


                        .irantheme-switch-color-var {
                            display: flex;
                            align-items: center;
                            border: 1px solid $color-gray-300;
                            border-radius: $border-radius-high;
                            cursor: pointer;
                            position: relative;
                            padding: 0.25rem 0.65rem;
                            column-gap: 0.5rem;
                            @include transition(0.2s);

                            .attr-color {
                                width: 1.18rem;
                                height: 1.18rem;
                                border-radius: 100%;
                                border: 1px solid $color-gray-400;
                                display: flex;
                                align-items: center;
                                justify-content: center;

                                &::after {
                                    line-height: normal;
                                    font-size: 0.6rem;
                                    font-weight: 900;
                                    content: '\f00c';
                                    font-family: $font-family-icons;
                                    display: none;
                                    @include transition(0.2s);
                                }

                                &.contrast-light {
                                    color: $color-white;
                                }

                                &.contrast-dark {
                                    color: $color-dark;
                                }
                            }

                            .attr-label {
                                font-size: 0.75rem;
                                color: $color-gray-700;
                            }

                            &.active {
                                .attr-color {
                                    &::after {
                                        display: flex;
                                    }
                                }

                                border-color:$color-gray-500;
                                box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
                                transform: scale(1.05);
                            }
                        }

                        .irantheme-switch-color-image-var {
                            display: flex;
                            width: 4rem;
                            height: auto;
                            border: 1px solid $color-gray-300;
                            border-radius: $border-radius-medium;
                            margin-left: 0.55rem;
                            cursor: pointer;
                            position: relative;
                            background-color: unset !important;
                            @include transition(0.2s);

                            img {
                                width: 100%;
                                max-width: 100%;
                                height: auto;
                                border-radius: $border-radius-medium;
                                overflow: hidden;
                            }

                            &.active {
                                border-color: $color-gray-500;
                                box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
                                transform: scale(1.05);
                            }
                        }
                    }

                    .irantheme-variation-switch-size {
                        display: flex;
                        align-items: center;
                        flex-wrap: wrap;

                        label {
                            margin-left: 1rem;
                            font-size: 0.9rem;
                            display: none;
                        }

                        .irantheme-switch-size-var {
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            text-align: center;
                            line-height: normal;
                            font-size: 0.7rem;
                            min-width: 3rem;
                            height: 2.1rem;
                            border: 1px solid $color-gray-400;
                            margin-left: 0.5rem;
                            padding: 0.15rem 0.5rem 0;
                            cursor: pointer;
                            position: relative;
                            color: $color-gray-700;
                            border-radius: $border-radius-low;

                            &.active {
                                border-color: $color-dark;
                                background-color: $color-dark;
                                color: $color-white;
                            }
                        }
                    }

                    .irantheme-variation-select.irantheme-select-type-custom-var {
                        visibility: hidden;
                        opacity: 0;
                        display: none;
                    }
                }

                .irantheme-reset-variation {
                    font-size: 0.65rem;
                    font-weight: 600;
                    color: $color-gray-600;
                    display: flex;
                    align-items: center;
                    width: fit-content;
                    padding: 0.2rem 0.75rem;
                    margin-top: 1rem;
                    background-color: $color-gray-200;
                    border-radius: $border-radius-medium;
                    transition: color 0.2s ease-in-out;

                    &:hover {
                        color: $color-dark;
                    }
                }
            }

            @media (max-width: 991.98px) {
                padding-top: 2rem;
            }

            &-wrapper {
                display: flex;
                flex-direction: column;
                width: 100%;
                padding: 1.2rem 1.5rem;
                border-radius: 1rem;
                border: 1px solid $color-gray-200;
                box-shadow: 5px 5px 50px #f2f2f2,
                    -5px -5px 50px #ffffff;
            }

            &-tools {
                display: flex;
                align-items: center;
                justify-content: space-between;
                width: 100%;
                padding: 0.5rem 1.5rem 1rem 1.5rem;

                &.mobile-screen {
                    padding: 0 0 1rem 0;

                    @media (min-width: 992px) {
                        display: none;
                    }
                }

                .product-sku {
                    font-size: 0.75rem;
                    color: $color-gray-700;
                }

                .product-tools {
                    display: flex;
                    align-items: center;
                    column-gap: 1rem;

                    &-item {
                        button {
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            width: 2.2rem;
                            height: 2.2rem;
                            border: 1px solid $color-gray-200;
                            border-radius: 0.8rem;
                            box-shadow: -1px 2px 4px rgba(33, 37, 41, 0.05);
                            background-color: $color-white;
                            transition: all 0.2s cubic-bezier(0.28, 0.12, 0.22, 1);

                            i {
                                font-size: 1rem;
                            }

                            &.wishlist-toggle:hover {
                                background-color: #FFF5F5;
                                color: $color-red-shine;
                                border-color: #FFF5F5;
                            }

                            &.wishlist-toggle.active {
                                .fa-heart {
                                    font-weight: bold;
                                    color: $color-red-shine;
                                }
                            }

                            &.share-link:hover {
                                background-color: #eef5ff;
                                color: $color-tip-info-color;
                                border-color: #eef5ff;
                            }
                        }
                    }

                }

                &:not(:has(.product-sku)) {
                    .product-tools {
                        margin-right: auto;
                    }
                }
            }

            .product-selected-features {
                &-list {
                    &-title {
                        font-size: 0.75rem;
                        font-weight: 600;
                        color: $color-gray-800;
                        padding-bottom: 0.5rem;
                    }

                    &-item {
                        display: flex;
                        align-items: center;
                        justify-content: flex-start;
                        width: 100%;

                        &:not(:last-child) {
                            padding-bottom: 0.5rem;
                        }

                        &-label {
                            display: flex;
                            align-items: center;
                            column-gap: 0.5rem;
                            width: 49%;

                            &-text {
                                display: flex;
                                align-items: center;
                                font-size: 0.75rem;
                                color: $color-gray-700;
                                width: 85%;
                            }

                            &-icon {
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                color: $color-gray-700;
                                font-size: 1rem;
                                width: 15%;
                            }

                        }

                        &-value {
                            display: flex;
                            font-size: 0.75rem;
                            color: $color-gray-800;
                            width: 51%;
                        }
                    }
                }
            }

            // Add to card btn (external.php, grouped.php, simple.php, variation-add-to-card-button.php)
            .product-add-to-card {
                display: flex;
                flex-direction: column;
                width: 100%;

                &-price {
                    display: flex;
                    align-items: center;
                    width: 100%;

                    // Hidden in mobile
                    @media (max-width: 991.98px) {
                        display: none;
                        opacity: 0;
                        visibility: hidden;
                    }

                    .irantheme-woocommerce-product-price {
                        padding: 0;
                        display: flex;
                        // align-items: center;
                        align-items: flex-end; // for price-label
                        width: 100%;
                        color: $color-dark;

                        &.left_space {
                            .woocommerce-Price-currencySymbol {
                                margin-right: 0.1rem;
                            }
                        }

                        &.right_space {
                            .woocommerce-Price-currencySymbol {
                                margin-left: 0.15rem;
                            }
                        }

                        .price {
                            display: flex;
                            align-items: center;
                            justify-content: space-between;
                            flex-wrap: wrap;
                            width: 100%;
                            line-height: normal;


                            .woocommerce-Price-amount {
                                font-size: 1.1rem;
                                font-weight: 600;
                                display: block;
                                margin-right: auto;
                                line-height: normal;


                                .woocommerce-Price-currencySymbol {
                                    line-height: normal;

                                    svg {
                                        color: $color-dark;
                                        width: 21px;
                                        height: 21px;

                                        &#currency-rial {
                                            width: 25px;
                                            height: 25px;
                                            stroke: $color-white;
                                            stroke-width: 0.8;
                                        }
                                    }
                                }
                            }

                            &-label {
                                font-size: 0.8rem;
                                color: $color-gray-800;
                                margin-left: auto;
                            }

                            &.offer-percentage {
                                justify-content: flex-end;
                            }

                            .price-offer-percentage {
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                order: 2;
                                column-gap: 0.25rem;
                                padding: 0.15rem 0.5rem;
                                font-size: 0.65rem;
                                font-weight: 600;
                                text-align: center;
                                line-height: normal;
                                border-radius: $border-radius-high;
                                background-color: $color-red-shine;
                                color: $color-white;
                                box-shadow: -2px 3px 4px 0px $color-tip-error-background;
                                margin-right: 0.5rem;

                                i {
                                    font-weight: 400;
                                }
                            }

                            del {
                                display: flex;
                                align-items: center;
                                order: 1;
                                color: $color-gray-500;

                                .woocommerce-Price-currencySymbol {
                                    display: none;
                                    opacity: 0;
                                    visibility: hidden;
                                    margin: 0;
                                }

                                .woocommerce-Price-amount {
                                    color: $color-gray-500;
                                    font-size: 0.75rem;
                                    font-weight: normal;
                                    margin: 0;
                                }
                            }

                            ins {
                                display: flex;
                                align-items: center;
                                margin-top: 0.5rem;
                                width: 100%;
                                text-decoration: none;
                                order: 3;
                            }
                        }

                    }

                    .free-product-price {
                        font-size: 1.1rem;
                        font-weight: 600;
                    }
                }

                &-stock-status {
                    margin-top: 0.5rem;
                    font-size: 0.75rem;
                    font-weight: 900;


                    &-item {

                        &.low-stock {
                            color: $color-red-shine;
                        }

                        &.in-stock {
                            color: $color-dark;
                        }

                        &.out-of-stock {
                            color: $color-red-shine;
                        }

                        &.backorder {
                            color: $color-tip-info-color;
                        }
                    }
                }

                &-last-price {
                    display: flex;
                    justify-content: space-between;
                    margin-bottom: 2rem;

                    &-label {
                        font-size: 0.6rem;
                        font-weight: 700;
                        line-height: 1rem;
                        color: $color-gray-700;
                    }

                    &-value {
                        display: flex;
                        flex-direction: column;
                        align-items: flex-end;
                        line-height: 1rem;
                        color: $color-gray-700;

                        &-date {
                            font-size: 0.6rem;
                            font-weight: 700;
                        }

                        &-price {
                            .woocommerce-Price-amount {
                                font-size: 1rem;
                                font-weight: 600;
                                display: block;
                                margin-right: auto;
                                line-height: normal;


                                .woocommerce-Price-currencySymbol {
                                    line-height: normal;
                                    margin-right: 0.1rem;

                                    svg {
                                        color: $color-gray-700;
                                        fill: $color-gray-700;
                                        width: 21px;
                                        height: 21px;

                                        &#currency-rial {
                                            width: 25px;
                                            height: 25px;
                                            stroke: $color-white;
                                            stroke-width: 0.8;
                                        }
                                    }
                                }
                            }

                            &-label {
                                font-size: 0.8rem;
                                color: $color-gray-800;
                                margin-left: auto;
                            }

                            &.offer-percentage {
                                justify-content: flex-end;
                            }

                            .price-offer-percentage {
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                order: 2;
                                column-gap: 0.25rem;
                                padding: 0.15rem 0.5rem;
                                font-size: 0.65rem;
                                font-weight: 600;
                                text-align: center;
                                line-height: normal;
                                border-radius: $border-radius-high;
                                background-color: $color-red-shine;
                                color: $color-white;
                                box-shadow: -2px 3px 4px 0px $color-tip-error-background;
                                margin-right: 0.5rem;

                                i {
                                    font-weight: 400;
                                }
                            }

                            del {
                                display: flex;
                                align-items: center;
                                order: 1;
                                color: $color-gray-500;

                                .woocommerce-Price-currencySymbol {
                                    display: none;
                                    opacity: 0;
                                    visibility: hidden;
                                    margin: 0;
                                }

                                .woocommerce-Price-amount {
                                    color: $color-gray-500;
                                    font-size: 0.85rem;
                                    font-weight: normal;
                                    margin: 0;
                                }
                            }

                            ins {
                                display: flex;
                                align-items: center;
                                margin-top: 0.5rem;
                                width: 100%;
                                text-decoration: none;
                                order: 3;
                            }
                        }
                    }
                }

                &-call-info {
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    font-size: 0.8rem;
                    font-weight: 600;
                    padding-top: 3rem;
                }

                &-tip {
                    font-size: 0.75rem;
                    font-weight: 600;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    gap: 1rem;
                    padding-top: 1rem;

                    &-icon {
                        font-size: 2.5rem;
                        color: $color-gray-600;
                    }
                }

                &-button {
                    display: flex;
                    flex-direction: column;
                    width: 100%;
                    margin-top: 1rem;

                    // Hidden in mobile
                    @media (max-width: 991.98px) {
                        display: none;
                        opacity: 0;
                        visibility: hidden;
                    }

                    &.call-for-price-info {
                        margin-top: 0;
                    }

                    .irantheme-single-product-quantity {
                        display: flex;
                        align-items: center;
                        position: relative;
                        border-radius: $border-radius-medium;
                        background-color: rgba($color-gray-500, 0.1);
                        overflow: hidden;
                        height: 55px;
                        width: 100%;
                        padding: 0.5rem;

                        .irantheme-input-text-quantity {
                            text-align: center;
                            border: none;
                            margin: 0;
                            padding: 0.5rem;
                            min-width: 3.5rem;
                            height: 100%;
                            font-size: 0.9rem;
                            font-weight: 600;
                            background-color: transparent;
                        }

                        .irantheme-quantity-btn {
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            margin: 0;
                            font-size: 0.85rem;
                            height: 39px;
                            width: 52px;
                            transition: color 0.2s ease-in-out;
                            color: $color-dark;
                            background-color: $color-white;
                            border-radius: $border-radius-low;

                            &:hover {
                                color: $color-gray-600;
                            }

                            i {
                                font-weight: 400;
                                line-height: normal;
                            }
                        }
                    }

                    .irantheme-single-add-to-cart-button {
                        position: relative;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        text-align: center;
                        font-size: 0.8rem;
                        background-color: $color-red-shine;
                        border-width: 1px;
                        border-style: solid;
                        border-color: $color-red-shine;
                        border-radius: $border-radius-medium;
                        color: $color-white;
                        height: 55px;
                        padding-left: 1.5rem;
                        padding-right: 1.5rem;
                        margin-top: 0.7rem;
                        transition: all 0.2s ease-in-out;
                        width: 100%;

                        &.outofstock {
                            cursor: default;
                        }

                        &.contrast-light {
                            color: $color-white;
                        }

                        &.contrast-dark {
                            color: $color-dark;
                        }

                        &.text-color-white {
                            color: $color-white;
                        }

                        &.text-color-dark {
                            color: $color-dark;
                        }

                        i.icon {
                            margin-left: 0.5rem;
                            font-size: 1rem;
                        }

                        &:not(.outofstock):hover {
                            background-color: $color-white !important;
                            color: $color-red-shine;
                        }

                        span {
                            opacity: 1;
                            display: flex;
                            align-items: center;
                            line-height: normal;
                        }

                        .irantheme-animate-rotate {
                            position: absolute;
                            width: 1.5rem;
                            height: 1.5rem;
                            border-radius: 50%;
                            border-width: 2px;
                            border-style: solid;
                            border-color: $color-gray-400 $color-gray-400 $color-gray-700 $color-gray-400;
                            transition: 0.3s;
                            transition: all 0.5s linear;
                            display: none;
                        }

                        &.active {
                            span {
                                opacity: 0;
                            }

                            .irantheme-animate-rotate {
                                display: flex !important;
                            }
                        }
                    }

                    // External product type
                    .irantheme-single-add-to-cart-secoundary-button-external {
                        display: block;
                        text-align: center;
                        font-size: .7rem;
                        margin-top: 1rem;
                        color: $color-gray-700;
                        @include transition(0.2s);

                        &:hover {
                            color: $color-gray-800;
                            text-decoration: underline;
                        }
                    }
                }
            }

            .product-last-update {
                display: flex;
                align-items: center;
                justify-content: space-between;
                padding-top: 1.3rem;
                font-size: 0.7rem;
                color: $color-gray-600;

                &-label {
                    display: flex;
                    align-items: center;
                    column-gap: 0.25rem;
                    line-height: normal;

                    i {
                        font-size: 0.9rem;
                    }
                }
            }
        }
    }
}