/*
=====================================
Communication section
=====================================
*/
.irantheme-communication-line-contact-section {
    .irantheme-communication-line-contact {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;

        .irantheme-communication-line-contact-wrapper {
            position: relative;
            z-index: 9;
        }

        // Contact heading
        .irantheme-communication-line-contact-heading {
            position: relative;
            z-index: 2;
        }

        // Contact heading
        .irantheme-communication-line-contact-heading {
            position: relative;

            // All columns
            div[class*="col"] {
                margin-bottom: 0;
            }

            .irantheme-service-item {
                margin: 0.5rem 0;

                &-wrapper {
                    padding: 0 !important;
                }

                &-icon {
                    margin-bottom: unset !important;
                }

                &-content {
                    p {
                        margin-bottom: 0 !important;
                    }
                }

                &:hover {
                    transform: none !important;
                }
            }
        }

        // Contact form
        .irantheme-communication-line-contact-form {
            .row {
                row-gap: 1rem;
            }

            .col {
                margin-bottom: 0;
            }

            .irantheme-btn-large {
                font-size: 0.8rem;
                align-items: center;
                justify-content: center;
                display: flex;
                border: none;
            }

            @media screen and (max-width: 767px) {
                .row {
                    flex-direction: column;
                }
            }

            .irantheme-contact-form-desc {
                min-height: unset !important;
            }
        }

        // Item
        .irantheme-service-item {
            position: relative;
            // overflow: hidden;
            display: flex;
            height: 100%;
            z-index: 1;

            // Wrapper
            .irantheme-service-item-wrapper {
                position: relative;
                border-radius: $border-radius-low;
                background-repeat: no-repeat;
                background-position: center;
                background-size: cover;
                display: flex;
                align-items: flex-start;
                // align-items: center;
                width: 100%;
                height: 100%;

                .irantheme-service-item-wrapper-content {
                    width: 100%;

                    // Icon side
                    &.irantheme-service-item-icon-side {
                        display: flex;
                        column-gap: 1rem;

                        .irantheme-service-item-icon {
                            margin-bottom: auto;
                        }
                    }
                }
            }

            // Icon
            &-icon {
                margin-bottom: 2rem;
                position: relative;
                z-index: 9;

                i {
                    @include transition(0.2s, all, ease-in);
                    font-size: 2.5rem;
                    // color: $color-gray-600;
                }
            }

            // Content
            &-content {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                z-index: 9;

                // Horizontal mode
                &-horizontal {
                    flex-direction: row;
                    align-items: flex-start;
                    justify-content: center;
                    display: flex;

                    .irantheme-service-item-content-desc-horizontal {
                        margin-right: 1rem;
                        margin-left: 1rem;
                    }
                }

                // Title
                h3 {
                    font-size: 1rem;
                    // color: $color-dark;

                    &.irantheme-service-item-content-title-number {
                        font-size: 2.4rem;
                        font-weight: bold;
                    }
                }

                // Description
                p {
                    font-size: 0.8rem;
                    // color: $color-gray-700;

                    &.irantheme-service-item-content-desc-number {
                        font-size: 1rem;
                        line-height: 1.8rem;
                        margin-top: 1rem;
                    }

                    &.irantheme-service-item-content-desc-number-small {
                        font-size: 0.8rem;
                        line-height: 1.4rem;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Item
            .irantheme-service-item {

                // Icon
                &-icon {

                    i {
                        color: $color-gray-600;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-800;
                    }

                    // Description
                    p {
                        color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Item
            .irantheme-service-item {

                // Icon
                &-icon {
                    i {
                        color: $color-gray-400;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-200;
                    }

                    // Description
                    p {
                        color: $color-gray-300;
                    }
                }
            }
        }
    }
}