// User info (Mini profile)
.irantheme-mini-profile {
    display: flex;
    align-items: center;
    width: 100%;
    position: relative;
    z-index: 9;

    // Button holder
    &-holder {
        display: flex;
        align-items: center;
        justify-content: center;
        position: relative;
        width: 100%;
        height: 2.75rem;
        padding: 0;
        line-height: normal;
        @include transition(0.3s);
        border-radius: $border-radius-high;
        column-gap: 0.5rem;

        &.not-logged-in {
            padding: 0 1rem;
            overflow: hidden;

            &::before {
                content: "";
                filter: blur(2rem);
                width: 4rem;
                height: 4rem;
                position: absolute;
                top: -1.5rem;
                right: -1.5rem;
                border-radius: 50%;
                @include transition(0.3s);
            }

            &:hover::before {
                right: 50%;
            }

            .irantheme-mini-profile-holder-avatar {

                i {
                    font-size: 1rem;
                    position: relative;
                    top: 2px;
                }
            }

            .irantheme-mini-profile-holder-info {
                margin: 0;

                &-heading {
                    font-weight: normal;
                }
            }
        }


        &:hover,
        &.active {
            box-shadow: none !important;
        }

        &.active {
            .irantheme-mini-profile-holder-arrow {
                @include transform(rotate(180deg));
            }
        }

        // Avatar
        &-avatar {
            position: relative;

            i {
                font-size: 2rem;
            }

            &-status {
                position: absolute;
                top: 0.1rem;
                right: 0.1rem;
                width: 7px;
                height: 7px;
                border-radius: 50%;
                background: $color-quaternary;
            }
        }

        // Info
        &-info {
            display: flex;
            flex-direction: column;
            text-align: right;

            // Heading
            &-heading {
                font-size: 0.7rem;
                font-weight: bold;
                // color: $color-dark;

                span {
                    padding: 0 0.25rem;
                }
            }

            // Details
            &-details {
                font-size: 0.6rem;
                margin-top: 0.1rem;
            }

            &.irantheme-element-mobile-hidden {
                @media only screen and (max-width: 1199px) {
                    display: none;
                }
            }

            @media only screen and (max-width: 1199px) {
                display: none;
            }
        }

        // Arrow
        &-arrow {
            font-size: 0.7rem;
            // color: $color-gray-500;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            @include transition(0.2s);

            &.irantheme-element-mobile-hidden {
                @media only screen and (max-width: 1199px) {
                    display: none;
                }
            }
        }

    }

    // Dropdown menu
    &-dropdown {
        position: absolute;
        // left: 50%;
        display: none;
        // background-color: $color-white;
        // @include transform(translateX(-50%));
        border-radius: $border-radius-high;
        padding: 1rem;

        // Mini profile
        &-holder {
            // background-color: $color-gray-100;
            display: flex;
            text-align: right;
            border-bottom-width: 1px;
            border-style: solid;
            padding-bottom: 0.5rem;
            margin-bottom: 0.5rem;

            // Avatar
            &-avatar {
                margin-left: 0.5rem;

                // Holder avatar
                &-holder {
                    position: relative;
                    display: block;
                    margin: auto;

                    &-status {
                        position: absolute;
                        top: 0.3rem;
                        right: 0.3rem;
                        width: 9px;
                        height: 9px;
                        border-radius: 50%;
                        background: $color-quaternary;
                    }
                }

                i {
                    font-size: 3rem;
                }
            }

            // Info
            &-info {
                line-height: normal;
                padding-top: 0.25rem;

                // Name
                &-name {
                    font-size: 0.9rem;
                    font-weight: normal;
                    display: block;
                    margin-bottom: 0.1rem;
                    // color: $color-dark;
                }

                // Role
                &-role {
                    display: block;
                    font-size: 0.7rem;
                    // color: $color-gray-600;

                    i {
                        margin-right: 0.25rem;
                        display: inline-block;
                        font-size: 0.8rem;
                    }
                }
            }

            // User short menu
            &-menu {

                // Ul list
                &-list {

                    // Item
                    &-item {

                        // Link
                        &-link {
                            display: flex;
                            align-items: center;
                            font-size: 0.8rem;
                            width: 100%;
                            padding: 0.5rem 1rem;
                            // color: $color-gray-700;
                            border-radius: $border-radius-medium;

                            i {
                                @include transition(0.2s);
                                margin-left: 1rem;
                                font-size: 1.2rem;
                                // color: $color-gray-600;
                            }

                            &:hover,
                            &.active {
                                // background-color: $color-gray-100;
                            }

                            .irantheme-mini-profile-dropdown-holder-menu-cart {
                                display: flex;
                                flex-direction: column;
                                text-align: right;
                                align-items: flex-start;
                                width: 100%;

                                &-cell {
                                    display: flex;
                                    width: 100%;
                                    flex-direction: column;
                                    justify-content: center;
                                    align-items: flex-start;

                                    &-title {
                                        display: flex;
                                        align-items: center;
                                    }

                                    &-price,
                                    .irantheme-shopping-cart-count {
                                        font-style: normal;
                                        line-height: normal;
                                        border-radius: $border-radius-medium;
                                        text-align: center;
                                        font-size: 0.8rem;
                                        font-weight: bold;
                                        // background-color: $color-gray-200;
                                        // color: $color-dark;

                                        cite {
                                            font-style: normal;
                                            margin-right: 0.25rem;
                                        }
                                    }
                                }

                                .woocommerce-Price-currencySymbol {
                                    font-weight: normal;

                                    svg {
                                        width: 1.15rem;
                                        height: 1.15rem;
                                    }
                                }
                            }
                        }

                        // Separator (Self)
                        &.irantheme-menu-item-separator {
                            border-bottom-width: 1px;
                            border-style: solid;
                            padding-bottom: 0.5rem;
                            margin-bottom: 0.5rem;
                            // border-color: $color-gray-100;
                        }
                    }
                }
            }
        }

        // Media
        @media only screen and (max-width: 1199px) {
            width: 200px !important;
        }
    }
}

// White
.irantheme-header-white,
.irantheme-header-white-important {
    .irantheme-mini-profile {
        // background-color: $color-white;

        .irantheme-mini-profile-holder {
            &.not-logged-in {

                &::before {
                    background-color: $color-gray-400;
                }

                &:hover {
                    border-color: transparent !important;
                }
            }

            // Avatar
            &-avatar {
                i {
                    color: $color-gray-600;
                }
            }

            // Info
            &-info {
                &-heading {
                    color: $color-gray-700;
                }

                &-details {
                    color: $color-gray-500;
                }
            }

            &-arrow {
                // Arrow
                color: $color-gray-600;
            }
        }

        // Dropdown menu
        .irantheme-mini-profile-dropdown {
            background-color: $color-white;
            @extend %box-shadow-white;

            &-holder {
                background-color: $color-white;
                border-color: $color-gray-100;

                .iconsax {
                    // color: $color-gray-600;
                }

                // Info
                &-info {
                    &-name {
                        color: $color-dark;
                    }

                    &-role {
                        color: $color-gray-600;
                    }
                }

                // Menu
                &-menu {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-700;

                                i {
                                    // color: $color-gray-600;
                                }

                                &:hover,
                                &.active {
                                    background-color: $color-gray-100;
                                }

                                .irantheme-mini-profile-dropdown-holder-menu-cart {
                                    &-cell {

                                        &-title {
                                            color: $color-gray-600 !important;
                                        }

                                        &-price,
                                        .irantheme-shopping-cart-count {
                                            color: $color-dark;

                                            cite,
                                            .woocommerce-Price-currencySymbol {
                                                color: $color-gray-500;
                                            }
                                        }
                                    }

                                    .irantheme-mini-profile-dropdown-holder-menu-cart-debt {
                                        .woocommerce-Price-currencySymbol {
                                            color: $color-dark;

                                            svg {
                                                fill: $color-dark;
                                            }
                                        }
                                    }
                                }
                            }

                            // Separator
                            &.irantheme-menu-item-separator {
                                border-color: $color-gray-100;
                            }
                        }
                    }
                }
            }
        }
    }
}

