/* Comments ####################### */

#latest-comments {
    background-repeat: no-repeat;
    background-position: top;
    background-attachment: fixed;
    background-color: $color-gray-900;
    background-size: cover;
    position: relative;
}

#latest-comments .container {
    position: relative;
}

#latest-comments .swiper-pagination {
    -webkit-transform: translateY(2.5rem);
    -ms-transform: translateY(2.5rem);
    transform: translateY(2.5rem);
}

#latest-comments .swiper-pagination .swiper-pagination-bullet:not(.swiper-pagination-bullet-active) {
    background: $color-white-transparent-4;
}

#latest-comments #label-of-comments {
    position: absolute;
    right: 0;
    top: 2rem;
    padding: 0 0.5rem;
    font-size: 0.6rem;
    background: $color-dark;
    color: $color-white;
    @include transform(translateY(-50%));
    width: auto;
    height: auto;
    z-index: 3;
    cursor: default;
}

#latest-comments .latest-comments-list {
    overflow: hidden;
    padding: 4rem 0;
    position: relative;
    z-index: 2;
}

#latest-comments .latest-comments-list .comment-item {
    padding: 1rem;
    background: $color-dark;
    cursor: default;
}

#latest-comments .latest-comments-list .comment-item::before,
#latest-comments .latest-comments-list .comment-item::after {
    content: '';
    display: table;
    clear: both;
}

#latest-comments .latest-comments-list .comment-item img {
    float: right;
    width: 3rem;
    height: 3rem;
    border-radius: 50%;
}

#latest-comments .latest-comments-list .comment-item div {
    margin-right: 4rem;
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-orient: vertical;
    -webkit-box-direction: normal;
    -ms-flex-direction: column;
    flex-direction: column;
    padding-top: 0.25rem;
}

#latest-comments .latest-comments-list .comment-item div cite {
    font-size: 0.8rem;
    font-weight: bold;
    font-style: normal;
    line-height: 1rem;
    color: $color-gray-200;
    margin-bottom: 2rem;
    display: block;
}

#latest-comments .latest-comments-list .comment-item div p {
    font-size: 0.7rem;
    color: $color-gray-300;
    margin-bottom: 1rem;
}

#latest-comments .latest-comments-list .comment-item div p a {
    color: $color-gray-200;
    background: transparent;
}

#latest-comments .latest-comments-list .comment-item div>a {
    background: $color-gray-800;
    margin-right: auto;
    font-size: 0.7rem;
    padding: 0 0.5rem;
    color: $color-gray-300;
    margin-top: 0.25rem;
    border-radius: $border-radius-low;
    display: inline-block;
}

#latest-comments .latest-comments-list .comment-item div a:hover {
    background: $color-gray-700;
}

/* Footer ################################ */

#footer-luxurious {
    width: 100%;
    padding: 3rem 0;
    position: relative;
    overflow: hidden;
    background: $color-dark;
    /* Heading footer */

    .heading-footer {
        b {
            font-size: 1.4rem;
            font-weight: normal;
            color: $color-gray-100;
            display: block;
            margin-bottom: 0.5rem;
        }

        em {
            color: $color-gray-200;
            font-size: 0.9rem;
            font-style: normal;
            display: block;
        }
    }

    /* Copyright */

    .copyright {
        font-size: 0.8rem;
        color: $color-gray-300;
        padding: 1rem 0;

        a {
            color: $color-gray-300;
        }
    }

    .irantheme-social-media {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
        -webkit-box-pack: end;
        -ms-flex-pack: end;
        justify-content: flex-end;
        position: relative;
        top: -10px;
        padding: 1rem 0;

        li {
            a {
                background: $color-gray-800;
                color: $color-gray-400;
                font-size: 0.9rem;
                width: 2.5rem;
                height: 2.5rem;
                text-align: center;
                display: flex;
                align-items: center;
                justify-content: center;

                svg,
                path {
                    color: $color-gray-400;
                    fill: $color-gray-400;
                    width: 0.9rem;
                    height: 0.9rem;
                    position: relative;
                    top: -2px;
                    transition: inherit;
                }

                &:hover {
                    opacity: 0.8;
                }
            }

            &:not(:last-child) {
                margin-left: 0.5rem;
            }
        }
    }

    @media screen and (max-width: 991px) {
        & {
            text-align: center;
        }

        & .irantheme-social-media {
            -webkit-box-pack: center;
            -ms-flex-pack: center;
            justify-content: center;
        }
    }
}