// Top bar
.irantheme-header-topbar {
    position: relative;
    z-index: 9999999;

    // Topbar fixed
    &.irantheme-header-fixed {
        position: absolute;
        top: 0;
        right: 0;
        width: 100%;
        z-index: 9999;
    }

    .irantheme-navbar-topbar-alignment {
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        align-items: center;
        min-height: 2rem;
        font-size: 0.8rem;

        &>* {
            padding-right: 0.75rem;
            padding-left: 0.75rem;
        }

        &.irantheme-topbar-border-bottom {
            border-bottom-width: 1px;
            border-style: solid;
        }

        // Right alignment =====================================
        &.irantheme-topbar-alignment-right {

            // Menu
            .irantheme-secondary-navbar-menu {
                // margin-left: 1rem;
            }

            // Cell note
            .irantheme-cell-note {
                margin-left: auto;
            }

            // Social
            .irantheme-social-media {}
        }

        // Menu left alignment =====================================
        &.irantheme-topbar-alignment-menu-left {

            // Menu
            .irantheme-secondary-navbar-menu {
                margin-right: auto;
                order: 2;
            }

            // Cell note
            .irantheme-cell-note {
                margin-left: auto;
                order: 1;
            }

            // Social
            .irantheme-social-media {
                order: 3;
            }
        }

        // Menu right alignment =====================================
        &.irantheme-topbar-alignment-menu-right {

            // Menu
            .irantheme-secondary-navbar-menu {
                margin-left: auto;
            }

            // Cell note
            .irantheme-cell-note {
                margin-right: auto;
            }

            // Social
            .irantheme-social-media {}
        }
    }

    // Full width header
    .irantheme-header-alignment-full {
        width: 100%;
        padding: 0 2rem;
    }

    // Cell note
    .irantheme-cell-note {
        display: flex;
        flex-wrap: wrap;
        column-gap: 1rem;

        @media only screen and (max-width: 1199px) {
            width: 100%;
        }
    }

    // Navbar menu (Secondary)
    .irantheme-container-navbar-menu {
        display: flex;
        align-items: center;
        height: 100%;

        // First ul
        .irantheme-navbar-menu-ul {
            display: flex;
            align-items: center;
            height: 100%;
            column-gap: 1rem;
            // font-size: 0.7rem;

            // All menu item (li)
            .menu-item {
                position: relative;
                display: flex;
                align-items: center;
                height: inherit;

                &-link {
                    align-self: stretch;
                    display: flex;
                    // color: $color-gray-700;

                    .irantheme-menu-item-link-title {
                        display: flex;
                        align-items: center;
                        column-gap: 0.5rem;

                        cite {
                            font-style: normal;
                            display: flex;
                            align-items: center;

                            i {
                                display: flex;
                                align-items: center;
                                margin-left: 0.25rem;
                            }
                        }
                    }

                    // Image
                    .irantheme-menu-item-link-image {
                        width: 1rem;
                        height: 1rem;
                        object-fit: cover;
                        object-position: center;
                        margin-left: 0.35rem;
                        border-radius: $border-radius-medium;
                        position: relative;
                        top: -1px
                    }

                    // Chevron icon
                    .irantheme-menu-item-link-icon-chevron {
                        font-size: 0.6rem;
                        display: inline-block;
                        margin-right: 0.25rem;
                        display: flex;
                        align-items: center;
                        @include transition(0.3s);
                    }

                    // Mode item
                    .irantheme-menu-item-link-mode {
                        font-weight: bold;
                        font-size: 0.5rem;
                        padding: 0.05rem 0.25rem;
                        line-height: 1rem;
                        display: inline-block;
                        margin-right: 0.25rem;
                        position: relative;
                        top: -1px;
                    }
                }

                // Hover li
                &:hover>.menu-item-link {
                    // color: $color-dark;

                    // Chevron icon
                    .irantheme-menu-item-link-icon-chevron {
                        @include transform(rotate(180deg));
                    }
                }

                // Show ul submenu in hover
                &.active>ul.sub-menu {
                    display: block;
                }
            }

            // All sub menu
            .sub-menu {
                position: absolute;
                top: 100%;
                right: 0;
                min-width: 160px;
                // background: $color-white;
                // box-shadow: 0 70px 140px rgba(0, 0, 0, 0.2);
                padding: 0.5rem 0 calc(0.5rem + 10px) 0;
                display: none;
                z-index: 999999;

                li {
                    width: 100%;

                    a {
                        font-size: 0.7rem;
                        padding: 0 0.5rem;
                        display: block;
                        width: 100%;
                        color: $color-gray-700;

                        &:hover {
                            background-color: $color-gray-100;
                        }
                    }

                    // Chevron icon
                    .irantheme-menu-item-link-icon-chevron {
                        display: none;
                    }
                }
            }
        }

        // Media
        @media only screen and (max-width: 1199px) {
            display: none;
        }
    }

    // Note
    .irantheme-topbar-note {
        display: flex;
        // font-size: 0.7rem;
        // color: $color-gray-700;
        align-items: center;
        column-gap: 0.5rem;

        i {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100%;
        }
    }

    // Social
    .irantheme-social-media {
        display: flex;
        align-items: center;
        justify-content: center;
        column-gap: 0.5rem;

        li {
            a {
                display: flex;
                align-items: center;
                justify-content: center;
                // color: $color-gray-700;
                // font-size: 0.8rem;

                i {
                    @include transition(0.2s);

                }

                &:hover {
                    // color: $color-dark;
                }
            }

            svg {
                width: 0.8rem;
                height: 0.8rem;
                // color: $color-white;
                // fill: $color-white;
                line-height: 1rem;
                @include transition(0.2s);

                path {
                    // fill: $color-white;
                    @include transition(0.2s);
                }
            }
        }

        @media only screen and (max-width: 1199px) {
            display: none;
        }
    }

    /*
    =====================================
    White mode
    =====================================
    */
    &.irantheme-header-topbar-white {
        background-color: $color-white;

        .irantheme-navbar-topbar-alignment {
            border-color: $color-gray-200;
        }


        // Navbar menu (Secondary)
        .irantheme-container-navbar-menu {

            // First ul
            .irantheme-navbar-menu-ul {

                // All menu item (li)
                .menu-item {
                    &-link {
                        color: $color-dark;
                    }

                    // Hover li
                    &:hover>.menu-item-link {
                        color: $color-gray-800;
                    }
                }

                // All sub menu
                .sub-menu {
                    background: $color-white;
                    box-shadow: 0 70px 140px rgba(0, 0, 0, 0.2);

                    li {
                        a {
                            color: $color-gray-700;

                            &:hover {
                                background-color: $color-gray-100;
                            }
                        }
                    }
                }
            }
        }

        // Note
        .irantheme-topbar-note {
            color: $color-gray-900;
        }

        // Social
        .irantheme-social-media {
            li {
                a {
                    color: $color-gray-700;

                    &:hover {
                        color: $color-dark;
                    }
                }

                svg {
                    color: $color-gray-700;
                    fill: $color-gray-700;

                    path {
                        fill: $color-gray-700;
                    }
                }

                &:hover {
                    color: $color-dark;

                    svg,
                    path,
                    i {
                        color: $color-dark;
                        fill: $color-dark;
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark mode
    =====================================
    */
    &.irantheme-header-topbar-dark {
        background-color: $color-dark;

        .irantheme-navbar-topbar-alignment {
            border-color: $color-gray-800;
        }

        // Navbar menu (Secondary)
        .irantheme-container-navbar-menu {

            // First ul
            .irantheme-navbar-menu-ul {

                // All menu item (li)
                .menu-item {
                    &-link {
                        color: $color-white;
                    }

                    // Hover li
                    &:hover>.menu-item-link {
                        color: $color-gray-200;
                    }
                }

                // All sub menu
                .sub-menu {
                    background: $color-dark;
                    box-shadow: 0 70px 140px rgba(255, 255, 255, 0.2);

                    li {
                        a {
                            color: $color-gray-300;

                            &:hover {
                                background-color: $color-gray-900;
                            }
                        }
                    }
                }
            }
        }

        // Note
        .irantheme-topbar-note {
            color: $color-gray-100;
        }

        // Social
        .irantheme-social-media {
            li {
                a {
                    color: $color-white;
                    ;

                    &:hover {
                        color: $color-gray-400;
                    }

                    svg {
                        color: $color-white;
                        fill: $color-white;

                        path {
                            fill: $color-white;
                        }
                    }

                    &:hover {
                        color: $color-gray-400;

                        svg,
                        path,
                        i {
                            color: $color-gray-400;
                            fill: $color-gray-400;
                        }
                    }
                }
            }
        }
    }
}