/*
=====================================
Gallery Social Section
=====================================
*/
.irantheme-gallery-social-section {
    background: transparent;
    overflow: hidden;

    .irantheme-gallery-social {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        // Viewpoints
        .irantheme-gallery-social-post-swiper {
            .swiper-slide {
                width: fit-content;
            }
        }

        .irantheme-gallery-social-post-wrapper {

            // All columns
            div[class*="col"]:last-of-type {
                margin-bottom: 0 !important;
            }

            // Item
            .irantheme-gallery-social-post-item {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: center;
                background: transparent;
                text-align: center;
                cursor: pointer;

                &-image {
                    width: 5rem;
                    height: 5rem;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 50%;
                    position: relative;

                    .irantheme-gallery-social-post-item-mask {
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        width: 100%;
                        height: 100%;
                        z-index: 2;
                        position: absolute;
                        top: 0;
                        right: 0;
                        background: $color-dark-transparent-6;
                        color: $color-white;
                        font-size: 1rem;
                        opacity: 0;
                        visibility: hidden;
                        border-radius: 50%;
                        @include transition(0.2s);
                    }
                }

                // Image user
                &-img {
                    width: 4.75rem;
                    height: 4.75rem;
                    object-fit: cover;
                    border-radius: 50%;
                    @include transition(0.2s);
                    border-width: 0.35rem;
                    border-style: solid;
                }

                // Type
                &-type {
                    position: absolute;
                    bottom: 0;
                    font-size: 0.6rem;
                    color: $color-white;
                    border-radius: $border-radius-low;
                    padding: 0.25rem 0.5rem;
                    line-height: 1;
                    @include transition(0.2s);
                    @include transform(translateY(50%));
                    font-style: normal;

                    &.video {
                        background: $color-gray-700;
                    }

                    &.special {
                        background: $color-primary;
                    }

                    &.hot {
                        background: $color-quinary-hover;
                    }
                }

                // Heading
                &-heading {
                    margin-top: 0.25rem;
                    font-size: 0.7rem;
                    color: $color-gray-700;
                    font-weight: normal;
                }

                // Hover
                &:hover {
                    .irantheme-gallery-social-post-item-mask {
                        opacity: 1;
                        visibility: visible;
                    }

                    .irantheme-gallery-social-post-item-img {
                        border-color: transparent !important;
                        padding: 0;
                        @include transform(scale(1.1));
                    }

                    .irantheme-gallery-social-post-item-type {
                        opacity: 0;
                    }

                    .irantheme-gallery-social-post-item-heading {
                        font-weight: bold;
                    }
                }
            }
        }

        // Fixed
        .irantheme-gallery-social-fixed {
            position: fixed;
            top: 0;
            right: 0;
            width: 100vw; // Use viewport width instead of %
            height: 100vh;
            inset: 0;
            background: $color-dark-transparent-9;
            z-index: 99999999;
            display: none;

            &.active {
                display: flex;
            }

            // Navigation buttons (Jump between stories)
            &-nav {
                position: absolute;
                top: 50%;
                transform: translateY(-50%);
                z-index: 9999;
                width: 3rem;
                height: 3rem;
                border-radius: 50%;
                background: $color-dark-transparent-6;
                color: $color-white;
                border: none;
                cursor: pointer;
                display: flex;
                align-items: center;
                justify-content: center;
                transition: all 0.3s ease;
                backdrop-filter: blur(8px);
                padding: 0;
                line-height: 1;

                i {
                    font-size: 1.5rem;
                    pointer-events: none;
                }

                &:hover:not(:disabled) {
                    background: $color-dark-transparent-9;
                    transform: translateY(-50%) scale(1.1);
                }

                &:focus {
                    outline: none;
                }

                &:disabled {
                    opacity: 0.3;
                    cursor: not-allowed;
                }

                &-prev {
                    right: 1.5rem;
                }

                &-next {
                    left: 1.5rem;
                }

                // Responsive
                @media screen and (max-width: 767px) {
                    width: 2.5rem;
                    height: 2.5rem;

                    i {
                        font-size: 1.2rem;
                    }

                    &-prev {
                        right: 0.5rem;
                    }

                    &-next {
                        left: 0.5rem;
                    }
                }
            }

            // Holder of media fixed
            &-holder {
                position: absolute;
                top: 0;
                right: 0;
                width: 100%;
                height: 100%;
                display: flex;
                align-items: center;
                justify-content: center;

                // Media fixed
                &-media {
                    position: relative;

                    &-wrapper {
                        max-width: 30rem;
                        min-width: 18rem;
                        max-height: 80vh;
                        aspect-ratio: 9/16;
                        border-radius: $border-radius-high;
                        background: $color-dark-transparent-9;
                        overflow: hidden;

                        @media screen and (max-width:767px) {
                            width: 80vw;
                        }
                    }

                    &::before {
                        content: '';
                        width: 100%;
                        height: 100%;
                        border-radius: $border-radius-high;
                        background: $color-white-transparent-1;
                        position: absolute;
                        top: 0;
                        right: 0;
                        z-index: -1;
                        @include transform(translate(0.5rem, 0.5rem));
                    }

                    &::after {
                        content: '';
                        width: 100%;
                        height: 100%;
                        border-radius: $border-radius-high;
                        background: $color-white-transparent-1;
                        position: absolute;
                        top: 0;
                        left: 0;
                        z-index: -1;
                        @include transform(translate(-0.5rem, -0.5rem));
                    }

                    // Header fixed
                    &-header {
                        position: absolute;
                        bottom: 1rem;
                        right: 1rem;
                        height: auto;
                        z-index: 9;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        background: $color-dark-transparent-6;
                        border-radius: $border-radius-high;
                        width: 3rem;

                        &-list {
                            display: flex;
                            flex-direction: column;
                            justify-content: center;
                            align-items: center;
                            width: 100%;

                            &-item {

                                &-link,
                                .like-button {
                                    display: flex;
                                    flex-direction: column;
                                    align-items: center;
                                    justify-content: center;
                                    row-gap: 0.5rem;
                                    line-height: 1;
                                    padding: 0.75rem 0;
                                    color: $color-gray-400;
                                    cursor: pointer;
                                    @include transition(0.2s);

                                    &[data-exists="yes"] {

                                        i {
                                            font-weight: bold;
                                        }

                                        .like-heart-no {
                                            display: none !important;
                                        }

                                        .like-heart-yes {
                                            display: flex !important;
                                            color: $color-tertiary;
                                        }
                                    }

                                    .like-heart-no {
                                        display: flex;
                                    }

                                    .like-heart-yes {
                                        display: none;
                                    }

                                    span {
                                        cite {
                                            display: none;
                                        }
                                    }

                                    i {
                                        font-size: 1.2rem;
                                        justify-content: center;
                                    }

                                    cite,
                                    em {
                                        font-size: 0.7rem;
                                        font-style: normal;
                                    }

                                    &.irantheme-gallery-social-fixed-like {
                                        border-bottom-left-radius: 0;
                                        border-bottom-right-radius: 0;
                                    }

                                    &.irantheme-gallery-social-fixed-comments {
                                        border-top-left-radius: 0;
                                        border-top-right-radius: 0;
                                    }

                                    &.irantheme-gallery-social-fixed-close {}

                                    &:hover {
                                        color: $color-white;
                                    }
                                }
                            }
                        }
                    }

                    // Product
                    &-product {
                        position: absolute;
                        bottom: 1rem;
                        left: 1rem;
                        right: 5rem;
                        display: flex;
                        align-items: center;
                        column-gap: 0.5rem;
                        z-index: 9;

                        &-image {
                            display: flex;
                            background: $color-white-transparent-6;
                            width: 2rem;
                            height: 2rem;
                            border-radius: $border-radius-medium;
                            overflow: hidden;

                            img {
                                width: 100%;
                                height: 100%;
                            }
                        }

                        &-heading {
                            min-height: 2rem;
                            padding: 0 0.5rem;
                            display: flex;
                            align-items: center;
                            flex-wrap: nowrap;
                            background: $color-dark-transparent-6;
                            border-radius: $border-radius-medium;

                            a {
                                color: $color-gray-300;

                                h2 {
                                    font-size: 0.7rem;
                                    line-height: normal;
                                    font-weight: bold;
                                }
                            }
                        }
                    }

                    // Swiper media
                    .irantheme-gallery-social-fixed-swiper {
                        .swiper-wrapper {
                            display: flex;
                            align-items: center;
                        }

                        img,
                        video {
                            width: 100%;
                            border-radius: $border-radius-high;
                            max-width: 30rem;
                            object-fit: cover;
                        }

                        .swiper-slide {
                            position: relative;
                        }

                        .irantheme-swiper-button-slider {
                            width: calc(100% - 2rem);
                            right: 1rem;
                            @include transform(none);
                            background: none;
                            box-shadow: none;
                            display: flex;
                            align-items: center;
                            justify-content: center;

                            .swiper-pagination {
                                width: 100%;
                                column-gap: 0.25rem;

                                .swiper-pagination-bullet {
                                    flex-grow: 1;
                                    width: 100%;
                                    height: 0.15rem;
                                    border-radius: $border-radius-medium;
                                    background: $color-white-transparent-4;
                                    opacity: 0.7;

                                    &-active {
                                        width: 100%;
                                        background-color: $color-white-transparent-8;
                                        opacity: 1;
                                    }
                                }
                            }
                        }
                    }

                    .video-container {
                        position: relative;
                        width: 100%;
                        cursor: pointer;
                        background: $color-dark;
                        border-radius: $border-radius-high;

                        video {
                            width: 100%;
                            height: auto;
                            max-height: 75vh;
                            object-fit: contain;
                            display: block;
                            cursor: pointer;
                        }

                        // Play button overlay
                        .video-play-button {
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            transform: translate(-50%, -50%);
                            width: 4rem;
                            height: 4rem;
                            background: $color-dark-transparent-8;
                            border-radius: 50%;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            cursor: pointer;
                            transition: all 0.3s ease;
                            z-index: 2;
                            backdrop-filter: blur(4px);

                            i {
                                font-size: 1.5rem;
                                color: $color-white;
                            }

                            &:hover {
                                transform: translate(-50%, -50%) scale(1.1);
                                background: $color-dark-transparent-9;
                            }
                        }

                        // Paused overlay (shows on hover when video is playing)
                        .video-paused-overlay {
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            transform: translate(-50%, -50%);
                            width: 3rem;
                            height: 3rem;
                            background: $color-dark-transparent-8;
                            border-radius: 50%;
                            display: none;
                            align-items: center;
                            justify-content: center;
                            cursor: pointer;
                            transition: all 0.3s ease;
                            z-index: 2;
                            backdrop-filter: blur(4px);

                            i {
                                font-size: 1.2rem;
                                color: $color-white;
                            }

                            &:hover {
                                transform: translate(-50%, -50%) scale(1.1);
                                background: $color-dark-transparent-9;
                            }
                        }

                        // Playing state
                        &.video-playing {
                            .video-play-button {
                                display: none !important;
                            }

                            .video-paused-overlay {
                                display: none;
                            }

                            &:hover {
                                .video-paused-overlay {
                                    display: flex !important;
                                }
                            }
                        }
                    }

                    // Comments
                    .irantheme-gallery-social-fixed-comments {
                        position: absolute;
                        top: 0;
                        right: 0;
                        width: 100%;
                        height: 100%;
                        background: $color-dark-transparent-9;
                        z-index: 99;
                        border-radius: $border-radius-high;
                        overflow-x: hidden;
                        overflow-y: auto;
                        padding: 3rem 1rem 1rem;
                        display: none;

                        // Close
                        &-close {
                            position: absolute;
                            top: 1rem;
                            left: 1rem;
                            z-index: 9;
                            color: $color-white;
                            font-size: 1.4rem;

                            &:hover {
                                color: $color-gray-300;
                            }
                        }

                        // Empty
                        &-empty {
                            width: 100%;
                            display: flex;
                            flex-direction: column;
                            align-items: center;
                            justify-content: center;
                            row-gap: 1rem;
                            text-align: center;
                            padding-top: 2rem;

                            i {
                                font-size: 1.8rem;
                                color: $color-white;
                            }

                            p {
                                font-size: 1rem;
                                color: $color-white;
                            }
                        }

                        // Comment
                        &-comment {
                            padding-top: 2rem;
                            padding-bottom: 2rem;

                            &-textarea {
                                background: transparent;
                                color: $color-gray-300;
                            }

                            &-button {
                                color: $color-white;
                                display: flex;
                                column-gap: 0.5rem;
                                align-items: center;

                                i {
                                    margin: 0;
                                    width: fit-content;
                                }

                                &:focus,
                                &:active {
                                    color: $color-white;
                                }

                                &:hover {
                                    color: $color-dark;
                                }
                            }
                        }

                        // Review
                        &-review {
                            margin-bottom: 1rem;
                            border-radius: $border-radius-high;
                            padding: 1rem;
                            background: $color-white-transparent-1;
                            @include transition(0.2s);

                            &:hover {
                                background: $color-white-transparent-2;
                            }

                            &-avatar {
                                float: right;
                                width: 2.5rem;

                                img {
                                    width: 2.5rem;
                                    height: 2.5rem;
                                    object-fit: cover;
                                    border-radius: 50%;
                                }
                            }

                            &-content {
                                margin-right: 3.5rem;

                                &-name {
                                    font-size: 0.7rem;
                                    font-weight: bold;
                                    color: $color-gray-100;
                                    margin-bottom: 0.5rem;
                                }

                                &-comment {
                                    font-size: 0.7rem;
                                    color: $color-gray-300;
                                }
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Viewpoints
            .irantheme-gallery-social-post-wrapper {

                // Item
                .irantheme-gallery-social-post-item {

                    // Image user
                    &-img {
                        border-color: $color-gray-200;
                    }

                    // Heading
                    &-heading {
                        color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Viewpoints
            .irantheme-gallery-social-post-wrapper {

                // Item
                .irantheme-gallery-social-post-item {

                    // Image user
                    &-img {
                        border-color: $color-gray-800;
                    }

                    // Heading
                    &-heading {
                        color: $color-gray-300;
                    }
                }
            }
        }
    }
}

// Spin animation for loading
@keyframes spin {
    from {
        transform: translate(-50%, -50%) rotate(0deg);
    }

    to {
        transform: translate(-50%, -50%) rotate(360deg);
    }
}