/*
=====================================
Woocommerce products and category products
=====================================
*/
.irantheme-woocommerce-category-products-section {
    .irantheme-woocommerce-category-products-cat {
        cursor: default;

        &-item {
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            flex-direction: column;
            flex-wrap: wrap;
            padding: 1rem;
            height: 100%;

            &-link {
                font-size: 0.7rem;
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                column-gap: 0.25rem;
                width: fit-content;
                border-radius: $border-radius-medium;
                padding: 0.25rem 0.5rem;
                line-height: normal;
                margin-bottom: 1rem;

                i {
                    position: relative;
                    top: 1px;
                }

                &:hover {
                    opacity: 0.9;
                }
            }

            &-image {
                width: 120px;
                height: 120px;
                max-width: 100%;
                max-height: 100%;
                margin-bottom: 1rem;

                @media only screen and (max-width:1199px) {
                    width: 90px;
                    height: 90px;
                }
            }

            &-heading {
                font-size: 1.2rem;
                border-radius: $border-radius-medium;
                padding: 0.25rem 0.5rem;
                line-height: normal;
            }

            &-description {
                font-size: 0.8rem;
                border-radius: $border-radius-medium;
                padding: 0.25rem 0.5rem;
                line-height: normal;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    .irantheme-woocommerce-products.white {
        background-color: $color-white;

        .irantheme-woocommerce-category-products-cat {
            &-item {

                &-link {
                    background: $color-white;
                    color: $color-dark;
                }

                &-heading {
                    color: $color-white;
                }

                &-description {
                    color: $color-gray-200;
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    .irantheme-woocommerce-products.dark {
        background-color: $color-dark;

        .irantheme-woocommerce-category-products-cat {
            &-item {

                &-link {
                    background: $color-dark;
                    color: $color-white;
                }

                &-heading {
                    color: $color-dark;
                }

                &-description {
                    color: $color-gray-800;
                }
            }
        }
    }
}