/*
=====================================
Cart woocommerce
=====================================
*/

// Navigation
.irantheme-woocommerce-cart-navigation {
    position: fixed;
    top: 0;
    left: 0;
    width: 400px;
    max-width: 100%;
    height: 100vh;
    z-index: 99999999;
    background: $color-white;
    display: flex;
    flex-direction: column;
    @include transition(0.4s, transform, cubic-bezier(0.215, 0.61, 0.355, 1));
    @include transform(translateX(-100%));

    &.active {
        @include box-shadow(rgba(0, 0, 0, 0.2) 0px 70px 140px);
        transition-delay: 0.6s;
        transform: translateX(0) !important;
    }

    &.active {
        .irantheme-woocommerce-cart-navigation-close {
            display: flex !important;
        }
    }

    // Close nav
    &-close {
        color: $color-gray-700;
        display: none;
        align-items: center;
        justify-content: center;
        text-align: center;
        @include transition(0.4s);
        width: 2.5rem;
        height: 2.5rem;
        margin-right: auto;
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
        background: $color-white;
        border-radius: 50%;
        position: absolute;
        top: 50%;
        right: -1.25rem;
        transform: translateY(-50%);
        z-index: 99999;

        &:hover {
            box-shadow: none !important;
        }

        i {
            font-size: 1.2rem;
        }
    }

    // Header
    &-header {
        width: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 1rem;

        // Togglers
        &-togglers {
            display: flex;
            align-items: center;
            justify-content: center;
            column-gap: 0.25rem;
            width: 100%;
            border-radius: $border-radius-medium;
            background: $color-gray-200;
            padding: 0.25rem;

            &-toggle {
                flex-grow: 1;
                padding: 0.5rem 1rem;
                border-radius: $border-radius-medium;
                color: $color-gray-900;
                @include transition(0.2s);
                font-size: 0.8rem;
                width: 50%;
                line-height: normal;
                display: flex;
                align-items: center;
                justify-content: center;
                text-align: center;
                position: relative;

                i {
                    margin-left: 0.5rem;
                    font-size: 1rem;
                }

                &.active,
                &:hover {
                    background: $color-white;
                }
            }
        }
    }

    // Empty state
    &-empty {
        font-size: 0.8rem;
        color: $color-gray-700;
        text-align: center;
        padding: 4rem 1rem;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;

        &-icon {
            font-size: 7rem;
            color: $color-gray-400;
            margin-bottom: 2rem;
        }

        &-title {
            font-size: 1.3rem;
            color: $color-gray-800;
            margin-bottom: 1rem;
            font-weight: bold;
        }

        &-desc {
            font-size: 0.9rem;
            color: $color-gray-600;
            margin-bottom: 1rem;
        }
    }

    // Wrapper
    &-wrapper {
        width: 100%;
        height: 100%;
        display: flex;
        flex-direction: column;
        padding: 1rem;

        .irantheme-woocommerce-cart-form {
            width: 100%;
            height: calc(100vh - 18rem);
            overflow-y: auto;
            overflow-x: hidden;
        }

        .woocommerce-notices-wrapper {
            display: none !important;
        }
    }

    // Products list
    &-list {
        display: flex;
        flex-direction: column;

        // Item
        &-item {
            width: 100%;
            background: $color-white;
            margin-bottom: 1rem;
            display: flex;
            column-gap: 1rem;
            @include transition(0.2s);
            position: relative;
            border-bottom: 1px solid $color-gray-100;

            &:hover {
                box-shadow: none;
            }

            // Thumbnail
            &-thumbnail {

                a {
                    width: 6rem;
                    height: 6rem;
                    display: flex;
                }

                img {
                    object-fit: contain;
                    width: 100%;
                    height: 100%;
                    @include transition(0.2s);
                    border-radius: $border-radius-medium;
                    background: $color-gray-100;
                }
            }

            // Content
            &-content {
                display: flex;
                flex-direction: column;
                padding: 0.5rem 0;
                width: 100%;

                // Categories
                &-categories {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;

                    &-list {
                        display: flex;
                        flex-wrap: wrap;
                        column-gap: 0.25rem;

                        a {
                            font-size: 0.6rem;
                            color: $color-gray-600;
                        }
                    }

                    &-rating {
                        font-size: 0.6rem;
                        display: flex;
                        column-gap: 0.25rem;
                        color: $color-gray-600;

                        i {
                            color: $color-quinary;
                        }
                    }
                }

                // Heading (Name)
                &-heading {
                    font-size: 0.8rem;
                    color: $color-gray-800;
                    font-weight: bold;

                    a {
                        -webkit-line-clamp: 2;
                        line-clamp: 2;
                        display: -webkit-box;
                        -webkit-box-orient: vertical;
                        overflow: hidden;
                    }
                }

                // Info (Price & quantity)
                &-info {
                    display: flex;
                    align-items: center;
                    justify-content: flex-end;
                    font-size: 0.7rem;
                    cursor: default;
                    margin-bottom: 0.5rem;

                    // Price
                    &-price {
                        color: $color-gray-700;

                        .irantheme-woocommerce-products-price {
                            display: flex;
                            flex-direction: column;
                            justify-content: center;
                            align-items: flex-end;
                            column-gap: 0.5rem;
                            line-height: normal;

                            del {
                                color: $color-gray-500;
                                font-size: 0.6rem;

                                .woocommerce-Price-currencySymbol {
                                    display: none;
                                }
                            }

                            ins {
                                color: $color-gray-800;
                                font-size: 0.7rem;
                                font-weight: bold;
                                text-decoration: none;
                            }
                        }
                    }
                }

                // Quantity
                &-quantity {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    margin-bottom: 1rem;

                    /* Quantity buttons styles */
                    .irantheme-quantity-input-wrapper {
                        display: flex;
                        align-items: center;
                        background: transparent;
                        overflow: hidden;
                        width: fit-content;
                        min-width: 100px;
                        height: 1.5rem;
                        border: 1px solid $color-gray-200;
                        border-radius: $border-radius-medium;
                    }

                    .irantheme-quantity-btn {
                        width: 1.5rem;
                        height: 100%;
                        border: none;
                        color: $color-dark;
                        font-size: 0.8rem;
                        cursor: pointer;
                        @include transition(0.2s);
                        display: flex;
                        align-items: center;
                        justify-content: center;

                        &:hover {
                            background: $color-gray-300;
                        }

                        &:disabled {
                            opacity: 0.5;
                            cursor: not-allowed;

                            &:hover {
                                background: $color-white;
                                color: $color-gray-700;
                            }
                        }

                        i {
                            font-size: 0.6rem;
                        }
                    }

                    .irantheme-quantity-display {
                        flex: 1;
                        min-width: 1.5rem;
                        text-align: center;
                        font-size: 0.6rem;
                        color: $color-dark;
                        height: 100%;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        padding: 0 5px;
                    }
                }
            }

            // Remove item
            &-remove {
                display: flex;
                justify-content: flex-end;

                &-button {
                    height: 1.5rem;
                    border-radius: $border-radius-medium;
                    line-height: normal;
                    font-size: 1rem;
                    color: $color-gray-500;
                    display: flex;
                    align-items: center;
                    column-gap: 0.25rem;
                    font-size: 0.6rem;
                    @include transition(0.2s);

                    i {
                        font-size: 0.8rem;
                    }

                    &:hover {
                        color: $color-gray-700;
                    }
                }
            }

            /* Loading state for individual items */
            .irantheme-woocommerce-cart-navigation-list-item.irantheme-updating {
                position: relative;
                opacity: 0.8;

                .irantheme-quantity-input-wrapper {
                    opacity: 0.5;
                }

                &:after {
                    content: '';
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                    width: 20px;
                    height: 20px;
                    border: 2px solid $color-gray-300;
                    border-top-color: $color-dark;
                    border-radius: 50%;
                    animation: irantheme-spin 0.6s linear infinite;
                    z-index: 2;
                }
            }

            /* Individual item preloader */
            .irantheme-item-preloader {
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(255, 255, 255, 0.8);
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 1;
                border-radius: $border-radius-medium;
            }

            .irantheme-spinner {
                width: 20px;
                height: 20px;
                border: 2px solid $color-gray-300;
                border-top-color: $color-dark;
                border-radius: 50%;
                animation: irantheme-spin 0.6s linear infinite;
            }

            @keyframes irantheme-spin {
                to {
                    transform: rotate(360deg);
                }
            }
        }
    }

    // Footer
    &-footer {
        margin-top: auto;
        display: flex;
        flex-direction: column;
        height: fit-content;
        width: calc(100% - 2rem);
        position: absolute;
        bottom: 1rem;
        right: 1rem;
        padding: 1rem;
        background: $color-white;
        border-radius: $border-radius-medium;
        @extend %box-shadow-white;

        // Subtotal price
        &-subtotal {
            display: flex;
            justify-content: space-between;
            padding: 1rem 0;

            &-title {
                font-style: normal;
                font-size: 0.9rem;
                color: $color-dark;
            }

            &-total {
                font-size: 0.9rem;
            }
        }

        // View cart
        &-view-cart {
            a {
                display: flex;
                justify-content: center;
                align-items: center;
                font-size: 0.8rem;
                padding: 0 1rem;
                margin-bottom: 0.5rem;
                border: 1px solid $color-gray-200;
                border-radius: $border-radius-medium;
                padding: 0.5rem 0;
                color: $color-dark;

                &:hover {
                    background: $color-gray-200;
                    color: $color-gray-900;
                }
            }
        }

        // Checkout
        &-checkout {
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;

            .irantheme-btn {
                font-size: 0.8rem;
                border-radius: $border-radius-medium;
                font-weight: bold;
                border: none !important;
            }
        }
    }
}