/*
=====================================
Woocommerce hotspot
=====================================
*/
.irantheme-woocommerce-hotspot-section {

    .irantheme-woocommerce-hotspot {
        position: relative;
        display: flex;
        justify-content: center;
        // overflow: hidden;

        .irantheme-object-group {
            width: 100%;
            height: 100%;
        }

        .irantheme-woocommerce-hotspot-image {
            position: relative;
            display: flex;
            width: fit-content;
            margin: auto;

            &-img {
                height: fit-content;
                object-fit: cover;
            }

            &-dots {
                position: absolute;
                top: 0;
                left: 0;
                width: 100%;
                height: 100%;
                z-index: 9999;

                &-hot {
                    position: absolute;
                    top: 0;
                    left: 0;
                    width: 2rem;
                    height: 2rem;
                    padding: 0;
                    // background: $color-white;
                    // color: $color-dark;
                    border-radius: 50%;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    text-align: center;
                    font-size: 1rem;

                    &::after {
                        content: '';
                        position: absolute;
                        top: 0;
                        right: 0;
                        width: 2rem;
                        height: 2rem;
                        border-radius: 50%;
                        // background: $color-white;
                        @include transform(translate(50%, -50%));
                        @include transition(0.3s, all, linear);
                        @extend %animation-circle-large-to-small;
                        z-index: -1;
                        opacity: 0;
                    }

                    // Product
                    .irantheme-woocommerce-products-col {
                        // background: $color-white;
                        position: absolute;
                        bottom: 100%;
                        left: calc(-125px + 1rem);
                        width: 250px;
                        height: auto;
                        @include transition(0.25s, all, ease-in);
                        opacity: 0;
                        visibility: hidden;
                        z-index: 10;
                        cursor: default;

                        &:hover {
                            opacity: 1;
                        }
                    }

                    // Hotspot hover
                    &:hover {
                        opacity: 1;
                        // color: $color-dark;

                        .irantheme-woocommerce-products-col {
                            opacity: 1;
                            visibility: visible;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            .irantheme-woocommerce-hotspot-image {
                &-dots {

                    &-hot {
                        background: $color-white;

                        &::after {
                            background: $color-white;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            .irantheme-woocommerce-hotspot-image {
                &-dots {

                    &-hot {
                        background: $color-dark;

                        &::after {
                            background: $color-dark;
                        }
                    }
                }
            }
        }
    }
}