/*
=====================================
Additional page builder preview in sections
=====================================
*/

.irantheme-section,
.irantheme-header-main,
.irantheme-navigation {

    // Action buttons
    .irantheme-page-builder-action-section-button-wrapper {
        position: absolute;
        top: 3px;
        right: 0;
        width: 100%;
        min-width: fit-content;
        z-index: 99999999;
        overflow: hidden;

        // Holder action buttons
        .irantheme-page-builder-action-section-button {
            display: flex;
            justify-content: center;
            align-items: center;
            flex-wrap: wrap;
            min-width: fit-content;
            @include transform(translateY(calc(-100% - 1px)));
            @include transition(0.2s);

            // Button item
            &-item,
            .irantheme-page-builder-add-object-button-item {
                display: flex;
                justify-content: center;
                align-items: center;
                text-align: center;
                color: $color-white;
                background: $color-primary;
                width: 2.75rem;
                height: 2rem;
                font-size: 0.8rem;
                @include transition(0.2s);

                &:hover {
                    background: $color-dark;
                }

                &:first-child {
                    border-bottom-right-radius: $border-radius-low;
                }

                &:last-child {
                    border-bottom-left-radius: $border-radius-low;
                }
            }
        }
    }

    // Hover section separator
    .irantheme-page-builder-hover-section-separator {
        &-item {
            position: absolute;
            background: $color-primary;
            z-index: 99999999;
            @include transition(0.2s);
            opacity: 0;
            visibility: hidden;
        }

        &-top {
            top: 0;
            right: 0;
            width: 100%;
            height: 3px;
        }

        &-right {
            top: 0;
            right: 0;
            width: 3px;
            height: 100%;
        }

        &-bottom {
            right: 0;
            bottom: 0;
            width: 100%;
            height: 3px;
        }

        &-left {
            top: 0;
            left: 0;
            width: 3px;
            height: 100%;
        }
    }

    &:hover,
    &.irantheme-section-page-builder-edit-active {

        // Action buttons
        .irantheme-page-builder-action-section-button-wrapper {

            .irantheme-page-builder-action-section-button {
                &:hover {
                    z-index: 99999999;
                }

                @include transform(translateY(0));
            }
        }

        // Hover separator
        .irantheme-page-builder-hover-section-separator {

            &-top,
            &-right,
            &-bottom,
            &-left {
                opacity: 1;
                visibility: visible;
            }
        }
    }

    // Action buttons (Header)
    .irantheme-page-builder-action-section-button-wrapper-header {
        position: absolute;
        bottom: 3px;
        right: 0;
        width: 100%;
        min-width: fit-content;
        z-index: 9;
        overflow: hidden;

        // Holder action buttons
        .irantheme-page-builder-action-section-button {
            display: flex;
            justify-content: center;
            align-items: center;
            flex-wrap: wrap;
            min-width: fit-content;
            @include transform(translateY(calc(100% + 1px)));
            @include transition(0.2s);

            // Button item
            &-item,
            .irantheme-page-builder-add-object-button-item {
                display: flex;
                justify-content: center;
                align-items: center;
                text-align: center;
                color: $color-white;
                background: $color-primary;
                width: 2.75rem;
                height: 2rem;
                font-size: 0.8rem;
                @include transition(0.2s);

                &:hover {
                    background: $color-dark;
                }

                &:first-child {
                    border-top-right-radius: $border-radius-low;
                }

                &:last-child {
                    border-top-left-radius: $border-radius-low;
                }
            }
        }
    }

    &:hover,
    &.irantheme-section-page-builder-edit-active {

        // Action buttons
        .irantheme-page-builder-action-section-button-wrapper-header {
            .irantheme-page-builder-action-section-button {
                @include transform(translateY(0));
            }
        }
    }
}

// Section adder
.irantheme-page-builder-holder-adders {
    background: $color-gray-100;
    padding: 4rem 2rem;
    display: flex;
    justify-content: center;
    align-items: center;

    &-open {}
}


/*
=====================================
Hidden page builder hidden require on inactive page builder status
=====================================
*/
.irantheme-page-builder-inactive {

    .irantheme-section,
    .irantheme-header-main,
    .irantheme-navigation {

        // Action buttons
        .irantheme-page-builder-action-section-button-wrapper,
        .irantheme-page-builder-action-section-button-wrapper-header {
            display: none !important;
            opacity: 0 !important;
            visibility: hidden !important;
        }

        // Hover section separator
        .irantheme-page-builder-hover-section-separator {
            display: none !important;
            opacity: 0 !important;
            visibility: hidden !important;
        }
    }

    // Section adder
    .irantheme-page-builder-holder-adders {
        display: none !important;
        opacity: 0 !important;
        visibility: hidden !important;
    }
}

/*
=====================================
Additional page builder preview in objects
=====================================
*/

body:not(.irantheme-page-builder-inactive) {
    .irantheme-object {
        *:not(.irantheme-page-builder-action-object-button-item) {
            cursor: move !important;
        }

        .irantheme-page-builder-action-object-button-item {
            * {
                cursor: pointer !important;
            }
        }
    }

    .irantheme-object-group {
        .irantheme-page-builder-action-object-group-button-item {
            * {
                cursor: pointer !important;
            }
        }
    }
}

// Objects
