        }

        &-top {
            top: 0;
            right: 0;
            width: 100%;
            height: 2px;
        }

        &-right {
            top: 0;
            right: 0;
            width: 2px;
            height: 100%;
        }

        &-bottom {
            right: 0;
            bottom: 0;
            width: 100%;
            height: 2px;
        }

        &-left {
            top: 0;
            left: 0;
            width: 2px;
            height: 100%;
        }
    }

    &:hover,
    &.irantheme-object-page-builder-edit-active {

        // Action buttons
        .irantheme-page-builder-action-object-button-wrapper {
            .irantheme-page-builder-action-object-button {
