/*
=====================================
Service Progress Section
=====================================
*/
.irantheme-service-progress-section {
    .irantheme-service-progress {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        // Service progress
        .irantheme-service-progress-holder {
            padding: 1rem 0;

            // Item
            .irantheme-service-progress-item {
                padding: 1rem;
                @include transition(0.3s, all, ease-in-out);
                z-index: 1;

                &.irantheme-box-style-shadow:hover {
                    box-shadow: none !important;
                }

                // Box style none
                &.irantheme-box-style-none {
                    padding: 0 !important;
                }

                // Heading
                &-heading {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    position: relative;
                    flex-wrap: wrap;
                    line-height: normal;

                    // Title
                    &-title {
                        font-size: 0.8rem;
                        // color: $color-gray-600;
                        font-weight: bold;
                        display: flex;
                        column-gap: 0.25rem;
                        align-items: center;
                    }

                    // Number with percent
                    &-percent {
                        font-size: 0.8rem;
                        // color: $color-gray-600;
                        font-weight: bold;
                        display: flex;
                        column-gap: 0.25rem;
                        align-items: center;
                    }
                }


                // Bar
                &-bar {
                    padding: 0.5rem 0 0.25rem;

                    // Line (Cleared)
                    &-line {
                        position: relative;
                        width: 100%;
                        height: 0.4rem;
                        // background: $color-gray-300;
                        border-radius: $border-radius-high;

                        // Line (Filled)
                        &-filled {
                            position: absolute;
                            right: 0;
                            top: 0;
                            height: 0.4rem;
                            // background-color: $color-gray-600;
                            border-radius: $border-radius-high;
                        }
                    }
                }

                // Description
                &-description {
                    font-size: 0.7rem;
                    // color: $color-gray-600;
                    flex-basis: 100%;
                    width: 100%;
                    padding: 0 0 0.25rem;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Service progress
            .irantheme-service-progress-holder {

                // Item
                .irantheme-service-progress-item {

                    // Shadow
                    &.irantheme-box-style-shadow {
                        @extend %box-shadow-white;
                    }

                    // Shadow
                    &.irantheme-box-style-border {
                        border: 1px solid $color-gray-200;
                    }

                    // Heading
                    &-heading {

                        // Title
                        &-title {
                            color: $color-gray-700;
                        }

                        // Number with percent
                        &-percent {
                            color: $color-gray-600;

                        }
                    }


                    // Bar
                    &-bar {

                        // Line (Cleared)
                        &-line {
                            background: $color-gray-300;

                            // Line (Filled)
                            &-filled {
                                background-color: $color-gray-800;
                            }
                        }
                    }

                    // Description
                    &-description {
                        color: $color-gray-600;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Service progress
            .irantheme-service-progress-holder {

                // Item
                .irantheme-service-progress-item {

                    // Shadow
                    &.irantheme-box-style-shadow {
                        @extend %box-shadow-dark;
                    }

                    // Shadow
                    &.irantheme-box-style-border {
                        border: 1px solid $color-gray-800;
                    }

                    // Heading
                    &-heading {

                        // Title
                        &-title {
                            color: $color-gray-300;
                        }

                        // Number with percent
                        &-percent {
                            color: $color-gray-400;

                        }
                    }


                    // Bar
                    &-bar {

                        // Line (Cleared)
                        &-line {
                            background: $color-gray-700;

                            // Line (Filled)
                            &-filled {
                                background-color: $color-gray-200;
                            }
                        }
                    }

                    // Description
                    &-description {
                        color: $color-gray-400;
                    }
                }
            }
        }
    }
}