/*
=====================================
Service Number Section
=====================================
*/
.irantheme-service-number-section {
    .irantheme-service-number {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Item
        .irantheme-service-item {
            position: relative;
            // overflow: hidden;
            display: flex;
            height: 100%;
            z-index: 1;

            // Wrapper
            .irantheme-service-item-wrapper {
                position: relative;
                padding: 1rem;
                border-radius: $border-radius-low;
                background-repeat: no-repeat;
                background-position: center;
                background-size: cover;
                display: flex;
                flex-direction: column;
                align-items: flex-start;
                // align-items: center;
                width: 100%;
                height: 100%;
                overflow: hidden;

                &.irantheme-service-item-box-style {
                    padding: 2rem;
                }

                .irantheme-service-item-wrapper-content {
                    width: 100%;
                }
            }

            // Icon
            &-icon {
                margin-bottom: 1.5rem;
                position: relative;
                z-index: 9;

                i {
                    @include transition(0.2s, all, ease-in);
                    font-size: 2.5rem;
                    // color: $color-gray-600;
                }
            }

            // Content
            &-content {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: center;
                z-index: 9;

                // Title
                h3 {
                    margin-bottom: 1rem;
                    // color: $color-dark;

                    &.irantheme-service-item-content-title-number {
                        font-size: 1.8rem;
                        font-weight: 600;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                    }
                }

                // Description
                h4 {
                    // color: $color-gray-700;

                    &.irantheme-service-item-content-desc-number {
                        font-size: 1rem;
                        line-height: 1.8rem;
                        font-weight: normal;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Item
            .irantheme-service-item {

                .irantheme-service-item-wrapper {
                    &.white {
                        background-color: $color-white;
                    }

                    &.irantheme-service-item-box-style {
                        background-color: $color-gray-100;
                    }
                }

                // Icon
                &-icon {
                    i {
                        color: $color-gray-800;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-800;
                    }

                    // Description
                    h4 {
                        color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Item
            .irantheme-service-item {

                .irantheme-service-item-wrapper {
                    &.dark {
                        background-color: $color-dark;
                    }

                    &.irantheme-service-item-box-style {
                        background-color: $color-gray-900;
                    }
                }

                // Icon
                &-icon {
                    i {
                        color: $color-gray-200;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-200;
                    }

                    // Description
                    h4 {
                        color: $color-gray-300;
                    }
                }
            }
        }
    }
}