.irantheme-business-about-me-section {
    .irantheme-business-about-me {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // Row
        .row {
            align-items: center;
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        &-animation {
            width: 100%;
        }

        // Image
        &-image {
            position: relative;
            width: 100%;
            margin: 1rem auto;
            max-width: 400px;

            aspect-ratio: 1/1;

            &-img {
                width: 100%;
                height: 100%;
                object-fit: contain;
                object-position: center;
                display: block;
            }
        }

        &-holder {
            display: flex;
            column-gap: 1.5rem;
        }

        &-social {
            .irantheme-social-media {
                display: flex;
                flex-direction: column;
                row-gap: 0.5rem;

                a {
                    display: inline-flex;
                    justify-content: center;
                    align-items: center;
                    width: 2.5rem;
                    height: 2.5rem;
                    @include transition(0.2s);

                    &:hover {
                        background: $color-gray-700;
                    }
                }

                i {
                    font-size: 1.1rem;
                }

                svg,
                path {
                    width: 1.1rem;
                    height: 1.1rem;
                }
            }
        }

        // Content
        &-content {
            display: flex;
            flex-direction: column;

            @media only screen and (max-width:991px) {
                align-items: center;
                text-align: center;
            }

            &-name {
                font-size: 1.4rem;
                color: $color-dark;
                margin-bottom: 2rem;
            }

            &-about {
                font-size: 0.8rem;
                color: $color-gray-700;
                margin-bottom: 2rem;
            }

            &-signature {

                &-image {
                    position: relative;
                    height: 100%;

                    &-src {}

                    .irantheme-business-about-me-gallery-item-hover-mask {
                        position: absolute;
                        top: 0;
                        right: 0;
                        width: 100%;
                        height: 100%;
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        background: $color-dark-transparent-2;
                        opacity: 0;
                        visibility: hidden;
                        z-index: 2;
                        cursor: pointer;
                        @include transition(0.2s);

                        i {
                            font-size: 1.5rem;
                            color: $color-white;
                        }

                    }

                    &:hover {
                        .irantheme-business-about-me-gallery-item-hover-mask {
                            opacity: 1;
                            visibility: visible;
                        }
                    }

                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            .irantheme-business-about-me-social {
                .irantheme-social-media {

                    a {
                        color: $color-gray-900;

                        &:hover {
                            background: $color-dark;
                            color: $color-white;

                            svg,
                            path {
                                fill: $color-white;
                            }
                        }

                        svg,
                        path {
                            color: $color-gray-900;
                            fill: $color-gray-900;
                        }
                    }
                }
            }

            // Content
            .irantheme-business-about-me-content {

                &-about {
                    color: $color-gray-600;

                    i {
                        color: $color-gray-900;
                    }
                }

                &-name {
                    color: $color-dark;
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            .irantheme-business-about-me-social {
                .irantheme-social-media {

                    a {
                        color: $color-gray-100;

                        &:hover {
                            background: $color-white;
                            color: $color-dark;

                            svg,
                            path {
                                fill: $color-dark;
                            }
                        }

                        svg,
                        path {
                            color: $color-gray-100;
                            fill: $color-gray-100;
                        }
                    }
                }
            }

            // Content
            .irantheme-business-about-me-content {

                &-about {
                    color: $color-gray-400;

                    i {
                        color: $color-gray-100;
                    }
                }

                &-name {
                    color: $color-white;
                }
            }
        }
    }
}