// Mode item (badge)
.irantheme-menu-item-link-mode {

    // blue color
    &-blue {
        background-color: $color-primary-trans;
        color: $color-primary;
    }

    // red mode
    &-red {
        background-color: $color-tertiary-trans;
        color: $color-tertiary;
    }

    // orange mode
    &-orange {
        background-color: $color-secondary-trans;
        color: $color-secondary;
    }

    // green mode
    &-green {
        background-color: $color-quaternary-trans;
        color: $color-quaternary;
    }

    // yellow mode
    &-yellow {
        background-color: $color-quinary-trans;
        color: $color-quinary;
    }

    // purple mode
    &-purple {
        background-color: $color-senary-trans;
        color: $color-senary;
    }
}

// Mini number count
%mini-number-count {
    // Mini shopping cart count
    border-radius: 50%;
    background-clip: padding-box;
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.6rem;
    height: 1rem;
    min-width: 1rem;
    letter-spacing: 0.5px;
    line-height: 1rem;
    margin: 0 !important;
    position: absolute;
    text-align: center !important;
    bottom: 50%;
    right: 1rem;
    transform: translateY(0) translateX(1rem);
    font-weight: bold;


    span {
        position: relative;
    }
}

// Service column separator
%service-column-separator {
    &::after {
        content: '';
        position: absolute;
        left: 0;
        top: 50%;
        @include transform(translateY(-50%));
        width: 1px;
        height: 7rem;
    }
}

// Button style
%button-dark-style {
    padding: 0.75rem 1.5rem !important;
    text-decoration: none !important;
    font-size: 0.8rem;
    background: $color-dark;
    color: $color-white !important;
    margin: 0.25rem;
    line-height: 1rem;

    &:hover {
        background: $color-gray-900;
    }
}

// Button style
%button-gray-style {
    padding: 0.75rem 1.5rem !important;
    text-decoration: none !important;
    font-size: 0.8rem;
    background: $color-gray-200;
    color: $color-dark !important;
    margin: 0.25rem;
    line-height: 1rem;

    &:hover {
        background: $color-gray-300;
    }
}

// Box shadow modes for boxes
%box-shadow-white {
    box-shadow: 0px 6px 10px 0px rgba(178, 189, 206, 0.2)
}

%box-shadow-dark {
    box-shadow: 0px 6px 10px 0px rgba(77, 66, 49, 0.2)
}

// Box shadow modes for boxes
%box-shadow-small-white {
    box-shadow: 0px 2px 4px 0px rgba(178, 189, 206, 0.2)
}

%box-shadow-small-dark {
    box-shadow: 0px 2px 4px 0px rgba(77, 66, 49, 0.2)
}