.irantheme-wc-checkout {
    background-color: $color-gray-100;

    &-wrapper {
        padding: 4rem;

        @media only screen and (max-width: 767.98px) {
            padding: 2.5rem;
        }

        @media only screen and (max-width: 575.98px) {
            padding: 1rem;
        }
    }

    &-title {
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: $color-white;
        padding: 1.5rem 0.5rem;
        margin-bottom: 1rem;
        border-radius: $border-radius-medium;

        ul {
            display: flex;

            li {
                display: flex;
                align-items: center;

                span {
                    display: flex;
                    align-items: center;
                    padding: 1rem 0.75rem;
                    color: $color-gray-500 !important;

                    i {
                        font-size: 1.3rem;
                        padding-left: 0.5rem;
                    }

                    strong {
                        font-size: 0.9rem;
                    }

                }

                &::after {
                    content: '';
                    width: 94px;
                    height: 1px;
                    margin: 0.75rem;
                    background: $color-gray-500;
                    position: relative;
                    top: 1px;
                }

                &.active {
                    span {
                        color: $color-dark !important;
                        transform: scale(1.1);
                    }
                }

                &.done {
                    span {
                        color: $color-quaternary !important;
                    }
                }

                &.success {
                    &::after {
                        content: none;
                    }
                }

                @media only screen and (max-width: 767.98px) {
                    &:not(.active) {
                        display: none;
                    }

                    &::after {
                        content: none;
                    }
                }
            }
        }
    }

    &-holder {
        background-color: $color-white;
        border-radius: $border-radius-medium;
        padding: 0.35rem;
    }

    // Main default wrapper of checkout
    .wc-block-checkout {
        padding: 0;
        margin: 0;

        .wc-block-components-sidebar-layout {
            align-items: stretch;
        }

        // Main col of checkout page
        .wc-block-checkout__main {
            display: flex;
            flex-direction: column;
            padding: 2rem !important;

            .wc-block-checkout__form {
                .wc-block-components-checkout-step__heading {
                    .wc-block-components-title {
                        color: $color-gray-700 !important;
                        font-size: 0.85rem !important;
                    }
                }

                .wc-block-components-checkout-step__container {
                    .wc-block-components-checkout-step__description {
                        color: $color-gray-600 !important;
                        font-size: 0.75rem !important;
                    }
                }

                .wc-block-checkout__login-prompt {
                    padding: 0.25rem 1rem;
                    background-color: $color-gray-200 !important;
                    color: $color-gray-700 !important;
                    font-size: 0.9rem !important;
                    border-radius: $border-radius-low !important;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    font-weight: normal !important;
                    @include transition(0.2s);

                    &::before {
                        content: '\f2f6';
                        font-family: $font-family-icons;
                        font-weight: 300;
                        margin-left: 0.25rem;
                        line-height: normal;
                    }

                    &:hover {
                        background-color: $color-gray-300 !important;
                    }
                }
            }

            // Shipping button container
            .wc-block-checkout__shipping-method-container {

                @media only screen and (max-width: 576px) {

                    flex-direction: column;
                }
            }
        }

        // Sidebar col of checkout page
        .wc-block-checkout__sidebar {
            padding: 2rem !important;
            margin: 0 !important;
            background-color: $color-gray-100;
            border-radius: $border-radius-low;
            color: $color-gray-700;
            align-self: unset;
            display: flex;
            flex-direction: column;
            align-items: stretch;
            font-size: 0.85rem;
            max-width: 100%;

            .wc-block-components-panel {
                font-size: 0.85rem;
                padding: 0 !important;
            }

            .wp-block-woocommerce-checkout-order-summary-block {
                border: none;
                border-radius: unset;

                // Title of sidebar
                .wc-block-components-checkout-order-summary__title {
                    color: $color-gray-700 !important;
                    font-size: 0.85rem !important;
                    margin: 8px 0;
                    display: flex;
                    align-items: center;

                    &::before {
                        content: '\f0ca';
                        font-family: $font-family-icons;
                        margin-left: 0.5rem;
                        font-weight: 300;
                    }

                    p {
                        margin: 0;
                    }
                }

                // Content of sidebar
                .wc-block-components-checkout-order-summary__content {

                    // Order summary
                    .wp-block-woocommerce-checkout-order-summary-cart-items-block {

                        .wc-block-components-order-summary {
                            padding: 0;

                            .wc-block-components-order-summary__content {

                                // Order summary item
                                .wc-block-components-order-summary-item {
                                    @media only screen and (max-width: 1300px) {
                                        flex-direction: column;
                                        align-items: center;
                                    }

                                    // Order summary item image
                                    .wc-block-components-order-summary-item__image {
                                        width: 3rem;

                                        img {
                                            width: 3rem;
                                            height: 3rem;
                                            max-width: 3rem;
                                            border-radius: $border-radius-low;
                                            border: 1px solid $color-gray-200;
                                        }

                                        .wc-block-components-order-summary-item__quantity {
                                            background: $color-dark !important;
                                            color: $color-white !important;
                                            border: none !important;
                                            min-width: 20px;
                                            height: 20px;
                                            padding: 0 !important;
                                            line-height: normal;

                                            span {
                                                font-size: 0.75rem !important;
                                                line-height: normal;
                                                padding: 0 0.15rem;
                                            }
                                        }
                                    }

                                    // Order summary item description
                                    .wc-block-components-order-summary-item__description {
                                        padding-right: 26px !important;
                                        padding-left: 20px !important;

                                        @media only screen and (max-width: 1300px) {
                                            padding-right: 0 !important;
                                            padding-left: 0 !important;
                                            text-align: center;
                                        }

                                        .wc-block-components-product-price {
                                            font-size: 0.6rem;

                                            .wc-block-components-product-price__regular {
                                                color: $color-gray-600;
                                            }
                                        }

                                        .wc-block-components-product-metadata {
                                            .wc-block-components-product-metadata__description {
                                                display: none;
                                            }

                                            .wc-block-components-product-details {
                                                color: $color-gray-600 !important;
                                                display: flex;
                                                align-items: center;
                                                flex-wrap: wrap;

                                                @media only screen and (max-width: 1300px) {
                                                    justify-content: center;
                                                }

                                                li {
                                                    padding-left: 0.5rem;

                                                    &:not(:first-child) {
                                                        padding-right: 0.5rem;
                                                    }

                                                    &:not(:last-child) {
                                                        border-left-width: 1px;
                                                        border-left-style: solid;
                                                        border-left-color: $color-gray-400;
                                                    }
                                                }
                                            }
                                        }

                                    }

                                    .wc-block-components-order-summary-item__total-price {
                                        font-size: 0.6rem;

                                        @media only screen and (max-width: 1300px) {
                                            margin-right: unset !important;
                                            text-align: center !important;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // Coupon
                    .wp-block-woocommerce-checkout-order-summary-coupon-form-block {
                        .wc-block-components-panel__button {
                            display: flex;
                            align-items: center;

                            &::before {
                                content: '\25';
                                font-family: $font-family-icons;
                                margin-left: 0.5rem;
                                font-weight: 300;
                            }
                        }

                        .wc-block-components-totals-coupon__button {
                            width: auto !important;
                        }
                    }

                    // Invoice Total
                    .wc-block-components-totals-item {
                        padding: 0 !important;

                        em {
                            font-style: normal !important;
                        }
                    }

                    .wp-block-woocommerce-checkout-order-summary-totals-block {
                        font-size: 0.85rem !important;

                        .wc-block-components-totals-shipping {
                            .wc-block-components-shipping-address {
                                display: flex;
                                align-items: center;

                                &::before {
                                    content: '\f3c5';
                                    font-family: $font-family-icons;
                                    margin-left: 0.25rem;
                                    font-weight: 300;
                                }
                            }
                        }
                    }

                    .wc-block-components-totals-footer-item {
                        .wc-block-components-totals-item__label {
                            font-size: 0.85rem !important;
                        }

                        .wc-block-components-totals-item__value {
                            font-size: 0.85rem !important;
                        }

                        .wc-block-components-totals-item__description {
                            font-size: 0.85rem !important;
                        }
                    }
                }

            }



        }

        // Input and button
        .wc-block-components-text-input input[type=text] {
            border-color: $color-gray-300 !important;
            box-shadow: none !important;
            font-size: 0.85rem;
            color: $color-gray-800;

            &:focus {
                border-color: $color-dark !important;
            }
        }

        .wc-block-components-text-input input[type=tel] {
            border-color: $color-gray-300 !important;
            box-shadow: none !important;
            font-size: 0.85rem;
            color: $color-gray-800;

            &:focus {
                border-color: $color-dark !important;
            }
        }

        .wc-block-components-text-input input,
        .wc-block-components-text-input textarea,
        .wc-block-checkout__add-note .wc-block-components-textarea,
        .wc-block-components-combobox .wc-block-components-combobox-control input.components-combobox-control__input:focus,
        .wc-block-components-combobox .wc-block-components-combobox-control input.components-combobox-control__input[aria-expanded=true],
        .wc-block-components-combobox .wc-block-components-combobox-control input.components-combobox-control__input,
        .wc-blocks-components-select select {
            font-size: 0.85rem;
            color: $color-gray-800;
            border-color: $color-gray-300 !important;
            box-shadow: none !important;

            &:focus {
                border-color: $color-dark !important;
            }

        }

        .wc-blocks-components-select select {
            border: 1px solid;
        }

        .wc-blocks-components-select .wc-blocks-components-select__container {
            border: none !important;
        }

        .wc-block-components-validation-error>p {
            font-size: 0.7rem;
            color: $color-tertiary;
        }

        .wc-block-components-text-input label,
        .wc-blocks-components-select label {
            font-size: 0.85rem !important;
            color: $color-gray-700 !important;
        }

        .wc-block-components-text-input.has-error label,
        .wc-block-components-validation-error {
            color: $color-gray-700 !important;
        }

        .wc-block-components-text-input.has-error input {
            border-color: $color-tertiary !important;
        }

        // Shipping button
        .wc-block-components-button.wc-block-checkout__shipping-method-option {
            background-color: $color-white !important;
            border-radius: $border-radius-low !important;
            border: 1px solid $color-gray-200 !important;
            outline: none !important;

            .wc-block-checkout__shipping-method-option-title {
                font-size: 0.85rem !important;
                color: $color-gray-700 !important;
                font-weight: normal !important;
            }

            svg {
                width: 25px;
                height: 25px;
                color: $color-gray-700;
            }

            &.wc-block-checkout__shipping-method-option--selected {
                .wc-block-checkout__shipping-method-option-title {
                    color: $color-gray-800 !important;
                }

                svg {
                    color: $color-gray-800;
                }

                background-color: $color-gray-200 !important;
            }
        }

        // Radio control
        .wc-block-components-radio-control {
            font-size: 0.85rem !important;

            .wc-block-components-radio-control__option-layout {
                .read-more-content {
                    padding: 0.5rem 0.75rem;
                    background-color: $color-tip-info-background;
                    color: $color-tip-info-color;
                    border-radius: $border-radius-low;
                    display: flex;
                    align-items: center;
                    font-size: 0.75rem;

                    &::before {
                        content: '\e243';
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        font-family: $font-family-icons;
                        font-size: 1.1rem;
                        margin-left: 0.5rem;
                        font-weight: 300;
                    }
                }
            }
        }

        .wc-block-components-radio-control .wc-block-components-radio-control__input {
            min-height: 12px !important;
            min-width: 12px !important;
            height: 12px !important;
            width: 12px !important;
            margin-top: 6.5px !important;

            &:focus {
                outline: none !important;
                outline-offset: unset !important;
            }
        }

        .wc-block-components-radio-control .wc-block-components-radio-control__input:checked:before {
            min-height: 6px !important;
            min-width: 6px !important;
            height: 6px !important;
            width: 6px !important;
        }

        // Local pickup

        .wc-block-components-radio-control--highlight-checked {
            &::after {
                content: unset !important;
            }
        }

        .wc-block-components-radio-control--highlight-checked label.wc-block-components-radio-control__option--checked-option-highlighted,
        .wc-block-components-radio-control-accordion-option--checked-option-highlighted {
            box-shadow: none !important;
            border-radius: $border-radius-low !important;
            background-color: $color-gray-100 !important;

            &::after {
                content: unset !important;
            }
        }

        // Shipping
        .wc-block-components-shipping-rates-control {
            font-size: 0.85rem !important;

            .wc-block-components-radio-control__input {
                margin-top: 0 !important;
            }
        }

        // Payment options
        .wc-block-checkout__payment-method {
            .wc-block-components-radio-control__input {
                margin-top: 0 !important;
            }
        }

        .wc-block-components-radio-control-accordion-option--checked-option-highlighted {
            box-shadow: none !important;
            border-radius: $border-radius-low !important;

            .wc-block-components-radio-control-accordion-content {
                div {
                    padding: 0.5rem 0.75rem;
                    background-color: $color-tip-info-background;
                    color: $color-tip-info-color;
                    border-radius: $border-radius-low;
                    display: flex;
                    align-items: center;
                    font-size: 0.75rem;

                    &::before {
                        content: '\e243';
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        font-family: $font-family-icons;
                        font-size: 1.1rem;
                        margin-left: 0.5rem;
                        font-weight: 300;
                    }
                }
            }
        }

        .wc-block-checkout__actions {
            padding-bottom: 1.5rem !important;
        }

        // Address wrapper
        .wc-block-components-address-address-wrapper {
            .wc-block-components-address-card-wrapper {
                .wc-block-components-address-card {
                    border: 1px solid $color-gray-300 !important;
                    font-size: 0.85rem !important;

                    address {
                        color: $color-gray-700 !important;
                    }

                    .wc-block-components-address-card__edit {
                        display: flex;
                        align-items: center;
                        @include transition(0.2s);

                        &:focus {
                            text-decoration: none !important;
                        }

                        &:hover {
                            text-decoration: none !important;
                            color: $color-gray-600;
                        }

                        &::before {
                            content: '\f044';
                            font-family: $font-family-icons;
                            margin-left: 0.25rem;
                            font-weight: 300;
                        }
                    }
                }
            }
        }

        // Address2 toggle
        .wc-block-components-address-form__address_2-toggle {
            font-size: 0.85rem !important;
            color: $color-gray-800 !important;
        }

        // Checkbox
        .wc-block-components-checkbox__input {
            margin-left: 0.5rem;

            &:focus {
                outline: none !important;
                outline-offset: unset !important;
            }
        }

        .wc-block-components-checkbox__label {
            font-size: 0.85rem !important;
            color: $color-gray-700 !important;
        }

        // Terms
        .wc-block-checkout__terms {
            font-size: 0.85rem !important;
            color: $color-gray-800 !important;
            display: flex;
            align-items: center;

            &::before {
                content: '\f772';
                font-family: $font-family-icons;
                margin-left: 0.5rem;
                font-weight: 300;
                line-height: normal;
            }
        }

        // Buttons
        body:not(.woocommerce-block-theme-has-button-styles) .wc-block-components-button:not(.is-link) {
            @extend %button-dark-style;
            margin: 0;
        }

        .wc-block-checkout__actions_row {
            @media (max-width: 479.98px) {
                flex-direction: column;

                .wc-block-components-checkout-return-to-cart-button {
                    width: 100%;
                    margin-bottom: 1rem;
                }

                .wc-block-components-button {
                    width: 100%;
                }
            }
        }

        .wc-block-components-button {
            background-color: $color-gray-200 !important;
            font-size: 0.9rem !important;
            border-radius: $border-radius-low;
            border: none;
            color: $color-gray-700;
            @include transition(0.2s);
            width: 48%;

            &:hover {
                background-color: $color-gray-300 !important;
            }

            &:focus {
                box-shadow: none !important;
                outline: none !important;
            }
        }

        .wc-block-components-checkout-return-to-cart-button {
            width: 48%;
            font-size: 0.9rem !important;
            padding: 0.5rem !important;
            display: flex;
            align-items: center;
            justify-content: center;

            &::before {
                content: "\f061";
                font-family: $font-family-icons;
                margin-left: 0.5rem;
                font-weight: 500;
                line-height: normal;
                font-size: 1rem;
            }

            svg {
                display: none;
                opacity: 0;
                visibility: hidden;
            }
        }

        .css-0 {
            display: none;
            visibility: hidden;
            opacity: 0;
        }

        .wc-block-must-login-prompt {
            &::before {
                content: '\f502';
                font-family: $font-family-icons;
                font-size: 2rem;
                font-weight: 300;
                color: $color-gray-700;
                margin-bottom: 1rem;
            }

            display: flex;
            flex-direction: column;
            padding: 2rem 0;
            align-items: center;
            justify-content: center;
            text-align: center;
            width: 100%;
            font-size: 0.8rem;

            a {
                color: $color-tip-info-color;
            }
        }
    }

    /* ---------------------------------------------------------
       1. Shared Box — Container for Date & Map
       --------------------------------------------------------- */

    .irantheme-checkout-box {
        margin: 24px 0;
        padding: 20px;
        background: #fafafa;
        border: 1px solid #eaeaea;
        border-radius: 12px;
    }

    .irantheme-checkout-box__title {
        display: flex;
        align-items: center;
        gap: 8px;
        margin: 0 0 6px;
        font-size: 16px;
        font-weight: 700;
        color: #1a1a1a;
        line-height: 1.4;
    }

    .irantheme-checkout-box__title .iconsax {
        font-size: 20px;
        color: #2c7be5;
        flex-shrink: 0;
    }

    .irantheme-checkout-box__desc {
        margin: 0 0 16px;
        font-size: 13px;
        color: #6b7280;
        line-height: 1.6;
    }

    .irantheme-checkout-box__hint {
        display: flex;
        align-items: center;
        gap: 6px;
        margin: 12px 0 0;
        font-size: 12px;
        color: #6b7280;
    }

    .irantheme-checkout-box__hint .iconsax {
        font-size: 15px;
        color: #f59e0b;
        flex-shrink: 0;
    }


    /* ---------------------------------------------------------
       2. Delivery Date — Cards
       --------------------------------------------------------- */

    .delivery-date-options {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
        gap: 10px;
        margin-bottom: 12px;
    }

    .delivery-date-card {
        position: relative;
        display: block;
        cursor: pointer;
        background: #fff;
        border: 2px solid #e5e7eb;
        border-radius: 10px;
        padding: 12px;
        min-height: 80px;
        transition: all 0.2s ease;
        text-align: center;
    }

    .delivery-date-card:hover {
        border-color: #93c5fd;
        box-shadow: 0 2px 8px rgba(44, 123, 229, 0.08);
    }

    .delivery-date-card.selected,
    .delivery-date-card:has(input:checked) {
        border-color: #2c7be5;
        background: #f0f7ff;
        box-shadow: 0 4px 12px rgba(44, 123, 229, 0.15);
    }

    .delivery-date-card input[type="radio"] {
        position: absolute;
        opacity: 0;
        pointer-events: none;
    }

    .delivery-date-card__content {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 4px;
        height: 100%;
    }

    .delivery-date-card__days {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        font-size: 13px;
        font-weight: 700;
        color: #2c7be5;
    }

    .delivery-date-card__days .iconsax {
        font-size: 16px;
    }

    .delivery-date-card__weekday {
        font-size: 12px;
        color: #6b7280;
    }

    .delivery-date-card__date {
        font-size: 13px;
        font-weight: 600;
        color: #1a1a1a;
        direction: ltr;
        font-variant-numeric: tabular-nums;
    }

    .delivery-date-native-select {
        display: none !important;
    }


    /* ---------------------------------------------------------
       3. Delivery Map — Search, Actions & Container
       --------------------------------------------------------- */

    .irantheme-map-search {
        position: relative;
        margin-bottom: 10px;
    }

    .irantheme-map-search .iconsax {
        position: absolute;
        top: 50%;
        inset-inline-start: 12px;
        transform: translateY(-50%);
        font-size: 18px;
        color: #9ca3af;
        pointer-events: none;
    }

    .irantheme-map-search input {
        width: 100%;
        padding: 10px 40px 10px 14px;
        border: 1px solid #d1d5db;
        border-radius: 8px;
        font-size: 13px;
        background: #fff;
        transition: border-color 0.2s, box-shadow 0.2s;
    }

    .irantheme-map-search input:focus {
        outline: none;
        border-color: #2c7be5;
        box-shadow: 0 0 0 3px rgba(44, 123, 229, 0.1);
    }

    .irantheme-map-actions {
        display: flex;
        gap: 8px;
        flex-wrap: wrap;
        margin-bottom: 12px;
    }

    .irantheme-map-actions .button {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 14px;
        font-size: 13px;
        border-radius: 8px;
        background: #fff;
        border: 1px solid #d1d5db;
        color: #374151;
        transition: all 0.2s ease;
        cursor: pointer;
        line-height: 1.4;
    }

    .irantheme-map-actions .button:hover {
        background: #2c7be5;
        border-color: #2c7be5;
        color: #fff;
    }

    .irantheme-map-actions .button .iconsax {
        font-size: 16px;
    }

    #irantheme_delivery_map,
    #irantheme_delivery_map_block {
        height: 320px;
        width: 100%;
        border-radius: 10px;
        margin-bottom: 10px;
        border: 1px solid #e5e7eb;
        z-index: 1;
    }

    .irantheme-map-coords {
        display: flex;
        align-items: center;
        gap: 6px;
        margin: 0;
        padding: 8px 12px;
        background: #fff;
        border: 1px solid #e5e7eb;
        border-radius: 8px;
        font-size: 12px;
        color: #6b7280;
        direction: ltr;
        text-align: left;
        font-family: 'SFMono-Regular', Consolas, 'Courier New', monospace;
        font-variant-numeric: tabular-nums;
    }

    .irantheme-map-coords .iconsax {
        font-size: 14px;
        color: #2c7be5;
        direction: rtl;
    }

    .irantheme-map-coords__sep {
        color: #d1d5db;
        margin: 0 4px;
    }


    /* ---------------------------------------------------------
       4. Admin — Order Edit Page Map
       --------------------------------------------------------- */

    .irantheme-admin-order-map {
        margin-top: 15px;
        padding: 16px;
        background: #fff;
        border: 1px solid #e5e7eb;
        border-radius: 10px;
    }

    .irantheme-admin-order-map__title {
        display: flex;
        align-items: center;
        gap: 8px;
        margin: 0 0 12px;
        font-size: 14px;
        font-weight: 700;
        color: #1a1a1a;
    }

    .irantheme-admin-order-map__title .iconsax {
        font-size: 18px;
        color: #2c7be5;
    }

    #irantheme_admin_order_map {
        height: 280px;
        width: 100%;
        border-radius: 8px;
        margin-bottom: 10px;
        border: 1px solid #e5e7eb;
    }

    .irantheme-admin-order-map .button {
        display: inline-flex;
        align-items: center;
        gap: 6px;
    }

    .irantheme-admin-order-map .button .iconsax {
        font-size: 16px;
    }


    /* ---------------------------------------------------------
       5. Admin — Order List Badge
       --------------------------------------------------------- */

    .irantheme-admin-badge {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        padding: 4px 10px;
        font-size: 12px;
        font-weight: 600;
        color: #2c7be5;
        background: #f0f7ff;
        border: 1px solid #bfdbfe;
        border-radius: 6px;
        text-decoration: none;
        transition: all 0.2s ease;
    }

    .irantheme-admin-badge:hover {
        background: #2c7be5;
        color: #fff;
        border-color: #2c7be5;
    }

    .irantheme-admin-badge .iconsax {
        font-size: 14px;
    }


    /* ---------------------------------------------------------
       6. Order Details & Email — Meta Lines
       --------------------------------------------------------- */

    .irantheme-order-meta-line {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        gap: 6px;
        margin: 6px 0;
        font-size: 14px;
        color: #374151;
    }

    .irantheme-order-meta-line .iconsax {
        font-size: 16px;
        color: #2c7be5;
    }

    .irantheme-order-meta-line a {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        color: #2c7be5;
        text-decoration: none;
        font-weight: 600;
    }

    .irantheme-order-meta-line a:hover {
        text-decoration: underline;
    }


    /* ---------------------------------------------------------
       7. Responsive
       --------------------------------------------------------- */

    @media (max-width: 600px) {

        .irantheme-checkout-box {
            margin: 16px 0;
            padding: 16px;
            border-radius: 10px;
        }

        .irantheme-checkout-box__title {
            font-size: 15px;
        }

        .irantheme-checkout-box__title .iconsax {
            font-size: 18px;
        }

        .delivery-date-options {
            grid-template-columns: repeat(2, 1fr);
            gap: 8px;
        }

        .delivery-date-card {
            padding: 10px;
            min-height: 72px;
        }

        .delivery-date-card__days {
            font-size: 12px;
        }

        .delivery-date-card__date {
            font-size: 12px;
        }

        .irantheme-map-actions {
            flex-direction: column;
        }

        .irantheme-map-actions .button {
            width: 100%;
            justify-content: center;
        }

        #irantheme_delivery_map,
        #irantheme_delivery_map_block {
            height: 260px;
        }

        #irantheme_admin_order_map {
            height: 220px;
        }
    }
}