/*
=====================================
Gallery banner
=====================================
*/
.irantheme-gallery-banner-section {
    .irantheme-gallery-banner {
        position: relative;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;

        // Wrapper
        &-wrapper {
            position: relative;
            z-index: 2;
        }

        // Animate
        &-animation {
            width: 100%;
            height: 100%;
            display: flex;
        }

        // Item
        &-item {
            display: flex;
            overflow: hidden;

            // All columns
            article:last-child {
                margin-bottom: 0 !important;
            }

            // Link
            &-link {
                width: 100%;
                height: 100%;
                display: flex;
                position: relative;

                // Image
                &-img {
                    object-fit: cover;
                    width: 100%;
                    height: 100%;
                }

                // Content
                &-content {
                    padding: 2rem;
                    display: flex;
                    flex-direction: column;
                    width: 100%;
                    height: 100%;
                    position: absolute;
                    top: 0;
                    right: 0;
                    z-index: 1;

                    &-heading {
                        font-size: 1.1rem;
                        // color: $color-white;
                        margin-bottom: 1rem;
                        line-height: 2rem;
                        max-width: 75%;
                    }

                    &-read-more {
                        font-size: 0.8rem;
                        border-bottom-width: 1px;
                        border-style: solid;
                        // border-color: $color-white;
                        width: fit-content;
                        // color: $color-white;
                        display: flex;
                        align-items: center;

                        &::after {
                            content: '\f060';
                            font-family: $font-family-icons;
                            // color: $color-white;
                            margin-right: 0.25rem;
                            font-weight: 400;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Item
            .irantheme-gallery-banner-item {

                // Link
                &-link {

                    &-content {
                        &-heading {
                            color: $color-dark;
                        }

                        &-read-more {
                            border-color: $color-dark;
                            color: $color-dark;

                            &::after {
                                color: $color-dark;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Item
            .irantheme-gallery-banner-item {

                // Link
                &-link {

                    &-content {
                        &-heading {
                            color: $color-white;
                        }

                        &-read-more {
                            border-color: $color-white;
                            color: $color-white;

                            &::after {
                                color: $color-white;
                            }
                        }
                    }
                }
            }
        }
    }
}