/*
=====================================
Footer master section
=====================================
*/
.irantheme-footer-master-section {
    // background: $color-dark;

    .irantheme-footer-master {
        position: relative;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;

        // Logo
        &-logo {
            margin-bottom: 1rem;

            // Logo image holder
            .irantheme-logo-img-holder {
                width: fit-content;

                // Logo img
                .irantheme-logo-img {
                    height: 100% !important;
                    width: auto;
                }
            }

            // Logo svg holder
            .irantheme-logo-svg-holder {
                width: fit-content;

                svg {
                    height: 100% !important;
                    width: auto;
                }
            }
        }

        // Headline
        .irantheme-footer-master-headline {
            position: relative;
            z-index: 9;

            // Heading
            .irantheme-footer-master-heading {
                font-size: 0.9rem;
                // color: $color-white;
                font-weight: bold;
                margin-bottom: 1rem;
                padding-top: 1rem;
            }

            // About
            .irantheme-footer-master-text {
                padding-bottom: 1rem;

                p {
                    font-size: 0.7rem;
                    // color: $color-gray-400;
                    margin-bottom: 0.5rem;
                }

                a {
                    font-size: 0.7rem;
                    font-weight: bold;
                    // color: $color-white;

                    &:hover {
                        i {
                            transform: translateX(-0.25rem);
                        }
                    }

                    i {
                        margin-right: 0.5rem;
                        transition: 0.3s;
                        font-size: 0.5rem;
                        font-weight: bold;
                    }
                }
            }

            // Social media
            .irantheme-social-media {
                display: flex;
                flex-direction: row;
                justify-content: flex-start;
                text-align: center;
                flex-wrap: wrap;
                gap: 1rem;

                li {
                    a {
                        // color: $color-white;
                        font-size: 1rem;
                        display: block;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        border-radius: 50%;

                        svg,
                        path {
                            // color: $color-white;
                            // fill: $color-white;
                            width: 1rem;
                            height: 1rem;
                            position: relative;
                            top: -2px;
                            transition: inherit;
                        }

                        &:hover {
                            // background: $color-gray-200;
                            // color: $color-dark;

                            svg,
                            path {
                                // color: $color-dark;
                                // fill: $color-dark;
                            }
                        }
                    }
                }
            }

            // Useful links
            .irantheme-footer-master-useful-links {
                &-list {
                    display: flex;
                    flex-direction: row;
                    flex-wrap: wrap;
                    row-gap: 0.5rem;

                    &-item {
                        flex-grow: 1;
                        width: 50%;

                        &-link {
                            font-size: 0.8rem;
                            // color: $color-gray-700;

                            &:hover {
                                // color: $color-gray-800;
                            }
                        }
                    }
                }
            }

            // Notes
            .irantheme-footer-master-note {
                display: flex;
                align-items: center;
                column-gap: 0.5rem;

                i {
                    font-size: 1rem;
                }

                p {
                    font-size: 0.7rem;
                    margin-bottom: 0;
                }
            }
        }

        // App
        .irantheme-footer-master-app {

            &-holder {
                display: flex;
                flex-wrap: wrap;
                gap: 0.5rem;
            }

            &-link {
                display: flex;
                width: 10.08rem;
                height: 3rem;

                img {
                    width: 100%;
                    height: 100%;
                    object-fit: fill;
                }
            }
        }

        // Badge
        &-badge {
            .irantheme-holder-badges {
                display: flex;
                flex-wrap: wrap;
                justify-content: flex-start;
                margin-top: 1rem;

                img {
                    max-width: 5rem;
                    height: auto;
                }

                @media only screen and (max-width:1199px) {
                    img {
                        max-width: 6rem;
                    }
                }

                @media only screen and (max-width:991px) {
                    flex-direction: row;
                    justify-content: flex-start;
                    margin-top: 2rem;
                }
            }
        }

        // Copyright
        .irantheme-footer-master-copyright {
            // background: $color-gray-900;
            display: flex;
            align-items: center;
            padding: 1rem 0;
            position: relative;
            z-index: 9;

            .irantheme-footer-master-copyright-text {
                display: flex;
                flex-direction: column;
                // color: $color-gray-500;
                font-size: 0.7rem;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .irantheme-footer-master {
            background-color: $color-white;

            // Headline
            .irantheme-footer-master-headline {

                // Heading
                .irantheme-footer-master-heading {
                    color: $color-dark;
                }

                // About
                .irantheme-footer-master-text {

                    p {
                        color: $color-gray-600;
                    }

                    a {
                        color: $color-dark;
                    }
                }

                // Notes
                .irantheme-footer-master-note {
                    i {
                        color: $color-gray-700;
                    }

                    p {
                        color: $color-gray-600;
                    }
                }

                // Useful links
                .irantheme-footer-master-useful-links {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-700;

                                &:hover {
                                    color: $color-gray-800;
                                }
                            }
                        }
                    }
                }
            }

            // Social media
            .irantheme-social-media {
                li {
                    a {
                        color: $color-gray-500;

                        svg,
                        path {
                            color: $color-gray-500;
                            fill: $color-gray-500;
                        }

                        &:hover {
                            color: $color-dark;

                            svg,
                            path {
                                color: $color-dark;
                                fill: $color-dark;
                            }
                        }
                    }
                }
            }

            // Copyright
            .irantheme-footer-master-copyright {
                background: $color-gray-100;

                .irantheme-footer-master-copyright-text {
                    color: $color-gray-600;
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .irantheme-footer-master {
            background-color: $color-dark;

            // Headline
            .irantheme-footer-master-headline {

                // Heading
                .irantheme-footer-master-heading {
                    color: $color-white;
                }

                // About
                .irantheme-footer-master-text {
                    p {
                        color: $color-gray-400;
                    }

                    a {
                        color: $color-white;
                    }
                }

                // Notes
                .irantheme-footer-master-note {
                    i {
                        color: $color-gray-300;
                    }

                    p {
                        color: $color-gray-400;
                    }
                }

                // Useful links
                .irantheme-footer-master-useful-links {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-300;

                                &:hover {
                                    color: $color-gray-200;
                                }
                            }
                        }
                    }
                }
            }

            // Social media
            .irantheme-social-media {
                li {
                    a {
                        color: $color-gray-500;

                        svg,
                        path {
                            color: $color-gray-500;
                            fill: $color-gray-500;
                        }

                        &:hover {
                            color: $color-white;

                            svg,
                            path {
                                color: $color-white;
                                fill: $color-white;
                            }
                        }
                    }
                }
            }

            // Copyright
            .irantheme-footer-master-copyright {
                background: $color-gray-900;

                .irantheme-footer-master-copyright-text {
                    color: $color-gray-400;
                }
            }
        }
    }
}