.irantheme-myaccount {
    $banner-height: 200px;
    padding: 2rem 0;
    background-color: $color-gray-100;

    // @media only screen and (max-width: 767.98px) {
    //     padding: 2.5rem;
    // }

    // @media only screen and (max-width: 575.98px) {
    //     padding: 1rem;
    // }

    &-holder {

        min-height: 90vh;

        @media only screen and (max-width: 767.98px) {
            min-height: unset;
        }

        // Sidebar ===========================================
        .irantheme-myaccount-sidebar-col {
            .irantheme-myaccount-sidebar {
                padding: 1.5rem;
                display: flex;
                flex-direction: column;
                background-color: $color-white;
                border-radius: $border-radius-2;
                min-height: 100%;

                @media (max-width: 575.98px) {
                    padding: 1rem;
                }

                .irantheme-woocommerce-myaccount-head-navigation-holder {
                    @media (max-width: 767.98px) {
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        gap: 1rem;
                    }


                    .irantheme-woocommerce-myaccount-navigation-mobile-trigger {
                        display: flex;
                        align-items: center;
                        gap: 0.5rem;
                        cursor: pointer;

                        .label {
                            font-size: 0.9rem;

                            @media (max-width: 575.98px) {
                                display: none;
                            }
                        }

                        i {
                            font-size: 1.4rem;
                            color: $color-gray-700;
                        }

                        @media (min-width: 768px) {
                            display: none;
                        }
                    }

                }

                .irantheme-woocommerce-profile {
                    display: flex;
                    align-items: center;
                    justify-content: flex-start;
                    text-align: center;
                    column-gap: 0.5rem;
                    margin-bottom: 2rem;
                    max-width: 95%;

                    @media (max-width: 767.98px) {
                        margin-bottom: 0;
                        max-width: 55%;
                    }

                    // Avatar
                    &-avatar {
                        // margin-bottom: 1rem;
                        min-width: 3.5rem;

                        // Image user
                        img {
                            border-radius: 50% !important;
                            margin: 0 !important;
                            width: 3.5rem;
                            height: 3.5rem;
                            aspect-ratio: 1/1;
                        }
                    }

                    // Content
                    &-content {
                        line-height: normal;
                        display: flex;
                        flex-direction: column;
                        align-items: flex-start;
                        width: 100%;
                        gap: 0.5rem;

                        // Heading name
                        &-title {
                            display: flex;
                            align-items: center;
                            flex-wrap: wrap;
                            width: 100%;
                            column-gap: 0.5rem;

                            &-heading {
                                font-size: 0.8rem;
                                color: $color-gray-800 ;
                                font-weight: 600;
                                white-space: nowrap;
                                overflow: hidden;
                                text-overflow: ellipsis;
                                max-width: 80%;
                            }

                            // Role caption
                            &-role {
                                display: flex;
                                align-items: center;
                                gap: 0.25rem;
                                font-size: 0.6rem;
                                font-weight: 600;
                                color: $color-gray-700 ;
                                background-color: $color-gray-200;
                                border-radius: $border-radius-medium;
                                padding: 0.2rem 0.3rem;
                            }
                        }

                        // Email user
                        &-email {
                            white-space: nowrap;
                            overflow: hidden;
                            text-overflow: ellipsis;
                            max-width: 80%;
                            font-size: 0.7rem;
                            color: $color-gray-700 ;
                            margin-bottom: 0;
                        }
                    }
                }

                .irantheme-woocommerce-myaccount-navigation-holder {
                    flex-grow: 1;
                    height: 100%;

                    @media (max-width: 767.98px) {
                        margin-top: 2rem;

                        &:not(.active) {
                            display: none;
                        }
                    }

                    .irantheme-woocommerce-myaccount-navigation {
                        display: flex;
                        flex-direction: column;
                        row-gap: 0.5rem;
                        align-items: flex-start;
                        height: 100%;

                        &-item {
                            display: flex;
                            align-items: center;
                            width: 100%;
                            color: $color-gray-800;
                            border-radius: $border-radius-high;
                            @include transition(0.2s);

                            &:hover,
                            &.is-active {
                                background-color: $color-gray-200;

                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    color: $color-gray-900;

                                    &::before {
                                        color: $color-gray-900;
                                    }
                                }
                            }

                            &.is-active {

                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    font-weight: 600;

                                    &::before {
                                        font-weight: 400;
                                    }
                                }
                            }

                            &-link {
                                display: flex;
                                align-items: center;
                                gap: 0.75rem;
                                width: 100%;
                                padding: 0.5rem 1rem;
                                font-size: 0.8rem;
                                color: $color-gray-700;
                                @include transition(0.2s);

                                &::before {
                                    content: '\e196';
                                    font-family: $font-family-icons;
                                    display: inline-block;
                                    color: $color-gray-700;
                                    font-weight: 300;
                                    font-size: 1.1rem;
                                    @include transition(0.2s);
                                }
                            }


                            &.woocommerce-MyAccount-navigation-link--dashboard {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\e1b0';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--orders {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\f49c';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--favorites {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\e189';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--tickets {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\e658';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--downloads {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\f0ed';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--edit-address {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\f5a0';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--edit-account {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\f2bb';
                                    }
                                }
                            }

                            &.woocommerce-MyAccount-navigation-link--customer-logout {
                                .irantheme-woocommerce-myaccount-navigation-item-link {
                                    &::before {
                                        content: '\f2f5';
                                    }
                                }
                            }
                        }
                    }
                }
            }

            @media (max-width: 767.98px) {
                margin-bottom: 1rem;
            }
        }

        // Content ===========================================
        .irantheme-myaccount-content-col {

            // Holder of myaccount content
            .irantheme-myaccount-content {
                background-color: $color-white;
                border-radius: $border-radius-2;
                min-height: 100%;
                padding: 1.5rem;
                overflow-x: auto;

                @media (max-width: 575.98px) {
                    padding: 1rem;
                }

                // Title of inner sections
                &-title {
                    font-size: 0.9rem;
                    font-weight: 600;
                    color: $color-gray-700;
                    padding: 0.5rem 0 1.5rem;
                    display: flex;
                    align-items: center;
                    gap: 0.5rem;

                    i {
                        font-size: 1.2rem;
                        font-weight: 400;
                    }
                }

                .irantheme-myaccount-dashboard {
                    &-holder {
                        .row {
                            row-gap: 1.5rem;
                        }
                    }

                    &-card-holder {}

                    &-welcome-card {
