                    .iconsax {
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        flex-shrink: 0;

                        font-size: 18px;
                        line-height: 1;
                        color: $color-primary;
                    }

                    /* Link display on map */
                    a {
                        display: inline-flex;
                        align-items: center;
                        gap: 6px;

                        margin-inline-start: 4px;
                        padding: 5px 12px;

                        font-family: $font-family-pack;
                        font-size: 13px;
                        font-weight: 600;
                        text-decoration: none;

                        color: $color-primary;
                        background: $color-primary-trans;
                        border: 1px solid transparent;
                        border-radius: $border-radius-low;

                        transition:
                            background-color 0.2s ease,
                            color 0.2s ease,
                            border-color 0.2s ease,
                            transform 0.2s ease;

                        .iconsax {
                            font-size: 15px;
                            color: $color-primary;
                            transition: color 0.2s ease;
                        }

                        &:hover {
                            color: $color-white;
                            background: $color-primary-hover;
                            border-color: $color-primary-hover;
                            transform: translateY(-1px);

                            .iconsax {
                                color: $color-white;
                            }
                        }

                        &:focus-visible {
                            outline: none;
                            box-shadow: 0 0 0 3px $color-primary-trans;
                        }

                        &:active {
                            transform: translateY(0);
                        }
                    }

                    /* Address line — accent with quaternary (green) */
                    /* Automatic detection: no <a> inside means it's the address line */
                    &:not(:has(a)) {
                        border-inline-start-color: $color-quaternary;

                        .iconsax {
                            color: $color-quaternary;
                        }
                    }
                }


                /* ---------------------------------------------------------
                   Responsive
                   --------------------------------------------------------- */

                @media (max-width: 600px) {

                    .irantheme-order-meta-line {
                        flex-direction: column;
                        align-items: flex-start;
                        gap: 6px;

                        padding: 10px 14px;
                        font-size: 13px;

                        a {
                            width: 100%;
                            justify-content: center;
                            margin-inline-start: 0;
                        }

                        strong {
                            white-space: normal;
                        }
                    }
                }
            }
        }
    }

    &-content {
        &-empty {
            padding: 1rem 0;
            margin-top: 3rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 1rem;

            &-icon {
                font-size: 5rem;
                color: $color-gray-600;
                margin-bottom: 1rem;
            }

            &-title {
                font-size: 0.8rem;
                font-weight: 600;
                color: $color-gray-800;
            }

            &-btn {
                font-size: 0.75rem;
                font-weight: normal;
                padding: 0.5rem 1rem;
                display: flex;
                align-items: center;
                gap: 0.25rem;
                color: $color-gray-700;
                @include transition(0.2s);

                .icon {
                    font-size: 0.8rem;
                }

                &:hover {
                    color: $color-gray-900;
                }
            }
        }
    }
}

