// Navbar options
.irantheme-navbar-options {
    text-align: left;
    display: flex;
    align-items: center;
    column-gap: 0.5rem;

    &.irantheme-navbar-options-desktop-hide {
        @media only screen and (min-width:1199px) {
            display: none !important;
        }
    }

    // Ul list
    &-list {
        display: flex;
        column-gap: 0.5rem;

        // Item
        &-item {
            display: flex;
            flex-direction: row;

            // Desktop hide
            &-desktop-hide {
                @media only screen and (min-width: 1199px) {
                    display: none;
                }
            }

            // Mobile hide
            &-mobile-hide {
                @media only screen and (max-width: 1199px) {
                    display: none;
                }
            }

            // Link
            &-link {
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.3rem;
                position: relative;
                width: 2.75rem;
                height: 2.75rem;
                border-radius: $border-radius-high;
                @include transition(0.2s);
                // color: $color-white;

                // Mini shopping cart count
                .irantheme-mini-number-count {
                    @extend %mini-number-count;
                }

                // Cart navigation
                &.irantheme-woocommerce-cart-navigation-open {
                    // font-size: 1.3rem;
                }

                &:hover,
                &.active {
                    // color: $color-gray-300;
                }
            }

            // Navbar trigger holder
            &.irantheme-navbar-trigger-holder {

                // Nav open
                .irantheme-navbar-trigger {
                    // background: transparent;
                    position: relative;
                    flex-direction: column;
                    justify-content: center;
                    margin-right: 0.75rem;
                    padding: 0;
                    border: none;
                    box-shadow: none;
                    display: flex;
                    width: 2rem;

                    span {
                        width: 100%;
                        height: 1px;
                        // background-color: $color-white;
                        display: block;
                        margin-right: auto;

                        &:not(:last-child) {
                            margin-bottom: 0.4rem;
                        }

                        &:first-child {
                            @include transition(0.6s,
                                all,
                                cubic-bezier(0.445, 0.05, 0.55, 0.95));
                            width: 60%;
                        }

                        &:last-child {
                            @include transition(0.4s,
                                all,
                                cubic-bezier(0.445, 0.05, 0.55, 0.95));
                            width: 50%;
                        }

                        &:nth-child(2) {
                            @include transition(0.2s,
                                all,
                                cubic-bezier(0.445, 0.05, 0.55, 0.95));
                            width: 80%;
                        }
                    }

                    &.active span {
                        width: 100%;
                    }
                }

                &[data-trigger-desktop="navigation"],
                &[data-trigger-desktop="fullscreen"] {
                    display: flex !important;
                }

                @media screen and (min-width:1199px) {
                    display: none;
                }
            }

        }
    }
}

/*
=====================================
Header white mode
=====================================
*/
// White mode
&.irantheme-header-white,
&.irantheme-header-white-important {

    // Header options
    .irantheme-navbar-options {

        // List options
        &-list {

            // Item options
            &-item {

                // Link options
                &-link {
                    background: $color-gray-100;
                    color: $color-gray-700;

                    &.irantheme-woocommerce-cart-navigation-open {

                        &:hover,
                        &.active {}
                    }

                    // Set color link options
                    &:hover,
                    &.active {
                        color: $color-dark;
                        background: $color-gray-200;
                        box-shadow: none;
                    }
                }

                // Nav open
                .irantheme-navbar-trigger {
                    background: transparent;

                    span {
                        background-color: $color-dark;
                    }
                }
            }
        }
    }
}

/*
=====================================
Dark mode
=====================================
*/
&.irantheme-header-dark,
&.irantheme-header-dark-important {

    // Header options
    .irantheme-navbar-options {

        // List options
        &-list {

            // Item options
            &-item {

                // Link options
                &-link {
                    background: $color-gray-900;
                    color: $color-gray-300;

                    &.irantheme-woocommerce-cart-navigation-open {

                        &:hover,
                        &.active {}
                    }

                    // Set color link options
                    &:hover,
                    &.active {
                        color: $color-white;
                        background: $color-gray-800;
                        box-shadow: none;
                    }
                }

                // Nav open
                .irantheme-navbar-trigger {
                    background: transparent;

                    span {
                        background-color: $color-white;
                    }
                }
            }
        }
    }
}