/*
=====================================
Business Authors post
=====================================
*/
.irantheme-business-authors-post-section {
    .irantheme-business-authors-post {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Slider (Swiper)
        .irantheme-business-authors-post-swiper {
            .swiper-slide {
                height: auto;
            }

            // Improvement styles bullet active in pagination
            .swiper-pagination {
                .swiper-pagination-bullet-active {
                    @include transition(0.3s, all, ease-in-out);
                    width: 1.2rem;
                    border-radius: $border-radius-high;
                }
            }
        }

        // Wrapper
        .irantheme-business-authors-post-wrapper {
            position: relative;
            z-index: 2;

            // Post item
            .irantheme-business-authors-post-item {
                background: transparent;
                width: 100%;
                height: 100%;
                position: relative;
                overflow: hidden;

                // Box style
                &.irantheme-business-authors-post-item-box-style {
                    background: $color-white;
                }

                // Border item
                &.irantheme-business-authors-post-item-border {
                    border-width: 1px;
                    border-style: solid;
                }

                // Border item
                &.irantheme-business-authors-post-item-padding {
                    padding: 1rem;

                    .irantheme-business-authors-post-item-content {
                        padding: 2rem 0 1rem !important;
                    }
                }

                // Image
                &-image {
                    width: 100%;
                    display: flex;
                    overflow: hidden;

                    // Anchor of img tag
                    &-anchor {
                        display: flex;
                        width: 100%;
                    }

                    // Img tag
                    &-src {
                        width: 100%;
                        height: 100%;
                        object-fit: fill;
                        display: block;
                        @include transition(0.2s);
                    }
                }

                // Content
                .irantheme-business-authors-post-item-content {
                    padding: 2rem;

                    // Heading
                    &-heading {

                        // Anchor of title
                        &-anchor {
                            display: block;
                        }

                        // Title
                        &-title {
                            // color: $color-gray-900;
                            font-size: 1rem;
                            font-weight: bold;
                        }

                        // Skills
                        &-skills {
                            // color: $color-gray-600;
                            font-size: 0.8rem;
                        }
                    }

                    // Description
                    &-desc {
                        padding-top: 1.5rem;
                        // color: $color-gray-700;
                        font-size: 0.8rem;
                    }

                    // Details
                    &-details {
                        padding-top: 1.5rem;

                        // Read more
                        &-link {
                            // color: $color-gray-600;
                            font-size: 0.8rem;
                            display: block;
                        }
                    }
                }

                // Social media
                &-social {
                    position: absolute;
                    top: 1rem;
                    left: 1rem;
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    align-items: center;
                    text-align: center;
                    border-radius: $border-radius-medium;
                    overflow: hidden;
                    // background: $color-white;

                    &-item {
                        font-size: 1rem;
                        // color: $color-gray-700;
                        padding: 0.25rem 0.5rem;

                        &:hover {
                            // color: $color-gray-900;
                        }
                    }
                }

                // Animations on hover
                &:hover {
                    .irantheme-business-authors-post-item {
                        &-image {
                            &-src {
                                @include transform(scale(1.1));
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            // Wrapper
            .irantheme-business-authors-post-wrapper {

                // Post item
                .irantheme-business-authors-post-item {

                    // Box style
                    &.irantheme-business-authors-post-item-box-style {
                        background: $color-white;
                    }

                    // Border item
                    &.irantheme-business-authors-post-item-border {
                        border-color: $color-gray-200;
                    }

                    // Shadow item
                    &.irantheme-business-authors-post-item-shadow {
                        @extend %box-shadow-white;
                    }

                    // Content
                    .irantheme-business-authors-post-item-content {

                        // Heading
                        &-heading {

                            // Title
                            &-title {
                                color: $color-gray-900;
                            }

                            // Skills
                            &-skills {
                                color: $color-gray-600;
                            }
                        }

                        // Description
                        &-desc {
                            color: $color-gray-700;
                        }

                        // Details
                        &-details {

                            // Read more
                            &-link {
                                color: $color-gray-600;
                            }
                        }
                    }

                    // Social media
                    &-social {
                        background: $color-white;

                        &-item {
                            color: $color-gray-600;


                            &:hover {
                                color: $color-dark;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            // Wrapper
            .irantheme-business-authors-post-wrapper {

                // Post item
                .irantheme-business-authors-post-item {

                    // Box style
                    &.irantheme-business-authors-post-item-box-style {
                        background: $color-dark;
                    }

                    // Border item
                    &.irantheme-business-authors-post-item-border {
                        border-color: $color-gray-800;
                    }

                    // Shadow item
                    &.irantheme-business-authors-post-item-shadow {
                        @extend %box-shadow-dark;
                    }

                    // Content
                    .irantheme-business-authors-post-item-content {

                        // Heading
                        &-heading {

                            // Title
                            &-title {
                                color: $color-gray-100;
                            }

                            // Skills
                            &-skills {
                                color: $color-gray-400;
                            }
                        }

                        // Description
                        &-desc {
                            color: $color-gray-300;
                        }

                        // Details
                        &-details {

                            // Read more
                            &-link {
                                color: $color-gray-400;
                            }
                        }
                    }

                    // Social media
                    &-social {
                        background: $color-dark;

                        &-item {
                            color: $color-gray-400;


                            &:hover {
                                color: $color-white;
                            }
                        }
                    }
                }
            }
        }
    }
}