/*
=====================================
Gallery section
=====================================
*/
.irantheme-gallery-master-section {
    background: transparent;
    overflow: hidden;

    .irantheme-gallery-master {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // overflow: hidden;


        // Contact wrapper
        .irantheme-gallery-master-post-wrapper {
            position: relative;
            z-index: 2;


            .irantheme-media-gallery-item {
                overflow: hidden;

                .irantheme-media-gallery-animation {
                    height: 100%;
                }

                .irantheme-media-gallery-item-inner-wrapper {
                    overflow: hidden;
                    position: relative;
                    height: 100%;

                    &.irantheme-media-gallery-item-hover-zoom-in {
                        .irantheme-media-gallery-item-video {
                            transform: scale(1.1);

                            &:hover {
                                transform: scale(1.2);
                            }
                        }

                        .irantheme-media-gallery-item-image {
                            transform: scale(1.1);

                            &:hover {
                                transform: scale(1.2);
                            }
                        }
                    }

                    .irantheme-gallery-item-hover-mask {
                        position: absolute;
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        width: 100%;
                        height: 100%;
                        top: 0;
                        left: 0;
                        background-color: $color-dark-transparent-6;
                        opacity: 0;
                        visibility: hidden;
                        @include transition(0.2s);

                        i {
                            font-size: 1.5rem;
                            color: $color-white;

                            &:hover {
                                color: $color-white;
                            }
                        }
                    }

                    &.irantheme-media-gallery-item-hover-mask:hover {
                        .irantheme-gallery-item-hover-mask {
                            opacity: 1;
                            visibility: visible;
                        }
                    }
                }
            }

            .irantheme-post-gallery-grid {
                .irantheme-media-gallery-item {
                    .irantheme-media-gallery-item-inner-wrapper {
                        height: 100%;
                        // height: 350px; 
                        width: 100%;

                        .irantheme-media-gallery-item-video {
                            width: 100%;
                            height: 100%;
                            min-height: 100%;
                            object-fit: cover;
                            transform: scale(1.1);
                            @include transition(0.2s);
                        }

                        // Video button
                        .irantheme-media-gallery-item-video-button {
                            position: absolute;
                            top: 50%;
                            right: 50%;
                            transform: translate(50%, -50%);

                            .irantheme-media-gallery-item-video-button-trigger {
                                width: 4rem;
                                height: 4rem;
                                padding: 0;
                                background: $color-white;
                                color: $color-dark;
                                border-radius: 50%;
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                text-align: center;
                                font-size: 1rem;
                                position: relative;
                                opacity: 0.8;
                                @include transition(0.2s);

                            }

                            &:hover {
                                .irantheme-media-gallery-item-video-button-trigger {
                                    opacity: 1;
                                    color: $color-dark;
                                }
                            }

                        }

                        .irantheme-media-gallery-item-image {
                            width: 100%;
                            height: 100%;
                            min-height: 100%;
                            object-fit: cover;
                            @include transition(0.2s);
                        }
                    }
                }
            }

            .irantheme-post-gallery-justified {

                .irantheme-media-gallery-item {
                    .irantheme-media-gallery-item-inner-wrapper {
                        height: 100%;
                        // height: 350px; 
                        // width: 100%;
                        cursor: pointer;

                        a {
                            display: flex;
                            justify-content: center;
                            align-items: center;
                            width: 100%;
                            height: 100%
