        &.dark {
            background-color: $color-dark;
        }
    }
}

/* Thumb magnification holder */

.irantheme-gallery-magnification-slider {
    position: fixed;
    top: 0;
    right: 0;
    width: 100%;
    height: 100%;
    display: none;
    z-index: 99999999;


    .irantheme-gallery-magnification-slider-wrapper {
        position: relative;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: stretch;
        width: 100%;
        height: 100%;

        .irantheme-gallery-magnification-slider-topbar {
            position: relative;
            display: flex;
            flex-direction: row;
            justify-content: space-between;
            align-items: center;
            text-align: center;
            width: 100%;
            height: auto;
            padding: 0.75rem 1rem;

            &-action {
                display: flex;
                flex-direction: row;
                align-items: center;
                text-align: center;

                &-btn {
                    color: $color-gray-500;
                    padding: 0.75rem;
                    margin-left: 0.25rem;
                    cursor: pointer;
                    @include transition(0.2s);
                    font-size: 1.2rem;

                    &:hover {
                        // color: $color-white;
                    }

                }

                .irantheme-gallery-magnification-slider-action-share-holder {
                    position: relative;

                    &.irantheme-btn-share-active {
                        .irantheme-gallery-magnification-slider-share-dropdown {
                            visibility: visible;
                            opacity: 1;
                            transform: translate3d(0, 0, 0);
                        }

                        .irantheme-gallery-magnification-slider-action-share {
                            // color: $color-white;
                        }
                    }

                    .irantheme-gallery-magnification-slider-share-dropdown {
                        position: absolute;
                        width: auto;
                        height: auto;
                        background-color: white;
                        padding: 0.6rem 0;
                        top: calc(100% + 16px);
                        right: 0;
                        border-radius: $border-radius-little;
                        transform: translate3d(0, 5px, 0);
                        visibility: hidden;
                        opacity: 0;
                        z-index: 999;
                        @include transition(0.2s);


                        li {
                            padding: 0.15rem 1rem;
                            display: block;
                            white-space: nowrap;
                            text-align: right;

                            a {
                                display: flex;
                                align-items: center;
                                font-size: 0.8rem;
                                // color: $color-dark;

                                i {}

                                span {
                                    margin-right: 0.5rem;
                                }
                            }
                        }

                        ::after {
                            content: '';
                            display: block;
                            height: 0;
                            width: 0;
                            position: absolute;
                            border: 8px solid transparent;
                            // border-bottom-color: #fff;
                            right: 15px;
                            top: -16px;
                        }
                    }
                }
            }

            &-page {
                display: flex;
                flex-direction: row;
                align-items: center;
                text-align: center;
                padding-left: 0.75rem;

                span {
                    color: $color-gray-500;
                    font-size: 1rem;
                    padding: 0.15rem;
                }

            }

        }

        .irantheme-gallery-magnification-slider-figure {
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-grow: 1;
            margin: 0;
            width: 100%;
            // height: 100%;
            padding: 1.5rem;
            min-height: 70%;

            .swiper-slide {
                text-align: center;
                font-size: 18px;
                display: flex;
                justify-content: center;
                align-items: center;

                img {
                    display: block;
                    max-width: 100%;
                    max-height: 100%;
                    width: auto;
                    object-fit: cover;

                    &::-moz-selection {
                        background: transparent;
                    }

                    &::selection {
                        background: transparent;
                    }
                }

                video {
                    display: block;
                    max-width: 100%;
                    max-height: 100%;
                    width: auto;
                    object-fit: cover;
                }
            }

        }

        .irantheme-gallery-magnification-slider-thumb {
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            height: 100%;
            max-height: 10%;
            padding: 1rem 2rem;

            .swiper-wrapper {
                position: relative;
            }

            .irantheme-gallery-magnification-slider-thumb-item {
                position: relative;
                height: 100%;
                cursor: pointer;

                &.swiper-slide {
                    position: relative;
                    overflow: hidden;
                    text-align: center;
                    font-size: 18px;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    opacity: 0.5;

                    img {
                        display: block;
                        height: 80px;
                        width: 80px;
                        object-fit: cover;
                    }

                    video {
                        display: block;
                        min-height: 150px;
                        width: auto;
                        object-fit: cover;
                    }

                    &.swiper-slide-thumb-active {
                        opacity: 1;
                    }
                }
            }

        }
    }

    &.irantheme-magnification-bg-dark {
        background: $color-darker;

        .irantheme-gallery-magnification-slider-wrapper {
            .irantheme-gallery-magnification-slider-topbar {

                &-action {
                    &-btn {
                        color: $color-gray-400;

                        &:hover {
                            color: $color-white;
                        }

                    }

                    .irantheme-gallery-magnification-slider-action-share-holder {
                        &.irantheme-btn-share-active {
                            .irantheme-gallery-magnification-slider-action-share {
                                color: $color-white;
                            }
                        }

                        .irantheme-gallery-magnification-slider-share-dropdown {
                            background-color: $color-white;

                            li {
                                a {
                                    color: $color-dark;
                                }
                            }

                            ::after {
                                content: '';
                                border-bottom-color: $color-white;
                            }
                        }
                    }
                }

                &-page {
                    span {
                        color: $color-gray-400;
                    }
                }
            }
        }
    }

    &.irantheme-magnification-bg-white {
        background: $color-white;

        .irantheme-gallery-magnification-slider-wrapper {
            .irantheme-gallery-magnification-slider-topbar {

                &-action {
                    &-btn {
                        color: $color-gray-600;

                        &:hover {
                            color: $color-dark;
                        }

                    }

                    .irantheme-gallery-magnification-slider-action-share-holder {
                        &.irantheme-btn-share-active {
                            .irantheme-gallery-magnification-slider-action-share {
                                color: $color-dark;
                            }
                        }

                        .irantheme-gallery-magnification-slider-share-dropdown {
                            background-color: $color-dark;

                            li {
                                a {
                                    color: $color-white;
                                }
                            }

                            ::after {
                                content: '';
                                border-bottom-color: $color-gray-900;
                            }
                        }
                    }
                }

                &-page {
                    span {
                        color: $color-gray-600;
                    }
                }
            }
        }
    }
}