/*
=====================================
Social media
=====================================
*/

.irantheme-social-media {
    display: flex;
    align-items: center;
    column-gap: 1rem;

    li {
        display: flex;
        height: 100%;

        a {
            display: flex;
            align-items: center;
            justify-content: center;
            // color: $color-gray-700;
            font-size: 1rem;

            i {
                // @include transition(0.2s);

            }

            &:hover {
                // color: $color-dark;
            }
        }

        &:first-child {
            a {
                padding-right: 0;
            }
        }

        &:last-child {
            a {
                padding-left: 0;
            }
        }

        svg {
            width: 1rem;
            height: 1rem;
            // color: $color-white;
            // fill: $color-white;
            line-height: 1rem;
            @include transition(0.2s);

            path {
                // fill: $color-white;
                @include transition(0.2s);
            }
        }
    }

    // Media
    @media only screen and (max-width: 1199px) {
        display: none !important;
    }
}


/*
=====================================
White mode
=====================================
*/
&.irantheme-header-white,
&.irantheme-header-white-important {
    .irantheme-social-media {

        li {

            a {
                color: $color-gray-700;

                &:hover {
                    color: $color-dark;

                    svg,
                    path {
                        fill: $color-dark;
                    }
                }
            }

            svg {
                color: $color-gray-700;
                fill: $color-gray-700;

                path {
                    fill: $color-gray-700;
                }
            }
        }
    }
}


/*
=====================================
Dark mode
=====================================
*/
&.irantheme-header-dark,
&.irantheme-header-dark-important {
    .irantheme-social-media {

        li {

            a {
                color: $color-gray-300;

                &:hover {
                    color: $color-white;

                    svg,
                    path {
                        fill: $color-white;
                    }
                }
            }

            svg {
                color: $color-gray-300;
                fill: $color-gray-300;

                path {
                    fill: $color-gray-300;
                }
            }
        }
    }
}