/*
=====================================
Business Box Reviews
=====================================
*/
.irantheme-business-box-reviews-section {
    .irantheme-business-box-reviews {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Viewpoints
        .irantheme-business-box-reviews-post-swiper {}

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        .irantheme-business-box-reviews-post-wrapper {
            position: relative;
            z-index: 2;
            text-align: right;

            // Item
            .irantheme-business-box-reviews-post-item {
                padding: 2rem;
                position: relative;
                display: flex;
                flex-direction: column;

                // Box style none
                &.irantheme-box-style-none {
                    padding: 0 !important;
                }

                // Content
                &-content {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    align-items: flex-start;
                    text-align: right;

                    // Description
                    &-desc {
                        // color: $color-gray-100;
                        font-size: 0.8rem;
                        margin-bottom: 2rem;

                        &.irantheme-business-box-reviews-width-limited {
                            max-width: 50%;

                            @media only screen and (max-width: 991px) {
                                max-width: 100%;
                            }
                        }
                    }
                }

                // Image user
                &-image {
                    display: flex;
                    align-items: center;

                    &-src {
                        width: 3rem;
                        height: 3rem;
                        border-radius: 50%;
                        margin-left: 1rem;
                    }

                    // Heading
                    &-heading {
                        line-height: normal;

                        // Title
                        &-title {
                            // color: $color-white;
                            font-size: 0.9rem;
                            font-weight: bold;
                            margin-bottom: 0.15rem;
                        }

                        // Skills
                        &-skills {
                            // color: $color-white;
                            font-size: 0.7rem;
                            margin-bottom: 0.35rem;
                        }

                        // Star
                        &-star {
                            cursor: default;
                            width: 100%;

                            // Holder star icons
                            &-holder {
                                display: flex;
                                column-gap: 0.15rem;
                            }

                            // Icon
                            &-icon {
                                color: $color-quinary-hover;
                                font-size: 0.7rem;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Viewpoints
            .irantheme-business-box-reviews-post-wrapper {

                // Item
                .irantheme-business-box-reviews-post-item {

                    // Shadow
                    &.irantheme-box-style-shadow {
                        @extend %box-shadow-white;
                    }

                    // Shadow
                    &.irantheme-box-style-border {
                        border: 1px solid $color-gray-200;
                    }

                    // Content
                    &-content {

                        // Description
                        &-desc {
                            color: $color-gray-600;
                        }
                    }

                    // Image user
                    &-image {

                        &-src {}

                        // Heading
                        &-heading {

                            // Title
                            &-title {
                                color: $color-gray-800;
                            }

                            // Skills
                            &-skills {
                                color: $color-gray-600;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Viewpoints
            .irantheme-business-box-reviews-post-wrapper {

                // Item
                .irantheme-business-box-reviews-post-item {

                    // Shadow
                    &.irantheme-box-style-shadow {
                        @extend %box-shadow-dark;
                    }

                    // Shadow
                    &.irantheme-box-style-border {
                        border: 1px solid $color-gray-800;
                    }

                    // Content
                    &-content {

                        // Description
                        &-desc {
                            color: $color-gray-400;
                        }
                    }

                    // Image user
                    &-image {

                        &-src {}

                        // Heading
                        &-heading {

                            // Title
                            &-title {
                                color: $color-gray-200;
                            }

                            // Skills
                            &-skills {
                                color: $color-gray-400;
                            }
                        }
                    }
                }
            }
        }
    }
}