/*
=====================================
Navbar full screen
=====================================
*/

.irantheme-navbar-full-screen {
    position: fixed;
    top: 0;
    right: 0;
    width: 100%;
    height: 100%;
    background-color: $color-dark-transparent-9;
    z-index: 9999999;
    display: none;
    overflow-y: auto;

    // Close
    &-close {
        position: absolute;
        left: 0;
        top: 0;
        // color: $color-gray-400;
        padding: 2rem;
        font-size: 1.8rem;
        z-index: 9999999;
        background: transparent !important;
        cursor: pointer;

        &:hover {
            // color: $color-white;
        }
    }

    &-holder {
        position: absolute;
        top: 0;
        right: 0;
        width: 100%;
        height: 100%;
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        text-align: center;
    }

    // Options
    &-options {
        &-ul {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            align-items: center;
            text-align: center;
            line-height: 0 !important;
            padding-top: 1rem;

            &-item {
                @extend %animation-top-to-bottom;
                @include transform(translateY(2.5rem));
                padding-right: 0.5rem;
                padding-left: 0.5rem;
                opacity: 0;

                &-link {
                    padding: 0.5rem;
                    display: block;
                    font-size: 1.2rem;
                    @include transition(all, 0.3s, ease-in-out);

                    i {
                        @include transition(0.2s);
                    }

                    // Mini shopping cart count
                    .irantheme-mini-number-count {
                        @extend %mini-number-count;

                        & {
                            right: calc(50% + 0.1rem);
                        }

                        // & {
                        //     right: calc(50% + 0.1rem);
                        //     top: calc(50% - 0.2rem);
                        // }
                    }

                    &:hover {
                        // color: $color-gray-400;

                        i {
                            // color: $color-gray-400;
                        }
                    }
                }
            }
        }
    }

    // Menu
    &-menu {
        padding-top: 1rem;

        &-ul {

            // First li item
            &>li.menu-item {
                // background-color: $color-white;
                @extend %animation-top-to-bottom;
                @include transform(translateY(-2.5rem));
                opacity: 0;

                // First link item
                &>a {
                    font-size: 1.2rem !important;
                    padding: 1rem 0 !important;
                }
            }

            // All li items
            li.menu-item {
                a {
                    font-size: 1rem;
                    padding: 1rem;
                    border: 0;
                    line-height: 0.8rem;
                    display: flex;
                    flex-direction: row;
                    justify-content: center;
                    text-align: center;
                    width: 100%;
                    // color: $color-gray-600;
                    position: relative;

                    // Link title
                    .irantheme-menu-item-link-title {

                        // Structure title
                        cite {
                            font-style: normal;

                            // Icon
                            .irantheme-menu-item-link-icon {
                                display: inline-block;
                                margin-left: 0.5rem;
                            }

                            // Image
                            .irantheme-menu-item-link-image {
                                width: 1.5rem;
                                height: 1.5rem;
                                object-fit: cover;
                                object-position: center;
                                margin-left: 0.5rem;
                                border-radius: $border-radius-medium;
                            }

                            // Mode
                            .irantheme-menu-item-link-mode {
                                font-weight: bold;
                                font-size: 0.6rem;
                                padding: 0.05rem 0.25rem;
                                line-height: 1rem;
                                display: inline-block;
                                margin-right: 0.25rem;
                                position: relative;
                                top: -1px;
                            }
                        }
                    }

                    // Hover link
                    &:hover {
                        // color: $color-dark;
                        background: transparent;
                    }

                    // Chevron link
                    .irantheme-menu-item-link-icon-chevron {
                        margin-right: 0.5rem;
                        display: flex;
                        align-items: center;
                        font-size: 0.7rem;
                        @include transition(0.2s);
                        @include transform(rotate(0));
                    }

                    &.active {
                        // color: $color-dark;

                        .irantheme-menu-item-link-icon-chevron {
                            @include transform(rotate(180deg));
                        }
                    }
                }
            }

            // All sub menus
            .sub-menu {
                // background-color: $color-gray-100;
                display: none;
                // padding-right: 0.5rem;
            }
        }

        @extend .irantheme-menu-item-link-mode;
    }

    // Social media
    .irantheme-social-media {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: center;
        text-align: center;
        line-height: 0 !important;
        padding-top: 1rem;
        padding-bottom: 1rem;

        li {
            @extend %animation-bottom-to-top;
            @include transform(translateY(2.5rem));
            opacity: 0;

            a {
                padding: 0.5rem;
                display: block;

                i {
                    font-size: 1rem;
                    // color: $color-white;
                    line-height: 1rem;
                    @include transition(0.2s);
                }

                svg {
                    width: 1rem;
                    height: 1rem;
                    // color: $color-white;
                    // fill: $color-white;
                    line-height: 1rem;
                    @include transition(0.2s);

                    path {
                        // fill: $color-white;
                        @include transition(0.2s);
                    }
                }

                &:hover {
                    // color: $color-gray-400;

                    svg,
                    path,
                    i {
                        // color: $color-gray-400;
                        // fill: $color-gray-400;
                    }
                }
            }
        }
    }
}

/*
  =====================================
  White mode
  =====================================
  */
.irantheme-navbar-full-screen {

    &.irantheme-navbar-full-screen-white {
        background-color: $color-white-transparent-9;

        // Close
        .irantheme-navbar-full-screen-close {
            color: $color-gray-600;

            &:hover {
                color: $color-dark;
            }
        }

        // Options
        .irantheme-navbar-full-screen-options {
            &-ul {

                &-item {

                    &-link {
                        color: $color-dark;

                        &:hover {
                            color: $color-gray-600;

                            i {
                                // color: $color-gray-400;
                            }
                        }
                    }
                }
            }
        }

        // Menu
        .irantheme-navbar-full-screen-menu {
            &-ul {

                // First li item
                &>li.menu-item {
                    // background-color: $color-white;
                }

                // All li items
                li.menu-item {
                    a {
                        background: transparent !important;
                        color: $color-dark !important;

                        &:hover {
                            color: $color-gray-600 !important;
                        }

                        &.active {
                            color: $color-gray-600 !important;
                        }
                    }
                }

                // All sub menus
                &>li.menu-item>.sub-menu {
                    // background-color: $color-white-transparent-6;
                }
            }
        }

        // Social media
        .irantheme-social-media {
            li {
                a {
                    i {
                        color: $color-dark;
                    }

                    svg {
                        color: $color-dark;
                        fill: $color-dark;

                        path {
                            fill: $color-dark;
                        }
                    }

                    &:hover {
                        color: $color-gray-500;

                        svg,
                        path,
                        i {
                            color: $color-gray-500;
                            fill: $color-gray-500;
                        }
                    }
                }
            }
        }
    }
}

