/*
=====================================
Wp blocks
=====================================
*/

.irantheme-sidebar-holder {
    .irantheme-sidebar-box-holder {
        background: $color-white;
        border-radius: $border-radius-medium;
        margin-bottom: 30px;
        padding: 1rem;
    }

    .widget-title,
    .irantheme-sidebar-box-title {
        font-size: 0.9rem;
        padding: 1rem;
        font-weight: normal;
        border-bottom: 1px solid $color-gray-100;
        display: flex;
        justify-content: space-between;
        align-items: center;
        color: $color-gray-900;
        margin: -1rem -1rem 1rem;

        &:not(.irantheme-sidebar-box-title-custom-icon)::after {
            content: '\e24e';
            font-family: $font-family-icons;
            color: $color-gray-800;
            font-weight: 300;
            font-size: 1rem;
        }

        &.irantheme-sidebar-box-title-custom-icon {
            i {
                color: $color-gray-800;
                font-weight: 300;
                font-size: 1rem;
            }
        }
    }

    // Wp block latest posts

    .wp-block-latest-posts {
        li {
            margin-bottom: 1rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid $color-gray-100;
            @extend .holding-table;

            &:last-child {
                border-bottom: none !important;
                padding-bottom: 0;
                margin-bottom: 0;
            }

            &>a {
                font-size: 0.8rem;
                color: $color-gray-800;

                &:hover {
                    color: $color-dark;
                }
            }

            .wp-block-latest-posts__featured-image {
                float: right;
                padding-left: 1rem;
                padding-bottom: 1rem;

                img {
                    border-radius: $border-radius-medium;
                    max-width: 100%;
                }
            }

            .wp-block-latest-posts__post-author {
                font-size: 0.7rem;
                color: $color-gray-700;
            }

            .wp-block-latest-posts__post-date {
                font-size: 0.6rem;
                color: $color-gray-600;
            }

            .wp-block-latest-posts__post-excerpt {
                font-size: 0.7rem;
                color: $color-gray-600;
            }
        }
    }

    // Wp block categories list

    .wp-block-categories,
    .wp-block-page-list,
    .irantheme-sidebar-box-holder ul:not([class]) {

        &>li.cat-item:first-child,
        &>li:first-child,
        &>li.wp-block-pages-list__item {
            border-top: none;
        }

        .cat-item,
        .wp-block-pages-list__item,
        li {
            font-size: 0.7rem;
            color: $color-primary;
            border-top: 1px solid $color-gray-100;

            a {
                padding: 0.5rem 0;
                font-size: 0.8rem;
                color: $color-gray-900;
                display: inline-block;
                margin-left: 0.25rem;

                &::before {
                    content: '\f104';
                    font-family: $font-family-icons;
                    margin-left: 0.5rem;
                    font-size: 0.4rem;
                    display: inline-block;
                }

                &:hover {
                    color: $color-primary;

                    &::before {
                        @extend %animation-left-to-right;
                    }
                }
            }

            .children {
                padding-right: 1rem;
            }
        }
    }

    // Wp block search

    .wp-block-search {

        // Label
        &__label {
            font-size: 0.8rem;
            color: $color-gray-600;
        }

        // Inside (Holder)
        &__inside-wrapper {
            border-color: $color-gray-200;
            padding: 4px !important;
            margin: 0 !important;
        }

        &__input {
            height: inherit;
            color: $color-gray-700;
            font-size: 0.8rem;
            padding: 0 1rem !important;

            &::placeholder {
                color: $color-gray-700;
                font-size: 0.8rem;
            }
        }

        &__button {
            height: inherit;
            background: none;
            border: 0;
            outline: none;
            margin: 0;
            padding: 1rem !important;
            background: $color-gray-200;
            font-size: 0.8rem;

            &:hover {
                background: $color-gray-300;
                color: $color-dark;
            }
        }
    }

    // Wp block tag cloud

    .list-tags,
    .wp-block-tag-cloud {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        padding-top: 1rem;

        a {
            font-size: 0.7rem;
            background: $color-darker;
            color: $color-white;
            padding: 0.25rem 0.5rem;
            margin: 0.125rem;
        }
    }

    // Wp block latest comments

    .wp-block-latest-comments {

        // Item
        &__comment {
            border-bottom: 1px solid $color-gray-100;

            &:last-child {
                border-bottom: none !important;
                padding-bottom: 0;
                margin-bottom: 0;
            }

            // Holder of author & link
            &-meta {
                line-height: 1.6rem;
                font-size: 0.8rem;
                color: $color-gray-700;
                padding-right: 0.5rem;
            }

            // Author
            &-author {
                font-size: 0.8rem;
                color: $color-dark;

                &:hover {
                    &::before {
                        @extend %animation-left-to-right;
                    }
                }

                &::before {
                    content: '\f104';
                    font-family: $font-family-icons;
                    font-size: 0.5rem;
                    color: $color-primary;
                    display: inline-block;
                    margin-left: 0.5rem;
                }
            }

            // Post text & link
            &-link {
                font-size: 0.8rem;
                color: $color-primary;

                &:hover {
                    color: $color-primary;
                }
            }

            // Excerpt
            &-excerpt {
                font-size: 0.8rem;
                color: $color-gray-700;
                padding-right: 0.5rem;
            }
        }
    }

    // Wp block video

    *[class*="wp-block-"] {
        figcaption {
            font-size: 0.8rem;
            color: $color-gray-800;
        }
    }

    // Wp block quote

    .wp-block-quote {
        background: $color-gray-100;
        margin-top: 1rem;
        margin-bottom: 1rem;
        padding: 1rem;
        border-right: 4px dashed $color-gray-600;
        font-size: 0.8rem;

        p {
            &::before {
                content: '"';
                margin-left: 0.25rem;
                color: $color-primary;
                font-size: 1rem;
            }

            &::after {
                content: '"';
                margin-right: 0.25rem;
                color: $color-primary;
                font-size: 1rem;
            }
        }

        cite {
            font-size: 0.7rem;
            font-style: italic;
            color: $color-dark;

            &::before {
                content: '~';
                font-family: $font-family-icons;
                position: relative;
                top: 2px;
                margin-left: 0.5rem;
                color: $color-primary;
            }
        }
    }

    // Wp block calendar

    .wp-block-calendar {
        font-size: 0.8rem;
    }

    // Product widgets
    .product_list_widget {
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;

        li {
            margin-bottom: 1rem;

            a {
                img {
                    margin-bottom: 0.5rem;
                }

                display: flex;
                flex-direction: column;

                span {
                    font-size: 0.9rem;
                    margin-bottom: 0.5rem;
                }
            }

            span {
                font-size: 0.8rem;
            }
        }
    }

    .wp-block-search__inside-wrapper {
        display: flex;
        border: 1px solid $color-gray-200;
        align-items: center;

        .wp-block-search__input {
            border: 0;
            outline: 0;
            height: inherit;
            margin-bottom: 0;
            display: flex;
        }

        .wp-block-search__button {}
    }

    .wp-block-calendar {
        td {
            color: $color-gray-700;
        }

        .wp-calendar-nav {

            span,
            a {
                color: $color-gray-600;
            }
        }
    }

    .wc-block-grid__product {
        &-title {
            color: $color-gray-800;
        }

        &-price {
            color: $color-gray-700;
        }

        &-add-to-cart {
            padding-top: 0;

            a {
                border-color: $color-gray-700;
                color: $color-gray-700;
            }
        }
    }

    .product_list_widget {
        a {
            .product-title {
                color: $color-gray-800;
            }
        }

        .woocommerce-Price-amount {
            color: $color-gray-600;
        }
    }

    .wc-block-grid__products {
        margin-bottom: 0;
    }

