/*
=====================================
Communication Google Map Section
=====================================
*/
.irantheme-communication-google-map-section {
    .irantheme-communication-google-map {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;

        // Google map wrapper
        .irantheme-communication-google-map-post-wrapper {
            .irantheme-communication-google-map-iframe-code {
                width: 100%;
                position: relative;

                iframe {
                    position: absolute;
                    top: 0;
                    right: 0;
                    width: 100%;
                    height: 100%;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;
        }
    }
}