/*
=====================================
Showcase Tag Section
=====================================
*/
.irantheme-showcase-tag-section {
    background: transparent;

    .irantheme-showcase-tag {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        // background-color: $color-gray-900;
        width: 100%;
        position: relative;
        text-align: center;
        overflow: hidden;

        &.irantheme-hero-fullscreen {
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;

            @media only screen and (max-width: 991px) {
                height: auto !important;
                // padding: 10rem 0;
            }
        }

        &-content {
            padding-bottom: 2rem;
        }

        .irantheme-content-center {
            display: flex;
            justify-content: center;
            text-align: center;
            width: 100%;
        }

        .irantheme-content-right {
            display: flex;
            justify-content: flex-start;
            text-align: right;
        }

        .irantheme-content-left {
            display: flex;
            justify-content: flex-end;
            text-align: left;
        }

        .irantheme-showcase-typed-holder {
            display: block;

            .typed-cursor {
                display: inline-block;
                font-size: 2.4rem;
                margin-bottom: 1rem;
            }
        }

        // Small heading
        .irantheme-showcase-small-heading {
            font-weight: bold;
            font-size: 1rem;
            // color: $color-gray-100;
            margin-bottom: 0.5rem;
            display: block;
        }

        // Heading
        .irantheme-showcase-heading {
            font-size: 2.4rem;
            display: inline-block;
            // color: $color-white;
            margin-bottom: 1rem;
        }

        // Description
        .irantheme-showcase-description {
            font-size: 1.2rem;
            // color: $color-gray-200;
            margin-bottom: 1rem;
        }

        &.irantheme-gradient-animation {
            animation: gradient-animation ease infinite;
        }

        @keyframes gradient-animation {
            0% {
                background-position: 0% 50%;
            }

            50% {
                background-position: 100% 50%;
            }

            100% {
                background-position: 0% 50%;
            }
        }

        .irantheme-showcase-tags {
            margin-bottom: 1.5rem;
            position: relative;
            z-index: 2;

            &-wrapper {
                width: 100%;
                display: flex;
                align-items: center;
                flex-wrap: wrap;
                row-gap: 1rem;
                column-gap: 1rem;

                &.tag-size-small {
                    .irantheme-showcase-tags-item {
                        &-content {
                            padding: 0.1rem 0.5rem;
                            font-size: 0.8rem;
                            border-radius: 1rem;

                            &-icon {
                                font-size: 0.8rem;
                            }
                        }
                    }
                }

                &.tag-size-medium {
                    .irantheme-showcase-tags-item {
                        &-content {
                            padding: 0.35rem 1rem;
                            font-size: 0.9rem;
                            border-radius: 1rem;

                            &-icon {
                                font-size: 0.95rem;
                            }
                        }
                    }
                }

                &.tag-size-large {
                    .irantheme-showcase-tags-item {
                        &-content {
                            padding: 0.65rem 1.5rem;
                            font-size: 1rem;
                            border-radius: 1rem;

                            &-icon {
                                font-size: 1.1rem;
                            }
                        }
                    }
                }

                .irantheme-showcase-tags-item {
                    display: flex;
                    align-items: center;

                    &-content {
                        background: $color-white-transparent-2;
                        color: $color-white;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        padding: 0.1rem 0.5rem;
                        font-size: 0.85rem;
                        border-radius: $border-radius-low;

                        &-icon {
                            margin-left: 0.5rem;
                            font-size: 0.9rem;
                            line-height: normal;
                        }

                        &-text {
                            cite {
                                font-style: normal;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Small heading
            .irantheme-showcase-small-heading {
                color: $color-dark;
            }

            // Heading
            .irantheme-showcase-heading {
                color: $color-gray-800;
            }

            // Description
            .irantheme-showcase-description {
                color: $color-gray-700;
            }
        }

        .irantheme-showcase-tags {
            &.white {
                .irantheme-showcase-tags-wrapper {
                    .irantheme-showcase-tags-item {
                        &-content {
                            background: $color-white-transparent-1;
                            color: $color-dark;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Small heading
            .irantheme-showcase-small-heading {
                color: $color-white;
            }

            // Heading
            .irantheme-showcase-heading {
                color: $color-gray-200;
            }

            // Description
            .irantheme-showcase-description {
                color: $color-gray-300;
            }
        }

        .irantheme-showcase-tags {
            &.dark {
                .irantheme-showcase-tags-wrapper {
                    .irantheme-showcase-tags-item {
                        &-content {
                            background: $color-dark-transparent-1;
                            color: $color-white;
                        }
                    }
                }
            }
        }
    }
}