/*
=====================================
post section
=====================================
*/
.irantheme-gallery-post-section {
    background: transparent;
    overflow: hidden;

    .irantheme-post-gallery {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // overflow: hidden;

        // Contact wrapper
        .irantheme-post-gallery-post-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-post-gallery-post-holder {
                .irantheme-post-gallery-post-item {
                    overflow: hidden;

                    .irantheme-post-gallery-animation {
                        height: 100%;
                    }

                    .irantheme-post-gallery-post-item-inner-wrapper {
                        overflow: hidden;
                        position: relative;
                        width: 100%;
                        height: 100%;
                        background-color: $color-gray-500;

                        a {
                            position: relative;
                            width: 100%;
                            height: 100%;
                            display: block;
                            direction: rtl;
                        }

                        .irantheme-post-gallery-post-item-overlay {
                            position: absolute;
                            width: 100%;
                            height: 100%;
                            opacity: 0;
                            visibility: hidden;
                            transition: all 0.3s cubic-bezier(0.785, 0.135, 0.15, 0.86);
                            z-index: 999;
                        }

                        .irantheme-post-gallery-post-item-category {
                            position: absolute;
                            width: 100%;
                            top: 0;
                            padding: 1.5rem;
                            // color: $color-white;
                            font-size: 0.7rem;
                            font-weight: 900;
                            transition: all 0.3s cubic-bezier(0.785, 0.135, 0.15, 0.86);
                            z-index: 9999;

                            ul {
                                display: flex;
                                align-items: center;
                                flex-wrap: wrap;
                                overflow: hidden;

                                li {
                                    padding: 0 0.5rem;
                                    margin-bottom: 10px;
                                    margin-left: 10px;
                                    border-radius: $border-radius-low;
                                    // background: rgba(43, 47, 57, 0.5);
                                }
                            }
                        }

                        .irantheme-post-gallery-post-item-image {
                            img {
                                width: 100%;
                                height: 100%;
                                min-height: 100%;
                                object-fit: cover;
                                transition: all 0.3s cubic-bezier(0.785, 0.135, 0.15, 0.86);
                            }

                            width: 100%;
                            height: 100%;
                        }

                        .irantheme-post-gallery-post-item-content {
                            position: absolute;
                            display: flex;
                            flex-direction: column;
                            width: 100%;
                            height: 100%;
                            padding: 1.5rem;
                            transition: all 0.3s cubic-bezier(0.785, 0.135, 0.15, 0.86);
                            z-index: 9999;

                            &-info {
                                font-size: 0.7rem;
                                padding-top: 0.7rem;
                                display: flex;
                                align-items: center;
                                flex-wrap: wrap;

                                // :first-child {
                                //     padding-right: 0;
                                // }

                                &-item {
                                    display: flex;
                                    align-items: center;
                                    // padding: 0 7px;
                                    margin-left: 0.7rem;

                                    i {
                                        margin-left: 0.4rem;
                                    }
                                }

                                &-author {
                                    // color: $color-white;
                                }

                                &-date {
                                    // color: $color-white;
                                }

                                &-comment {
                                    display: flex;
                                    align-items: center;
                                    // color: $color-white;

                                    span {
                                        display: block;
                                        margin-right: 5px;
                                    }
                                }
                            }

                            .irantheme-post-gallery-post-item-content-title {
                                font-size: 1rem;
                                // color: $color-white;
                            }
                        }

                        &.irantheme-post-gallery-item-hover-normal {
                            .irantheme-post-gallery-post-item-overlay {
                                // background-color: $color-dark-transparent-4;
                                visibility: visible;
                                opacity: 1;
                            }
                        }

                        &.irantheme-post-gallery-item-hover-transform {
                            .irantheme-post-gallery-post-item-content {
                                transform: translateY(100%);
                            }

                            .irantheme-post-gallery-post-item-category {
                                transform: translateY(-100%);
                            }

                            .irantheme-post-gallery-post-item-overlay {
                                // background-image: rgba(0, 0, 0, 50%);
                                // background: linear-gradient(180deg, rgba(0, 0, 0, 0.5) 0%, rgba(255, 255, 255, 0) 45%, rgba(0, 0, 0, 0.75) 100%);
                                // background-image: linear-gradient(to top, rgba(0, 0, 0, .75) 0%, transparent 60%);
                            }

                            &:hover {
                                .irantheme-post-gallery-post-item-content {
                                    transform: translateY(0);
                                }

                                .irantheme-post-gallery-post-item-category {
                                    transform: translateY(0);
                                }

                                .irantheme-post-gallery-post-item-overlay {
                                    opacity: 1;
                                    visibility: visible;
                                }
                            }
                        }

                        &.irantheme-post-gallery-item-hover-mask {
                            .irantheme-post-gallery-post-item-content {
                                opacity: 0;
                                visibility: hidden;
                            }

                            .irantheme-post-gallery-post-item-category {
                                opacity: 0;
                                visibility: hidden;
                            }

                            .irantheme-post-gallery-post-item-overlay {
                                // background-color: $color-dark-transparent-4;
                            }

                            &:hover {

                                .irantheme-post-gallery-post-item-content {
                                    opacity: 1;
                                    visibility: visible;
                                }

                                .irantheme-post-gallery-post-item-category {
                                    opacity: 1;
                                    visibility: visible;
                                }

                                .irantheme-post-gallery-post-item-overlay {
                                    opacity: 1;
                                    visibility: visible;
                                }
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Contact wrapper
            .irantheme-post-gallery-post-wrapper {
                .irantheme-post-gallery-post-holder {
                    .irantheme-post-gallery-post-item {
                        .irantheme-post-gallery-post-item-inner-wrapper {

                            // background-color: $color-gray-500;
                            .irantheme-post-gallery-post-item-category {
                                color: $color-white;

                                ul {
                                    li {
                                        background: $color-dark-transparent-6;
                                    }
                                }
                            }

                            .irantheme-post-gallery-post-item-content {

                                &-info {

                                    &-item {


                                        i {}
                                    }

                                    &-author {
                                        color: $color-white;
                                    }

                                    &-date {
                                        color: $color-white;
                                    }

                                    &-comment {
                                        color: $color-white;
                                    }
                                }

                                &-title {
                                    color: $color-white;
                                }
                            }

                            &.irantheme-post-gallery-item-hover-normal {
                                .irantheme-post-gallery-post-item-overlay {
                                    background-image: linear-gradient(to top, $color-dark-transparent-8 0%, transparent 60%);
                                }
                            }

                            &.irantheme-post-gallery-item-hover-transform {
                                .irantheme-post-gallery-post-item-overlay {
                                    background-image: $color-dark-transparent-4;
                                    // background: linear-gradient(180deg, rgba(0, 0, 0, 0.5) 0%, rgba(255, 255, 255, 0) 45%, rgba(0, 0, 0, 0.75) 100%);
                                    background-image: linear-gradient(to top, $color-dark-transparent-8 0%, transparent 60%);
                                }
                            }

                            &.irantheme-post-gallery-item-hover-mask {
                                .irantheme-post-gallery-post-item-overlay {
                                    background-color: $color-dark-transparent-4;
                                }
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Contact wrapper
            .irantheme-post-gallery-post-wrapper {
                .irantheme-post-gallery-post-holder {
                    .irantheme-post-gallery-post-item {
                        .irantheme-post-gallery-post-item-inner-wrapper {

                            // background-color: $color-gray-500;
                            .irantheme-post-gallery-post-item-category {
                                color: $color-dark;

                                ul {
                                    li {
                                        background: $color-white-transparent-6;
                                    }
                                }
                            }

                            .irantheme-post-gallery-post-item-content {

                                &-info {

                                    &-item {


                                        i {}
                                    }

                                    &-author {
                                        color: $color-dark;
                                    }

                                    &-date {
                                        color: $color-dark;
                                    }

                                    &-comment {
                                        color: $color-dark;
                                    }
                                }

                                &-title {
                                    color: $color-dark;
                                }
                            }

                            &.irantheme-post-gallery-item-hover-normal {
                                .irantheme-post-gallery-post-item-overlay {
                                    background-image: linear-gradient(to top, $color-white-transparent-8 0%, transparent 60%);
                                }
                            }

                            &.irantheme-post-gallery-item-hover-transform {
                                .irantheme-post-gallery-post-item-overlay {
                                    background-image: $color-white-transparent-4;
                                    // background: linear-gradient(180deg, rgba(0, 0, 0, 0.5) 0%, rgba(255, 255, 255, 0) 45%, rgba(0, 0, 0, 0.75) 100%);
                                    background-image: linear-gradient(to top, $color-white-transparent-8 0%, transparent 60%);
                                }
                            }

                            &.irantheme-post-gallery-item-hover-mask {
                                .irantheme-post-gallery-post-item-overlay {
                                    background-color: $color-white-transparent-4;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// Gallery post grid style ========================
.irantheme-post-gallery-grid {
    display: grid;
    max-width: 100%;

    &.irantheme-grid-one-col {
        grid-template-columns: repeat(1, 1fr);
    }

    &.irantheme-grid-two-col {
        grid-template-columns: repeat(2, 1fr);
    }

    &.irantheme-grid-three-col {
        grid-template-columns: repeat(3, 1fr);
    }

    &.irantheme-grid-four-col {
        grid-template-columns: repeat(4, 1fr);
    }

    &.irantheme-grid-six-col {
        grid-template-columns: repeat(6, 1fr);
    }

    @media (max-width: 1399.98px) {
        // &.irantheme-grid-four-col {
        //     grid-template-columns: repeat(3, 1fr);
        // }

        // &.irantheme-grid-six-col {
        //     grid-template-columns: repeat(6, 1fr);
        // }
    }

    @media (max-width: 1199.98px) {
        &.irantheme-grid-four-col {
            grid-template-columns: repeat(3, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(4, 1fr);
            }
        }

        &.irantheme-grid-six-col {
            grid-template-columns: repeat(4, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(6, 1fr);
            }
        }
    }

    @media (max-width: 991.98px) {
        &.irantheme-grid-four-col {
            grid-template-columns: repeat(3, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(4, 1fr);
            }
        }

        &.irantheme-grid-six-col {
            grid-template-columns: repeat(3, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(6, 1fr);
            }
        }
    }

    @media (max-width: 767.98px) {
        &.irantheme-grid-two-col {
            grid-template-columns: repeat(2, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(2, 1fr);

                .irantheme-post-gallery-item {
                    grid-column: unset;
                    grid-row: unset;
                }
            }
        }

        &.irantheme-grid-three-col {
            grid-template-columns: repeat(2, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(2, 1fr);

                .irantheme-post-gallery-item {
                    grid-column: unset;
                    grid-row: unset;
                }
            }
        }

        &.irantheme-grid-four-col {
            grid-template-columns: repeat(2, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(2, 1fr);

                .irantheme-post-gallery-item {
                    grid-column: unset;
                    grid-row: unset;
                }
            }
        }

        &.irantheme-grid-six-col {
            grid-template-columns: repeat(2, 1fr);

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: repeat(2, 1fr);

                .irantheme-post-gallery-item {
                    grid-column: unset;
                    grid-row: unset;
                }
            }
        }
    }

    @media (max-width: 575.98px) {
        &.irantheme-grid-two-col {
            grid-template-columns: 1fr;

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: 1fr;
            }
        }

        &.irantheme-grid-three-col {
            grid-template-columns: 1fr;

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: 1fr;
            }
        }

        &.irantheme-grid-four-col {
            grid-template-columns: 1fr;

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: 1fr;
            }
        }

        &.irantheme-grid-six-col {
            grid-template-columns: 1fr;

            &.irantheme-grid-metro-ltr-type,
            &.irantheme-grid-metro-rtl-type {
                grid-template-columns: 1fr;
            }
        }
    }
}

// Gallery post justified style ========================
.irantheme-post-gallery-justified {
    display: flex;
    flex-wrap: wrap;

    &:after {
        content: '';
        flex-grow: 99999;
        min-width: calc(100vw / 4);
    }
}

// Gallery post masonry style ========================
.irantheme-post-gallery-masonry {
    width: 100%;

    &.irantheme-grid-masonry:after {
        /* masonry clearfix */
        content: '';
        display: block;
        clear: both;
    }
}

// Gallery post carousel style ========================
.irantheme-post-gallery-carousel {
    width: 100%;
}