/*
=====================================
Gallery slider
=====================================
*/
.irantheme-gallery-slider-section {
    .irantheme-gallery-slider {
        position: relative;
        background-position: center;
        background-repeat: no-repeat;
        background-size: cover;

        // Wrapper
        &-wrapper {
            position: relative;
            z-index: 2;
        }

        // Animate
        &-animation {
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
        }

        // Item
        &-item {
            display: flex;

            // Link
            &-link {
                width: 100%;
                height: 100%;
                display: flex;
                position: relative;
                overflow: hidden;

                // Image
                &-img {
                    object-fit: fill;
                    width: 100%;
                    height: 100%;

                    &::selection {
                        background-color: transparent;
                        color: inherit
                    }
                }
            }

            // Content
            &-content {
                padding: 2rem;
                display: flex;
                flex-direction: column;
                width: 100%;
                height: 100%;
                position: absolute;
                top: 0;
                right: 0;
                z-index: 1;

                &-heading {
                    font-size: 1rem;
                    // color: $color-white;
                    margin-top: 1rem;
                    line-height: 2rem;
                    width: 100%;

                    &::selection {
                        background-color: transparent;
                        color: inherit
                    }

                    &-link {
                        display: block;
                    }
                }

                &-desc {
                    font-size: 0.8rem;
                }
            }
        }

        .irantheme-post-gallery-carousel {
            .irantheme-gallery-slider-item {
                margin-bottom: 0 !important;
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Item
            .irantheme-gallery-slider-item {

                &-content {
                    &-heading {
                        &-link {
                            color: $color-dark;
                        }
                    }

                    &-desc {
                        color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Item
            .irantheme-gallery-slider-item {

                &-content {
                    &-heading {
                        &-link {
                            color: $color-white;
                        }
                    }

                    &-desc {
                        color: $color-gray-300;
                    }
                }
            }
        }
    }
}