/*
=====================================
post section
=====================================
*/
.irantheme-post-sidebar-section {
    background: transparent;
    overflow: hidden;

    .irantheme-sidebar {
        display: flex;
        flex-direction: column;
        row-gap: 1.5rem;

        .irantheme-sidebar-box-holder {
            margin-bottom: 0;
        }
    }

    .irantheme-post-sidebar {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        // Heading of posts
        &-heading-posts {
            display: flex;
            justify-content: space-between;
            flex-wrap: wrap;
            align-items: center;
            width: 100%;
            margin-bottom: 1rem;

            &-title {
                font-size: 1.1rem;
                // color: $color-gray-700;
            }

            &-link {
                font-size: 0.8rem;
                // color: $color-gray-600;

                i {
                    margin-right: 0.5rem;
                    position: relative;
                    top: 2px;
                }
            }
        }

        .irantheme-post-sidebar-post-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-post-sidebar-post-item-holder {
                // display: flex;

                .row {
                    row-gap: 1.5rem;
                }

                .irantheme-post-sidebar-item {
                    overflow: hidden;
                    height: 100%;
                    @include transition(all, 0.4s, cubic-bezier(0.785, 0.135, 0.15, 0.86));

                    &.irantheme-post-sidebar-item-transparent {
                        background-color: transparent !important;
                    }

                    .irantheme-post-sidebar-animation {
                        height: 100%;
                    }

                    &.irantheme-post-sidebar-item-border-little {
                        // border: 1px solid $color-gray-200;
                        border-style: solid;
                        border-width: 1px;
                    }

                    .irantheme-post-sidebar-item-inner-wrapper {
                        position: relative;
                        // background-color: $color-white;
                        height: 100%;
                        overflow: hidden;
                        display: flex;
                        flex-direction: column;
                        row-gap: 1rem;

                        // Horizontal post
                        &.irantheme-post-sidebar-item-horizontal {
                            flex-direction: row;
                            column-gap: 1rem;
                            row-gap: 1rem;

                            .irantheme-post-sidebar-item-content {
                                padding: 0 !important;
                            }

                            @media screen and (max-width: 768px) {
                                flex-direction: column;
                            }
                        }

                        .irantheme-post-sidebar-item-img {
                            a {
                                display: block;

                                .irantheme-post-sidebar-item-img-wrapper {
                                    overflow: hidden;
                                    position: relative;

                                    img {
                                        width: 100%;
                                        height: 100%;
                                        @include transition(0.2s);
                                    }

                                    &::before {
                                        content: " ";
                                        width: 100%;
                                        height: 100%;
                                        position: absolute;
                                        top: 0;
                                        right: 0;
                                        background: transparent;
                                        transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
                                        z-index: 2;
                                    }
                                }
                            }
                        }

                        .irantheme-post-sidebar-item-content {
                            display: flex;
                            flex-direction: column;
                            row-gap: 0.25rem;
                            padding: 1rem;

                            .irantheme-post-sidebar-item-content-details {
                                display: flex;
                                flex-wrap: wrap;

                                &-date,
                                &-author,
                                &-comment {
                                    font-size: 0.7rem;
                                    // color: $color-gray-600;
                                    display: flex;
                                    flex-wrap: wrap;
                                    align-items: center;

                                    em {
                                        margin-left: 0.25rem;
                                        font-style: normal;
                                    }

                                    a {

                                        &:not(:last-child) {
                                            margin-left: 0.5rem;
                                        }
                                    }

                                    i {
                                        margin-left: 5px;
                                    }
                                }

                                // Separator
                                &-separator {
                                    font-size: 2rem;
                                    margin-right: 0.5rem;
                                    margin-left: 0.5rem;
                                    position: relative;
                                    top: -0.3rem;
                                }
                            }

                            .irantheme-post-sidebar-item-content-title {
                                font-size: 0.9rem;
                            }

                            .irantheme-post-sidebar-item-content-description {
                                font-size: 0.8rem;
                                // color: $color-gray-600;
                            }

                            // Category
                            .irantheme-post-sidebar-item-content-category {
                                font-size: 0.75rem;
                                display: flex;
                                flex-wrap: wrap;

                                a {
                                    &:not(:last-child) {
                                        margin-left: 0.5rem;
                                    }
                                }
                            }
                        }
                    }

                    &.irantheme-post-sidebar-item-zoom-image-hover:hover {
                        .irantheme-post-sidebar-item-img {
                            .irantheme-post-sidebar-item-img-wrapper {
                                img {
                                    @include transform(rotate(2deg) scale(1.1));
                                }
                            }
                        }
                    }

                    &.irantheme-post-sidebar-item-mask-hover:hover {
                        .irantheme-post-sidebar-item-img {
                            .irantheme-post-sidebar-item-img-wrapper {
                                &::before {
                                    background: $color-dark-transparent-4;
                                }
                            }
                        }
                    }

                    &.irantheme-post-sidebar-item-transform-hover:hover {
                        @include transform(translateY(-15px));

                        &.irantheme-post-sidebar-item-shadow-little {
                            box-shadow: none;
                        }

                        &:not(.irantheme-post-sidebar-item-shadow-little) {
                            @extend %box-shadow-white;
                        }
                    }

                    &.irantheme-post-sidebar-item-zoom-post-hover:hover {
                        @include transform(scale(1.03));

                        &.irantheme-post-sidebar-item-shadow-little {
                            box-shadow: none;
                        }

                        &:not(.irantheme-post-sidebar-item-shadow-little) {
                            @extend %box-shadow-white;
                        }
                    }

                    &.irantheme-post-sidebar-item-shadow-hover:hover {
                        &.irantheme-post-sidebar-item-shadow-little {
                            box-shadow: none;
                        }

                        &:not(.irantheme-post-sidebar-item-shadow-little) {
                            @extend %box-shadow-white;
                        }
                    }
                }

                /*
                =====================================
                Slider
                =====================================
                */
                .irantheme-post-sidebar-slider-item {
                    overflow: hidden;
                    @include transition(all, 0.4s, cubic-bezier(0.785, 0.135, 0.15, 0.86));

                    .irantheme-post-sidebar-slider-animation {}

                    .irantheme-post-sidebar-slider-item-inner-wrapper {
                        position: relative;
                        // background-color: $color-white;
                        overflow: hidden;
                        display: flex;
                        flex-direction: column;

                        .irantheme-post-sidebar-slider-item-img {
                            a {
                                display: block;

                                .irantheme-post-sidebar-slider-item-img-wrapper {
                                    overflow: hidden;
                                    position: relative;

                                    // Overlay
                                    &-overlay {
                                        position: absolute;
                                        width: 100%;
                                        height: 100%;
                                        transition: all 0.3s cubic-bezier(0.785, 0.135, 0.15, 0.86);
                                        z-index: 9;
                                        background-image: linear-gradient(to top, rgba(31, 34, 41, 0.9) 0%, transparent 100%);
                                    }

                                    img {
                                        width: 100%;
                                        height: 100%;
                                        object-fit: cover;
                                        @include transition(0.2s);
                                    }

                                    &::before {
                                        content: " ";
                                        width: 100%;
                                        height: 100%;
                                        position: absolute;
                                        top: 0;
                                        right: 0;
                                        background: transparent;
                                        transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
                                        z-index: 2;
                                    }
                                }
                            }
                        }

                        .irantheme-post-sidebar-slider-item-content {
                            display: flex;
                            flex-direction: column;
                            padding: 1rem;
                            position: absolute;
                            bottom: 0;
                            right: 0;
                            height: auto;
                            width: 100%;
                            padding: 2rem;
                            z-index: 99;

                            .irantheme-post-sidebar-slider-item-content-details {
                                display: flex;
                                flex-wrap: wrap;
                                margin-bottom: 1rem;

                                &-date,
                                &-author,
                                &-comment {
                                    font-size: 0.7rem;
                                    // color: $color-gray-600;
                                    display: flex;
                                    flex-wrap: wrap;
                                    align-items: center;

                                    em {
                                        margin-left: 0.25rem;
                                        font-style: normal;
                                    }

                                    a {

                                        &:not(:last-child) {
                                            margin-left: 0.5rem;
                                        }
                                    }

                                    i {
                                        margin-left: 5px;
                                    }
                                }

                                // Separator
                                &-separator {
                                    font-size: 2rem;
                                    margin-right: 0.5rem;
                                    margin-left: 0.5rem;
                                    position: relative;
                                    top: -0.3rem;
                                }
                            }

                            .irantheme-post-sidebar-slider-item-content-title {
                                font-size: 1rem;
                            }

                            .irantheme-post-sidebar-slider-item-content-description {
                                margin-top: 1rem;
                                font-size: 0.8rem;
                                // color: $color-gray-600;
                            }

                            // Category
                            .irantheme-post-sidebar-slider-item-content-category {
                                font-size: 0.75rem;
                                display: flex;
                                flex-wrap: wrap;
                                margin-top: 1rem;

                                a {
                                    &:not(:last-child) {
                                        margin-left: 0.5rem;
                                    }
                                }
                            }
                        }
                    }
                }

                // Slider pagination
                .irantheme-swiper-button-slider {
                    @include transform(none !important);
                }
            }
        }

        .irantheme-post-sidebar-carousel {
            padding-top: 1rem;
            padding-bottom: 2.5rem;
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            // Heading of posts
            .irantheme-post-sidebar-heading-posts {

                &-title {
                    color: $color-gray-700;
                }

                &-link {
                    color: $color-gray-600;
                }
            }

            .irantheme-post-sidebar-post-wrapper {
                .irantheme-post-sidebar-post-item-holder {
                    .irantheme-post-sidebar-item {
                        background-color: $color-white;

                        &.irantheme-post-sidebar-item-border-little {
                            border-color: $color-gray-200;
                        }

                        &.irantheme-post-sidebar-item-shadow-little {
                            @extend %box-shadow-white;
                        }

                        .irantheme-post-sidebar-item-inner-wrapper {

                            .irantheme-post-sidebar-item-content {
                                .irantheme-post-sidebar-item-content-details {

                                    &-date,
                                    &-author,
                                    &-comment {
                                        color: $color-gray-600;

                                        a {
                                            color: $color-gray-600;
                                        }
                                    }

                                    // Separator
                                    &-separator {
                                        color: $color-gray-500;
                                    }
                                }

                                .irantheme-post-sidebar-item-content-title {
                                    a {
                                        color: $color-dark;

                                        &:hover {
                                            color: $color-gray-700;
                                        }
                                    }
                                }

                                .irantheme-post-sidebar-item-content-description {
                                    color: $color-gray-600;
                                }

                                // Category
                                .irantheme-post-sidebar-item-content-category {

                                    a {
                                        color: $color-gray-500;
                                    }
                                }
                            }
                        }
                    }

                    // Slider
                    .irantheme-post-sidebar-slider-item {
                        background-color: $color-white;

                        .irantheme-post-sidebar-slider-item-inner-wrapper {

                            .irantheme-post-sidebar-slider-item-img {
                                a {
                                    .irantheme-post-sidebar-slider-item-img-wrapper {

                                        // Overlay
                                        &-overlay {
                                            background-image: linear-gradient(to top, rgba(31, 34, 41, 0.9) 0%, transparent 100%);
                                        }
                                    }
                                }
                            }

                            .irantheme-post-sidebar-slider-item-content {
                                .irantheme-post-sidebar-slider-item-content-details {

                                    &-date,
                                    &-author,
                                    &-comment {
                                        color: $color-gray-400;

                                        a {
                                            color: $color-gray-400;
                                        }
                                    }

                                    // Separator
                                    &-separator {
                                        color: $color-gray-500;
                                    }
                                }

                                .irantheme-post-sidebar-slider-item-content-title {
                                    a {
                                        color: $color-white;

                                        &:hover {
                                            color: $color-gray-300;
                                        }
                                    }
                                }

                                .irantheme-post-sidebar-slider-item-content-description {
                                    color: $color-gray-400;
                                }

                                // Category
                                .irantheme-post-sidebar-slider-item-content-category {

                                    a {
                                        color: $color-gray-500;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            // Heading of posts
            .irantheme-post-sidebar-heading-posts {

                &-title {
                    color: $color-gray-300;
                }

                &-link {
                    color: $color-gray-400;
                }
            }

            .irantheme-post-sidebar-post-wrapper {
                .irantheme-post-sidebar-post-item-holder {
                    .irantheme-post-sidebar-item {
                        background-color: $color-dark;

                        &.irantheme-post-sidebar-item-border-little {
                            border-color: $color-gray-800;
                        }

                        &.irantheme-post-sidebar-item-shadow-little {
                            @extend %box-shadow-dark;
                        }

                        .irantheme-post-sidebar-item-inner-wrapper {

                            .irantheme-post-sidebar-item-content {
                                .irantheme-post-sidebar-item-content-details {

                                    &-date,
                                    &-author,
                                    &-comment {
                                        color: $color-gray-400;

                                        a {
                                            color: $color-gray-400;
                                        }

                                        &:not(:last-child) {
                                            &::after {
                                                color: $color-gray-500;
                                            }
                                        }
                                    }

                                    // Separator
                                    &-separator {
                                        color: $color-gray-500;
                                    }
                                }

                                .irantheme-post-sidebar-item-content-title {
                                    a {
                                        color: $color-white;

                                        &:hover {
                                            color: $color-gray-300;
                                        }
                                    }
                                }

                                .irantheme-post-sidebar-item-content-description {
                                    color: $color-gray-400;
                                }

                                // Category
                                .irantheme-post-sidebar-item-content-category {

                                    a {
                                        color: $color-gray-500;
                                    }
                                }
                            }

                        }
                    }

                    // Slider
                    .irantheme-post-sidebar-slider-item {
                        background-color: $color-dark;

                        .irantheme-post-sidebar-slider-item-inner-wrapper {

                            .irantheme-post-sidebar-slider-item-img {
                                a {
                                    .irantheme-post-sidebar-slider-item-img-wrapper {

                                        // Overlay
                                        &-overlay {
                                            background-image: linear-gradient(to top, rgba(219, 216, 209, 0.9) 0%, transparent 100%);
                                        }
                                    }
                                }
                            }

                            .irantheme-post-sidebar-slider-item-content {
                                .irantheme-post-sidebar-slider-item-content-details {

                                    &-date,
                                    &-author,
                                    &-comment {
                                        color: $color-gray-600;

                                        a {
                                            color: $color-gray-600;
                                        }

                                        &:not(:last-child) {
                                            &::after {
                                                color: $color-gray-500;
                                            }
                                        }
                                    }

                                    // Separator
                                    &-separator {
                                        color: $color-gray-500;
                                    }
                                }

                                .irantheme-post-sidebar-slider-item-content-title {
                                    a {
                                        color: $color-dark;

                                        &:hover {
                                            color: $color-gray-700;
                                        }
                                    }
                                }

                                .irantheme-post-sidebar-slider-item-content-description {
                                    color: $color-gray-600;
                                }

                                // Category
                                .irantheme-post-sidebar-slider-item-content-category {

                                    a {
                                        color: $color-gray-500;
                                    }
                                }
                            }

                        }
                    }
                }
            }
        }
    }
}