/*
=====================================
Footer white simple
=====================================
*/

#footer-contemporary {

    // Mini menu
    .mini-menu ul {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        width: 100%;
        background: $color-dark;
        padding: 3rem 0;

        li {
            padding: 1rem;

            a {
                color: $color-gray-500;
                font-size: 0.8rem;
            }
        }
    }

    .copyright-contemporary {
        text-align: center;
        background: $color-white;
        padding: 2rem 0;
        font-size: 0.8rem;
        color: $color-gray-500;

        a {
            color: $color-gray-500;
        }
    }
}