/*
=====================================
Business section
=====================================
*/
.irantheme-business-department-section {
    .irantheme-business-department {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Viewpoints
        .irantheme-business-department-post-swiper {}

        .irantheme-business-department-post-wrapper {
            text-align: right;
            position: relative;
            z-index: 2;

            // Item
            .irantheme-business-department-post-item {
                padding: 1rem;
                position: relative;
                margin-bottom: 0;

                &.irantheme-business-department-post-item-transparent {
                    background-color: transparent !important;
                }

                // Shadow
                &.irantheme-business-department-item-shadow {
                    @extend %box-shadow-white;
                }

                // Image user
                &-image {
                    display: flex;
                    align-items: center;
                    height: 100%;

                    @media only screen and (max-width:991px) {
                        margin-bottom: 1rem;
                    }

                    &-src {
                        width: 100%;
                        height: auto;
                    }

                }

                // Heading
                &-heading {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    height: 100%;

                    @media only screen and (max-width:991px) {
                        margin-bottom: 1rem;
                    }

                    // Title
                    &-title {
                        // color: $color-white;
                        font-size: 1.2rem;
                        margin-bottom: 1rem;
                    }

                    // Small title
                    &-small-title {
                        // color: $color-white;
                        font-size: 0.8rem;

                        &-list {
                            display: flex;
                            flex-wrap: wrap;

                            &-item {
                                font-size: 0.8rem;

                                &:not(:first-child)::before {
                                    content: '';
                                    width: 5px;
                                    height: 5px;
                                    border-radius: $border-radius-low;
                                    background: $color-gray-400;
                                    display: inline-block;
                                    margin-right: 1rem;
                                    margin-left: 1rem;
                                }
                            }
                        }
                    }
                }

                // Description
                &-description {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    height: 100%;

                    @media only screen and (max-width:991px) {
                        margin-bottom: 1rem;
                    }

                    // Description
                    &-desc {
                        // color: $color-gray-100;
                        font-size: 0.7rem;

                        &.irantheme-business-department-width-limited {
                            max-width: 50%;

                            @media only screen and (max-width: 991px) {
                                max-width: 100%;
                            }
                        }
                    }

                    // Icon
                    &-icon {
                        // color: $color-gray-100;
                        font-size: 1rem;
                        margin-bottom: 1rem;
                    }

                    // Link
                    &-link {
                        display: flex;
                        align-items: center;
                        justify-content: flex-end;
                        height: 100%;

                        a {
                            width: 2.5rem;
                            height: 2.5rem;
                            border-radius: $border-radius-medium;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            font-size: 1rem;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            // Viewpoints
            .irantheme-business-department-post-wrapper {

                // Item
                .irantheme-business-department-post-item {
                    background-color: $color-white;

                    // Shadow
                    &.irantheme-business-department-item-shadow {
                        @extend %box-shadow-white;
                    }

                    // Heading
                    &-heading {

                        // Title
                        &-title {
                            color: $color-gray-800;
                        }

                        // Small title
                        &-small-title {
                            &-list {

                                &-item {
                                    color: $color-gray-600;

                                    &:not(:first-child)::before {
                                        background: $color-gray-400;
                                    }
                                }
                            }
                        }
                    }

                    // Description
                    &-description {

                        // Description
                        &-desc {
                            color: $color-gray-600;
                        }

                        // Icon
                        &-icon {
                            color: $color-gray-900;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            // Viewpoints
            .irantheme-business-department-post-wrapper {

                // Item
                .irantheme-business-department-post-item {
                    background-color: $color-dark;

                    // Shadow
                    &.irantheme-business-department-item-shadow {
                        @extend %box-shadow-dark;
                    }

                    // Heading
                    &-heading {

                        // Title
                        &-title {
                            color: $color-gray-200;
                        }

                        // Small title
                        &-small-title {
                            &-list {

                                &-item {
                                    color: $color-gray-400;

                                    &:not(:first-child)::before {
                                        background: $color-gray-600;
                                    }
                                }
                            }
                        }
                    }

                    // Description
                    &-description {

                        // Description
                        &-desc {
                            color: $color-gray-400;
                        }

                        // Icon
                        &-icon {
                            color: $color-gray-100;
                        }
                    }
                }
            }
        }
    }
}