/*
=====================================
Archive and blog
=====================================
*/

.irantheme-archive,
.irantheme-blog,
.irantheme-single {
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    background-attachment: fixed;
    background-color: $color-gray-100;
    position: relative;
    padding: 3rem 0 1.5rem;

    &.white {
        background-color: $color-gray-100;
    }

    &.dark {
        background-color: $color-gray-900;
    }
}

.irantheme-row-content {
    @media screen and (max-width:992px) {
        order: 1;
    }
}

.irantheme-row-sidebar {
    @media screen and (max-width:992px) {
        order: 2;
    }
}

/*
=====================================
Post little box
=====================================
*/
.irantheme-archive-traditional {
    .post-holder {
        margin-bottom: 30px;
    }

    .post-box-little {
        background: $color-gray-100;
        height: 100%;
        display: block;
        border-radius: $border-radius-medium;
        overflow: hidden;

        &:hover {
            .post-thumbnail-little {
                img {
                    // opacity: 0.75;
                }
            }
        }

        .post-thumbnail-little {
            width: 100%;
            position: relative;
            overflow: hidden;

            img {
                width: 100%;
                height: 100%;
                @include transition(all, 0.3s, ease-out);
            }
        }

        .post-content {
            padding: 1rem;

            // Category
            .post-category {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                margin-bottom: 0.5rem;

                a {
                    font-size: 0.7rem;

                    &:not(:last-child) {
                        &::after {
                            content: '.';
                            color: $color-dark;
                            border-radius: 50%;
                            margin-right: 0.5rem;
                            margin-left: 0.5rem;
                            font-size: 1.4rem;
                            display: inline-block;
                        }
                    }
                }
            }

            // Heading
            .post-heading {
                margin-bottom: 0.5rem;

                span {
                    font-size: 0.7rem;
                    color: $color-gray-700;

                    i {
                        margin-left: 0.5rem;
                        color: $color-primary;
                    }
                }

                h2 {
                    font-size: 1.1rem;
                    line-height: normal;

                    a {
                        color: $color-dark;

                        &:hover {
                            opacity: 0.8;
                        }
                    }
                }
            }

            // Options
            .post-options-little {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                margin-bottom: 0.5rem;

                span {
                    cursor: default;
                    font-size: 0.7rem;
                    color: $color-gray-600;
                    display: flex;
                    flex-wrap: wrap;
                    align-items: center;

                    &:not(:last-child) {

                        &::after {
                            content: '|';
                            margin-right: 0.5rem;
                            margin-left: 0.5rem;
                            color: $color-gray-500;
                            font-size: 0.7rem;
                        }
                    }

                    em {
                        font-style: normal;
                        margin-right: 0.5rem;
                    }

                    a {
                        font-size: 0.7rem;
                        color: $color-gray-600;
                    }
                }
            }

            // Post text
            .post-text {
                font-size: 0.8rem;
                color: $color-gray-700;
                margin-bottom: 0.5rem;
            }

            .post-read-more {
                a {
                    font-size: 0.7rem;
                }
            }
        }

    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .post-box-little {
            background-color: $color-white;

            .post-content {

                // Category
                .post-category {
                    a {
                        &:not(:last-child) {
                            &::after {
                                color: $color-dark;
                            }
                        }
                    }
                }

                // Heading
                .post-heading {
                    span {
                        color: $color-gray-700;

                        i {
                            color: $color-primary;
                        }
                    }

                    h2 {

                        a {
                            color: $color-dark;
                        }
                    }
                }

                // Options
                .post-options-little {
                    span {
                        color: $color-gray-600;

                        &:not(:last-child) {
                            &::after {
                                color: $color-gray-500;
                            }
                        }

                        a {
                            color: $color-gray-600;
                        }
                    }
                }

                // Post text
                .post-text {
                    color: $color-gray-700;
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .post-box-little {
            background-color: $color-dark;

            .post-content {

                // Category
                .post-category {
                    a {
                        &:not(:last-child) {
                            &::after {
                                color: $color-white;
                            }
                        }
                    }
                }

                // Heading
                .post-heading {
                    span {
                        color: $color-gray-300;

                        i {
                            color: $color-primary;
                        }
                    }

                    h2 {

                        a {
                            color: $color-white;
                        }
                    }
                }

                // Options
                .post-options-little {
                    span {
                        color: $color-gray-400;

                        &:not(:last-child) {
                            &::after {
                                color: $color-gray-500;
                            }
                        }

                        a {
                            color: $color-gray-400;
                        }
                    }
                }

                // Post text
                .post-text {
                    color: $color-gray-300;
                }
            }
        }
    }
}

/*
=====================================
luxurious archive
=====================================
*/
.irantheme-archive-luxurious {

    .post-holder {
        margin-bottom: 30px;
    }

    .post {
        background: $color-white;
        overflow: hidden;
        border-radius: $border-radius-high;
        display: flex;
        -webkit-box-orient: vertical;
        -webkit-box-direction: normal;
        -ms-flex-direction: column;
        flex-direction: column;
        width: 100%;
        height: 100%;

        // Post image
        &-image {
            &-link {
                display: block;
                overflow: hidden;
                position: relative;

                &::before {
                    content: '';
                    position: absolute;
                    top: 0;
                    right: 0;
                    width: 100%;
                    height: 100%;
                    background: $color-dark-transparent-2;
                    z-index: 1;
                    @include transition(0.25s, all, ease-in);
                }

                img {
                    @include transition(0.3s, all, ease-in-out);
                    @include transform(scale(1.11));
                    width: 100%;
                }

                &:hover {
                    img {
                        @include transform(scale(1.01));
                    }

                    &::before {
                        opacity: 0;
                    }
                }
            }
        }

        // Post content
        .post-content {
            background: $color-white;
            padding: 1rem;
            width: calc(100% - 2rem);
            margin-right: auto;
            margin-left: auto;
            margin-bottom: 0;
            border-radius: $border-radius-high;
            // @include transform(translateY(-5rem));
            position: relative;
            z-index: 2;
            overflow: hidden;

            &-top {
                display: flex;
                flex-wrap: wrap;
                margin-bottom: 1rem;

                /* Post category */
                .post-category {
                    display: flex;
                    -webkit-box-orient: horizontal;
                    -webkit-box-direction: normal;
                    -ms-flex-direction: row;
                    flex-direction: row;
                    z-index: 2;

                    a {
                        margin-left: 0.5rem;
                        /* border-radius: $border-radius-low; */
                        font-size: 0.7rem;
                        color: $color-dark;
                        @include transition(0.3s, all, ease-in-out);
                        display: inline-block;

                        &:not(:last-child) {
                            margin-left: 0.5rem;
                        }

                        &:hover {
                            opacity: 0.8;
                        }
                    }
                }

                // Post date
                .post-date {
                    margin-right: 0.5rem;

                    span {
                        font-size: 0.7rem;
                        color: $color-gray-600;
                    }
                }
            }


            // Post heading
            .post-heading {
                margin-bottom: 1rem;

                h2 {
                    a {
                        display: block;
                        font-size: 1.1rem;
                        color: $color-gray-900;
                        line-height: normal;
                    }
                }
            }
        }

        // Post text
        .post-text {
            font-size: 0.8rem;
            color: $color-gray-700;
            /* text-align: justify; */
            line-height: 1.6rem;

            p {
                margin-bottom: 0;
            }

            a {
                color: $color-gray-500;

                &:hover {
                    color: $color-gray-700;
                }
            }

            img {
                display: none;
            }
        }

        .post-read-more {
            a {
                font-size: 0.8rem;
            }
        }

        // Post info
        .post-info {
            padding: 0 2rem 1rem;
            display: flex;
            flex-wrap: wrap;

            &-option {
                display: flex;
                align-items: center;

                &:not(:last-child) {
                    &::after {
                        content: '-';
                        color: $color-gray-600;
                        border-radius: 50%;
                        margin-right: 1rem;
                        margin-left: 1rem;
                        position: relative;
                        top: 2px;
                    }
                }

                &-text {
                    display: flex;
                    flex-direction: row;
                    align-items: center;

                    i {
                        color: $color-gray-600;
                        font-size: 0.8rem;
                    }

                    cite {
                        line-height: 1;
                        font-style: normal;
                        font-size: 0.7rem;
                        color: $color-gray-600;
                        font-weight: normal;
                        margin-right: 0.5rem;
                    }

                    span,
                    a {
                        margin-right: 0.5rem;
                        font-size: 0.7rem;
                        color: $color-gray-600;
                    }
                }
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .post {
            background: $color-white;

            // Post image
            &-image {
                &-link {
                    &::before {
                        background: $color-dark-transparent-2;
                    }
                }
            }

            // Post content
            .post-content {
                background: $color-white;

                &-top {

                    /* Post category */
                    .post-category {

                        a {
                            color: $color-dark;
                        }
                    }

                    // Post date
                    .post-date {

                        span {
                            color: $color-gray-600;
                        }
                    }
                }


                // Post heading
                .post-heading {
                    h2 {
                        a {
                            color: $color-gray-900;
                        }
                    }
                }
            }

            // Post text
            .post-text {
                color: $color-gray-700;

                a {
                    color: $color-gray-500;

                    &:hover {
                        color: $color-gray-700;
                    }
                }
            }

            // Post info
            .post-info {

                &-option {

                    &:not(:last-child) {
                        &::after {
                            color: $color-gray-600;
                        }
                    }

                    i {
                        color: $color-gray-600;
                    }

                    &-text {

                        i {
                            color: $color-gray-600;
                        }

                        cite {
                            color: $color-gray-600;
                        }

                        span,
                        a {
                            color: $color-gray-600;
                        }
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .post {
            background: $color-dark;

            // Post image
            &-image {
                &-link {
                    &::before {
                        background: $color-white-transparent-2;
                    }
                }
            }

            // Post content
            .post-content {
                background: $color-dark;

                &-top {

                    /* Post category */
                    .post-category {

                        a {
                            color: $color-white;
                        }
                    }

                    // Post date
                    .post-date {

                        span {
                            color: $color-gray-400;
                        }
                    }
                }


                // Post heading
                .post-heading {
                    h2 {
                        a {
                            color: $color-gray-100;
                        }
                    }
                }
            }

            // Post text
            .post-text {
                color: $color-gray-300;

                a {
                    color: $color-gray-500;

                    &:hover {
                        color: $color-gray-300;
                    }
                }
            }

            // Post info
            .post-info {

                &-option {

                    &:not(:last-child) {
                        &::after {
                            color: $color-gray-400;
                        }
                    }

                    i {
                        color: $color-gray-400;
                    }

                    &-text {

                        i {
                            color: $color-gray-400;
                        }

                        cite {
                            color: $color-gray-400;
                        }

                        span,
                        a {
                            color: $color-gray-400;
                        }
                    }
                }
            }
        }
    }
}

/*
=====================================
contemporary archive
=====================================
*/
.irantheme-archive-contemporary {
    position: relative;
    z-index: 1;

    .post-holder {
        margin-bottom: 30px;
    }

    .heading-mode {
        padding: 2rem 15px 0;
    }

    .post {
        position: relative;
        height: 100%;
        background: $color-white;
        border-radius: $border-radius-medium;
        overflow: hidden;

        // Link
        .post-link {
            position: relative;
            display: block;
        }

        // Image
        .post-image {
            width: 100%;
            display: flex;
            position: relative;
            overflow: hidden;

            img {
                width: 100%;
                object-fit: cover;
                @include transition(all, 0.4s, cubic-bezier(0.785, 0.135, 0.15, 0.86));
            }
        }

        // Categories
        .post-categories {
            display: flex;
            flex-direction: row;
            flex-wrap: wrap;
            width: 100%;
            padding: 1rem 1rem 0;

            &.post-category-fixed {
                z-index: 9;
                position: absolute;
                top: 0;
                right: 0;
            }

            a {
                background: $color-dark;
                border-radius: $border-radius-medium;
                color: $color-gray-100;
                font-size: 0.7em;
                margin: 0 0 0.5rem 0.5rem;
                padding: 0 0.5rem;
                display: flex;
                align-items: center;
            }
        }

        // Content
        .post-content {
            width: 100%;
            padding: 1rem;

            // Heading
            .post-heading {
                margin-bottom: 0;

                h2 {
                    font-size: 0.9rem;
                    line-height: 1.6rem;
                    font-weight: normal;
                    color: $color-dark;
                    margin-bottom: 0;
                    position: relative;
                    margin-bottom: 0.5rem;

                    a {
                        display: block;
                    }
                }
            }

            p {
                font-size: 0.8rem;
                color: $color-gray-700;
                margin-bottom: 0.25rem;
            }

            .post-read-more {
                a {
                    font-size: 0.8rem;
                }
            }
        }

        // Post info
        .post-info {
            display: flex;
            align-items: center;
            flex-wrap: wrap;
            padding: 0 1rem 1rem;
            width: 100%;

            &>*:not(:last-child)::after {
                content: '-';
                border-radius: 50%;
                color: $color-gray-600;
                margin-left: 0.5rem;
                margin-right: 0.5rem;
                display: inline-block;
                position: relative;
                top: 1px;
            }

            // Author
            &-author {
                display: flex;
                align-items: center;

                &-img {
                    width: 2rem;

                    img {
                        width: 100%;
                        height: auto;
                        object-fit: cover;
                        border-radius: 50%;
                    }
                }

                h4 {
                    font-size: 0.75rem;
                    margin-right: 0.5rem;

                    a {
                        color: $color-gray-600;
                    }
                }
            }

            // Date
            &-date {
                font-size: 0.75rem;
                color: $color-gray-600;
            }

            // Like
            &-like {
                font-size: 0.75rem;
                color: $color-gray-600;

                span {
                    margin-right: 0.25rem;
                }
            }

            // Comment
            &-comment {
                font-size: 0.75rem;
                color: $color-gray-600;

                span {
                    margin-right: 0.25rem;
                }
            }
        }

        // Icons
        .post-icons {
            position: absolute;
            top: 0;
            left: 0;
            z-index: 3;

            i {
                border-radius: 50%;
                color: $color-gray-100;
                display: flex;
                justify-content: center;
                align-items: center;
                @include transition(all, 0.6s, cubic-bezier(0.785, 0.135, 0.15, 0.86));
                opacity: 1;
                font-size: 1.6rem;
                opacity: 0;
                padding: 1rem;
                @include transform(translateY(1rem));
                cursor: zoom-in;

                &:hover {
                    color: $color-gray-400;
                }
            }
        }

        &:hover {
            .post-image img {
                @include transform(scale(1.2));
            }

            .post-content {
                opacity: 1;
                visibility: visible;

                .post-heading {
                    position: relative;

                    h2 {
                        opacity: 1;
                        visibility: visible;
                        @include transform(translateY(0));
                    }

                    .post-categories {
                        opacity: 1;
                        visibility: visible;
                        @include transform(translateY(0));
                    }
                }
            }

            .post-icons {
                i {
                    @include transform(translateY(0));
                    opacity: 1;
                }
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .post {
            background: $color-white;

            // Categories
            .post-categories {

                a {
                    background: $color-dark;
                    color: $color-gray-100;
                }
            }

            // Content
            .post-content {

                // Heading
                .post-heading {

                    h2 {

                        a {
                            color: $color-dark;
                        }
                    }
                }

                p {
                    color: $color-gray-700;
                }
            }

            // Post info
            .post-info {
                &>*:not(:last-child)::after {
                    color: $color-gray-500;
                }

                // Author
                &-author {
                    h4 {
                        a {
                            color: $color-gray-500;
                        }
                    }
                }

                // Date
                &-date {
                    color: $color-gray-500;
                }

                // Like
                &-like {
                    color: $color-gray-500;
                }

                // Comment
                &-comment {
                    color: $color-gray-500;
                }
            }

            // Icons
            .post-icons {

                i {
                    color: $color-gray-100;

                    &:hover {
                        color: $color-gray-400;
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .post {
            background: $color-dark;

            // Categories
            .post-categories {

                a {
                    background: $color-white;
                    color: $color-gray-900;
                }
            }

            // Content
            .post-content {

                // Heading
                .post-heading {

                    h2 {

                        a {
                            color: $color-white;
                        }
                    }
                }

                p {
                    color: $color-gray-300;
                }
            }

            // Post info
            .post-info {
                &>*:not(:last-child)::after {
                    color: $color-gray-500;
                }

                // Author
                &-author {
                    h4 {
                        a {
                            color: $color-gray-500;
                        }
                    }
                }

                // Date
                &-date {
                    color: $color-gray-500;
                }

                // Like
                &-like {
                    color: $color-gray-500;
                }

                // Comment
                &-comment {
                    color: $color-gray-500;
                }
            }

            // Icons
            .post-icons {

                i {
                    color: $color-gray-900;

                    &:hover {
                        color: $color-gray-600;
                    }
                }
            }
        }
    }
}

/*
=====================================
technological archive
=====================================
*/
.irantheme-archive-technological {
    position: relative;

    .post-holder {
        margin-bottom: 30px;
    }

    .post {
        display: block;
        position: relative;
        overflow: hidden;
        background-color: $color-white;
        border-radius: $border-radius-medium;
        height: 100%;
        @include transition(all, 0.4s, cubic-bezier(0.785, 0.135, 0.15, 0.86));

        &:hover {
            @include transform(translateY(-15px));
            @extend %box-shadow-white;
        }

        // Image
        .post-image {

            // Standard
            a {
                display: block;

                img {
                    width: 100%;
                    height: auto;
                    object-fit: cover;
                }
            }

            // Quote
            &__quote {
                padding: 10rem 2rem 0;
                text-align: right;
                font-size: 10rem;
                color: $color-white;
                font-family: sans-serif;
            }
        }

        // Content
        .post-content {
            padding: 2rem;

            // Categories
            &__categories {
                display: flex;
                flex-direction: row;
                flex-wrap: wrap;
                margin-bottom: 1rem;

                a {
                    color: $color-primary;
                    font-size: 0.7rem;
                    margin-left: 1rem;
                }
            }

            // Heading
            &__heading {
                margin-bottom: 0;

                h2 {
                    font-size: 1rem;
                    line-height: 1.6rem;
                    color: $color-dark;
                    margin-bottom: 1rem;

                    a {
                        color: $color-dark;
                    }
                }
            }

            // Text
            &__text {
                p {
                    font-size: 0.75rem;
                    color: $color-gray-600;
                }
            }

            // Read more
            .post-read-more {
                a {
                    font-size: 0.8rem;
                }
            }

            // Info
            &__info {
                padding-top: 2rem;
                display: flex;
                flex-wrap: wrap;
                align-items: center;

                // Item
                &-item,
                a {
                    font-size: 0.6rem;
                    color: $color-gray-500;

                    &:not(:last-child) {
                        margin-left: 1rem;
                    }

                    span {
                        margin-right: 0.25rem;
                    }
                }
            }
        }

        // Post quote
        &.post-quote {
            background-color: $color-primary !important;

            // Heading
            .post-content__heading {
                h2 {
                    a {
                        color: $color-white !important;
                    }
                }
            }

            // Text
            .post-content__text {
                display: none;
            }

            // Info
            .post-content__info {
                &-date {
                    color: $color-gray-200;
                }
            }
        }

        // Post video, audio, gallery
        &.post-video,
        &.post-audio,
        &.post-gallery {
            background-repeat: no-repeat;
            background-size: cover;
            background-position: center;
            background-color: $color-dark;

            // Image
            .post-image {
                position: relative;
                z-index: 3;

                // Video & Audio & gallery
                &__video,
                &__audio,
                &__gallery {
                    padding: 2rem;
                    min-height: 300px;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    font-size: 6rem;
                    color: $color-white;
                    font-family: sans-serif;

                    a {
                        color: $color-gray-600;

                        &:hover {
                            color: $color-gray-100;
                        }
                    }

                }
            }

            &::before {
                content: '';
                background-color: $color-dark-transparent-6;
                position: absolute;
                width: 100%;
                height: 100%;
                top: 0;
                right: 0;
                z-index: 1;
            }

