    }

    .post-content {}

    // Post image
    .post-image {
        a.post-image-link {
            display: block;
        }
    }

    // Post thumbnail
    .post-thumbnail {
        position: relative;
        border-radius: $border-radius-medium;
        overflow: hidden;

        &::before {
            content: '';
            width: 100%;
            height: 100%;
            position: absolute;
            top: 0;
            right: 0;
            background: transparent;
            transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
            z-index: 2;
        }

        // Post image link hover
        &:hover {
            img {
                transform: scale(1.2);
            }

            &::before {
                background: $color-dark-transparent-2;
            }
        }

        img {
            width: 100%;
            transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
        }
    }

    // Post slider
    .post-slider {
        .post-slider-link {
            display: block;
            position: relative;
        }

        .post-image-slider-buttons {
            position: absolute;
            bottom: 0;
            left: 0;
            display: -webkit-box;
            display: -ms-flexbox;
            display: flex;
            -webkit-box-orient: horizontal;
            -webkit-box-direction: normal;
            -ms-flex-direction: row;
