        }

        i {
            margin-right: 1rem;
            position: relative;
            top: 1px;
            animation-name: rotator;
            animation-timing-function: linear;
            animation-duration: 1.25s;
            animation-iteration-count: infinite;
            animation-play-state: paused;
        }
    }
}

@keyframes rotator {
    from {
        transform: rotate(0);
    }

    to {
        transform: rotate(360deg);
    }
}

/*
=====================================
Categories
=====================================
*/
.irantheme-categories-trigger {
    margin-bottom: 1rem;

    ul {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;

        // justify-content: center;
        /* background-color: $color-gray-100; */
        li {
            margin-bottom: 0.5rem;

            &:not(:last-child) {
                margin-left: 0.5rem;
            }

            span {
                background-color: $color-white;
                padding: 0.25rem 1rem;
                font-size: 0.8rem;
                color: $color-gray-700;
                cursor: pointer;
                transition: all 0.1s ease-in-out;
                border-radius: $border-radius-low;
                display: flex;
                align-items: center;

                i {
                    margin-left: 0.5rem;
                }

                &.active {
                    background-color: $color-gray-300;
                    opacity: 1;
                    color: $color-white;
                }
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        ul {
            li {
                span {
                    background-color: $color-white;
                    color: $color-gray-700;

                    &.active {
                        background-color: $color-gray-500;
                        color: $color-white;
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        ul {
            li {
                span {
                    background-color: $color-dark;
                    color: $color-gray-300;

                    &.active {
                        background-color: $color-gray-500;
                        color: $color-white;
                    }
                }
            }
        }
    }
}

/*
=====================================
Related post
=====================================
*/
.post-box-style {

    .post-box-item {
        margin-bottom: 2rem;
    }

    .post-box-image-space {
        margin-bottom: 1rem;
    }

    .post-box-thumbnail-space {
        overflow: hidden;
        aspect-ratio: 4/3;

        img {
            height: 100%;
            width: 100%;
            object-fit: cover;
            @include transition(all, 0.3s, ease-out);

            &:hover {
                @include transform(scale(1.1) rotate(-2.5deg));
                opacity: 0.9;
            }
        }

        @media (max-width: 1199px) {
            height: 8rem;
        }

        @media (max-width: 991px) {
            height: 20rem;
        }
    }

    .post-box-content-space {
        padding: 0;
    }

    .post-box-heading-space {
        margin-bottom: 0.5rem;

        span {
            font-size: 0.7rem;
            display: none;

            i {
                margin-left: 0.5rem;
            }
        }

        h2 {
            font-size: 0.9rem;
            line-height: 1.4rem;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;

            a {
                color: $color-gray-800;
            }
        }
    }

    // Options
    .post-box-list-options {
        span {
            cursor: default;
            font-size: 0.7rem;
            color: $color-gray-600;

            &:not(:last-child) {
                margin-left: 1rem;
            }

            i {
                margin-left: 0.5rem;
                font-size: 0.8rem;
                position: relative;
                top: 2px;
            }

            em {
                margin-right: 0.5rem;
                font-style: normal;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .post-box-heading-space {

            h2 {
                a {
                    color: $color-gray-800;
                }
            }
        }

        // Options
        .post-box-list-options {
            span {
                color: $color-gray-600;
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .post-box-heading-space {

            h2 {
                a {
                    color: $color-gray-200;
                }
            }
        }

        // Options
        .post-box-list-options {
            span {
                color: $color-gray-400;
            }
        }
    }
}