.irantheme-wc-notice {
    &-error {
        padding: 1rem;
        display: flex;
        align-items: center;
        flex-direction: column;
        position: relative;

        &-item {
            padding: 0.5rem 1rem;
            background-color: $color-tip-error-background;
            color: $color-tip-error-color;
            border: 1px solid $color-tip-error-border;
            border-radius: $border-radius-medium;
            font-size: 0.9rem;
            display: flex;
            align-items: center;
            justify-content: center;

            &::before {
                position: relative;
                content: "\f071";
                font-weight: 300;
                font-family: $font-family-icons;
                font-size: 1.2rem;
                margin-left: 1rem;
                color: $color-tip-error-color;
            }
        }
    }

    &-info {
        padding: 0.5rem 1rem;
        background-color: $color-tip-info-background;
        color: $color-tip-info-color;
        border: 1px solid $color-tip-info-border;
        border-radius: $border-radius-medium;
        font-size: 0.9rem;
        display: flex;
        align-items: center;
        justify-content: center;

        &::before {
            position: relative;
            content: "\f071";
            font-weight: 300;
            font-family: $font-family-icons;
            font-size: 1.2rem;
            margin-left: 1rem;
            color: $color-tip-info-color;
        }
    }

    &-success {
        padding: 0.5rem 1rem;
        background-color: $color-tip-success-background;
        color: $color-tip-success-color;
        border: 1px solid $color-tip-success-border;
        border-radius: $border-radius-medium;
        font-size: 0.9rem;
        display: flex;
        align-items: center;
        justify-content: center;

        &::before {
            position: relative;
            content: "\f071";
            font-weight: 300;
            font-family: $font-family-icons;
            font-size: 1.2rem;
            margin-left: 1rem;
            color: $color-tip-success-color;
        }
    }
}