/*
=====================================
Header main
=====================================
*/
.irantheme-header-main {
    position: relative;
    z-index: 999999;
    width: 100%;
    @include transition(0.2s);
    cursor: default;

    .irantheme-header-row {
        display: flex;
        width: 100%;
    }

    // Full width header
    .irantheme-header-alignment-full {
        width: 100%;
        padding: 0 0.75rem;

        .irantheme-header-alignment {
            margin-right: 0 !important;
            margin-left: 0 !important;
        }
    }

    // Header fixed
    &.irantheme-header-fixed {
        position: absolute;
        top: 0;
        right: 0;
    }

    // Header sticky
    &.irantheme-header-sticky {
        position: fixed;
        top: 0;
        right: 0;
    }

    // Alignments
    .irantheme-header-alignment {
        width: 100%;
        position: relative;
        @include transition(0.2s);

        .irantheme-header-row {
            width: 100%;
            height: inherit;
            flex-wrap: nowrap;
            margin-left: 0 !important;
            margin-right: 0 !important;

            .irantheme-header-col {
                display: flex;
                padding-right: 0.75rem;
                padding-left: 0.75rem;
                column-gap: 1.5rem;
                align-items: center;
            }
        }

        .irantheme-header-wrapper-main {
            width: 100%;
            display: flex;
            align-items: center;
            @include transition(0.2s);
        }

        // Column three =======================================
        &.irantheme-header-alignment-column-three {
            .irantheme-header-wrapper-main {
                .irantheme-header-row {
                    justify-content: space-between;

                    .irantheme-header-col:nth-child(2) {
                        flex-grow: 1;

                        .irantheme-search-form {
                            @media only screen and (max-width: 1199px) {
                                display: none !important;
                            }
                        }
                    }

                    .irantheme-header-col:last-child {
                        justify-content: flex-end;
                        flex-grow: 1;
                    }
                }
            }

            .irantheme-header-wrapper-menu {
                padding: 0.5rem 0;

                .irantheme-header-row {
                    justify-content: space-between;

                    .irantheme-header-col:last-child {
                        justify-content: flex-end;
                    }

                    .irantheme-header-col:first-child {
                        flex-grow: 1;
                        justify-content: flex-start;
                    }
                }

                @media only screen and (max-width: 1199px) {
                    display: none !important;
                }
            }
        }

        // Right =======================================
        &.irantheme-header-alignment-right {
            .irantheme-header-row {
                justify-content: space-between;
            }
        }

        // Left =======================================
        &.irantheme-header-alignment-left {
            .irantheme-header-row {
                justify-content: space-between;
            }
        }

        // Center =======================================
        &.irantheme-header-alignment-center {

            .irantheme-header-row {
                align-items: center;
                flex-direction: column;

                .irantheme-logo-brand {
                    padding-top: 1rem;
                    padding-bottom: 0.5rem;
                }
            }

            // Separator
            .irantheme-header-col-column-separator {
                width: 100%;
                height: 1px;
                opacity: 0.5;
                padding: 0;
                margin: 0.75rem auto !important;
                display: none;
                margin: 0;
                border: 0 !important;

                &.white {
                    background: $color-gray-300;
                }

                &.dark {
                    background: $color-gray-700;
                }
            }

            @media screen and (max-width:1199px) {
                height: inherit;
                padding-top: 0;
                padding-bottom: 0;

                .irantheme-header-row {
                    align-items: center;
                    justify-content: space-between;
                    flex-direction: row;

                    .irantheme-logo-brand {
                        padding-top: 0.75rem;
                        padding-bottom: 0.75rem;
                    }
                }

            }

            @media screen and (min-width:1199px) {
                height: auto !important;

                // Separator
                .irantheme-header-col-column-separator {
                    width: 60% !important;
                    display: block !important;
                }
            }
        }

        // Center split =======================================
        &.irantheme-header-alignment-center-split {

            .irantheme-header-row {
                justify-content: center;

                .irantheme-header-col:first-child {
                    margin-left: auto;
                }

                .irantheme-header-col:last-child {
                    margin-right: auto;
                }
            }

            @media screen and (min-width:1199px) {
                .irantheme-header-col-logo {
                    .irantheme-logo-brand {
                        display: none !important;
                    }
                }
            }
        }

        // Center double =======================================
        &.irantheme-header-alignment-center-double {
            .irantheme-header-row {
                justify-content: center;

                .irantheme-header-col {
                    flex-grow: 1;
                    flex-basis: 0;
                }

                .irantheme-header-col:nth-child(2) {
                    justify-content: center;
                }

                .irantheme-header-col:first-child {
                    margin-left: auto;
                }

                .irantheme-header-col:last-child {
                    margin-right: auto;
                    justify-content: flex-end;
                }
            }

            @media only screen and (max-width: 1199px) {
                .irantheme-header-row {
                    .irantheme-header-col {
                        flex-grow: 0;
                        flex-basis: auto;
                    }

                    .irantheme-header-col:first-child {
                        display: none !important;
                    }

                    .irantheme-header-col:nth-child(2) {
                        justify-content: flex-start;
                    }
                }
            }
        }

        // Justify =======================================
        &.irantheme-header-alignment-justify {

            .irantheme-header-row {
                justify-content: center;

                .irantheme-header-col:first-child {
                    margin-left: auto;
                }

                .irantheme-header-col:last-child {
                    margin-right: auto;
                }
            }
        }

        // Navigation =======================================
        &.irantheme-header-alignment-navigation {

            .irantheme-header-row {
                justify-content: space-between;
            }
        }

        // Navigation =======================================
        &.irantheme-header-alignment-toggle-menu {

            .irantheme-header-row {
                justify-content: space-between;
            }
        }
    }

    // White mode
    &.irantheme-header-white {
        background-color: $color-white;

        // Border mode color
        &.irantheme-header-border-mode {
            border-bottom: 1px solid $color-gray-200;

            // Shadow mode for main wrapper
            .irantheme-header-wrapper-main {
                border-bottom: 1px solid $color-gray-200;
            }
        }

        // Shadow mode color
        &.irantheme-header-shadow-mode {
            box-shadow: 0 0 20px 0 rgba(54, 83, 120, .0784313725490196);
        }

    }

    // Dark mode
    &.irantheme-header-dark {
        background-color: $color-dark;

        // Border mode color
        &.irantheme-header-border-mode {
            border-bottom: 1px solid $color-gray-800;

            // Shadow mode for main wrapper
            .irantheme-header-wrapper-main {
                border-bottom: 1px solid $color-gray-800;
            }
        }

        // Shadow mode color
        &.irantheme-header-shadow-mode {
            box-shadow: 0 0 20px 0 rgba(201, 172, 135, .0784313725490196);
        }

    }

    // White mode
    &.irantheme-header-white-important {
        background-color: $color-white !important;

        // Border mode color
        &.irantheme-header-border-mode {
            border-bottom: 1px solid $color-gray-300;

            // Shadow mode for main wrapper
            .irantheme-header-wrapper-main {
                border-bottom: 1px solid $color-gray-300;
            }
        }

        // Shadow mode color
        &.irantheme-header-shadow-mode {
            box-shadow: 0 0 20px 0 rgba(54, 83, 120, .0784313725490196);
        }

    }

    // Dark mode
    &.irantheme-header-dark-important {
        background-color: $color-dark !important;

        // Border mode color
        &.irantheme-header-border-mode {
            border-bottom: 1px solid $color-gray-700;

            // Shadow mode for main wrapper
            .irantheme-header-wrapper-main {
                border-bottom: 1px solid $color-gray-700;
            }
        }

        // Shadow mode color
        &.irantheme-header-shadow-mode {
            box-shadow: 0 0 20px 0 rgba(201, 172, 135, .0784313725490196);
        }

    }

    @media only screen and (max-width: 1199px) {
        display: block !important;
    }

    @extend .irantheme-menu-item-link-mode;

    // Import menu
    @import 'navbar/navbar-menu';
    // Import dropdown
    @import 'navbar/navbar-dropdown';
    // Import options
    @import 'navbar/navbar-options';
    // Import search
    @import 'navbar/navbar-search-box';
    // Import social media
    @import 'navbar/navbar-social-media';
}

.irantheme-container-header-full {
    width: 100%;
    margin-right: auto;
    margin-left: auto;
    padding-right: 0;
    padding-left: 0;
}

// Import logo
@import 'navbar/navbar-logo';

// Import top bar
@import 'navbar/navbar-topbar';

// Import mini profile
@import 'navbar/navbar-mini-profile';

// Import navigation
@import 'navbar/navbar-navigation';

// Import navbar full screen
@import 'navbar/navbar-full-screen';