/*
=====================================
Service Semi Saster Section
=====================================
*/
.irantheme-service-semi-master-section {
    .irantheme-service-semi-master {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        // Item
        .irantheme-service-item {
            position: relative;
            // overflow: hidden;
            display: flex;
            height: 100%;
            padding: 2.5rem;
            border-radius: $border-radius-high;
            @include transition(0.3s, all, ease-in-out);
            z-index: 1;

            &.irantheme-service-box-shadow:hover {
                box-shadow: none !important;
            }

            // Wrapper
            .irantheme-service-item-wrapper {
                position: relative;
                background-repeat: no-repeat;
                background-position: center;
                background-size: cover;
                display: flex;
                flex-direction: column;
                row-gap: 1.5rem;
                // align-items: center;
                width: 100%;
                height: 100%;
            }

            // Icon
            &-icon {
                position: relative;
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 9;

                i {
                    @include transition(0.2s, all, ease-in);
                    font-size: 2rem !important;
                    width: 6rem;
                    height: 6rem;
                    border-radius: 50%;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    // color: $color-gray-600;
                }
            }

            // Content
            &-content {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                z-index: 9;

                // Title
                h3 {
                    font-size: 1rem;
                    // color: $color-dark;

                    &.irantheme-service-item-content-title-number {
                        font-size: 2.4rem;
                        font-weight: bold;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Item
            .irantheme-service-item {
                &.irantheme-service-box-shadow {
                    @extend %box-shadow-white;
                }

                // Icon
                &-icon {

                    i {
                        background: $color-white-transparent-2;
                        color: $color-gray-500;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-800;
                    }
                }

                &.irantheme-color-details-active:hover {
                    .irantheme-service-item-content h3 {
                        color: $color-white !important;
                    }

                    .irantheme-service-item-icon i {
                        color: $color-white !important;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Item
            .irantheme-service-item {
                &.irantheme-service-box-shadow {
                    @extend %box-shadow-dark;
                }

                // Icon
                &-icon {

                    i {
                        background: $color-dark-transparent-2;
                        color: $color-gray-500;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-200;
                    }
                }

                &.irantheme-color-details-active:hover {
                    .irantheme-service-item-content h3 {
                        color: $color-dark !important;
                    }

                    .irantheme-service-item-icon i {
                        color: $color-dark !important;
                    }
                }
            }
        }
    }
}