/*
=====================================
Woocommerce products and offers products
=====================================
*/
.irantheme-woocommerce-products-section {

    .irantheme-woocommerce-products {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        &-wrapper {
            position: relative;
            z-index: 2;
        }

        .irantheme-woocommerce-slider-pagination-btn {
            display: flex;
            align-items: center;
            padding: 0.75rem;

            .swiper-pagination {
                position: relative;
                display: flex;
                align-items: center;
                justify-content: center;

                .swiper-pagination-bullet {
                    &-active {
                        width: 1.5rem;
                        border-radius: $border-radius-high;
                    }
                }
            }
        }

        &-wrapper {}

        // Columns
        .irantheme-woocommerce-products-col {
            padding-top: 0.75rem;
            padding-bottom: 0.75rem;
            height: auto;

            .irantheme-woocommerce-products-item {
                // @include transition(0.2s);
            }
        }

        // Hover shadow
        &-hover-shadow {
            // overflow: hidden;

            &:hover {
                @include transition(0.2s);
                // background: $color-white;
                border-radius: $border-radius-low;
            }
        }

        // Hover scale
        &-hover-scale {
            // overflow: hidden;

            .irantheme-woocommerce-products-item {
                &-image {
                    img {
                        @include transition(0.5s, all, ease-in-out);
                    }
                }

                &:hover {
                    .irantheme-woocommerce-products-item-image {
                        img:first-child {
                            animation-duration: 0.5s;
                            animation-name: scale;
                            animation-timing-function: cubic-bezier(0.47, 0, 0.745, 0.715);
                            animation-delay: 0.01s;
                            animation-direction: alternate;
                            animation-iteration-count: infinite;
                        }
                    }
                }

                .irantheme-woocommerce-products-item-image:hover {
                    img:first-child {
                        animation-play-state: paused;
                    }
                }
            }

            @keyframes scale {
                from {
                    @include transform(scale(1));
                }

                to {
                    @include transform(scale(1.25));
                }
            }
        }

        // Item
        &-item {
            position: relative;
            height: 100%;
            display: flex;
            flex-direction: column;
            @include transition(0.2s);

            &:hover {
                @include box-shadow(none !important);
            }

            // Remove extra spacing of last child
            &>*:last-child {
                margin-bottom: 0 !important;
            }

            // Border
            &.irantheme-woocommerce-products-item-border {
                border-width: 1px;
                border-style: solid;
                // border-color: $color-gray-200;

                .irantheme-woocommerce-products-item-content {
                    padding: 0 1rem 1rem;
                }
            }

            // Shadow
            &.irantheme-woocommerce-products-item-shadow {

                .irantheme-woocommerce-products-item-content {
                    padding: 0 1rem 1rem;
                }
            }

            // Padding
            &.irantheme-woocommerce-products-item-padding {
                padding: 1rem;

                @media (max-width: 479.98px) {
                    padding: 0.45rem;
                }


                .irantheme-woocommerce-products-item-content {
                    padding: 0 !important;
                }
            }

            // Transparent
            &.irantheme-woocommerce-products-item-transparent {

                // background-color: $color-white;
                .irantheme-woocommerce-products-item-content {
                    padding: 0;
                }
            }

            &.irantheme-out-of-stock-product {
                .irantheme-woocommerce-products-item-image {
                    img {
                        filter: grayscale(100%);
                    }
                }
            }

            // Images & gallery
            &-image {
                position: relative;
                overflow: hidden;
                margin-bottom: 0.75rem;
                display: flex;
                justify-content: center;

                &>a {
                    display: block;
                    position: relative;
                    width: 100%;
                    aspect-ratio: 1 / 1;

                    // fallback for old browsers without aspect-ratio
                    @supports not (aspect-ratio: 1 / 1) {
                        height: 0;
                        padding-bottom: 100%; // 1:1 ratio
                    }

                    img {
                        display: block;
                        position: absolute;
                        top: 0;
                        left: 0;
                        width: 100%;
                        height: 100%;
                        object-fit: cover;
                        @include transition(0.2s, all, linear);
                    }
                }

                // Absolute options
                .irantheme-woocommerce-products-item-abs {
                    position: absolute;
                    right: 1rem;
                    top: 1rem;
                    z-index: 99;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    flex-direction: column;
                    text-align: center;
                    width: 2.75rem;

                    // Total sales
                    &-item {
                        // background: $color-dark;
                        // color: $color-white;
                        width: 100%;
                        padding: 0 0.25rem;
                        display: flex;
                        flex-direction: column;
                        align-items: center;
                        justify-content: center;
                        cursor: default;

                        i {
                            font-size: 1rem;
                            padding: 0.5rem 0;
                            color: $color-white;
                            width: 100%;
                            border-top-left-radius: $border-radius-medium;
                            border-top-right-radius: $border-radius-medium;
                        }

                        span {
                            width: 100%;
                            background: $color-white;
                            border-bottom-left-radius: $border-radius-medium;
                            border-bottom-right-radius: $border-radius-medium;
                            font-size: 0.9rem;
                            display: flex;
                            flex-direction: column;
                            align-items: center;
                            justify-content: center;
                            line-height: normal;
                            padding: 0.25rem 0 0.5rem;

                            cite {
                                font-size: 0.6rem;
                                font-style: normal;
                            }
                        }
                    }
                }

                // Color circles
                .irantheme-woocommerce-products-item-colors {
                    position: absolute;
                    z-index: 5;
                    bottom: 1rem;
                    left: 1rem;
                    @include transform(translateX(-50%));

                    &-list {
                        display: flex;
                        flex-direction: column;
                        align-items: center;
                        justify-content: center;
                        flex-wrap: wrap;
                        gap: 0.25rem;

                        &-item {
                            display: flex;
                            align-items: center;
                            justify-content: center;

                            &-circle {
                                width: 0.5rem;
                                height: 0.5rem;
                                border-radius: 50%;
                            }
                        }
                    }
                }

                .irantheme-woocommerce-products-item-gallery-img {
                    position: absolute;
                    top: 0;
                    right: 50%;
                    width: 100%;
                    height: auto;
                    z-index: 1;
                    opacity: 0;
                    visibility: hidden;
                    @include transition(0.2s, all, linear);
                    @include transform(translateX(50%));
                }

                &.irantheme-woocommerce-products-item-image-changer {

                    // Hover image
                    &:hover {
                        .irantheme-woocommerce-products-item-gallery-img {
                            opacity: 1;
                            visibility: visible;
                        }
                    }
                }

                // Options
                .irantheme-woocommerce-products-item-options {
                    position: absolute;
                    top: 1rem;
                    left: 1rem;
                    z-index: 1;
                    display: none;

                    &.active {
                        display: block !important;
                    }

                    .irantheme-woocommerce-products-item-options-list {
                        border-radius: $border-radius-medium;
                    }

                    &.irantheme-extra-option-vertical-left {
                        &.hover-active {
                            .irantheme-woocommerce-products-item-options-list {
                                @include transition(0.25s);
                                @include transform(translate3d(-0.75rem, 0, 0) scale(0.7) rotate(-4deg));
                                opacity: 0;

                                &-li {}
                            }
                        }

                        .irantheme-woocommerce-products-item-options-list {
                            display: flex;
                            flex-direction: column;

                            &-li {

                                &-link {
                                    display: flex;
                                    width: 2.5rem;
                                    height: 2.5rem;
                                    align-items: center;
                                    justify-content: center;
                                    text-align: center;
                                    // background: $color-white;
                                    // color: $color-dark;
                                    font-size: 1rem;

                                    &.active {
                                        i {
                                            font-weight: bold;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    &.irantheme-extra-option-horizontal-center {
                        top: 50%;
                        left: 50%;
                        @include transform(translate3d(-50%, -50%, 0));

                        &.hover-active {
                            .irantheme-woocommerce-products-item-options-list {
                                @include transition(0.25s);
                                @include transform(translate3d(0, 0.5rem, 0) scale(0.7) rotate(2deg));
                                opacity: 0;

                                &-li {}
                            }
                        }

                        .irantheme-woocommerce-products-item-options-list {
                            display: flex;
                            flex-direction: row;

                            &-li {
                                padding: 0 0.25rem;

                                &.heart {
                                    order: 3;
                                }

                                &.shop {
                                    order: 2;
                                }

                                &.glass {
                                    order: 1;
                                }

                                &-link {
                                    display: flex;
                                    width: 2.1rem;
                                    height: 2.1rem;
                                    align-items: center;
                                    justify-content: center;
                                    text-align: center;
                                    // background: $color-white;
                                    // color: $color-dark;
                                    font-size: 1rem;

                                    &.active {
                                        i {
                                            font-weight: bold;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    &.irantheme-extra-option-horizontal-bottom {
                        top: auto;
                        bottom: 1rem;
                        left: 50%;
                        transform: translate3d(-50%, 0, 0);

                        &.hover-active {
                            .irantheme-woocommerce-products-item-options-list {
                                @include transition(0.25s);
                                @include transform(translate3d(0, 0.5rem, 0) scale(0.7) rotate(-2deg));
                                opacity: 0;

                                &-li {}
                            }
                        }

                        .irantheme-woocommerce-products-item-options-list {
                            display: flex;
                            flex-direction: row;

                            &-li {
                                padding: 0 0.25rem;

                                &.heart {
                                    order: 3;
                                }

                                &.shop {
                                    order: 2;
                                }

                                &.glass {
                                    order: 1;
                                }

                                &-link {
                                    display: flex;
                                    width: 2.1rem;
                                    height: 2.1rem;
                                    align-items: center;
                                    justify-content: center;
                                    text-align: center;
                                    // background: $color-white;
                                    // color: $color-dark;
                                    font-size: 1rem;

                                    &.active {
                                        i {
                                            font-weight: bold;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    .irantheme-woocommerce-products-item-options-list-li-link {
                        .irantheme-animate-rotate {
                            width: 1rem;
                            height: 1rem;
                            border-radius: 50%;
                            border-width: 2px;
                            border-style: solid;
                            border-color: $color-gray-400 $color-gray-400 $color-gray-800 $color-gray-400;
                            transition: 0.3s;
                            display: none;
                            transition: all 0.5s linear;
                        }

                        .irantheme-icon-check {
                            display: none;
                            box-shadow: inset 0px 0px 0px $color-white;
                            animation: fill .3s ease-in-out .3s forwards, scale .2s ease-in-out .8s both;
                            transition: all 0.4s linear;
                        }

                        &.wishlist-toggle {
                            transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);

                            &:hover {
                                transform: scale(1.05);
                            }

                            &.active {
                                transform: scale(1);
                                animation: heartBeat 0.6s ease;

                                &:hover {
                                    transform: scale(1.15);
                                }
                            }

                            /* Pulse animation */
                            @keyframes heartBeat {
                                0% {
                                    transform: scale(1);
                                }

                                25% {
                                    transform: scale(1.2);
                                }

                                50% {
                                    transform: scale(1.1);
                                }

                                75% {
                                    transform: scale(1.15);
                                }

                                100% {
                                    transform: scale(1);
                                }
                            }
                        }
                    }
                }
            }

            &:hover {
                .irantheme-woocommerce-products-item-options {
                    &.irantheme-extra-option-vertical-left {
                        &.hover-active {
                            .irantheme-woocommerce-products-item-options-list {
                                @include transform(scale(1));
                                opacity: 1;

                                &-li {}
                            }
                        }
                    }

                    &.irantheme-extra-option-horizontal-center {
                        &.hover-active {
                            .irantheme-woocommerce-products-item-options-list {
                                @include transform(scale(1));
                                opacity: 1;

                                &-li {}
                            }
                        }
                    }

                    &.irantheme-extra-option-horizontal-bottom {
                        &.hover-active {
                            .irantheme-woocommerce-products-item-options-list {
                                @include transform(scale(1));
                                opacity: 1;

                                &-li {}
                            }
                        }
                    }
                }
            }

            // Content
            &-content {
                display: flex;
                flex-direction: column;
                row-gap: 1rem;
                flex-grow: 1;

                &-top {
                    display: flex;
                    justify-content: space-between;
                }

                // Category
                &-category {
                    font-size: 0.7rem;
                    display: flex;
                    flex-wrap: wrap;
                    column-gap: 0.5rem;

                    a {
                        // color: $color-gray-600;

                        &:hover {
                            // color: $color-gray-900;
                        }
                    }
                }

                // Rating
                &-rating {
                    display: flex;
                    align-items: center;
                    flex-wrap: nowrap;

                    &.flex-right {
                        justify-content: flex-start;
                    }

                    &.flex-left {
                        justify-content: flex-end;
                    }

                    &.flex-center {
                        justify-content: center;
                    }

                    &-score {
                        font-size: 0.75rem;
                        // color: $color-gray-600;
                    }

                    i {
                        color: $color-quinary;
                        font-size: 0.8rem;
                    }

                    span {
                        position: relative;
                        top: 1px;
                        margin-left: 0.25rem;
                        font-size: 0.7rem;
                    }
                }

                // Heading
                &-heading {
                    font-size: 0.8rem;
                    font-weight: 600;
                    min-height: 2rem;
                    line-height: normal;

                    a {
                        -webkit-line-clamp: 2;
                        line-clamp: 2;
                        display: -webkit-box;
                        -webkit-box-orient: vertical;
                        overflow: hidden;
                        // color: $color-dark;
                    }
                }

                // Excerpt
                &-excerpt {
                    font-size: 0.7rem;
                    // color: $color-gray-700;
                }

                // Bottom content
                &-bottom {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    column-gap: 0.5rem;

                    // Price
                    &-price {
                        font-size: 0.8rem;
                        line-height: normal;
                        font-weight: bold;
                        display: flex;
                        justify-content: flex-end;
                        align-items: center;
                        text-align: left;
                        margin-right: auto;
                        // color: $color-gray-800;

                        .irantheme-woocommerce-products-holder {
                            display: flex;
                            align-items: center;
                            column-gap: 0.25rem;
                            justify-content: flex-end;
                        }

                        .irantheme-woocommerce-products-discount {
                            padding: 0.25rem;
                            font-size: 0.6rem;
                            border-radius: $border-radius-medium;
                        }

                        del {
                            font-size: 0.7rem;
                            // color: $color-gray-600;
                            display: block;
                            font-weight: normal;

                            .woocommerce-Price-currencySymbol {
                                display: none;
                            }
                        }

                        ins {
                            text-decoration: none;
                            display: block;
                        }

                        svg {
                            width: 1.1rem;
                            height: 1.1rem;

                            position: relative;
                            top: -2px;
                        }
                    }
                }
            }

            // Add to cart
            &-add-to-cart {

                .irantheme-btn-group {
                    display: flex;
                    justify-content: space-between;

                    &.flex-right {
                        justify-content: flex-start;

                        .irantheme-btn-detail:first-child {
                            order: 1;
                        }
                    }

                    &.flex-left {
                        justify-content: flex-end;

                        .irantheme-btn-main {
                            order: 1;
                        }
                    }

                    &.flex-center {
                        justify-content: center;
                    }
                }

                &-button {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    padding: 0.75rem 1rem !important;
                    width: 3rem;
                    height: 3rem;
                    z-index: 9;
                    @include transition(0.2s);
                    @include transform(scale(0.9));

                    &:hover {
                        @include transform(scale(0.95));
                    }

                    &:active {
                        @include transform(scale(1));
                    }

                    i {
                        font-size: 1.4rem;
                        margin: 0 !important;
                    }

                    &-success {
                        display: none;
                        font-weight: bold;
                    }

                    // Spinner hide
                    .irantheme-animate-rotate {
                        width: 1.3rem;
                        height: 1.3rem;
                        aspect-ratio: 1/1;
                        border-radius: 50%;
                        border-width: 3px;
                        border-style: solid;
                        // border-color: $color-gray-400 $color-gray-400 $color-gray-700 $color-gray-400;
                        transition: 0.3s;
                        transition: all 0.5s linear;

                        &.active {
                            display: flex !important;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            &-wrapper {}

            .irantheme-woocommerce-products-col {}

            // Hover shadow
            .irantheme-woocommerce-products-hover-shadow {

                &:hover {

                    .irantheme-woocommerce-products-item {
                        @extend %box-shadow-white;
                    }
                }
            }

            // Item
            .irantheme-woocommerce-products-item {
                background: $color-white;

                // Transparent
                &.irantheme-woocommerce-products-item-transparent {
                    background: transparent;
                }

                // Border
                &.irantheme-woocommerce-products-item-border {
                    border-color: $color-gray-100;
                }

                // Shadow
                &.irantheme-woocommerce-products-item-shadow {
                    @extend %box-shadow-white;
                }

                // Images & gallery
                &-image {

                    // Absolute options
                    .irantheme-woocommerce-products-item-abs {

                        // Total sales
                        &-item {

                            i {
                                color: $color-white;
                            }

                            span {
                                background: $color-white;
                            }
                        }
                    }

                    // Options
                    .irantheme-woocommerce-products-item-options {

                        .irantheme-woocommerce-products-item-options-list {
                            background: $color-white;

                            &-li {

                                &-link {
                                    color: $color-gray-700;
                                }
                            }
                        }
                    }
                }

                // Content
                &-content {

                    // Heading
                    &-heading {
                        a {
                            color: $color-dark;
                        }
                    }

                    // Category
                    &-category {

                        a {
                            color: $color-gray-600;

                            &:hover {
                                color: $color-gray-900;
                            }
                        }
                    }

                    // Rating
                    &-rating {

                        &-score {
                            color: $color-gray-600;
                        }

                        span {
                            color: $color-gray-700;
                        }
                    }

                    // Excerpt
                    &-excerpt {
                        color: $color-gray-600;
                    }

                    // Bottom content
                    &-bottom {

                        // Price
                        &-price {
                            color: $color-gray-900;

                            // Discount
                            .irantheme-woocommerce-products-discount {
                                background: $color-gray-300;
                                color: $color-dark;
                            }

                            del {
                                color: $color-gray-500;
                            }

                            svg {
                                fill: $color-gray-900;
                            }
                        }
                    }
                }

                // Add to cart
                &-add-to-cart {

                    &-button {
                        background: $color-gray-900;
                        color: $color-gray-100;
                        border-color: $color-white;

                        // Spinner hide
                        .irantheme-animate-rotate {
                            border-color: $color-gray-300 $color-gray-300 $color-gray-700 $color-gray-300;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            &-wrapper {}

            .irantheme-woocommerce-products-col {}

            // Hover shadow
            .irantheme-woocommerce-products-hover-shadow {

                &:hover {

                    .irantheme-woocommerce-products-item {
                        @extend %box-shadow-dark;
                    }
                }
            }

            // Item
            .irantheme-woocommerce-products-item {
                background: $color-dark;

                // Transparent
                &.irantheme-woocommerce-products-item-transparent {
                    background: transparent;
                }

                // Border
                &.irantheme-woocommerce-products-item-border {
                    border-color: $color-gray-900;
                }

                // Shadow
                &.irantheme-woocommerce-products-item-shadow {
                    @extend %box-shadow-dark;
                }

                // Images & gallery
                &-image {

                    // Absolute options
                    .irantheme-woocommerce-products-item-abs {

                        // Total sales
                        &-item {

                            i {
                                color: $color-dark;
                            }

                            span {
                                background: $color-dark;
                            }
                        }
                    }

                    // Options
                    .irantheme-woocommerce-products-item-options {

                        .irantheme-woocommerce-products-item-options-list {
                            background: $color-dark;

                            &-li {

                                &-link {
                                    color: $color-gray-300;
                                }
                            }
                        }
                    }
                }

                // Content
                &-content {

                    // Heading
                    &-heading {
                        a {
                            color: $color-white;
                        }
                    }

                    // Category
                    &-category {

                        a {
                            color: $color-gray-400;

                            &:hover {
                                color: $color-gray-100;
                            }
                        }
                    }

                    // Rating
                    &-rating {

                        &-score {
                            color: $color-gray-400;
                        }

                        span {
                            color: $color-gray-300;
                        }
                    }

                    // Excerpt
                    &-excerpt {
                        color: $color-gray-400;
                    }

                    // Bottom content
                    &-bottom {

                        // Price
                        &-price {
                            color: $color-gray-100;

                            // Discount
                            .irantheme-woocommerce-products-discount {
                                background: $color-gray-700;
                                color: $color-white;
                            }

                            del {
                                color: $color-gray-500;
                            }

                            svg {
                                fill: $color-gray-100;
                            }
                        }
                    }
                }

                // Add to cart
                &-add-to-cart {

                    &-button {
                        background: $color-gray-100;
                        color: $color-gray-900;
                        border-color: $color-dark;

                        // Spinner hide
                        .irantheme-animate-rotate {
                            border-color: $color-gray-700 $color-gray-700 $color-gray-300 $color-gray-700;
                        }
                    }
                }
            }
        }
    }

    .irantheme-woocommerce-products-schedule {
        width: fit-content;
        // height: 1.4rem;
        padding: 0 0.5rem;
        line-height: normal;
        position: absolute;
        top: 0rem;
        right: 50%;
        @include transform(translateX(50%) translateY(-50%));
        display: flex;
