// Primary colors
$color-primary: #346DF9;
$color-primary-hover: #1f5dfb;
$color-primary-trans: hsla(223, 94%, 59%, 0.2);
// Secondary colors
$color-secondary: #e67e22;
$color-secondary-hover: #d35400;
$color-secondary-trans: hsla(28, 80%, 52%, 0.2);
// Tertiary colors
$color-tertiary: #e74c3c;
$color-tertiary-hover: #c0392b;
$color-tertiary-trans: hsla(6, 78%, 57%, 0.2);
$color-tertiary-trans-half: hsla(6, 78%, 57%, 0.5);
// Quaternary color
$color-quaternary: #2ecc71;
$color-quaternary-hover: #27ae60;
$color-quaternary-trans: hsla(145, 63%, 49%, 0.2);
$color-quaternary-trans-half: hsla(145, 63%, 42%, 0.5);
// Quinary color
$color-quinary: #f1c430;
$color-quinary-hover: #f39d31;
$color-quinary-trans: hsla(46, 87%, 57%, 0.2);
// senary color
$color-senary: #9b59b6;
$color-senary-hover: #8e44ad;
$color-senary-trans: hsla(282, 44%, 47%, 0.2);
// White colors
$color-white: #fff;
$color-white-transparent-9: rgba(255, 255, 255, 0.9);
$color-white-transparent-8: rgba(255, 255, 255, 0.8);
$color-white-transparent-7: rgba(255, 255, 255, 0.7);
$color-white-transparent-6: rgba(240, 240, 240, 0.6);
$color-white-transparent-5: rgba(240, 240, 240, 0.5);
$color-white-transparent-4: rgba(240, 240, 240, 0.4);
$color-white-transparent-2: rgba(240, 240, 240, 0.2);
$color-white-transparent-1: rgba(240, 240, 240, 0.1);
$color-gray-transparent-9: rgba(200, 200, 200, 0.9);
$color-gray-transparent-8: rgba(200, 200, 200, 0.8);
$color-gray-transparent-6: rgba(200, 200, 200, 0.6);
$color-gray-transparent-5: rgba(200, 200, 200, 0.5);
$color-gray-transparent-4: rgba(200, 200, 200, 0.4);
$color-gray-transparent-2: rgba(200, 200, 200, 0.2);
$color-gray-transparent-1: rgba(200, 200, 200, 0.1);
// Gray colors
$color-gray-100: #f8f9fa;
$color-gray-200: #e9ecef;
$color-gray-300: #dee2e6;
$color-gray-400: #ced4da;
$color-gray-500: #adb5bd;
$color-gray-600: #6c757d;
$color-gray-700: #495057;
$color-gray-800: #343a40;
$color-gray-900: #2a2e33;

// Dark colors
$color-dark: #1F2229;
$color-darker: #000000;
$color-dark-transparent-9: rgba(31, 34, 41, 0.9);
$color-dark-transparent-8: rgba(31, 34, 41, 0.8);
$color-dark-transparent-7: rgba(31, 34, 41, 0.7);
$color-dark-transparent-6: rgba(43, 47, 57, 0.6);
$color-dark-transparent-5: rgba(43, 47, 57, 0.5);
$color-dark-transparent-4: rgba(43, 47, 57, 0.4);
$color-dark-transparent-2: rgba(43, 47, 57, 0.2);
$color-dark-transparent-1: rgba(43, 47, 57, 0.1);

// Tips colors
// Info
$color-tip-info-color: #052c65;
$color-tip-info-background: #cfe2ff;
$color-tip-info-border: #9ec5fe;
// Success
$color-tip-success-color: #0a3622;
$color-tip-success-background: #d1e7dd;
$color-tip-success-border: #a3cfbb;
// Error
$color-tip-error-color: #58151c;
$color-tip-error-background: #f8d7da;
$color-tip-error-border: #f1aeb5;
// Warning
$color-tip-warning-color: #664d03;
$color-tip-warning-background: #fff3cd;
$color-tip-warning-border: #ffe69c;

// Fonts variables
$font-family-primary: 'IRANSansX';
$font-family-secondary: 'IRANYekanX';
$font-family-ternary: sans-serif;
$font-family-icons: 'Font Awesome 7 Pro';
$font-family-pack: $font-family-primary, $font-family-secondary,
    $font-family-ternary;

// Border radius
$border-radius-little: 0.15rem;
$border-radius-low: 0.25rem;
$border-radius-medium: 0.5rem;
$border-radius-high: 1rem;
$border-radius-2: 2rem;
$border-radius-3: 3rem;

// Custom color
$color-red-shine: #E83A46;