// Navbar mobile
.irantheme-navbar-mobile {
    position: fixed;
    right: .75rem;
    left: .75rem;
    bottom: .75rem;
    width: calc(100% - 1.5rem);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: .1rem .75rem;
    z-index: 999999;
    opacity: 0 !important;
    visibility: hidden !important;
    min-height: 4rem;

    // Full width mode
    &.irantheme-navbar-mobile-full-width {
        right: 0;
        left: 0;
        bottom: 0;
        width: 100%;
        border-radius: 0;
    }

    &.irantheme-navbar-mobile-glass-bg {
        backdrop-filter: blur(18px) !important;
    }

    @media only screen and (max-width:992px) {
        opacity: 1 !important;
        visibility: visible !important;
    }

    // List
    &-list {
        display: flex;
        justify-content: space-between;
        flex-wrap: nowrap;
        align-items: center;
        text-align: center;
        width: 100%;
        height: 100%;

        // Item
        &-item {
            height: 60px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex: 1;

            // Link
            &-link {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                position: relative;
                padding-top: 0.65rem;
                @include transition(all, 0.2s, ease-out);
                height: 100%;
                width: 100%;

                &::before {
                    content: '';
                    position: absolute;
                    top: 0;
                    left: 50%;
                    transform: translateX(-50%);
                    width: 10px;
                    height: 0.15rem;
                    border-radius: $border-radius-high;
                    overflow: hidden;
                    opacity: 0;
                    visibility: hidden;
                    @include transition(all, 0.2s, ease-out);
                }

                &.active,
                &:hover {

                    &::before {
                        opacity: 1;
                        visibility: visible;
                    }

                    .irantheme-navbar-mobile-list-item-link-icon {
                        font-weight: 600;
                    }
                }

                // Icon
                &-icon {
                    font-size: 1.4rem;

                    // @include transition(all, 0.3s, ease-in);
                }

                // Title
                &-title {
                    font-size: 0.65rem;
                    font-weight: 600;
                    // @include transition(all, 0.3s, ease-in);
                }

                // Mini shopping cart count
                .irantheme-mini-number-count {
                    @extend %mini-number-count;

                    & {
                        top: 25%;
                        right: 51%;
                    }
                }
            }
        }
    }

    // White mode
    &.white {
        background: $color-white;
        border: 1px solid $color-gray-200;
        @include box-shadow(0 -0.1rem 1rem 0.1rem rgba(31, 34, 41, 0.1));

        &.irantheme-navbar-mobile-glass-bg {
            background: rgba($color-white, 0.7);
        }

        // List
        .irantheme-navbar-mobile-list {

            // Item
            &-item {

                // Link
                &-link {
                    color: $color-gray-700;

                    &::before {
                        background: $color-primary-hover;
                    }

                    &.active,
                    &:hover {
                        color: $color-primary-hover;
                    }
                }
            }
        }
    }

    // Dark mode
    &.dark {
        background: $color-dark;
        border: 1px solid $color-gray-800;
        @include box-shadow(0 -0.1rem 1rem 0.1rem rgba(224, 221, 214, 0.1));

        &.irantheme-navbar-mobile-glass-bg {
            background: rgba($color-dark, 0.7);
        }

        // List
        .irantheme-navbar-mobile-list {

            // Item
            &-item {

                // Link
                &-link {
                    color: $color-gray-300;

                    &::before {
                        background: $color-primary-hover;
                    }

                    &.active,
                    &:hover {
                        color: $color-primary-hover;
                    }
                }
            }
        }
    }
}