/*
=====================================
Navigation
=====================================
*/

.irantheme-navigation {
    width: 250px;
    height: 100%;
    position: fixed;
    top: 0;
    // background-color: $color-white;
    @include transition(0.4s, transform, cubic-bezier(0.215, 0.61, 0.355, 1));
    z-index: 9999999;

    &.irantheme-navigation-right {
        border-left: 1px solid;

        @media only screen and (max-width: 1199px) {
            @include transform(translateX(100%));
        }
    }

    &.irantheme-navigation-left {
        border-right: 1px solid;

        @media only screen and (max-width: 1199px) {
            @include transform(translateX(-100%));
        }
    }

    &.active {
        transition-delay: 0.6s;
        transform: translateX(0) !important;
    }

    // Mask (Global)
    &-mask {
        position: absolute;
        top: 0;
        right: 0;
        width: inherit;
        height: inherit;
        overflow-y: auto;
        display: flex;
        flex-direction: column;
    }

    // Mask white
    &-mask-white {
        background-color: $color-white-transparent-9;
    }

    // Mask dark
    &-mask-dark {
        background-color: $color-dark-transparent-9;
    }

    // Brand (Logo)
    &-brand {
        display: flex;
        justify-content: flex-start;
        align-items: center;
        padding: 1rem;

        // Close
        .irantheme-navigation-close {
            &[data-position="navigation"] {
                display: none;
                visibility: hidden;
                opacity: 0;

                @media only screen and (max-width: 1199px) {
                    display: block;
                    visibility: visible;
                    opacity: 1;
                }
            }

            margin-right: auto;

            &-button {
                width: 2rem;
                height: 2rem;
                // background-color: $color-gray-100;
                display: flex;
                align-items: center;
                justify-content: center;
                text-align: center;
                font-size: 1.2rem;

                &:hover {
                    // background-color: $color-gray-200;
                }

                i {
                    @include transition(0.2s, all, cubic-bezier(0.165, 0.84, 0.44, 1));
                }
            }
        }

        // Logo text
        .irantheme-logo-text-holder {
            .irantheme-logo-text {
                // color: $color-dark;

                &:hover {
                    // color: $color-gray-700;
                }
            }
        }

        // Logo img
        .irantheme-logo-img-holder {
            .irantheme-logo-img {
                height: 100%;
            }
        }

        // Logo svg
        .irantheme-logo-svg-holder {
            display: block;

            svg {
                height: 100% !important;
                width: auto;
                // fill: $color-dark;

                path {
                    // fill: $color-dark;
                }
            }
        }

        .irantheme-logo-mobile {
            display: none;
        }

        @media only screen and (max-width: 1199px) {
            .irantheme-logo-svg-holder.irantheme-has-logo-mobile {
                display: none;
            }

            .irantheme-logo-mobile {
                display: block;
            }
        }

        @media only screen and (max-width: 1199px) {
            .irantheme-logo-img-holder.irantheme-has-logo-mobile {
                display: none;
            }

            .irantheme-logo-mobile {
                display: flex;
            }
        }
    }

    // Search
    &-search {
        border-bottom-width: 1px;
        border-style: solid;
        // border-color: $color-gray-100;
        padding-bottom: 1rem;

        // Search form
        .irantheme-navigation-search-form {
            display: flex;
            align-items: center;
            padding: 0 1rem;

            // Search case (Icon)
            .irantheme-navigation-search-case {
                height: 100%;
                display: flex;
                align-items: center;

                i {
                    @include transform(rotate(90deg));
                    // color: $color-gray-600;
                    font-size: 1.1rem;
                }
            }

            // Search input
            .irantheme-navigation-search-input {
                height: 100%;
                width: 100%;
                border: none;
                background: none;
                box-shadow: none;
                font-size: 0.8rem;
                margin: 0;
                padding: 0.5rem;
                // color: $color-gray-600;

                &::placeholder {
                    // color: $color-gray-600;
                }
            }
        }
    }

    // Options
    &-options {
        border-bottom-width: 1px;
        border-style: solid;
        // border-color: $color-gray-100;

        &-ul {
            display: flex;
            flex-wrap: nowrap;
            justify-content: center;
            align-items: center;
            width: 100%;

            &-item {
                flex-grow: 1;

                a {
                    padding: 1rem;
                    display: block;
                    text-align: center;
                    position: relative;
                    // color: $color-dark;

                    &:hover {
                        // background-color: $color-white-transparent-2;
                        // color: $color-gray-700;
                    }

                    // Mini shopping cart count
                    .irantheme-mini-number-count {
                        @extend %mini-number-count;

                        & {
                            right: calc(50% + 0.1rem);
                            top: calc(50% - 0.2rem);
                        }
                    }
                }
            }
        }
    }

    // Biography
    &-biography {
        padding: 1rem;

        // Avatar
        &-avatar {
            margin-bottom: 1rem;

            img {
                border-radius: 50%;
                width: 8rem;
                height: 8rem;
                border-width: 3px;
                border-style: solid;
                // border-color: $color-gray-200;
            }
        }

        // Title
        &-title {
            margin-bottom: 1rem;

            h3 {
                font-size: 1rem;
                // color: $color-gray-900;
            }
        }

        // Text
        &-text {
            p {
                font-size: 0.75rem;
                // color: $color-gray-600;
            }
        }
    }

    // Menu
    &-menu {
        &-ul {

            // First li item
            &>li.menu-item {
                // background-color: $color-white;

                // First link item
                &>a {
                    font-size: 0.8rem !important;
                    padding: 1rem !important;
                }
            }

            // All li items
            li.menu-item {

                a {
                    font-size: 0.75rem;
                    padding: 0.75rem 1rem;
                    border: 0;
                    line-height: 0.8rem;
                    display: flex;
                    flex-direction: row;
                    justify-content: space-between;
                    width: 100%;
                    // color: $color-gray-600;
                    position: relative;

                    // Link title
                    .irantheme-menu-item-link-title {

                        // Structure title
                        cite {
                            font-style: normal;

                            // Icon
                            .irantheme-menu-item-link-icon {
                                display: inline-block;
                                margin-left: 0.5rem;
                            }

                            // Image
                            .irantheme-menu-item-link-image {
                                width: 1.5rem;
                                height: 1.5rem;
                                object-fit: cover;
                                object-position: center;
                                margin-left: 0.5rem;
                                border-radius: $border-radius-medium;
                            }

                            // Mode
                            .irantheme-menu-item-link-mode {
                                font-weight: bold;
                                font-size: 0.6rem;
                                padding: 0.05rem 0.25rem;
                                line-height: 1rem;
                                display: inline-block;
                                margin-right: 0.25rem;
                                position: relative;
                                top: -1px;
                                border-radius: $border-radius-medium;
                            }
                        }
                    }

                    // Hover link
                    &:hover {
                        // color: $color-dark;
                    }

                    // Chevron link
                    .irantheme-menu-item-link-icon-chevron {
                        display: flex;
                        align-items: center;
                        @include transition(0.2s);
                        @include transform(rotate(0));
                    }

                    &.active {
                        // color: $color-dark;

                        .irantheme-menu-item-link-icon-chevron {
                            @include transform(rotate(180deg));
                        }
                    }
                }
            }

            // All sub menus
            .sub-menu {
                // background-color: $color-gray-100;
                display: none;
                padding-right: 0.5rem;
            }
        }

        @extend .irantheme-menu-item-link-mode;
    }

    // Navigation bottom position
    &-bottom-position {
        margin-top: auto;
        width: 100%;
    }

    // Social media
    .irantheme-social-media {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: center;
        text-align: center;
        padding: 0.75rem 0.5rem;
        line-height: 0 !important;

        li {
            a {
                padding: 0.5rem;
                display: block;

                i {
                    font-size: 1rem;
                    // color: $color-white;
                    line-height: 1rem;
                    @include transition(0.2s);
                }

                svg {
                    width: 1rem;
                    height: 1rem;
                    // color: $color-white;
                    // fill: $color-white;
                    line-height: 1rem;
                    @include transition(0.2s);

                    path {
                        // fill: $color-white;
                        @include transition(0.2s);
                    }
                }

                &:hover {
                    // color: $color-gray-400;

                    svg,
                    path,
                    i {
                        // color: $color-gray-400;
                        // fill: $color-gray-400;
                    }
                }
            }
        }
    }

    .irantheme-mini-profile {
        padding: 0.5rem 0 1rem 0;
    }

    /*
  =====================================
  White mode
  =====================================
  */
    &.irantheme-navigation-white {
        background-color: $color-white;
        border-color: $color-gray-100;

        // Brand
        .irantheme-navigation-brand {

            // Close
            .irantheme-navigation-close {
                &-button {

                    &:hover {
                        color: $color-gray-600;
                    }
                }

            }

            // Logo text
            .irantheme-logo-text-holder {
                .irantheme-logo-text {
                    color: $color-dark;

                    &:hover {
                        color: $color-gray-700;
                    }
                }
            }

            // Logo svg
            .irantheme-logo-svg-holder {
                .irantheme-logo-svg {
                    svg {
                        fill: $color-dark;

                        path {
                            fill: $color-dark;
                        }
                    }
                }
            }
        }

        // Search
        .irantheme-navigation-search {
            border-color: $color-gray-100;

            // Search form
            .irantheme-navigation-search-form {

                // Search case (Icon)
                .irantheme-navigation-search-case {
                    i {
                        color: $color-gray-600;
                    }
                }

                // Search input
                .irantheme-navigation-search-input {
                    color: $color-gray-600;

                    &::placeholder {
                        color: $color-gray-600;
                    }
                }
            }
        }

        // Options
        .irantheme-navigation-options {
            border-color: $color-gray-100;

            &-ul {

                &-item {

                    a {
                        color: $color-gray-700;

                        &:hover {
                            background-color: $color-white-transparent-2;
                            color: $color-dark;
                        }
                    }
                }
            }
        }

        // Biography
        .irantheme-navigation-biography {

            // Avatar
            &-avatar {
                img {
                    border-color: $color-gray-200;
                }
            }

            // Title
            &-title {
                h3 {
                    color: $color-gray-800;
                }
            }

            // Text
            &-text {
                p {
                    color: $color-gray-600;
                }
            }
        }

        // Menu
        .irantheme-navigation-menu {
            &-ul {

                // First li item
                &>li.menu-item {
                    // background-color: $color-white;
                }

                // All li items
                li.menu-item {
                    a {
                        background: transparent !important;
                        color: $color-gray-600 !important;

                        &:hover {
                            color: $color-dark;
                        }

                        &.active {
                            color: $color-dark;
                        }
                    }
                }

                // All sub menus
                &>li.menu-item>.sub-menu {
                    background-color: $color-white-transparent-6;
                }
            }
        }

        // Social media
        .irantheme-social-media {
            li {
                a {
                    i {
                        color: $color-dark;
                    }

                    svg {
                        color: $color-dark;
                        fill: $color-dark;

                        path {
                            fill: $color-dark;
                        }
                    }

                    &:hover {
                        color: $color-gray-600;

                        svg,
                        path,
                        i {
                            color: $color-gray-600;
                            fill: $color-gray-600;
                        }
                    }
                }
            }
        }

        .irantheme-mini-profile {
            // background-color: $color-white;

            .irantheme-mini-profile-holder {
                &.active {
                    .irantheme-mini-profile-holder-arrow {
                        color: $color-dark !important;
                    }
                }

                // Info
                &-info {
                    &-heading {
                        color: $color-dark;
                    }

                    &-details {
                        color: $color-gray-600;
                    }
                }

                // Arrow
                color: $color-gray-500;
            }

            // Dropdown menu
            .irantheme-mini-profile-dropdown {
                background-color: $color-white;

                &-holder {
                    background-color: $color-white;
                    border-color: $color-gray-100;

                    // Info
                    &-info {
                        &-name {
                            color: $color-dark;
                        }

                        &-role {
                            color: $color-gray-600;
                        }
                    }

                    // Menu
                    &-menu {
                        &-list {
                            &-item {
                                &-link {
                                    color: $color-gray-700;

                                    i {
                                        color: $color-gray-600;
                                    }

                                    &:hover,
                                    &.active {
                                        background-color: $color-gray-100;
                                    }

                                    .irantheme-mini-profile-dropdown-holder-menu-cart {
                                        &-count {
                                            display: flex;
                                            align-items: center;

                                            &-arrow {
                                                color: $color-gray-600 !important;
                                            }

                                            &-num,
                                            .irantheme-shopping-cart-count {
                                                color: $color-dark;
                                            }
                                        }
                                    }
                                }

                                // Separator
                                &.irantheme-menu-item-separator {
                                    border-color: $color-gray-100;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /*
  =====================================
  Dark mode
  =====================================
