            }

            // Dropdown menu
            .irantheme-mini-profile-dropdown {
                background-color: $color-dark;

                &-holder {
                    background-color: $color-dark;
                    border-color: $color-gray-900;

                    // Info
                    &-info {
                        &-name {
                            color: $color-white;
                        }

                        &-role {
                            color: $color-gray-400;
                        }
                    }

                    // Menu
                    &-menu {
                        &-list {
                            &-item {
                                &-link {
                                    color: $color-gray-300;

                                    i {
                                        color: $color-gray-400;
                                    }

                                    &:hover,
                                    &.active {
                                        background-color: $color-gray-900;
                                    }

                                    .irantheme-mini-profile-dropdown-holder-menu-cart {
                                        &-count {

                                            &-arrow {
