/*
=====================================
Business Modern Plane Section
=====================================
*/
.irantheme-service-master-section {
    .irantheme-service-master {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        // Separator border side
        &.irantheme-service-border-side {

            div[class*="col-"]:last-child {
                .irantheme-service-item {
                    &::after {
                        display: none;
                    }
                }
            }

            .irantheme-service-heading-col {
                @extend %service-column-separator;
            }

            div[class*="col-lg-6"]:nth-child(odd) {
                .irantheme-service-item {
                    @extend %service-column-separator;
                }
            }

            div[class*="col-lg-4"]:not(:nth-child(3n)) {
                .irantheme-service-item {
                    @extend %service-column-separator;
                }
            }

            div[class*="col-lg-3"]:not(:nth-child(4n)) {
                .irantheme-service-item {
                    @extend %service-column-separator;
                }
            }

            div[class*="col-lg-2"]:not(:nth-child(6n)) {
                .irantheme-service-item {
                    @extend %service-column-separator;
                }
            }

            @media only screen and (max-width: 991px) {
                .row {
                    &.irantheme-service-edge {
                        div[class*="col-"]:not(:last-child) {
                            .irantheme-service-item {
                                &::after {
                                    content: '';
                                    position: absolute;
                                    left: 50%;
                                    top: 100%;
                                    @include transform(translateY(0) translateX(-50%));
                                    width: 7rem;
                                    height: 1px;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Separator border box
        &.irantheme-service-border-box {
            .irantheme-service-item-wrapper {
                border-width: 1px;
                border-style: solid;
                // border-color: $color-gray-200;
            }

            &.irantheme-service-no-space {

                // All columns
                div[class*="col-"] {

                    @media only screen and (min-width: 992px) {
                        &.irantheme-service-heading-col {
                            border-width: 0 0 1px 1px;
                            border-style: solid;
                            // border-color: $color-gray-200;
                        }
                    }
                }

                .irantheme-service-item-wrapper {
                    border-width: 0 0 1px 0;
                    border-style: solid;

                    @media only screen and (min-width: 992px) {
                        &::before {
                            content: "";
                            position: absolute;
                            left: 0;
                            top: 0;
                            width: 1px;
                            height: 100%;
                            // background: $color-gray-200;
                            z-index: 1;
                        }
                    }
                }

                @media only screen and (max-width: 991px) {
                    div[class*="col-"] {
                        .irantheme-service-item-wrapper {
                            border-width: 1px 1px 0 1px;
                        }
                    }
                }
            }
        }

        // Service space
        &.irantheme-service-no-space {

            .irantheme-object-group {
                row-gap: 0 !important;
            }

            .irantheme-service-edge {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }

            div[class*="col-"] {
                padding-right: 0 !important;
                padding-left: 0 !important;
                margin-bottom: 0 !important;

                // Item
                .irantheme-service-item {

                    // Wrapper
                    .irantheme-service-item-wrapper {
                        border-radius: 0 !important;
                    }
                }

            }

            @media only screen and (max-width: 991px) {
                div[class*="col-"]:last-child {
                    .irantheme-service-item-wrapper {
                        border-width: 1px;
                    }
                }
            }
        }

        // Item
        .irantheme-service-item {
            position: relative;
            // overflow: hidden;
            display: flex;
            height: 100%;
            z-index: 1;

            // Wrapper
            .irantheme-service-item-wrapper {
                position: relative;
                padding: 2rem;
                border-radius: $border-radius-low;
                background-repeat: no-repeat;
                background-position: center;
                background-size: cover;
                display: flex;
                align-items: flex-start;
                // align-items: center;
                width: 100%;
                height: 100%;
                overflow: hidden;

                @media only screen and (max-width:575px) {
                    padding: 0;
                }

                &.irantheme-service-box-shadow {
                    @include box-shadow(0 15px 25px -7px rgba(0, 0, 0, 0.09),
                        0 -12px 10px -10px rgba(0, 0, 0, 0.04));
                    @include transition(0.4s);

                    &:hover {
                        @include box-shadow(none);
                    }
                }

                // Background item
                &.irantheme-service-item-image {
                    &::after {
                        content: '';
                        width: 100%;
                        height: 100%;
                        position: absolute;
                        top: 0;
                        right: 0;
                        @include transition(0.3s);
                        background-color: $color-dark-transparent-8;
                    }

                    &:hover {
                        &::after {
                            background-color: $color-dark-transparent-9;
                        }
                    }

                    // Icon
                    .irantheme-service-item-icon {

                        i {
                            color: $color-gray-400;
                        }
                    }

                    // Content
                    .irantheme-service-item-content {

                        // Title
                        h3 {
                            color: $color-white;
                        }

                        // Description
                        p {
                            color: $color-gray-300;
                        }

                        // Button
                        &-button {
                            a {
                                color: $color-gray-300;
                                border-color: transparent;

                                &::after {
                                    background-color: $color-gray-200;
                                }
                            }
                        }
                    }
                }

                .irantheme-service-item-wrapper-content {
                    width: 100%;

                    // Icon side
                    &.irantheme-service-item-icon-side {
                        display: flex;
                        column-gap: 1rem;

                        .irantheme-service-item-icon {
                            margin-bottom: auto;
                        }
                    }
                }

                // Double icon
                .irantheme-service-item-double-icon {
                    position: absolute;
                    top: 0;
                    right: 0;
                    font-size: 14rem;
                    // color: $color-gray-200;
                    @include transform(translateY(-2rem) translateX(2rem));
                    z-index: 8;
                }
            }

            // Icon
            &-icon {
                margin-bottom: 2rem;
                position: relative;
                z-index: 9;

                &.icon-box-style {
                    display: inline-flex;
                    justify-content: center;
                    align-items: center;
                    aspect-ratio: 1 /1;

                    &.border-style {
                        background-color: transparent;
                        border-width: 1px;
                        border-style: solid;
                    }
                }

                i {
                    @include transition(0.2s, all, ease-in);
                    font-size: 2.5rem;
                    // color: $color-gray-600;
                }
            }

            // Content
            &-content {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                z-index: 9;

                // Horizontal mode
                &-horizontal {
                    flex-direction: row;
                    align-items: flex-start;
                    justify-content: center;
                    display: flex;

                    .irantheme-service-item-content-desc-horizontal {
                        margin-right: 1rem;
                        margin-left: 1rem;
                    }

                    // Separator
                    .irantheme-service-item-content-separator {
                        width: 2px;
                        height: 2rem;
                        margin-right: 1rem;
                    }
                }

                // Title
                h3 {
                    font-size: 1rem;
                    // color: $color-dark;

                    &.irantheme-service-item-content-title-number {
                        font-size: 2.4rem;
                        font-weight: bold;
                    }
                }

                // Description
                p {
                    font-size: 0.8rem;
                    // color: $color-gray-700;
                    margin-top: 0.5rem;

                    &.irantheme-service-item-content-desc-number {
                        font-size: 1rem;
                        line-height: 1.8rem;
                    }

                    &.irantheme-service-item-content-desc-number-small {
                        font-size: 0.8rem;
                        line-height: 1.4rem;
                    }
                }

                // Separator service number
                &-separator {
                    width: 2rem;
                    height: 2px;
                    margin-bottom: 1rem;
                    display: inline-block;
                    // background: $color-white;
                }

                // Button
                &-button {
                    margin-top: 0.5rem;

                    &.irantheme-btn-group {
                        margin-top: 1.5rem;

                        a {
                            &::after {
                                content: none !important;
                            }
                        }
                    }

                    a {
                        font-size: 0.8rem;
                        border-width: 0 0 2px 0;
                        border-style: solid;

                        // border-color: $color-gray-500;
                        // color: $color-gray-600;
                        &:not(.irantheme-btn) {
                            padding: 0.25rem 0;
                        }

                        position: relative;

                        &::after {
                            content: '';
                            position: absolute;
                            top: 100%;
                            right: 0;
                            width: 0;
                            height: 1px;
                            @include transition(0.2s, all, cubic-bezier(.59, .32, .48, 1.01));
                        }

                        &:hover {
                            &::after {
                                width: 100%;
                            }
                        }
                    }
                }
            }
        }

