// Container navbar menu
.irantheme-container-navbar-menu {
    display: flex;
    align-items: center;
    height: 100%;

    // Main menu
    .irantheme-navbar-menu-ul {
        display: flex;
        height: 100%;
        padding: 0;
        column-gap: 1.5rem;

        // Parent
        &>li.irantheme-normal-menu-item {
            position: relative;

            // All lis in normal menu
            li {
                position: relative;
            }
        }

        // Mega menu (First layer)
        &>li.irantheme-mega-menu-item {
            position: relative;

            // Active all ul sub-menu
            &.active>ul.sub-menu,
            &:hover>ul.sub-menu {
                display: flex !important;
            }

            // Main link mega menu
            &>a {

                &.menu-item-parent-link {

                    .irantheme-menu-item-link-icon-chevron,
                    .irantheme-menu-item-link-icon,
                    .irantheme-menu-item-link-title {
                        font-weight: bold;
                    }
                }

                &.irantheme-button-style {

                    .irantheme-menu-item-link-icon-chevron,
                    .irantheme-menu-item-link-icon,
                    .irantheme-menu-item-link-title {
                        font-weight: bold;
                    }
                }
            }

            // First layer (Parent holder)
            &>ul.sub-menu {
                display: flex;
                flex-direction: column;
                width: 925px !important;
                min-width: 925px !important;
                max-width: 100% !important;
                min-height: 320px !important;
                border-radius: $border-radius-medium;
                overflow-x: hidden;
                overflow-y: auto;
                max-height: 580px;
                padding: 0.5rem !important;
                display: none;

                li {

                    // Nested submenus
                    ul.sub-menu {
                        top: 0;
                        right: 100%;
                        animation: slideRight 0.2s ease-out;
                    }
                }

                // First mega menu li
                &>li {
                    display: block;
                    flex-direction: row;
                    width: 100%;
                    @include transition(0.1s);

                    // First li > a in mega menu
                    &>a {
                        width: 240px;
                        // background: $color-gray-100;
                        font-weight: bold;
                        display: block;
                        text-align: right;
                        border-radius: $border-radius-medium !important;
                        padding: 0.75rem 1rem;
                        font-size: 0.7rem;
                        @include transition(0.1s);

                        &:hover {}

                        i {
                            font-size: 1rem;
                            margin-left: 0.75rem;
                            width: 2rem;
                            height: 2rem;
                            border-radius: $border-radius-medium;
                            font-weight: normal;
                            // background: $color-gray-200;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            text-align: center;
                            @include transition(0.1s);
                        }
                    }

                    &:hover,
                    &.active {
                        &>a {
                            // background: $color-white;

                            i {
                                // background: $color-dark;
                                // color: $color-white;
                            }
                        }

                        ul.sub-menu {
                            display: flex;
                        }
                    }

                    // All link in mega menu
                    a {
                        // border-radius: 0 !important;
                    }

                    // Second layer
                    &>ul.sub-menu {
                        box-shadow: none !important;
                        justify-content: flex-start;
                        top: 0.5rem;
                        right: calc(240px + 1rem);
                        bottom: 0.5rem;
                        width: calc(100% - 240px - 1.5rem);
                        height: calc(100% - 1rem);
                        opacity: 1;
                        visibility: visible;
                        flex-direction: row;
                        flex-wrap: wrap;
                        position: absolute;
                        max-width: calc(100% - 240px);
                        overflow-x: hidden;
                        overflow-y: auto;
                        background: transparent;
                        padding: 0.5rem !important;
                        border-radius: $border-radius-medium !important;

                        // Layer of background image
                        &::before {
                            border-radius: 0 !important;
                        }

                        &>li {
                            min-width: 200px;
                            margin-bottom: 1rem;
                        }

                        &>li>a {
                            position: relative;
                            display: flex;
                            font-weight: bold;

                            &::before {
                                content: '';
                                width: 0.15rem;
                                height: 1rem;
                                // background: $color-dark;
                                border-radius: $border-radius-medium;
                                margin-left: 0.5rem;
                                display: flex;
                            }
                        }

                        // Three layer
                        ul.sub-menu {
                            display: flex;
                            flex-direction: column;
                            box-shadow: none !important;
                            justify-content: flex-start;
                            position: relative;
                            top: 0;
                            right: 0;
                            padding: 0;
                            background: transparent;
                            min-width: 202.1px;
                            max-width: 250px;
                        }

                        a {
                            padding: 0.15rem 1rem;
                            border-radius: $border-radius-medium !important;
                            display: flex;
                            justify-content: flex-start;
                            align-items: center;
                            width: 100%;
                            background: transparent;

                            &:hover {
                                // background: $color-gray-100 !important;
                                // color: $color-dark;
                            }
                        }
                    }
                }

                // Angle icon (Specific for parent)
                .irantheme-menu-item-link-icon-chevron {
                    display: none !important;
                }
            }
        }

        // Main lis (First layer)
        &>li {
            display: flex;
            align-items: center;
            height: 100%;

            // Gtranslate specific style
            &.menu-item-gtranslate {
                display: flex;
                align-items: center;
                position: relative;

                .glink {
                    column-gap: 0.5rem;
                }

                .sub-menu {
                    .menu-item {
                        opacity: 1 !important;
                    }
                }
            }

            &:first-child>.menu-item-link {
                margin-right: 0;
            }

            &:last-child>.menu-item-link {}

            // Main links, (First layer)
            &>a {
                position: relative;
                align-items: center;
                display: flex;
                font-size: 0.8rem;
                font-weight: normal;
                padding: 0.5rem 0;
                // color: $color-white;

                i.irantheme-menu-item-link-icon {
                    font-size: 0.9rem;
                }

                &:not(.irantheme-button-style) {
                    border-radius: $border-radius-medium;
                }

                &:hover,
                &.active {}
            }

            // First sub menu (First layer)
            &>ul.sub-menu {
                top: 100%;
                right: 0;

                // Li submenus
                li {

                    // Nested submenus
                    ul.sub-menu {
                        top: 0;
                        right: 100%;
                    }
                }
            }

            // All ul submenu
            ul.sub-menu {
                min-width: 250px;
                max-width: 300px;
                padding: 1rem 1rem calc(0.5rem + 10px);
                // background-color: $color-white;
                border-radius: $border-radius-medium;
                position: absolute;
                z-index: 99999;
                flex-direction: column;
                display: none;
                animation: slideDown 0.2s ease-out;

                li {
                    a {
                        font-size: 0.75rem;
                        padding: 0.25rem 1rem;
                        display: block;
                        border-radius: $border-radius-medium;
                        // color: $color-gray-700;

                        &:hover {
                            // background-color: $color-gray-100;
                        }
                    }
                }
            }

            // Hover on children's
            &:hover>a,
            &.active>a {
                // background-color: $color-gray-200;
                // color: $color-gray-400;

                &::after {
                    @include transform(scaleX(1));
                }
            }

            // Show ul submenu in hover
            &.active>ul.sub-menu {
                display: block;
            }
        }

        .menu-item {
            // a:not(.irantheme-logo-mobile, .menu-item-child-link) {
            //     height: 100%;
            // }

            a:not(.irantheme-logo-mobile) {
                display: flex;
                justify-content: space-between;
                align-items: center;

                // Menu item link title
                .irantheme-menu-item-link-title {
                    cite {
                        font-style: normal;
                        display: flex;
                        align-items: center;
                        white-space: nowrap;
                    }
                }

                // Icon angle
                .irantheme-menu-item-link-icon-chevron {
                    font-size: 0.6rem;
                    margin-right: 0.5rem;
                    // display: none;
                    @include transition(all, 0.2s, ease-out);
                }

                // Mode item
                .irantheme-menu-item-link-mode {
                    font-weight: bold;
                    font-size: 0.5rem;
                    padding: 0.05rem 0.25rem;
                    line-height: 1rem;
                    display: inline-block;
                    margin-right: 0.25rem;
                    position: relative;
                    top: -1px;
                }
            }

            &.active>a,
            &:hover>a {

                // Icon chevron
                .irantheme-menu-item-link-icon-chevron {
                    @include transform(rotate(180deg));
                }
            }

            &:hover {
                &>ul.sub-menu {
                    display: flex;
                }
            }
        }

        // Icon
        .irantheme-menu-item-link-icon {
            margin-left: 0.5rem;
            font-size: 0.8rem;
        }

        // Image
        .irantheme-menu-item-link-image {
            width: 2rem;
            height: 2rem;
            object-fit: cover;
            object-position: center;
            margin-left: 0.75rem;
            border-radius: $border-radius-medium;
        }

        // Navbar button style
        .irantheme-button-holder {
            align-items: center !important;

            &>a {
                border-radius: $border-radius-medium;
                padding-right: 0.75rem !important;
                padding-left: 0.75rem !important;
                // margin-right: 0.5rem;
                height: auto !important;
                font-size: 0.7rem;
            }
        }

        // Navbar background image
        .irantheme-image-menu-item {

            &>ul.sub-menu::before {
                content: '';
                position: absolute;
                top: 0;
                right: 0;
                width: 100%;
                height: 100%;
                // background: $color-white-transparent-9;
                z-index: -1;
                border-bottom-left-radius: $border-radius-medium;
                border-bottom-right-radius: $border-radius-medium;
                backdrop-filter: blur(10px);
            }
        }
    }

    // Set a little space between secondary menu item
    &.irantheme-secondary-navbar-menu {
        @media only screen and (max-width: 1320px) {
            display: none !important;
        }
    }

    // Set center split logo
    .irantheme-logo-brand {

        a {
            width: max-content;

            &::after {
                display: none;
            }
        }
    }

    // Media
    @media only screen and (max-width: 1199px) {
        display: none !important;
    }
}

// Animation keyframes
@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideRight {
    from {
        opacity: 0;
        transform: translateX(-10px);
    }

    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/*
=====================================
White mode
=====================================
*/
&.irantheme-header-white,
&.irantheme-header-white-important {

    // Navbar
    .irantheme-container-navbar-menu {
        .irantheme-navbar-menu-ul {

            // Button style
            .irantheme-button-style {
                &.irantheme-button-style-default {
                    background-color: $color-dark !important;
                    color: $color-white !important;

                    // Hover first layer link
                    &:hover {
                        color: $color-gray-300 !important;
                    }
                }
            }

            // First layer lis
            &>li {

                // First layer links
                &>a {
                    color: $color-gray-700;

                    // Hover first layer link
                    &:hover {
                        color: $color-dark;
                    }
                }

                // First layer hover and active
                &:hover>a,
                &.active>a {
                    color: $color-dark;
                }
            }
        }
    }
}

