/*
=====================================
Business Modern Plane Section
=====================================
*/
.irantheme-business-modern-plane-service-section {
    .irantheme-business-modern-plane-service {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        // Plane service
        .irantheme-business-modern-plane-service-post-wrapper {
            .irantheme-business-modern-plane-service-post-row {
                row-gap: 1.5rem;
            }

            position: relative;
            z-index: 2;

            &.special-mode {
                // Add space between before element and plane wrapper
                margin-top: 2.2rem;

                // Add inner space of plane item when special mode is enable
                .irantheme-business-modern-plane-service-post-item {
                    padding-top: 2.2rem;
                }

                &.special-mode-style-highlight-box {

                    // Increase row-gap when special mode is enable
                    .irantheme-business-modern-plane-service-post-row {
                        row-gap: 3.5rem;
                    }
                }

                &.special-mode-style-highlight-badge {

                    // Increase row-gap when special mode is enable
                    .irantheme-business-modern-plane-service-post-row {
                        row-gap: 2.5rem;
                    }
                }
            }

            .irantheme-business-modern-plane-service-post-item-box-scale {
                transform: scale(1.05);

                @media (max-width: 767.9px) {
                    transform: unset;
                }
            }

            .irantheme-business-modern-plane-service-post-item-special-mode {
                margin: 0 !important;

                &.highlight-box {
                    position: absolute;
                    left: 0.5rem;
                    right: 0.5rem;
                    top: -2.2rem;
                    bottom: -0.3rem;
                    background-color: $color-gray-200;
                    // border: 1px solid $color-gray-300;
                    border-radius: 2.3rem;

                    .irantheme-business-modern-plane-service-post-item-special-mode-content {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        padding-top: 0.5rem;
                        gap: 0.35rem;

                        span {
                            color: $color-dark;
                            font-size: 0.7rem;
                            font-weight: 600;
                            line-height: normal;
                        }

                        i {
                            font-size: 0.8rem;
                            font-weight: 600;
                        }
                    }
                }

                &.highlight-badge {
                    position: absolute;
                    top: -0.85rem;
                    left: 50%;
                    transform: translateX(-50%);
                    background-color: $color-gray-200;
                    color: $color-dark;
                    z-index: 3;
                    border-radius: $border-radius-high;

                    .irantheme-business-modern-plane-service-post-item-special-mode-content {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        padding: 0.5rem 1.5rem;
                        gap: 0.35rem;

                        span {
                            color: $color-dark;
                            font-size: 0.7rem;
                            font-weight: 600;
                            line-height: normal;
                        }

                        i {
                            font-size: 0.8rem;
                            font-weight: 600;
                        }
                    }
                }
            }

            .irantheme-business-modern-plane-service-post-item {
                background: transparent;
                padding: 2rem;
                border-radius: $border-radius-low;
                // overflow: hidden;
                position: relative;
                display: flex;
                flex-direction: column;
                gap: 1rem;
                height: 100%;
                z-index: 1;

                &.plane-box-border {
                    border-width: 1px;
                    border-style: solid;
                }

                // Box style
                &.irantheme-business-modern-plane-service-post-item-box-style {
                    background: $color-white;
                }

                // Box shadow
                &.irantheme-business-modern-plane-service-post-item-box-shadow {
                    @include box-shadow(0 8px 16px 0px rgba(0, 0, 0, 0.09),
                        0 -12px 10px -10px rgba(0, 0, 0, 0.04));
                    @include transition(0.4s);

                    &:hover {
                        @include box-shadow(none);
                    }
                }

                // Box style
                &.irantheme-business-modern-plane-service-post-item-border {
                    border-width: 2px;
                    border-style: solid;
                }

                &-topbar {
                    display: flex;
                    align-items: flex-start;
                    justify-content: space-between;
                    margin-bottom: 1rem;

                    &-icon {
                        font-size: 2rem;
                        margin-bottom: 0;

                        &.icon-box-style {
                            display: inline-flex;
                            justify-content: center;
                            align-items: center;
                            aspect-ratio: 1 /1;
                            width: 4rem;

                            &.border-style {
                                background-color: transparent;
                                border-width: 1px;
                                border-style: solid;
                            }
                        }
                    }

                    &-badge {
                        display: flex;

                        span {
                            padding: 0 0.75rem;
                            background-color: $color-gray-100;
                            border-radius: $border-radius-high;
                            font-size: 0.7rem;
                            color: $color-gray-700;
                            font-weight: 600;
                        }
                    }
                }

                &-content {

                    // Title
                    &-title {
                        font-size: 1.1rem;
                        margin-bottom: 0.8rem;
                        color: $color-gray-900;
                        font-weight: 600;
                    }

                    // Description
                    &-desc {
                        font-size: 0.8rem;
                        color: $color-gray-600;
                        margin-bottom: 1rem;
                    }
                }

                // Price
                &-price {
                    font-size: 1.3rem;
                    line-height: 2rem;
                    color: $color-gray-700;
                    display: flex;
                    flex-direction: column;
                    flex-wrap: wrap;
                    justify-content: center;

                    &-main {
                        color: $color-gray-700;
                        font-weight: 600;
                        width: auto;
                    }

                    &-discount {
                        color: $color-gray-500;
                        font-size: 1rem;
                        position: relative;
                        width: auto;
                        text-decoration: line-through;
                        // &::after {
                        //     content: '';
                        //     width: 100%;
                        //     height: 2px;
                        //     background: $color-gray-600;
                        //     @include transform(rotate(-10deg));
                        //     position: absolute;
                        //     top: 50%;
                        //     right: 0;
                        // }
                    }
                }

                // Features list
                &-features-list {
                    font-size: 0.9rem;
                    color: $color-gray-700;

                    .irantheme-tinymce-content {
                        font-size: 0.9rem;

                        ul {
                            li {
                                &::before {
                                    display: inline-flex;
                                    justify-content: center;
                                    align-items: center;
                                    aspect-ratio: 1 /1;
                                    border-radius: $border-radius-medium;
                                    font-size: 0.75rem;
                                    width: 1.5rem;
                                    background-color: $color-gray-200;
                                    color: $color-gray-700;
                                }
                            }
                        }

                        ol {
                            li {
                                &::before {
                                    border-radius: unset;
                                    border: none !important;
                                    font-size: 0.85rem;
                                    color: $color-gray-700;
                                }
                            }
                        }
                    }
                }

                // Button
                &-button {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    width: 100%;
                    gap: 0.75rem;
                    margin-top: auto;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            // Plane service
            .irantheme-business-modern-plane-service-post-wrapper {
                .irantheme-business-modern-plane-service-post-item {
                    &.plane-box-border {
                        border-color: $color-gray-200;
                    }

                    // Box style
                    &.irantheme-business-modern-plane-service-post-item-box-style {
                        background: $color-white;
                    }

                    // Box shadow
                    &.irantheme-business-modern-plane-service-post-item-box-shadow {
                        @include box-shadow(0 15px 25px -7px rgba(0, 0, 0, 0.09),
                            0 -12px 10px -10px rgba(0, 0, 0, 0.04));
                        @include transition(0.4s);

                        &:hover {
                            @include box-shadow(none);
                        }
                    }


                    &-content {

                        // Title
                        &-title {
                            color: $color-gray-900;
                        }

                        // Description
                        &-desc {
                            color: $color-gray-600;
                        }
                    }

                    // Price
                    &-price {
                        color: $color-gray-700;

                        &-discount {
                            color: $color-gray-500;

                            &::after {
                                background: $color-gray-600;
                            }
                        }

                        &-main {
                            color: $color-gray-700;
                        }
                    }

                    // Features list
                    &-features-list {
                        color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            // Plane service
            .irantheme-business-modern-plane-service-post-wrapper {
                .irantheme-business-modern-plane-service-post-item {
                    &.plane-box-border {
                        border-color: $color-gray-800;
                    }

                    // Box style
                    &.irantheme-business-modern-plane-service-post-item-box-style {
                        background: $color-dark;
                    }

                    // Box shadow
                    &.irantheme-business-modern-plane-service-post-item-box-shadow {
                        @include box-shadow(0 15px 25px -7px rgba(233, 233, 233, 0.09),
                            0 -12px 10px -10px rgba(233, 233, 233, 0.04));
                        @include transition(0.4s);

                        &:hover {
                            @include box-shadow(none);
                        }
                    }

                    // Box style
                    &.irantheme-business-modern-plane-service-post-item-border {
                        border-color: $color-gray-800;
                    }

                    &-content {

                        // Title
                        &-title {
                            color: $color-gray-100;
                        }

                        // Description
                        &-desc {
                            color: $color-gray-400;
                        }
                    }

                    // Price
                    &-price {
                        color: $color-gray-300;

                        &-main {
                            color: $color-gray-300;
                        }

                        &-discount {
                            color: $color-gray-500;

                            &::after {
                                background: $color-gray-400;
                            }
                        }
                    }

                    // Features list
                    &-features-list {
                        color: $color-gray-300;
                    }
                }
            }
        }
    }
}