.irantheme-woocommerce-box-brands-section {

    .irantheme-woocommerce-box-brands {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        &-wrapper {
            position: relative;
            padding: 1rem 0;
            z-index: 2;
        }

        .row {
            row-gap: 2rem;
        }

        // Columns
        .irantheme-woocommerce-box-brands-col {
            @include transition(0.2s);

            &:hover {
                box-shadow: none !important;
            }

            // Set box style
            &.irantheme-woocommerce-box-brands-box-style-border {
                padding: 0.75rem;
            }

            // Set box style
            &.irantheme-woocommerce-box-brands-box-style-shadow {
                padding: 0.75rem;
            }
        }

        // Item
        &-item {
            height: auto;
            display: flex;
            flex-direction: column;
            row-gap: 3rem;
            justify-content: center;
            width: 100%;
            cursor: default;

            // Heading
            &-heading {
                display: flex;
                justify-content: space-between;
                align-items: center;
                column-gap: 1rem;
                width: 100%;

                &-image {
                    position: relative;
                    overflow: hidden;
                    width: 100%;
                    display: flex;
                    justify-content: flex-end;

                    &-img {
                        object-fit: contain;
                        max-width: 4rem;
                        max-height: 2rem;
                    }
                }

                // Title
                &-title {
                    font-size: 0.9rem;
                    // color: $color-gray-700;
                    margin-bottom: 0.25rem;
                    display: -webkit-box;
                    -webkit-line-clamp: 1;
                    -webkit-box-orient: vertical;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    font-weight: bold;
                    width: 100%;

                    &-product-count {
                        // color: $color-gray-600;
                        margin-right: 0.25rem;
                        font-size: 0.6rem;
                    }
                }
            }

            &-footer {
                display: flex;
                justify-content: space-between;
                align-items: center;
                column-gap: 1rem;
                width: 100%;

                // Description
                &-desc {
                    font-size: 0.8rem;
                    display: -webkit-box;
                    -webkit-line-clamp: 1;
                    -webkit-box-orient: vertical;
                    overflow: hidden;
                    text-overflow: ellipsis;
                }

                // Link
                &-link {
                    font-size: 0.7rem;
                    display: flex;
                    align-items: center;
                    column-gap: 0.5rem;
                    opacity: 0.8;
                    padding: 0.5rem 0.75rem;

                    &:hover {
                        opacity: 1;
                    }

                    i {
                        margin: 0;
                        width: fit-content;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            &-wrapper {}

            .irantheme-woocommerce-box-brands-col {
                background: $color-white;

                // Set box style
                &.irantheme-woocommerce-box-brands-box-style-border {
                    border: 1px solid $color-gray-100;
                }

                // Set box style
                &.irantheme-woocommerce-box-brands-box-style-shadow {
                    @extend %box-shadow-white;
                }
            }

            // Item
            .irantheme-woocommerce-box-brands-item {

                // Heading
                &-heading {

                    // Image
                    &-image {
                        // background: $color-gray-200;
                        background: transparent;
                    }

                    // Title
                    &-title {
                        color: $color-gray-900;

                        &-product-count {
                            color: $color-gray-500;
                        }
                    }
                }

                // Footer
                &-footer {

                    // Description
                    &-desc {
                        color: $color-gray-600;
                    }

                    // Link
                    &-link {
                        color: $color-gray-900;
                        background: $color-gray-200;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            &-wrapper {}

            .irantheme-woocommerce-box-brands-col {
                background: $color-dark;

                // Set box style
                &.irantheme-woocommerce-box-brands-box-style-border {
                    border: 1px solid $color-gray-900;
                }

                // Set box style
                &.irantheme-woocommerce-box-brands-box-style-shadow {
                    @extend %box-shadow-dark;
                }
            }

            // Item
            .irantheme-woocommerce-box-brands-item {

                // Heading
                &-heading {

                    // Image
                    &-image {
                        // background: $color-gray-800;
                        background: transparent;
                    }

                    // Title
                    &-title {
                        color: $color-gray-100;

                        &-product-count {
                            color: $color-gray-500;
                        }
                    }
                }

                // Footer
                &-footer {

                    // Description
                    &-desc {
                        color: $color-gray-400;
                    }

                    // Link
                    &-link {
                        color: $color-gray-100;
                        background: $color-gray-800;
                    }
                }
            }
        }
    }
}