.irantheme-preloader-abs {
    position: absolute;
    top: 0;
    right: 0;
    width: 100%;
    height: 100%;
    z-index: 9999;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
    transition: 0.1s;
    visibility: hidden;
    opacity: 0;

    &.active {
        visibility: visible;
        opacity: 1;
    }

    &.dark {
        background: $color-dark;
    }

    &.dark-trans-4 {
        background: $color-dark-transparent-4;
    }

    &.dark-trans-8 {
        background: $color-dark-transparent-8;
    }

    &.white {
        background: $color-white;
    }

    &.white-trans-4 {
        background: $color-white-transparent-4;
    }

    &.white-trans-8 {
        background: $color-white-transparent-8;
    }

    &.trans {
        background: transparent;
    }

    .irantheme-preloader-loader {
        width: 2.5rem;
        height: 2.5rem;
        border-radius: 50%;
        border-width: 5px;
        border-style: solid;
        -webkit-transition: 0.3s;
        -o-transition: 0.3s;
        transition: 0.3s;

        &.thin {
            border-width: 2.5px;
        }
    }

    &.dark .irantheme-preloader-loader {
        border-color: $color-gray-600 $color-gray-600 $color-gray-200 $color-gray-600;
    }

    &.white .irantheme-preloader-loader {
        border-color: $color-gray-400 $color-gray-400 $color-gray-800 $color-gray-400;
    }
}