/*
=====================================
Product fast access
=====================================
*/
.irantheme-product-fast-access {
    position: fixed;
    top: 0;
    right: 0;
    width: 100%;
    height: 100%;
    z-index: 999999;
    display: none;

    .col-lg-6 {
        position: relative;
    }

    // Wrapper of content
    &-wrapper {
        position: absolute;
        top: 0;
        right: 0;
        height: 100%;
        width: 100%;
        display: none;
        z-index: 3;
    }

    // Close button
    &-close {
        position: absolute;
        top: 0.5rem;
        right: 0.5rem;
        width: 1.75rem;
        height: 1.75rem;
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 2;
        background: $color-dark;
        border-radius: 50%;
        @include transition(0.2s);
        color: $color-white;

        i {
            font-size: 0.9rem;
        }

        &:hover {
            background: $color-gray-transparent-5;
            color: $color-dark;
        }
    }

    // Box ajax content
    &-box {
        position: absolute;
        top: 50%;
        right: 50%;
        width: 800px;
        max-width: calc(100% - 2rem);
        height: fit-content;
        background: $color-white;
        display: flex;
        padding: 1rem;
        overflow-x: hidden;
        overflow-y: auto;
        border-radius: $border-radius-high;
        @include transform(translate(50%, -50%));

        .row {
            row-gap: 1rem;
        }

        // Gallery
        &-gallery {
            width: 100%;
            position: relative;

            // Swiper slider
            &-slider {
                width: 100%;
                height: 100%;

                img {
                    width: 100% !important;
                    height: 100%;
                    object-fit: contain;
                    border-radius: $border-radius-high;
                }
            }
        }

        // Content
        &-content {
            display: flex;
            flex-direction: column;
            row-gap: 2rem;
            height: 100%;
            width: 100%;

            // Top elements
            &-top {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: space-between;

                &-title {
                    font-size: 0.8rem;
                    font-weight: bold;
                    display: flex;
                    align-items: center;
                    column-gap: 0.5rem;


                    i {
                        font-weight: bold;
                        color: $color-dark;
                    }

                    cite {
                        color: $color-dark;
                        font-style: normal;
                    }
                }

                // Rating
                &-rating {
                    display: flex;
                    align-items: center;
                    flex-wrap: nowrap;

                    &.flex-right {
                        justify-content: flex-start;
                    }

                    &.flex-left {
                        justify-content: flex-end;
                    }

                    &.flex-center {
                        justify-content: center;
                    }

                    &-score {
                        font-size: 0.75rem;
                        color: $color-dark;
                    }

                    i {
                        color: $color-quinary;
                        font-size: 0.8rem;
                    }

                    span {
                        color: $color-dark;
                        position: relative;
                        top: 1px;
                        margin-left: 0.25rem;
                        font-size: 0.7rem;
                    }
                }
            }

            // Text
            &-text {
                margin-top: auto;
                margin-bottom: auto;
                text-align: right;

                &-heading {
                    font-size: 1rem;
                    line-height: normal;

                    a {
                        color: $color-dark;
                    }
                }

                &-excerpt {
                    font-size: 0.8rem;
                    line-height: normal;
                    margin-top: 1rem;
                    color: $color-gray-700;
                }
            }

            // Add to cart
            .irantheme-woocommerce-products-item-add-to-cart {
                display: flex;
                align-items: center;
                justify-content: space-between;

                &-button {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    padding: 0.75rem 1rem !important;
                    border-radius: 50%;
                    width: 3rem;
                    height: 3rem;
                    z-index: 9;
                    @include transition(0.2s);
                    @include transform(scale(0.9));
                    background: $color-white;

                    &:hover {
                        @include transform(scale(0.95));
                    }

                    &:active {
                        @include transform(scale(1));
                    }

                    i {
                        color: $color-dark;
                        font-size: 1.2rem;
                        margin: 0 !important;
                        font-weight: bold;
                    }

                    &-success {
                        display: none;
                    }

                    // Spinner hide
                    .irantheme-animate-rotate {
                        width: 1.1rem;
                        height: 1.1rem;
                        border-radius: 50%;
                        border-width: 2px;
                        border-style: solid;
                        transition: 0.3s;
                        transition: all 0.5s linear;
                        display: none;
                        border-color: $color-gray-300 $color-gray-300 $color-gray-700 $color-gray-300;

                        &.active {
                            display: flex !important;
                        }
                    }
                }

                // Added to cart
                .added_to_cart {
                    font-size: 0.7rem;
                    margin-top: 0.5rem;
                    color: $color-gray-700;
                    text-align: center !important;
                    display: none !important;
                }
            }

            // Price
            &-price {
                font-size: 0.8rem;
                line-height: normal;
                font-weight: bold;
                display: flex;
                justify-content: flex-end;
                align-items: center;
                text-align: left;
                margin-right: auto;
                color: $color-gray-800;

                .irantheme-woocommerce-products-holder {
                    display: flex;
                    align-items: center;
                    column-gap: 0.25rem;
                    justify-content: flex-end;
                }

                .irantheme-woocommerce-products-discount {
                    padding: 0.25rem;
                    font-size: 0.6rem;
                    border-radius: $border-radius-medium;
                    color: $color-dark;
                    background: $color-gray-300;
                }

                del {
                    font-size: 0.7rem;
                    color: $color-gray-500;
                    display: block;
                    font-weight: normal;

                    .woocommerce-Price-currencySymbol {
                        display: none;
                    }
                }

                ins {
                    text-decoration: none;
                    display: block;
                    color: $color-dark;
                }

                svg {
                    width: 1.1rem;
                    height: 1.1rem;
                    fill: $color-dark;
                    position: relative;
                    top: -2px;
                }
            }
        }
    }

    // Spinner hide
    .irantheme-animate-rotate {
        width: 3rem;
        height: 3rem;
        border-radius: 50%;
        border-width: 5px;
        border-style: solid;
        border-color: $color-gray-400 $color-gray-400 $color-gray-700 $color-gray-400;
        transition: 0.3s;
        margin-left: 0.5rem;
        transition: all 0.5s linear;
        // display: none;

        &.active {
            display: flex !important;
        }
    }
}