/*
=====================================
Service Note Slider Section
=====================================
*/
.irantheme-service-note-slider-section {
    .irantheme-service-note-slider {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        .irantheme-section-service-note-slider-swiper {
            margin-right: -4rem;
            margin-left: -4rem;
            margin-top: 0;
            margin-bottom: 0;
            position: relative;

            @media only screen and (max-width:991px) {
                margin-right: 0;
                margin-left: 0;
                margin-top: -2rem;
                margin-bottom: -2rem;
            }

            // Item note
            .irantheme-section-service-note-slider-item {
                padding: 2rem;
                display: flex;
                column-gap: 1rem;
                align-items: center;

                &-counter {
                    font-size: 4rem;
                    opacity: 0.35;
                    color: $color-gray-500;
                    z-index: -1;
                    cursor: default;
                }

                &-content {

                    &-heading {
                        // color: $color-white;
                        font-size: 1rem;
                        font-weight: bold;
                        margin-bottom: 0.25rem;
                    }

                    &-description {
                        // color: $color-gray-300;
                        font-size: 0.8rem;
                    }

                    &-link {
                        font-size: 1rem;
                        width: 2.5rem;
                        height: 2.5rem;
                        border-radius: 50%;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        text-align: center;
                        margin-right: auto;
                    }
                }

            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            .irantheme-section-service-note-slider-swiper {
                background: $color-white;
                @extend %box-shadow-white;

                .irantheme-section-service-note-slider-item-content-heading {
                    color: $color-dark;
                }

                .irantheme-section-service-note-slider-item-content-description {
                    color: $color-gray-700;
                }

                .irantheme-section-service-note-slider-item-content-link {
                    background: $color-gray-100;
                    color: $color-dark;

                    &:hover {
                        background: $color-gray-200;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            .irantheme-section-service-note-slider-swiper {
                background: $color-dark;
                @extend %box-shadow-dark;

                .irantheme-section-service-note-slider-item-content-heading {
                    color: $color-white;
                }

                .irantheme-section-service-note-slider-item-content-description {
                    color: $color-gray-300;
                }

                .irantheme-section-service-note-slider-item-content-link {
                    background: $color-gray-900;
                    color: $color-white;

                    &:hover {
                        background: $color-gray-800;
                    }
                }
            }
        }
    }
}