/*
=====================================
Business Ibanner Section
=====================================
*/
.irantheme-business-ibanner-section {
    .irantheme-business-ibanner {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Viewpoints
        .irantheme-business-ibanner-post-swiper {}

        .irantheme-business-ibanner-post-wrapper {
            text-align: right;

            .irantheme-business-ibanner-post-container {
                row-gap: 1.5rem;
            }

            // All columns
            div[class*="col"] {
                margin-bottom: 0 !important;
            }

            // Item
            .irantheme-business-ibanner-post-item {
                position: relative;
                display: flex;
                flex-direction: column;
                background-repeat: no-repeat;
                background-position: center;
                background-size: cover;
                overflow: hidden;

                // Shadow
                &.irantheme-business-ibanner-item-shadow {
                    @extend %box-shadow-white;
                }

                // Image user
                &-image {
                    &-link {
                        display: flex;
                        width: 100%;
                        height: 100%;
                    }

                    &-src {
                        width: 100%;
                        height: auto;
                        object-fit: cover;
                        object-position: center;
                    }
                }

                // Content
                &-content {
                    display: flex;
                    flex-direction: column;
                    width: 100%;
                    height: 100%;
                    padding: 1rem;
                    z-index: 99;
                    position: absolute;
                    top: 0;
                    right: 0;

                    .irantheme-tinymce-content {
                        * {
                            margin: 0 0 0.5rem 0 !important;
                        }
                    }

                    .irantheme-btn-group {
                        margin: 0 !important;
                        padding: 0 !important;
                        margin-top: 0.5rem !important;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            // Viewpoints
            .irantheme-business-ibanner-post-wrapper {

                // Item
                .irantheme-business-ibanner-post-item {

                    // Shadow
                    &.irantheme-business-ibanner-item-shadow {
                        @extend %box-shadow-white;
                    }

                    // Image user
                    &-image {}


                    // Content
                    &-content {}
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            // Viewpoints
            .irantheme-business-ibanner-post-wrapper {

                // Item
                .irantheme-business-ibanner-post-item {

                    // Shadow
                    &.irantheme-business-ibanner-item-shadow {
                        @extend %box-shadow-dark;
                    }

                    // Image user
                    &-image {}


                    // Content
                    &-content {}
                }
            }
        }
    }
}