/*
=====================================
Business Viewpoints post
=====================================
*/
.irantheme-business-viewpoints-post-section {
    .irantheme-business-viewpoints-post {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Viewpoints
        .irantheme-business-viewpoints-post-swiper {}

        .irantheme-business-viewpoints-post-wrapper {
            text-align: center;

            // Item
            .irantheme-business-viewpoints-post-item {
                position: relative;
                padding: 2rem;

                // Box style none
                &.irantheme-box-style-none {
                    padding: 0 !important;
                }

                // Image user
                &-image {
                    margin-bottom: 2rem;

                    &-src {
                        width: 5rem;
                        height: 5rem;
                        border-radius: 50%;
                    }
                }

                // Content
                &-content {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    align-items: center;
                    text-align: center;

                    // Heading
                    &-heading {

                        // Title
                        &-title {
                            // color: $color-white;
                            font-size: 1rem;
                        }

                        // Skills
                        &-skills {
                            // color: $color-white;
                            font-size: 0.8rem;
                        }
                    }

                    // Description
                    &-desc {
                        // color: $color-gray-100;
                        font-size: 0.8rem;
                        margin-bottom: 1rem;
                    }
                }

                // Star
                &-star {
                    cursor: default;
                    margin-bottom: 2rem;

                    // Holder star icons
                    &-holder {}

                    // Icon
                    &-icon {
                        color: $color-quinary-hover;
                        font-size: 0.8rem;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            // Viewpoints
            .irantheme-business-viewpoints-post-wrapper {

                // Item
                .irantheme-business-viewpoints-post-item {

                    // Shadow
                    &.irantheme-box-style-shadow {
                        @extend %box-shadow-white;
                    }

                    // Shadow
                    &.irantheme-box-style-border {
                        border: 1px solid $color-gray-200;
                    }

                    // Content
                    &-content {

                        // Heading
                        &-heading {

                            // Title
                            &-title {
                                color: $color-gray-800;
                            }

                            // Skills
                            &-skills {
                                color: $color-gray-700;
                            }
                        }

                        // Quote
                        &-quote {
                            color: $color-gray-600;
                        }

                        // Description
                        &-desc {
                            color: $color-gray-600;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            // Viewpoints
            .irantheme-business-viewpoints-post-wrapper {

                // Item
                .irantheme-business-viewpoints-post-item {

                    // Shadow
                    &.irantheme-box-style-shadow {
                        @extend %box-shadow-dark;
                    }

                    // Shadow
                    &.irantheme-box-style-border {
                        border: 1px solid $color-gray-800;
                    }

                    // Content
                    &-content {

                        // Heading
                        &-heading {

                            // Title
                            &-title {
                                color: $color-gray-200;
                            }

                            // Skills
                            &-skills {
                                color: $color-gray-300;
                            }
                        }

                        // Quote
                        &-quote {
                            color: $color-gray-400;
                        }

                        // Description
                        &-desc {
                            color: $color-gray-400;
                        }
                    }
                }
            }
        }
    }
}