.irantheme-woocommerce-categories-section {

    .irantheme-woocommerce-categories {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        &-wrapper {
            position: relative;
            z-index: 2;

            .swiper-wrapper {
                justify-content: space-around;
            }
        }

        // Columns
        .irantheme-woocommerce-categories-col {
            padding: 1rem;
            height: auto;
        }

        // Item
        &-item {
            display: flex;
            flex-direction: column;

            // Flex alignments
            &.flex-right {
                align-items: flex-start;
            }

            &.flex-left {
                align-items: flex-end;
            }

            &.flex-center {
                align-items: center;
            }

            // Image
            &-image {
                position: relative;
                overflow: hidden;
                width: 100%;
                aspect-ratio: 1 / 1;
                max-width: 8rem;
                // background: $color-gray-200;
                margin-bottom: 1rem;

                &::before {
                    content: '';
                    position: absolute;
                    top: 0;
                    right: 0;
                    height: 100%;
                    width: 100%;
                    z-index: -1;
                }

                &.irantheme-woocommerce-category-image-radius {
                    border-radius: 50%;
                }

                &-img {
                    object-fit: cover;
                    width: 100%;
                    height: 100%;
                    @include transition(0.2s);
                }

                &:hover {
                    .irantheme-woocommerce-categories-item-image-img {
                        @include transform(scale(1.1));
                    }

                    .irantheme-woocommerce-categories-item-image-product-count {
                        opacity: 0;
                    }
                }

                &-product-count {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    @include transform(translate(-50%, -50%));
                    @include transition(0.2s);
                    min-width: 1.5rem;
                    min-height: 1.5rem;
                    border-radius: 50%;
                    // background: $color-dark-transparent-6;
                    // color: $color-white;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    text-align: center;
                    line-height: normal;
                    font-size: 0.7rem;
                    z-index: 9;
                }
            }

            // Heading
            &-heading {
                display: flex;
                flex-direction: column;
                justify-content: center;
                width: fit-content;

                // Title
                &-title {
                    font-size: 0.9rem;
                    // color: $color-gray-700;
                    margin-bottom: 0.25rem;

                    &-product-count {
                        // color: $color-gray-600;
                        margin-right: 0.15rem;
                        font-size: 0.8rem;
                    }
                }

                // Product count
                &-product-count {
                    // color: $color-gray-600;
                    font-size: 0.7rem;
                    cursor: default;

                    &-number {
                        // color: $color-gray-600;
                    }

                    &-title {
                        font-style: normal;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            &-wrapper {}

            .irantheme-woocommerce-categories-col {}

            // Item
            .irantheme-woocommerce-categories-item {

                // Image
                &-image {
                    // background: $color-gray-200;
                    background: transparent;

                    &::before {
                        background: $color-gray-100;
                    }

                    &-product-count {
                        background: $color-white;
                        color: $color-dark;
                    }
                }

                // Heading
                &-heading {

                    // Title
                    &-title {
                        a {
                            color: $color-gray-700;
                        }

                        &-product-count {
                            color: $color-gray-600;
                        }
                    }

                    // Product count
                    &-product-count {
                        color: $color-gray-600;

                        &-number {
                            color: $color-gray-600;
                        }

                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            &-wrapper {}

            .irantheme-woocommerce-categories-col {}

            // Item
            .irantheme-woocommerce-categories-item {

                // Image
                &-image {
                    // background: $color-gray-800;
                    background: transparent;

                    &::before {
                        background: $color-gray-900;
                    }

                    &-product-count {
                        background: $color-dark;
                        color: $color-white;
                    }
                }

                // Heading
                &-heading {

                    // Title
                    &-title {

                        a {
                            color: $color-gray-300;
                        }

                        &-product-count {
                            color: $color-gray-400;
                        }
                    }

                    // Product count
                    &-product-count {
                        color: $color-gray-400;

                        &-number {
                            color: $color-gray-400;
                        }

                    }
                }
            }
        }
    }
}