/*
=====================================
Parallax
=====================================
*/

.parallax-container {
	z-index: 2;

	&::before {
		content: '';
		background-color: $color-dark-transparent-9;
		width: 100%;
		height: 100%;
		position: absolute;
		top: 0;
		right: 0;
		z-index: 1;
	}
}

