/*
=====================================
Diagonal borders
=====================================
*/

.diagonal-border {
	&::after {
		content: '';
		width: calc(100vw + 20rem);
		height: 10rem;
		background-color: $color-white;
		position: absolute;
		right: -3rem;
		bottom: -8rem;
		transform: rotate(-2deg);
		z-index: 3;
	}
}

/*
=====================================
Init grid masonry
=====================================
*/

#single-post {
	.grid-masonry {
		width: 100% !important;

		.grid-sizer,
		.grid-item {
			width: 100%;
			padding: 15px;

			@media only screen and (min-width: 576px) {
				& {
					width: 100%;
				}
			}

			@media only screen and (min-width: 768px) {
				& {
					width: 100%;
				}
			}

			@media only screen and (min-width: 992px) {
				& {
					width: 50%;
				}
			}

			@media only screen and (min-width: 1200px) {
				& {
					width: 50%;
				}
			}
		}
	}
}

/*
=====================================
Heading mode
=====================================
*/

.heading-mode {
	margin-bottom: 1rem;

	h2 {
		font-size: 1.1rem;
		display: block;
		margin-bottom: 0.9rem;
	}

	p {
		display: block;
		margin-bottom: 1rem;
		font-size: 1.1rem;
	}

	// Light
	&.heading-mode-light {
		h2 {
			color: $color-white;
		}

		p {
			color: $color-gray-300;
		}
	}

	// Dark
	&.heading-mode-dark {
		h2 {
			color: $color-dark;
		}

		p {
			color: $color-gray-700;
		}
	}
}

/*
=====================================
Holding table
=====================================
*/

.holding-table {

	&::before,
	&::after {
		content: '';
		display: table;
		clear: both;
	}
}

/*
=====================================
Go to top
=====================================
*/
.irantheme-scroll-up {
	position: fixed;
	bottom: 1rem;
	opacity: 0.9;
	width: 2rem;
	height: 2rem;
	border-radius: $border-radius-low;
	display: flex;
	justify-content: center;
	align-items: center;
	text-align: center;
	font-size: 0.9rem;
	font-weight: bold;
	z-index: 9999999;
	cursor: pointer;

	&:hover,
	&.active {
		opacity: 1;
	}

	&.scroll-left {
		left: 1rem;
	}

	&.scroll-right {
		right: 1rem;
	}

	&.scroll-dark {
		background-color: $color-gray-700;
		color: $color-white;
	}

	&.scroll-white {
		background-color: $color-gray-300;
		color: $color-dark;
	}
}

/*
=====================================
Separator (Line)
=====================================
*/
.irantheme-separator-line {
	margin-top: 2rem;
	margin-bottom: 2rem;
	display: block;
	height: 1px;
	width: 100%;
	opacity: 1;
	border: none !important;

	&.white {
		background: $color-gray-600;
	}

	&.dark {
		background: $color-gray-400;
	}
}

