/*
=====================================
Slider Split Screen Section
=====================================
*/
.irantheme-service-semi-split-image-section {
    .irantheme-service-semi-split-image {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        .irantheme-service-semi-split-image-images {
            display: flex;
            width: 100%;
            position: relative;
            overflow: hidden;

            // Trigger
            .irantheme-service-semi-split-image-trigger {
                z-index: 99;
                width: 0.15rem;
                height: 100%;
                position: absolute;
                top: 0;
                left: 50%;
                // background: $color-white;

                &-toggle {
                    width: 3rem;
                    height: 3rem;
                    font-size: 1.2rem;
                    // color: $color-gray-600;
                    // background: $color-white-transparent-8;
                    // border: 2px solid $color-white;
                    border-radius: 50%;
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    @include transform(translate(-50%, -50%));
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    text-align: center;
                    cursor: col-resize;
                }
            }

            &-img {
                width: 100%;
                object-fit: contain;
                user-select: none;
                position: relative;
                height: fit-content;

                &::selection {
                    background: transparent !important;
                }

                &-1 {
                    z-index: 8;
                }

                &-2 {
                    z-index: 16;
                    width: 100%;
                    height: 100%;
                    position: absolute;
                    top: 0;
                    left: 0 !important;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            .irantheme-service-semi-split-image-images {

                // Trigger
                .irantheme-service-semi-split-image-trigger {
                    background: $color-white;

                    &-toggle {
                        color: $color-gray-600;
                        background: $color-white-transparent-8;
                        border: 2px solid $color-white;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            .irantheme-service-semi-split-image-images {

                // Trigger
                .irantheme-service-semi-split-image-trigger {
                    background: $color-dark;

                    &-toggle {
                        color: $color-gray-400;
                        background: $color-dark-transparent-8;
                        border: 2px solid $color-dark;
                    }
                }
            }
        }
    }
}