/*
=====================================
Header blog
=====================================
*/

#header-advanced {
    width: 100%;
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
    background-color: $color-dark;
    position: relative;

    .irantheme-container-inner {
        position: relative;
        z-index: 3;

        .heading-info {
            padding: 6rem 0;

            // Breadcrumbs
            .breadcrumbs {
                margin-bottom: 0.5rem;

                ul {
                    display: flex;
                    flex-direction: row;

                    li {
                        position: relative;
                        display: flex;

                        &::after {
                            content: '\f104';
                            font-family: $font-family-icons;
                            font-size: 0.6rem;
                            color: $color-primary;
                            display: inline-block;
                            margin-right: 0.5rem;
                        }

                        &:not(:last-child) {
                            margin-left: 0.5rem;
                        }

                        &:last-child::after {
                            display: none;
                        }

                        a,
                        span {
                            font-size: 0.7rem;
                            color: $color-gray-300;
                            display: block;

                            &:hover {
                                color: $color-white;
                            }
                        }

                        span {
                            color: $color-primary !important;
                        }
                    }
                }
            }
        }

        // Options
        .options {
            display: flex;
            margin-bottom: 1rem;

            .options-layer {
                background: $color-white-transparent-4;
                border-radius: 3rem;
                display: flex;
                flex-direction: row;
                font-size: 0.7rem;
                overflow: hidden;

                .irantheme-holder-options {
                    background: $color-white-transparent-6;
                    padding: 0 1rem;
                    display: flex;
                    border-top-left-radius: 1.5rem;
                    border-bottom-left-radius: 1.5rem;

                    span {
                        margin-left: 0.5rem;
                        cursor: pointer;
                    }

                    // Social networks
                    .irantheme-social-media {
                        display: flex;

                        li {
                            &:not(:last-child) {
                                margin-left: 0.5rem;
                            }

                            a {

                                path,
                                svg {
                                    width: 0.7rem;
                                    height: 0.7rem;
                                    position: relative;
                                    top: -2px;
                                    transition: inherit;
                                }

                                &:hover {
                                    color: $color-white;

                                    path,
                                    svg {
                                        color: $color-white;
                                        fill: $color-white;
                                        width: 0.7rem;
                                        height: 0.7rem;
                                    }
                                }

                                &.search-alt {
                                    &:hover {
                                        color: $color-primary;
                                        cursor: pointer;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Heading main info
        .heading-main-info {
            h1 {
                font-size: 2rem;
                margin: 0 0 1rem;
                color: $color-white;

                a {
                    color: $color-white;
                }
            }

            p {
                font-size: 0.8rem;
                color: $color-gray-300;
            }
        }
    }
}