.irantheme-woocommerce-mini-products-section {

    .irantheme-woocommerce-mini-products {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        &-wrapper {
            position: relative;
            z-index: 2;
        }

        // Heading
        &-heading {
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
            position: relative;

            // Title
            &-title {
                font-size: 1.05rem;
                font-weight: 700;
                line-height: 1.3;
                letter-spacing: -0.015em;
                color: $color-gray-900;
                margin: 0;
                display: inline-flex;
                align-items: center;
                gap: 0.625rem;

                // Minimal accent dot before title
                &-dot {
                    display: inline-block;
                    width: 6px;
                    height: 6px;
                    border-radius: 50%;
                    background: currentColor;
                    flex-shrink: 0;
                }
            }

            // Link / icon button
            &-icon {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 0.375rem;
                width: 2rem;
                height: 2rem;
                border-radius: 50%;
                background: transparent;
                color: $color-gray-500;
                font-size: 0.75rem;
                text-decoration: none;
                @include transition(0.2s, all, ease);

                i {
                    line-height: 1;
                    transition: transform 0.2s ease;
                }

                &:hover {
                    color: $color-gray-900;
                    border-color: $color-gray-400;
                    background: $color-gray-100;

                    i {
                        transform: translateX(-2px); // RTL: arrow points left
                    }
                }
            }
        }

        // Columns
        .irantheme-woocommerce-mini-products-col {
            padding-top: 0.75rem;
            padding-bottom: 0.75rem;
            height: fit-content;
        }

        // Hover shadow
        &-hover-shadow {
            @include transition(0.2s);
            overflow: hidden;

            &:hover {
                // background: $color-white;
                @include transform (translateY(-1rem));
                border-radius: $border-radius-low;
            }
        }

        // Hover scale
        &-hover-scale {
            overflow: hidden;

            .irantheme-woocommerce-mini-products-item {
                &-image {
                    img {
                        @include transition(3s, 'all', ease-in-out);
                    }
                }

                &-image:hover {
                    img {
                        animation-duration: 3s;
                        animation-name: scale;
                        animation-timing-function: cubic-bezier(0.47, 0, 0.745, 0.715);
                        animation-delay: 0.2s;
                        animation-direction: alternate;
                        animation-iteration-count: infinite;
                    }
                }
            }

            @keyframes scale {
                from {
                    @include transform(scale(1));
                }

                to {
                    @include transform(scale(1.25));
                }
            }
        }

        // Item
        &-item {
            position: relative;
            height: 100%;
            overflow: hidden;
            display: flex;
            column-gap: 1rem;

            @media only screen and (max-width: 768px) {
                column-gap: 0.5rem;
            }

            &:hover {
                box-shadow: none !important;
            }

            // Remove extra spacing of last child
            &>*:last-child {
                margin-bottom: 0 !important;
            }

            // Border
            &.irantheme-woocommerce-mini-products-item-padding {
                padding: 1rem !important;
            }

            // Border
            &.irantheme-woocommerce-mini-products-item-border {
                border-width: 1px;
                border-style: solid;
                padding: 0.5rem;
                // border-color: $color-gray-200;
            }

            // Shadow
            &.irantheme-woocommerce-mini-products-item-shadow {
                padding: 0.5rem;
                @include transition(0.2s);
            }

            // Transparent
            &.irantheme-woocommerce-mini-products-item-transparent {
                background-color: transparent !important;
            }

            // Images & gallery
            &-image {
                position: relative;
                flex-shrink: 0;
                width: var(--irantheme-thumb-size, 100px);
                height: var(--irantheme-thumb-size, 100px);
                border-radius: inherit;
                overflow: hidden;
                background-color: $color-gray-100; // placeholder while loading

                // Responsive: shrink thumbnail on smaller screens
                @media only screen and (max-width: 768px) {
                    width: calc(var(--irantheme-thumb-size, 100px) * 0.75);
                    height: calc(var(--irantheme-thumb-size, 100px) * 0.75);
                }

                @media only screen and (max-width: 480px) {
                    width: calc(var(--irantheme-thumb-size, 100px) * 0.5);
                    height: calc(var(--irantheme-thumb-size, 100px) * 0.5);
                }

                // Sale badge overlay (top-left corner)
                &-sale {
                    position: absolute;
                    top: 0.375rem;
                    left: 0.375rem;
                    z-index: 3;
                    display: inline-flex;
                    align-items: center;
                    gap: 0.25rem;
                    padding: 0.2rem 0.45rem;
                    font-size: 0.6rem;
                    font-weight: 700;
                    line-height: 1;
                    color: $color-white;
                    border-radius: $border-radius-medium;
                    backdrop-filter: blur(4px);
                    pointer-events: none;

                    i {
                        font-size: 0.55rem;
                        line-height: 1;
                    }
                }

                &-link {
                    display: block;
                    position: relative;
                    width: 100%;
                    height: 100%;
                    border-radius: inherit;
                    overflow: hidden;
                }

                img {
                    display: block;
                    width: 100%;
                    height: 100%;
                    object-fit: contain;
                    object-position: center;
                    @include transition(0.3s, all, ease);
                }

                // Base image (first/featured)
                .irantheme-woocommerce-mini-products-item-img {
                    position: relative;
                    z-index: 0;
                }

                // Gallery image (overlay on hover)
                .irantheme-woocommerce-mini-products-item-gallery-img {
                    position: absolute;
                    inset: 0;
                    z-index: 1;
                    opacity: 0;
                    visibility: hidden;
                    @include transition(0.3s, all, ease);
                }

                &.irantheme-woocommerce-mini-products-item-image-changer {
                    &:hover {
                        .irantheme-woocommerce-mini-products-item-gallery-img {
                            opacity: 1;
                            visibility: visible;
                        }
                    }
                }
            }

            // Content
            &-content {
                display: flex;
                flex-direction: column;
                justify-content: center;
                width: 100%;

                &-head {
                    display: flex;
                    justify-content: space-between
                }

                // Category
                &-category {
                    font-size: 0.7rem;

                    a {
                        // color: $color-gray-600;
                        display: inline-block;

                        &:not(:last-child) {
                            margin-left: 0.5rem;
                        }

                        &:hover {
                            // color: $color-gray-900;
                        }
                    }
                }

                // Heading
                &-heading {
                    font-size: 0.7rem;
                    font-weight: bold;
                    margin-bottom: 0.25rem;

                    a {
                        // color: $color-dark;
                        -webkit-line-clamp: 2;
                        line-clamp: 2;
                        display: -webkit-box;
                        -webkit-box-orient: vertical;
                        overflow: hidden;
                    }
                }

                // Sale count
                &-sale {
                    display: inline-flex;
                    align-items: center;
                    gap: 0.25rem;
                    font-size: 0.65rem;
                    font-weight: 600;
                    line-height: 1;
                    padding: 0.25rem 0.5rem;
                    border-radius: $border-radius-medium;
                    background-color: $color-gray-100;
                    color: $color-gray-700;
                    width: fit-content;
                    margin-bottom: 0.375rem;

                    i {
                        font-size: 0.6rem;
                        color: $color-quinary; // fire icon in accent color
                        line-height: 1;
                    }

                    &-count {
                        font-weight: 700;
                        color: $color-gray-900;
                    }

                    &-label {
                        opacity: 0.75;
                    }
                }
            }

            // Details
            &-details {
                display: flex;
                justify-content: space-between;
                flex-wrap: wrap;
            }

            // Rating
            &-rating {
                display: flex;
                align-items: center;
                flex-wrap: nowrap;

                &-score {
                    font-size: 0.75rem;
                    // color: $color-gray-600;
                }

                i {
                    color: $color-quinary;
                    font-size: 0.8rem;
                }

                span {
                    position: relative;
                    top: 1px;
                    margin-left: 0.25rem;
                    font-size: 0.7rem;
                }
            }

            // Price
            &-price {
                font-size: 0.8rem;
                line-height: normal;
                font-weight: bold;
                display: flex;
                justify-content: flex-end;
                align-items: center;
                text-align: left;
                margin-left: auto;
                // color: $color-gray-800;

                .irantheme-woocommerce-products-price {
                    display: flex;
                    flex-direction: column;
                    padding-bottom: 0.5rem;
                }

                .irantheme-woocommerce-products-holder {
                    display: flex;
                    align-items: center;
                    column-gap: 0.25rem;
                    justify-content: flex-end;
                }

                .irantheme-woocommerce-products-discount {
                    padding: 0.25rem;
                    font-size: 0.6rem;
                    border-radius: $border-radius-medium;
                }

                del {
                    font-size: 0.7rem;
                    // color: $color-gray-600;
                    display: block;
                    font-weight: normal;

                    .woocommerce-Price-currencySymbol {
                        display: none;
                    }
                }

                ins {
                    text-decoration: none;
                    display: block;
                }

                svg {
                    width: 1.1rem;
                    height: 1.1rem;

                    position: relative;
                    top: -2px;
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            &-wrapper {}

            // Heading
            .irantheme-woocommerce-mini-products-heading {
                &::after {
                    background: linear-gradient(to left, $color-gray-200, transparent);
                }

                &-title {
                    color: $color-gray-900;
                }

                &-icon {
                    background: $color-gray-100;
                    color: $color-gray-700;

                    &:hover {
                        background: $color-gray-200;
                        color: $color-gray-900;
                    }
                }
            }

            .irantheme-woocommerce-mini-products-col {}

            // Hover shadow
            .irantheme-woocommerce-mini-products-hover-shadow {

                &:hover {

                    .irantheme-woocommerce-mini-products-item {
                        background: $color-white;
                    }
                }
            }

            // Item
            .irantheme-woocommerce-mini-products-item {
                background: $color-white;

                // Border
                &.irantheme-woocommerce-mini-products-item-border {
                    border-color: $color-gray-100;
                }

                // Shadow
                &.irantheme-woocommerce-mini-products-item-shadow {
                    @extend %box-shadow-white;
                }

                // Images & gallery
                &-image {}

                // Content
                &-content {

                    // Category
                    &-category {

                        a {
                            color: $color-gray-600;

                            &:hover {
                                color: $color-gray-900;
                            }
                        }
                    }

                    // Heading
                    &-heading {
                        a {
                            color: $color-dark;
                        }
                    }

                    // Excerpt
                    &-excerpt {
                        color: $color-gray-700;
                    }
                }

                // Rating
                &-rating {

                    &-score {
                        color: $color-gray-600;
                    }

                    span {
                        color: $color-gray-700;
                    }
                }

                // Price
                &-price {
                    color: $color-gray-900;

                    // Discount
                    .irantheme-woocommerce-products-discount {
                        background: $color-gray-300;
                        color: $color-dark;
                    }

                    del {
                        color: $color-gray-500;
                    }

                    svg {
                        fill: $color-gray-900;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            &-wrapper {}

            // Heading
            .irantheme-woocommerce-mini-products-heading {
                &::after {
                    background: linear-gradient(to left, $color-gray-800, transparent);
                }

                &-title {
                    color: $color-white;
                }

                &-icon {
                    background: $color-gray-800;
                    color: $color-gray-300;

                    &:hover {
                        background: $color-gray-700;
                        color: $color-white;
                    }
                }
            }

            .irantheme-woocommerce-mini-products-col {}

            // Hover shadow
            .irantheme-woocommerce-mini-products-hover-shadow {

                &:hover {

                    .irantheme-woocommerce-mini-products-item {
                        background: $color-dark;
                    }
                }
            }

            // Item
            .irantheme-woocommerce-mini-products-item {
                background: $color-dark;

                // Border
                &.irantheme-woocommerce-mini-products-item-border {
                    border-color: $color-gray-900;
                }

                // Shadow
                &.irantheme-woocommerce-mini-products-item-shadow {
                    @extend %box-shadow-dark;
                }

                // Images & gallery
                &-image {}

                // Content
                &-content {

                    // Category
                    &-category {

                        a {
                            color: $color-gray-400;

                            &:hover {
                                color: $color-gray-100;
                            }
                        }
                    }

                    // Heading
                    &-heading {
                        a {
                            color: $color-white;
                        }
                    }

                    // Excerpt
                    &-excerpt {
                        color: $color-gray-300;
                    }
                }

                // Rating
                &-rating {

                    &-score {
                        color: $color-gray-400;
                    }

                    span {
                        color: $color-gray-300;
                    }
                }

                // Price
                &-price {
                    color: $color-gray-100;

                    // Discount
                    .irantheme-woocommerce-products-discount {
                        background: $color-gray-700;
                        color: $color-white;
                    }

                    del {
                        color: $color-gray-500;
                    }

                    svg {
                        fill: $color-gray-100;
                    }
                }
            }
        }
    }
}