/*
=====================================
Business Portfolio
=====================================
*/
.irantheme-business-portfolio-section {
    .irantheme-business-portfolio {
        position: relative;
        background-position: center;
        background-repeat: no-repeat;
        background-size: cover;

        // Wrapper
        &-wrapper {
            position: relative;
            z-index: 2;
        }

        // Animate
        &-animation {
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
        }

        // Item
        &-item {
            display: flex;
            height: auto !important;
            // margin-bottom: 1rem;

            &-holder {
                position: relative;
                display: flex;
                flex-direction: column;
                height: 100%;
                overflow: hidden;

                &.irantheme-portfolio-card-wrapper {
                    .irantheme-business-portfolio-item-content-wrap {
                        margin-top: 1rem;
                    }
                }

                &:hover {
                    .irantheme-business-portfolio-item-hero-hover-button-wrap {
                        opacity: 1;
                        visibility: visible;
                    }
                }
            }

            &-hero {
                position: relative;
                z-index: 1;

                // hero
                &-image-wrap {
                    position: relative;
                    width: 100%;
                    height: 100%;
                    display: flex;
                    overflow: hidden;
                    z-index: 1;

                    // Image
                    img {
                        object-fit: fill;
                        width: 100%;
                        // height: 100%;

                        &::selection {
                            background-color: transparent;
                            color: inherit
                        }

                        &.irantheme-portfolio-item-border-little {
                            border: 1px solid $color-gray-500;
                        }
                    }

                }

                &-hover-button-wrap {
                    position: absolute;
                    content: '';
                    width: 100%;
                    height: 100%;
                    top: 0;
                    left: 0;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    z-index: 3;
                    opacity: 0;
                    visibility: hidden;
                    overflow: hidden;
                    @include transition(0.2s);

                    &.dark {
                        background-color: $color-dark-transparent-8;
                    }

                    &.white {
                        background-color: $color-white-transparent-8;
                    }

                    .irantheme-business-portfolio-item-hero-button-wrap {
                        position: absolute;
                        top: 50%;
                        transform: translateY(-50%);
                        // left: 10%;
                        // right: 10%;
                        min-width: 50%;
                        max-width: 80%;
                        display: flex;
                        flex-direction: column;
                        align-items: center;
                        gap: 1rem;

                        .irantheme-business-portfolio-item-hero-button {
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            text-align: center;
                            width: 100%;
                            padding: 0.45rem 1rem;
                            font-size: 0.85rem;
                            line-height: 2rem;
                            z-index: 4;
                        }
                    }
                }

                &-badge-wrap {
                    position: absolute;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    padding: 0.15rem 0.5rem;
                    background-color: $color-dark;
                    z-index: 2;

                    &.position-up-right {
                        right: 0.75rem;
                        top: 0.75rem;
                    }

                    &.position-up-left {
                        left: 0.75rem;
                        top: 0.75rem;
                    }

                    &.position-down-right {
                        right: 0.75rem;
                        bottom: 0.75rem;
                    }

                    &.position-down-left {
                        right: 0.75rem;
                        bottom: 0.75rem;
                    }

                    &.relative-badge-wrap {
                        position: relative !important;
                    }

                    span {
                        display: flex;
                        color: $color-white;
                        font-size: 0.75rem;
                        font-weight: 600;

                        &.dark {
                            color: $color-dark;
                        }

                        &.white {
                            color: $color-white;
                        }
                    }
                }
            }

            // Content
            &-content-wrap {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: flex-start;
                z-index: 1;

                &.justify-content-center {
                    height: 100%;
                }

                .irantheme-business-portfolio-item-content-heading {
                    font-size: 1rem;
                    // color: $color-white;
                    // margin-top: 1rem;
                    line-height: 1.6rem;
                    // width: 100%;


                    &::selection {
                        background-color: transparent;
                        color: inherit
                    }
                }

                .irantheme-business-portfolio-item-content-heading-wrap {
                    display: flex;
                    align-items: center;
                    flex-wrap: wrap;
                    gap: 0.5rem;
                    width: 100%;

                    &.justify-content-end {
                        flex-direction: row-reverse;
                        justify-content: flex-start !important;
                    }

                    .irantheme-business-portfolio-item-content-badge-wrap {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        z-index: 2;
                        background-color: $color-dark;
                        padding: 0 0.5rem;

                        span {
                            display: flex;
                            color: $color-white;
                            font-size: 0.6rem;
                            font-weight: 600;

                            &.dark {
                                color: $color-dark;
                            }

                            &.white {
                                color: $color-white;
                            }
                        }
                    }
                }


                .irantheme-business-portfolio-item-content-description {
                    font-size: 0.8rem;
                    // color: $color-white;
                    // margin-top: 0.75rem;
                    line-height: 1.4rem;
                    padding-top: 1rem;
                    width: 100%;

                    &::selection {
                        background-color: transparent;
                        color: inherit
                    }
                }

                .irantheme-business-portfolio-item-content-button-wrap {
                    min-width: 60%;
                    // width: 100%;
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    gap: 0.75rem;
                    margin-top: 0.75rem;

                    .irantheme-business-portfolio-item-content-button {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        text-align: center;
                        padding: 0.3rem 0.5rem;
                        font-size: 0.85rem;
                        line-height: 2rem;
                        z-index: 4;
                        width: 100%;
                        // width: fit-content;
                        // min-width: 50%;
                    }
                }
            }
        }

        .irantheme-post-gallery-carousel {
            .irantheme-business-portfolio-item {
                margin-bottom: 0 !important;
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;
        }

        // Item
        .irantheme-business-portfolio-item {

            &.white {
                .irantheme-business-portfolio-item-holder {
                    background-color: $color-gray-100;

                    &.irantheme-portfolio-item-shadow-little {
                        @extend %box-shadow-white;
                    }
                }

                .irantheme-business-portfolio-item-hero {
                    img {}
                }

                .irantheme-business-portfolio-item-content {
                    &-heading {
                        color: $color-dark;
                    }

                    &-description {
                        color: $color-gray-600;
                    }
                }
            }
        }


        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;
        }

        // Item
        .irantheme-business-portfolio-item {

            &.dark {
                .irantheme-business-portfolio-item-holder {
                    background-color: $color-gray-900;

                    &.irantheme-portfolio-item-shadow-little {
                        @extend %box-shadow-dark;
                    }
                }

                .irantheme-business-portfolio-item-hero {
                    img {}
                }

                .irantheme-business-portfolio-item-content {
                    &-heading {
                        color: $color-white;
                    }

                    &-description {
                        color: $color-gray-400;
                    }
                }
            }
        }
    }
}