.post-single-technological {
    padding: 1rem;
    background: $color-white;
    border-radius: $border-radius-low;

    /*
    =====================================
    Single post
    =====================================
    */

    #single-post {
        background: $color-white;
        padding: 3rem 0;

        // All posts, grid masonry (main)
        main.grid-masonry {

            // padding: 0 -15px;
            // Post holder
            .post-holder {
                margin-bottom: 30px;
            }
        }
    }

    // Single thumbnail
    .irantheme-single-technological-thumbnail {
        img {
            width: 100%;
        }
    }

    .irantheme-single-technological-content {
        background: $color-white;
        position: relative;
        width: calc(100% - 8rem);
        margin: -2rem auto 0;
        padding: 2rem;
        z-index: 9;
        border-radius: $border-radius-medium;

        @media only screen and (max-width:1199px) {
            width: calc(100% - 4rem);
        }

        @media only screen and (max-width:991px) {
            width: calc(100% - 2rem);
            padding: 1rem;
        }
    }

    .irantheme-single-technological-top {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        margin-bottom: 2rem;

        &>*:not(:last-child) {
            &::after {
                content: '.';
                font-size: 2rem;
                color: $color-primary;
                margin-right: 0.5rem;
                margin-left: 0.5rem;
                border-radius: 50%;
                display: inline-block;
                position: relative;
                top: -0.35rem;
            }
        }

        // Single author
        &-author {
            display: flex;
            align-items: center;

            img {
                width: 2.5rem;
                height: 2.5rem;
                border-radius: 50%;
                margin-left: 0.5rem;
            }

            &-name {
                font-size: 0.8rem;
                color: $color-gray-900;
                border-radius: $border-radius-low;
                width: fit-content;
                margin-right: auto;
                display: flex;
                align-items: center;

                a {
                    margin-right: 0.25rem;
                    color: $color-gray-900;
                }

                @media only screen and (max-width: 991px) {
                    margin-left: auto;
                    margin-right: unset;
                }
            }
        }

        // Date
        &-date {
            font-size: 0.8rem;
            color: $color-gray-900;
            display: flex;
            align-items: center;
        }

        // Category
        &-category {
            display: flex;
            align-items: center;

            a {
                color: $color-gray-900;
                font-size: 0.8rem;
                margin-left: 0.5rem;

                &:not(:first-child) {
                    margin-right: 0.5rem;
                }
            }
        }
    }

    // Heading
    .irantheme-single-technological-heading {
        margin-bottom: 1rem;

        h2 {
            font-size: 1.3rem;
            color: $color-dark;
            line-height: normal;
            margin: 0;

            a {
                color: inherit;
            }
        }
    }

    // Single like share
    .single-like-share {
        display: flex;
        height: 2rem;
        margin-top: 2rem;
        margin-bottom: 2rem;
        width: 100%;

        // Like
        .like-button {
            margin: 0;
            padding: 0 1rem;
            background: $color-gray-100;
            border: 0;
            outline: 0;
            color: $color-gray-900;
            line-height: inherit;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: $border-radius-low;
            cursor: pointer;
            transition: background 0.3s ease;

            &[data-exists="yes"] {
                background: $color-gray-100;

                i {
                    font-weight: bold;
                }

                .like-heart-no {
                    display: none !important;
                }

                .like-heart-yes {
                    display: flex !important;
                    color: $color-primary; // Add this for liked state
                }

                .text-heart-no {
                    display: none !important;
                }

                .text-heart-yes {
                    display: flex !important;
                }
            }

            .like-heart-no {
                display: flex;
            }

            .like-heart-yes {
                display: none;
            }

            .text-heart-no {
                display: flex !important;
            }

            .text-heart-yes {
                display: none !important;
            }

            &:hover {
                background: darken($color-gray-100, 5%);
            }

            i {
                margin-left: 0.5rem;
                margin-right: 0;
                transition: 0.3s;
                color: $color-gray-700;
                background: transparent;
                display: flex;
                align-items: center;
                align-self: stretch;
                font-size: 0.8rem;
            }

            span {
                font-size: 0.8rem;
                color: $color-dark;
                display: flex;

                cite {
                    font-style: normal;
                }
            }

            .like-count {
                font-style: normal;
                font-size: inherit;
                margin-right: 0.5rem;
            }
        }

        // Button share
        .single-share-button {
            margin: 0 0.5rem 0 0;
            padding: 0 1rem;
            background: $color-gray-100;
            font-size: 0.8rem;
            color: $color-gray-700;
            border-radius: $border-radius-low;
            @include transition(all, 0.4s);
            z-index: 2;

            i {
                margin-left: 0.5rem;
            }

            &:hover {
                box-shadow: inset -10rem 0 0 $color-gray-200;
            }
        }

        // List share
        .single-share-list {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            @include transition(all, 0.3s);
            @include transform(translate(5rem, 0));
            opacity: 0;
            z-index: 1;
            visibility: hidden;
            font-size: 0.8rem;

            &.active {
                padding-right: 0.25rem;
                @include transform(translate(0, 0));
                opacity: 1;
                visibility: visible;
            }

            a {
                margin: 0.25rem;
                color: $color-gray-600;

                &:hover {
                    color: $color-gray-900;
                }
            }
        }
    }


    // Single tags
    .single-tags {
        margin-bottom: 1rem;
        padding-top: 2rem;

        .single-tags-list {
            display: flex;
            flex-wrap: wrap;

            h3 {
                margin-bottom: 0.5rem;

                a {
                    font-size: 0.7rem;
                    background: $color-gray-100;
                    padding: 0.5rem;
                    color: $color-gray-600;
                    border-radius: $border-radius-low;

                    i {
                        margin-left: 0.5rem;
                    }

                    &:hover {
                        color: $color-gray-900;
                    }

                }

                &:not(:last-child) {
                    margin-left: 0.5rem;
                }
            }
        }
    }

    // Single next prev post
    .next-prev-post {
        margin-bottom: 2rem;
        display: flex;
        flex-direction: row-reverse;
        justify-content: space-between;

        a {
            display: flex;
            justify-content: center;
            align-items: center;
            color: $color-gray-600;

            i {
                color: $color-primary;
                @include transition(0.3s, all, ease-out);
            }

            &:hover {
                i {
                    color: $color-gray-700;
                }
            }

            div {
                display: flex;
                flex-direction: column;
                padding: 0 1rem;

                cite {
                    color: $color-gray-500;
                    font-size: 0.6rem;
                    font-style: normal;
                    @include transition(0.3s, all, ease-out);
                }

                b {
                    font-weight: normal;
                    font-size: 0.7rem;
                    color: $color-gray-700;
                    @include transition(0.3s, all, ease-out);
                    overflow: hidden;
                    text-overflow: ellipsis;
                    white-space: nowrap;
                    max-width: 12rem;
                }
            }

            &:hover {
                div {
                    cite {
                        color: $color-gray-700;
                    }

                    b {
                        color: $color-primary;
                    }
                }
            }

            &.disable {
                color: $color-gray-600 !important;

                b {
                    color: $color-gray-500 !important;
                }

                &:hover {
                    cursor: default;
                }
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        background: $color-white;

        /*
        =====================================
        Single post
        =====================================
        */

        #single-post {
            background: $color-white;
        }

        .irantheme-single-technological-content {
            background: $color-white;
        }

        .irantheme-single-technological-top {

            &>*:not(:last-child) {
                &::after {
                    color: $color-primary;
                }
            }

            // Single author
            &-author {

                &-name {
                    color: $color-gray-700;

                    a {
                        color: $color-gray-700;
                    }
                }
            }

            // Date
            &-date {
                color: $color-gray-700;
            }

            // Category
            &-category {

                a {
                    color: $color-gray-700;
                }
            }
        }

        // Heading
        .irantheme-single-technological-heading {

            h2 {
                color: $color-dark;
            }
        }

        // Single like share
        .single-like-share {

            // Like
            .like-button {
                background: $color-gray-100;
                color: $color-gray-900;

                &[data-exists=yes] {
                    & {
                        background: $color-gray-200;
                    }
                }

                &:hover {
                    background: $color-gray-200;
                }

                i {
                    color: $color-primary;
                }

                span {
                    color: $color-gray-700;
                }

                .like-count {
                    color: $color-gray-600;
                }
            }

            // Button share
            .single-share-button {
                background: $color-gray-100;
                color: $color-gray-700;

                &:hover {
                    box-shadow: inset -10rem 0 0 $color-gray-200;
                }
            }

            // List share
            .single-share-list {

                a {
                    color: $color-gray-600;

                    &:hover {
                        color: $color-gray-900;
                    }
                }
            }
        }

        // Single tags
        .single-tags {

            .single-tags-list {

                a {
                    background: $color-gray-100;
                    color: $color-gray-600;

                    &:hover {
                        color: $color-gray-900;
                    }
                }
            }
        }

        // Single next prev post
        .next-prev-post {

            a {
                color: $color-gray-600;

                i {
                    color: $color-primary;
                }

                &:hover {
                    i {
                        color: $color-gray-700;
                    }
                }

                div {

                    cite {
                        color: $color-gray-500;
                    }

                    b {
                        color: $color-gray-700;
                    }
                }

                &:hover {
                    div {
                        cite {
                            color: $color-gray-700;
                        }

                        b {
                            color: $color-primary;
                        }
                    }
                }

                &.disable {
                    color: $color-gray-600 !important;

                    b {
                        color: $color-gray-500 !important;
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        background: $color-dark;

        /*
        =====================================
        Single post
        =====================================
        */

        #single-post {
            background: $color-dark;
        }

        .irantheme-single-technological-content {
            background: $color-dark;
        }

        .irantheme-single-technological-top {

            &>*:not(:last-child) {
                &::after {
                    color: $color-primary;
                }
            }

            // Single author
            &-author {

                &-name {
                    color: $color-gray-100;

                    a {
                        color: $color-gray-100;
                    }
                }
            }

            // Date
            &-date {
                color: $color-gray-100;
            }

            // Category
            &-category {

                a {
                    color: $color-gray-100;
                }
            }
        }

        // Heading
        .irantheme-single-technological-heading {

            h2 {
                color: $color-white;
            }
        }

        // Single like share
        .single-like-share {

            // Like
            .like-button {
                background: $color-gray-900;
                color: $color-gray-100;

                &[data-exists=yes] {
                    & {
                        background: $color-gray-800;
                    }
                }

                &:hover {
                    background: $color-gray-800;
                }

                i {
                    color: $color-primary;
                }

                span {
                    color: $color-gray-300;
                }

                .like-count {
                    color: $color-gray-400;
                }
            }

            // Button share
            .single-share-button {
                background: $color-gray-900;
                color: $color-gray-300;

                &:hover {
                    box-shadow: inset -10rem 0 0 $color-gray-800;
                }
            }

            // List share
            .single-share-list {

                a {
                    color: $color-gray-400;

                    &:hover {
                        color: $color-gray-100;
                    }
                }
            }
        }

        // Single tags
        .single-tags {

            .single-tags-list {

                a {
                    background: $color-gray-900;
                    color: $color-gray-400;

                    &:hover {
                        color: $color-gray-100;
                    }
                }
            }
        }

        // Single next prev post
        .next-prev-post {

            a {
                color: $color-gray-400;

                i {
                    color: $color-primary;
                }

                &:hover {
                    i {
                        color: $color-gray-300;
                    }
                }

                div {

                    cite {
                        color: $color-gray-500;
                    }

                    b {
                        color: $color-gray-300;
                    }
                }

                &:hover {
                    div {
                        cite {
                            color: $color-gray-300;
                        }

                        b {
                            color: $color-primary;
                        }
                    }
                }

                &.disable {
                    color: $color-gray-400 !important;

                    b {
                        color: $color-gray-500 !important;
                    }
                }
            }
        }
    }
}