/*
=====================================
post section
=====================================
*/
.irantheme-post-simple-section {
    background: transparent;
    overflow: hidden;

    .irantheme-post-simple {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;

        .irantheme-post-simple-post-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-post-simple-post-item-holder {
                // display: flex;

                .irantheme-post-simple-item {
                    .irantheme-post-simple-animation {
                        height: 100%;
                    }

                    .irantheme-post-simple-item-inner-wrapper {
                        position: relative;
                        // background-color: $color-white;
                        height: 100%;
                        transition: 0.4s all cubic-bezier(0.785, 0.135, 0.15, 0.86);
                        overflow: hidden;

                        &.irantheme-post-simple-item-border-little {
                            // border: 1px solid $color-gray-200;
                            border-style: solid;
                            border-width: 1px;
                        }

                        &.irantheme-post-simple-without-image {
                            .irantheme-post-simple-item-category {
                                position: relative;
                            }
                        }

                        .irantheme-post-simple-item-img {
                            a {
                                display: block;

                                .irantheme-post-simple-item-img-wrapper {
                                    overflow: hidden;
                                    position: relative;

                                    img {
                                        width: 100%;
                                        height: 100%;
                                        transform: scale(1.1);
                                        @include transition(0.2s);
                                    }

                                    &::before {
                                        content: " ";
                                        width: 100%;
                                        height: 100%;
                                        position: absolute;
                                        top: 0;
                                        right: 0;
                                        background: transparent;
                                        transition: all 0.3s cubic-bezier(0.39, 0.575, 0.565, 1);
                                        z-index: 2;
                                    }

                                    .irantheme-post-simple-item-date {
                                        position: absolute;
                                        background-color: $color-dark;
                                        padding: 0.45rem 0.65rem;
                                        display: flex;
                                        flex-direction: column;
                                        justify-content: center;
                                        align-items: center;
                                        font-weight: 900;
                                        z-index: 999;
                                        line-height: normal;

                                        &.white {
                                            color: $color-white;
                                        }

                                        &.dark {
                                            color: $color-dark;
                                        }

                                        &.position {
                                            &-up-right {
                                                top: 20px;
                                                right: 20px;
                                            }

                                            &-up-left {
                                                top: 20px;
                                                left: 20px;
                                            }

                                            &-down-right {
                                                bottom: 20px;
                                                right: 20px;
                                            }

                                            &-down-left {
                                                bottom: 20px;
                                                left: 20px;
                                            }
                                        }

                                        &-day {
                                            font-size: 1.1rem;
                                        }

                                        &-month {
                                            font-size: 0.8rem;
                                        }

                                    }
                                }
                            }
                        }


                        .irantheme-post-simple-item-content {
                            display: flex;
                            flex-direction: column;
                            padding: 1rem 0;

                            @media only screen and (max-width: 575px) {
                                &.post-card-has-padding {
                                    padding: 1rem !important;
                                }
                            }

                            &.post-card-has-padding {
                                padding: unset;
                            }

                            .irantheme-post-simple-item-date.whiteout-thumbnail {
                                position: relative;
                                background-color: $color-dark;
                                padding: 0.45rem 0.65rem;
                                display: flex;
                                flex-direction: column;
                                justify-content: center;
                                align-items: center;
                                font-weight: 900;
                                line-height: normal;
                                width: fit-content;
                                margin-bottom: 0.8rem;

                                &.white {
                                    color: $color-white;
                                }

                                &.dark {
                                    color: $color-dark;
                                }

                                &-day {
                                    font-size: 1.1rem;
                                }

                                &-month {
                                    font-size: 0.8rem;
                                }

                            }

                            .irantheme-post-simple-item-content-details {
                                display: flex;
                                flex-wrap: wrap;

                                &-category {
                                    display: flex;
                                    align-items: center;
                                    font-size: 0.75rem;
                                    flex-wrap: wrap;

                                    // color: $color-gray-600;
                                    &-item {
                                        margin-left: 10px;
                                    }
                                }

                            }

                            .irantheme-post-simple-item-content-title {
                                font-size: 1rem;
                                padding: 0.8rem 0;
                                line-height: normal;
                            }

                            .irantheme-post-simple-item-content-description {
                                font-size: 0.8rem;
                                // color: $color-gray-600;
                            }

                            .irantheme-post-simple-item-content-read-more {
                                font-size: 0.8rem;
                                padding-top: 0.8rem;
                            }

                            .irantheme-post-simple-item-content-more-details {
                                display: flex;
                                align-items: center;
                                justify-content: space-between;
                                padding-top: 0.8rem;

                                &-comment {
                                    display: flex;
                                    align-items: center;
                                    font-size: 0.75rem;
                                    color: $color-gray-600;

                                    i {
                                        margin-left: 10px;
                                    }

                                    span {
                                        margin-right: 5px;
                                    }
                                }

                                &-author {
                                    display: flex;
                                    align-items: center;

                                    &-img {
                                        width: 2rem;
                                        height: auto;

                                        img {
                                            width: 100%;
                                            height: auto;
                                            object-fit: cover;
                                            border-radius: 50%;
                                        }
                                    }

                                    h4 {
                                        font-size: 0.75rem;
                                        margin-right: 0.5rem;

                                        a {
                                            // color: $color-gray-700;
                                        }
                                    }
                                }
                            }
                        }

                        &.irantheme-post-simple-item-zoom-image-hover:hover {
                            .irantheme-post-simple-item-img {
                                img {
                                    transform: rotate(2deg) scale(1.2);
                                }
                            }
                        }

                        &.irantheme-post-simple-item-mask-hover:hover {
                            .irantheme-post-simple-item-img {
                                .irantheme-post-simple-item-img-wrapper {
                                    &::before {
                                        background: $color-dark-transparent-4;
                                    }
                                }
                            }
                        }

                        &.irantheme-post-simple-item-transform-hover:hover {
                            transform: translateY(-15px);

                            &.irantheme-post-simple-item-shadow-little {
                                box-shadow: none;
                            }

                            &:not(.irantheme-post-simple-item-shadow-little) {
                                @extend %box-shadow-white;
                            }
                        }

                        &.irantheme-post-simple-item-zoom-post-hover:hover {
                            transform: scale(1.03);

                            &.irantheme-post-simple-item-shadow-little {
                                box-shadow: none;
                            }

                            &:not(.irantheme-post-simple-item-shadow-little) {
                                @extend %box-shadow-white;
                            }
                        }

                        &.irantheme-post-simple-item-shadow-hover:hover {
                            &.irantheme-post-simple-item-shadow-little {
                                box-shadow: none;
                            }

                            &:not(.irantheme-post-simple-item-shadow-little) {
                                @extend %box-shadow-white;
                            }
                        }
                    }

                }

            }
        }

        .irantheme-blog-post-carousel {
            padding-top: 1rem;
            padding-bottom: 2.5rem;
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            .irantheme-post-simple-post-wrapper {
                .irantheme-post-simple-post-item-holder {
                    .irantheme-post-simple-item {
                        .irantheme-post-simple-item-inner-wrapper {
                            &.bg-color-default {
                                background-color: $color-white;
                            }

                            &.bg-color-transparent {
                                background-color: transparent;
                            }

                            &.irantheme-post-simple-item-border-little {
                                border-color: $color-gray-200;
                            }

                            &.irantheme-post-simple-item-shadow-little {
                                @extend %box-shadow-white;
                            }

                            .irantheme-post-simple-item-content-details {
                                &-category {
                                    &-item {
                                        a {
                                            color: $color-gray-600;
                                        }
                                    }
                                }
                            }

                            .irantheme-post-simple-item-content {
                                .irantheme-post-simple-item-content-details {

                                    &-category {
                                        color: $color-gray-600;
                                    }
                                }

                                .irantheme-post-simple-item-content-title {
                                    a {
                                        color: $color-dark;

                                        &:hover {
                                            color: $color-gray-600;
                                        }
                                    }
                                }

                                .irantheme-post-simple-item-content-description {
                                    color: $color-gray-600;
                                }

                                .irantheme-post-simple-item-content-read-more {
                                    color: $color-dark;
                                }

                                .irantheme-post-simple-item-content-more-details {
                                    &-comment {
                                        color: $color-gray-600;
                                    }

                                    &-author {
                                        h4 {
                                            a {
                                                color: $color-gray-700;
                                            }
                                        }
                                    }
                                }
                            }


                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            .irantheme-post-simple-post-wrapper {
                .irantheme-post-simple-post-item-holder {
                    .irantheme-post-simple-item {
                        .irantheme-post-simple-item-inner-wrapper {
                            &.bg-color-default {
                                background-color: $color-dark;
                            }

                            &.bg-color-transparent {
                                background-color: transparent;
                            }

                            &.irantheme-post-simple-item-border-little {
                                border-color: $color-gray-800;
                            }

                            &.irantheme-post-simple-item-shadow-little {
                                @extend %box-shadow-dark;
                            }

                            .irantheme-post-simple-item-content-details {
                                &-category {
                                    &-item {
                                        a {
                                            color: $color-gray-400;
                                        }
                                    }
                                }
                            }

                            .irantheme-post-simple-item-content {
                                .irantheme-post-simple-item-content-details {

                                    &-category {
                                        color: $color-gray-400;
                                    }
                                }

                                .irantheme-post-simple-item-content-title {
                                    a {
                                        color: $color-white;

                                        &:hover {
                                            color: $color-gray-400;
                                        }
                                    }
                                }

                                .irantheme-post-simple-item-content-description {
                                    color: $color-gray-400;
                                }

                                .irantheme-post-simple-item-content-read-more {
                                    color: $color-white;
                                }

                                .irantheme-post-simple-item-content-more-details {
                                    &-comment {
                                        color: $color-gray-400;
                                    }

                                    &-author {
                                        h4 {
                                            a {
                                                color: $color-gray-300;
                                            }
                                        }
                                    }
                                }
                            }

                        }
                    }
                }
            }
        }
    }
}