.post-single-luxurious {

    /* Single ######################################## */
    #single .single-post {
        width: 100%;
        background: $color-white;
        position: relative;
        padding: 1rem;
        margin-bottom: 30px;
        border-radius: $border-radius-low;
        overflow: hidden;
    }

    .post-content {
        padding: 1rem;
    }

    #single .single-post .single-gallery .single-gallery-img img,
    #single .single-post .single-gallery .single-gallery-list img {
        width: 100%;
        height: auto;
        border-radius: $border-radius-low;
    }

    #single .single-post .single-gallery.active .single-gallery-img img,
    #single .single-post .single-gallery.active .single-gallery-list img {
        cursor: pointer;
    }

    #single .single-post .single-gallery .single-gallery-list {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
        -ms-flex-wrap: wrap;
        flex-wrap: wrap;
    }

    #single .single-post .single-gallery .single-gallery-list li {
        width: 33.33333333%;
        height: 6rem;
        margin-top: 10px;
    }

    @media screen and (max-width: 991px) {
        #single .single-post .single-gallery .single-gallery-list li {
            height: 9rem;
        }

        #single .single-post .single-content .single-heading h1 {
            padding-top: 1rem;
        }
    }

    @media screen and (max-width: 767px) {
        #single .single-post .single-gallery .single-gallery-list li {
            height: 7rem;
        }
    }

    #single .single-post .single-gallery .single-gallery-list li:not(:nth-child(3n)) {
        padding-left: 10px;
    }

    /* Single content */

    /* #single .single-post .single-content {
      padding: 1rem;
    } */

    /* Single heading */

    #single .single-post .single-content .single-heading h2 {
        font-size: 1.2rem;
        position: relative;
        margin: 1rem 0 2rem;
        line-height: 1.8rem;
        color: $color-gray-900;
    }

    #single .single-post .single-content .single-heading h2::after {
        content: '';
        width: 50px;
        height: 2px;
        background: $color-primary;
        position: absolute;
        top: 100%;
        right: 0;
        -webkit-transform: translateY(1rem);
        -ms-transform: translateY(1rem);
        transform: translateY(1rem);
    }

    #single .single-post .single-content .single-info ul {
        border-bottom: 1px solid $color-gray-200;
        padding: 1.5rem 0;
    }

    #single .single-post .single-content .single-info ul li {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
        font-size: 0.8rem;
        padding: 0.25rem 0;
    }

    #single .single-post .single-content .single-info ul li>* {
        -webkit-box-flex: 1;
        -ms-flex: 1 0 50%;
        flex: 1 0 50%;
    }

    #single .single-post .single-content .single-info ul li span a {
        margin-left: 0.5rem;
    }

    #single .single-post .single-content .single-info ul li span,
    #single .single-post .single-content .single-info ul li span a {
        color: $color-gray-600;
        font-size: 0.7rem;
    }

    /* Share */

    #single .single-post .single-content .single-info ul li .single-share {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
    }

    #single .single-post .single-content .single-info ul li .single-share a {
        margin-left: 1rem;
    }

    /* Single labels */

    #single .single-post .single-content .single-info span {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
        -ms-flex-wrap: wrap;
        flex-wrap: wrap;
    }

    #single .single-post .single-content .single-info b {
        color: $color-gray-900;
    }

    #single .single-post .single-content .single-info .single-labels span h3 {
        margin: 0 0 0.25rem 0;
    }

    #single .single-post .single-content .single-info .single-labels span a {
        background: $color-gray-200;
        padding: 0.25rem 0.5rem;
        font-size: 0.7rem;
        border-radius: $border-radius-low;
    }

    #single .single-post .single-content .single-info .single-labels span a:hover {
        background: $color-gray-300;
    }

    #single .single-post .single-content .single-info .single-labels {
        border-bottom: none !important;
    }

    /* Comments ############################## */

    #comments {
        margin-bottom: 6rem;
    }

    #comments .comments-holder {
        width: 100%;
        padding: 1rem;
        background: $color-white;
    }

    #comments .comments-holder ul {
        padding: 1rem;
        border: 1px solid $color-gray-200;
    }

    /* Comments list */

    #comments .comments-list .comment {
        padding: 1rem;
    }

    /* Comment avatar */

    #comments .comments-list .comment .comment-avatar {
        float: right;
        width: 6rem;
    }

    #comments .comments-list .comment .comment-avatar img {
        width: 6rem;
        height: 6rem;
        border-radius: 50%;
    }

    #comments .comments-list .comment .comment-content {
        margin-right: 7.5rem;
    }

    /* Comment heading */

    #comments .comments-list .comment .comment-content .comment-heading {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
        -webkit-box-pack: justify;
        -ms-flex-pack: justify;
        justify-content: space-between;
    }

    #comments .comments-list .comment .comment-content .comment-heading b {
        font-size: 0.8rem;
        color: $color-gray-800;
    }

    #comments .comments-list .comment .comment-content .comment-heading span {
        font-size: 0.7rem;
        color: $color-gray-800;
    }

    /* Comment body */

    #comments .comments-list .comment .comment-content .comment-body {
        font-size: 0.8rem;
        color: $color-gray-600;
        padding-top: 0.5rem;
    }

    /* Comment options */

    #comments .comments-list .comment .comment-content .comment-options {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-orient: horizontal;
        -webkit-box-direction: normal;
        -ms-flex-direction: row;
        flex-direction: row;
        padding-top: 1rem;
    }

    #comments .comments-list .comment .comment-content .comment-options a {
        padding: 0 0.5rem;
        font-size: 0.8rem;
        color: $color-gray-600;
        border-radius: $border-radius-little;
        border: 1px solid $color-gray-400;
        margin: 0 0 0.5rem 0.5rem;
    }

    #comments .comments-list .comment .comment-content .comment-options a:hover {
        background: $color-gray-100;
    }

    /* Single gallery overlay ................................. */

    .single-gallery-overlay {
        position: fixed;
        top: 0;
        right: 0;
        width: 100%;
        height: 100%;
        background: $color-dark-transparent-6;
        z-index: 6;
        padding: 10vh 0;
        overflow: hidden;
        display: none;
    }

    .single-gallery-overlay img {
        width: 100%;
        -o-object-fit: cover;
        object-fit: cover;
        max-height: 80vh;
    }

    .single-gallery-overlay .container div[class*='col-'] {
        overflow: hidden;
        padding: 0;
    }

    .single-gallery-overlay #close-gallery-overlay {
        position: absolute;
        padding: 1rem;
        top: 2rem;
        right: 1rem;
        font-size: 3rem;
        z-index: 7;
        color: $color-gray-200;
        cursor: pointer;
    }

    // Post box
    .post-box {
        background: $color-white;
        margin-bottom: 30px;
        border-radius: $border-radius-low;
    }

    // Holder
    .post-like {
        display: flex;
        justify-content: space-between;
        margin-left: 1rem;
        padding-top: 1rem;

        // Like
        .like-button {
            margin: 0;
            padding: 0.25rem 1rem;
            background: $color-gray-100;
            border: 0;
            outline: 0;
            color: $color-gray-900;
            line-height: inherit;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: $border-radius-low;
            cursor: pointer;
            transition: background 0.3s ease;

            &[data-exists="yes"] {
                background: $color-gray-100;

                i {
                    font-weight: bold;
                }

                .like-heart-no {
                    display: none !important;
                }

                .like-heart-yes {
                    display: flex !important;
                    color: $color-primary; // Add this for liked state
                }

                .text-heart-no {
                    display: none !important;
                }

                .text-heart-yes {
                    display: flex !important;
                }
            }

            .like-heart-no {
                display: flex;
            }

            .like-heart-yes {
                display: none;
            }

            .text-heart-no {
                display: flex !important;
            }

            .text-heart-yes {
                display: none !important;
            }

            &:hover {
                background: darken($color-gray-100, 5%);
            }

            i {
                margin-left: 0.5rem;
                margin-right: 0;
                transition: 0.3s;
                color: $color-gray-700;
                background: transparent;
                display: flex;
                align-items: center;
                align-self: stretch;
                font-size: 0.8rem;
            }

            span {
                font-size: 0.8rem;
                color: $color-dark;
                display: flex;

                cite {
                    font-style: normal;
                }
            }

            .like-count {
                font-style: normal;
                font-size: inherit;
                margin-right: 0.5rem;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {

        /* Single ######################################## */
        #single .single-post {
            background: $color-white;
        }

        #single .single-post .single-content .single-heading h1 {
            color: $color-gray-900;
        }

        #single .single-post .single-content .single-heading h1::after {
            background: $color-primary;
        }

        #single .single-post .single-content .single-info ul {
            border-bottom: 1px solid $color-gray-200;
        }

        #single .single-post .single-content .single-info b {
            color: $color-gray-900;
        }

        #single .single-post .single-content .single-info ul li span,
        #single .single-post .single-content .single-info ul li span a {
            color: $color-gray-600;
        }

        #single .single-post .single-content .single-info .single-labels span a {
            background: $color-gray-200;
        }


        #single .single-post .single-content .single-info .single-labels span a:hover {
            background: $color-gray-300;
        }

        /* Comments ############################## */
        #comments .comments-holder {
            background: $color-white;
        }

        #comments .comments-holder ul {
            border: 1px solid $color-gray-200;
        }

        #comments .comments-list .comment .comment-content .comment-options a {
            border: 1px solid $color-gray-400;
            color: $color-gray-600;
        }

        #comments .comments-list .comment .comment-content .comment-options a:hover {
            background: $color-gray-100;
        }

        /* Single gallery overlay ................................. */

        .single-gallery-overlay {
            background: $color-dark-transparent-6;
        }

        .single-gallery-overlay #close-gallery-overlay {
            color: $color-gray-200;
        }

        // Post box
        .post-box {
            background: $color-white;
        }

        // Holder
        .post-like {

            // Like
            .like-button {
                background: $color-gray-100;
                color: $color-gray-900;

                &[data-exists=yes] {
                    & {
                        background: $color-gray-100;
                    }
                }

                &:hover {
                    background: $color-gray-100;
                }

                i {
                    color: $color-gray-700;
                    background: $color-gray-100;
                }

                span {
                    color: $color-dark;
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {

        /* Single ######################################## */
        #single .single-post {
            background: $color-dark;
        }

        #single .single-post .single-content .single-heading h1::after {
            background: $color-primary;
        }

        #single .single-post .single-content .single-heading h1 {
            color: $color-gray-100;
        }

        #single .single-post .single-content .single-info ul {
            border-bottom: 1px solid $color-gray-800;
        }

        #single .single-post .single-content .single-info b {
            color: $color-gray-100;
        }

        #single .single-post .single-content .single-info ul li span,
        #single .single-post .single-content .single-info ul li span a {
            color: $color-gray-400;
        }

        #single .single-post .single-content .single-info .single-labels span a {
            background: $color-gray-800;
        }

        #single .single-post .single-content .single-info .single-labels span a:hover {
            background: $color-gray-700;
        }

        /* Comments ############################## */
        #comments .comments-holder {
            background: $color-dark;
        }

        #comments .comments-holder ul {
            border: 1px solid $color-gray-800;
        }

        #comments .comments-list .comment .comment-content .comment-options a {
            border: 1px solid $color-gray-600;
            color: $color-gray-400;
        }

        #comments .comments-list .comment .comment-content .comment-options a:hover {
            background: $color-gray-900;
        }

        /* Single gallery overlay ................................. */

        .single-gallery-overlay {
            background: $color-white-transparent-6;
        }

        .single-gallery-overlay #close-gallery-overlay {
            color: $color-gray-800;
        }

        // Post box
        .post-box {
            background: $color-dark;
        }

        // Holder
        .post-like {

            // Like
            .like-button {
                background: $color-gray-900;
                color: $color-gray-100;

                &[data-exists=yes] {
                    & {
                        background: $color-gray-900;
                    }
                }

                &:hover {
                    background: $color-gray-900;
                }

                i {
                    color: $color-gray-300;
                    background: $color-gray-900;
                }

                span {
                    color: $color-white;
                }
            }
        }
    }
}