/*
=====================================
Footer nav section
=====================================
*/
.irantheme-footer-classic-section {
    // background: $color-dark;

    .irantheme-footer-classic {
        position: relative;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;

        .irantheme-footer-classic-title {
            font-weight: bold;
            font-size: 0.9rem;
            margin-bottom: 1rem;
            display: flex;
            column-gap: 0.5rem;
            align-items: center;
        }

        &-row {
            display: flex;
            gap: 1.5rem;

            @media only screen and (max-width:991px) {
                flex-direction: column;
            }

            .irantheme-footer-classic-col {
                flex-grow: 1;

                @media only screen and (max-width:991px) {
                    flex-grow: unset;
                    width: 100%;
                }

                @media only screen and (min-width:992px) {
                    max-width: 35%;
                }
            }
        }

        // Headline
        .irantheme-footer-classic-headline {
            position: relative;
            z-index: 9;

            // Useful links
            .irantheme-footer-classic-useful-links {
                width: 100%;

                &-list {
                    display: flex;
                    flex-direction: column;
                    flex-wrap: wrap;
                    row-gap: 0.5rem;

                    &-item {
                        display: flex;

                        &-link {
                            font-size: 0.8rem;
                            // color: $color-gray-700;

                            &:hover {
                                // color: $color-gray-800;
                            }
                        }
                    }
                }
            }

            // Details
            .irantheme-footer-classic-details {
                font-size: 0.8rem;
                display: flex;
                flex-direction: column;
                row-gap: 1rem;
            }

            // Newsletter
            .irantheme-communication-newsletter-form {
                margin-bottom: 2rem;

                .irantheme-communication-newsletter-form-input-holder {
                    display: flex;
                    flex-wrap: nowrap;
                    column-gap: 0.5rem;

                    .irantheme-communication-newsletter-form-submit {
                        height: 2.5rem;
                        width: auto;
                        flex-grow: 1;
                        font-weight: bold;
                    }

                    .irantheme-communication-newsletter-form-email {
                        height: 2.5rem;
                        width: 100%;
                        flex-grow: 1;
                        margin-bottom: 0;
                        font-size: 0.8rem;
                    }
                }
            }
        }

        // Service
        &-service {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            row-gap: 1rem;

            // Logo
            &-logo {

                // Logo image holder
                .irantheme-logo-img-holder {
                    width: fit-content;

                    // Logo img
                    .irantheme-logo-img {
                        height: 100% !important;
                        width: auto;
                    }
                }

                // Logo svg holder
                .irantheme-logo-svg-holder {
                    width: fit-content;

                    svg {
                        height: 100% !important;
                        width: auto;
                    }
                }
            }

            // Service list
            &-list {
                display: flex;
                flex-wrap: wrap;
                row-gap: 1rem;
                column-gap: 2rem;

                &-item {
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    row-gap: 0.25rem;

                    &-value {
                        font-weight: bold;
                        font-size: 1rem;
                        display: flex;
                    }

                    &-title {
                        font-weight: bold;
                        font-style: normal;
                        font-size: 0.8rem;
                    }
                }
            }
        }

        // Badge
        &-badge {
            .irantheme-holder-badges {
                display: flex;
                gap: 0.25rem;
                align-items: flex-end;

                .irantheme-badge-item {
                    padding: 0.5rem;

                    img {
                        width: 75px;
                        height: 75px;
                    }
                }

                @media only screen and (max-width:991px) {
                    flex-direction: row;
                    align-items: flex-start;
                }
            }
        }

        // Platform applications
        &-app {
            display: flex;
            flex-wrap: wrap;
            gap: 1rem;
            padding-top: 2rem;

            &-holder {
                display: flex;
                flex-wrap: wrap;
                gap: 1rem;
            }

            &-link {
                display: flex;
                width: 10.08rem;
                height: 3rem;

                img {
                    width: 100%;
                    height: 100%;
                    object-fit: fill;
                }
            }
        }


        // Social media
        .irantheme-social-media {
            display: flex;
            flex-direction: row;
            justify-content: flex-start;
            text-align: center;
            flex-wrap: wrap;
            column-gap: 2rem;

            li {
                a {
                    // color: $color-white;
                    font-size: 1.2rem;
                    display: block;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 50%;

                    svg,
                    path {
                        // color: $color-white;
                        // fill: $color-white;
                        width: 1.2rem;
                        height: 1.2rem;
                        position: relative;
                        top: -2px;
                        transition: inherit;
                    }

                    &:hover {
                        // background: $color-gray-200;
                        // color: $color-dark;

                        svg,
                        path {
                            // color: $color-dark;
                            // fill: $color-dark;
                        }
                    }
                }
            }
        }

        // About
        .irantheme-footer-classic-text {
            padding: 1rem;
            margin-top: 2rem;

            p {
                font-size: 0.8rem;
                // color: $color-gray-400;
                margin-bottom: 0.5rem;
            }

            a {
                font-size: 0.7rem;
                font-weight: bold;
                // color: $color-white;

                &:hover {
                    i {
                        transform: translateX(-0.25rem);
                    }
                }

                i {
                    margin-right: 0.5rem;
                    transition: 0.3s;
                    font-size: 0.5rem;
                    font-weight: bold;
                }
            }
        }

        // Copyright
        .irantheme-footer-classic-copyright {
            // background: $color-gray-900;
            display: flex;
            flex-direction: column;
            padding: 2rem 0 1rem;
            position: relative;
            z-index: 9;

            .irantheme-footer-classic-copyright-text {
                font-size: 0.8rem;
            }
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .irantheme-footer-classic {
            background-color: $color-white;

            .irantheme-footer-classic-title {
                color: $color-gray-900;
            }

            // Headline
            .irantheme-footer-classic-headline {

                // Top
                .irantheme-footer-classic-top {
                    color: $color-dark;

                    // Return to top
                    &-return-to-top {

                        &-button {
                            background: $color-dark;
                            color: $color-white;
                        }
                    }
                }

                // Useful links
                .irantheme-footer-classic-useful-links {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-700;

                                &:hover {
                                    color: $color-gray-900;
                                }
                            }
                        }
                    }
                }

                // Details
                .irantheme-footer-classic-details {
                    color: $color-gray-700;
                }
            }

            // Social media
            .irantheme-social-media {
                li {
                    a {
                        color: $color-gray-700;

                        svg,
                        path {
                            color: $color-gray-700;
                            fill: $color-gray-700;
                        }

                        &:hover {
                            color: $color-gray-900;

                            svg,
                            path {
                                color: $color-gray-900;
                                fill: $color-gray-900;
                            }
                        }
                    }
                }
            }

            // Service list
            .irantheme-footer-classic-service-list {

                &-item {
                    &-value {
                        color: $color-gray-900;
                    }

                    &-title {
                        color: $color-gray-500;
                    }
                }
            }

            // Badge
            .irantheme-footer-classic-badge {
                .irantheme-holder-badges {

                    .irantheme-badge-item {
                        box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.1);
                    }
                }
            }

            // About
            .irantheme-footer-classic-text {
                background: $color-gray-100;

                p {
                    color: $color-gray-600;
                }

                a {
                    color: $color-dark;
                }
            }

            // Copyright
            .irantheme-footer-classic-copyright {
                // background: $color-white;

                .irantheme-footer-classic-copyright-text {
                    color: $color-gray-600;
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .irantheme-footer-classic {
            background-color: $color-dark;

            .irantheme-footer-classic-title {
                color: $color-gray-100;
            }

            // Headline
            .irantheme-footer-classic-headline {

                // Top
                .irantheme-footer-classic-top {
                    color: $color-white;

                    // Return to top
                    &-return-to-top {

                        &-button {
                            background: $color-white;
                            color: $color-dark;
                        }
                    }
                }

                // Useful links
                .irantheme-footer-classic-useful-links {
                    &-list {
                        &-item {
                            &-link {
                                color: $color-gray-300;

                                &:hover {
                                    color: $color-gray-100;
                                }
                            }
                        }
                    }
                }

                // Details
                .irantheme-footer-classic-details {
                    color: $color-gray-300;
                }
            }

            // Social media
            .irantheme-social-media {
                li {
                    a {
                        color: $color-gray-300;

                        svg,
                        path {
                            color: $color-gray-300;
                            fill: $color-gray-300;
                        }

                        &:hover {
                            color: $color-gray-100;

                            svg,
                            path {
                                color: $color-gray-100;
                                fill: $color-gray-100;
                            }
                        }
                    }
                }
            }

            // Service list
            .irantheme-footer-classic-service-list {

                &-item {
                    &-value {
                        color: $color-gray-100;
                    }

                    &-title {
                        color: $color-gray-500;
                    }
                }
            }

            // Badge
            .irantheme-footer-classic-badge {
                .irantheme-holder-badges {

                    .irantheme-badge-item {
                        box-shadow: inset 0 0 6px rgba(255, 255, 255, 0.1);
                    }
                }
            }

            // About
            .irantheme-footer-classic-text {
                background: $color-gray-900;

                p {
                    color: $color-gray-400;
                }

                a {
                    color: $color-white;
                }
            }

            // Copyright
            .irantheme-footer-classic-copyright {
                // background: $color-dark;

                .irantheme-footer-classic-copyright-text {
                    color: $color-gray-400;
                }
            }
        }
    }
}