/*
=====================================
Search box
=====================================
*/
#irantheme-search-box {
    border-bottom-width: 1px;
    border-style: solid;
    display: none;
    position: relative;
    top: 0;
    right: 0;
    padding-top: 1rem;
    padding-bottom: 1rem;
    width: 100%;
    height: 100%;
    z-index: 9999;

    // Alignment & container
    .irantheme-search-box-alignment {
        width: 100%;
        height: 100%;
        display: flex;
        align-items: center;
    }

    .irantheme-search-form {
        width: 50%;

        @media only screen and (max-width: 1600px) {
            width: 50%;
        }

        @media only screen and (max-width: 1200px) {
            width: 50%;
        }

        @media only screen and (max-width: 992px) {
            width: 60%;
        }

        @media only screen and (max-width: 768px) {
            width: 80%;
        }

        @media only screen and (max-width: 576px) {
            width: 100%;
        }

        @media only screen and (max-width: 320px) {
            width: 100%;
        }
    }
}

// Search form
.irantheme-search-form {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-orient: horizontal;
    -webkit-box-direction: normal;
    -ms-flex-direction: row;
    flex-direction: row;
    width: 100%;
    position: relative;
    border-radius: $border-radius-high;
    margin: auto;

    // Search input
    .irantheme-search-input {
        border: 0;
        box-shadow: none;
        background: transparent;
        height: 3rem;
        font-size: 0.7rem;
        padding: 0.25rem 0;
        margin: 0;
        -webkit-box-flex: 1;
        -ms-flex-positive: 1;
        flex-grow: 1;

        &::placeholder {
            font-size: 0.7rem;
        }
    }

    // Search options
    .irantheme-search-case {
        width: auto;
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-pack: center;
        -ms-flex-pack: center;
        justify-content: center;
        -webkit-box-align: center;
        -ms-flex-align: center;
        align-items: center;
        font-size: 1.1rem;
        margin-right: 1rem;
        border-radius: $border-radius-medium;
        height: 2.5rem;
        width: 2.75rem;
        background: transparent;
        @include transition(0.2s);
        margin: 0.25rem;

        &#irantheme-search-box-close {
            cursor: pointer;
        }

        // Search alt
        #irantheme-search-alt {
            @include transform(rotate(90deg));
        }

        // Spinner
        .irantheme-animate-rotate {
            width: 1.5rem;
            height: 1.5rem;
            border-radius: 50%;
            border-width: 3px;
            border-style: solid;
            // border-color: $color-gray-400 $color-gray-400 $color-gray-800 $color-gray-400;
            -webkit-transition: 0.3s;
            -o-transition: 0.3s;
            transition: 0.3s;
            display: none;
        }
    }

    // Search results
    .irantheme-search-results {
        position: absolute;
        top: 100%;
        right: 0;
        width: 100%;
        max-height: 36rem;
        padding: 1rem;
        overflow-y: auto;
        overflow-x: hidden;
        border-radius: $border-radius-high;
        z-index: 9;
        display: none;

        // Label
        &-label {
            font-size: 0.8rem;
            margin-bottom: 0.15rem;
            display: flex;
            align-items: center;
            width: 100%;
            height: fit-content;
            column-gap: 0.5rem;
        }

        // Result posts 
        .irantheme-search-result-post {
            background: transparent;
            margin-bottom: 1rem;
            border-radius: $border-radius-high;

            &>a {
                overflow: hidden;
                display: flex;
                column-gap: 0.75rem;
                padding: 0.75rem;
            }

            &-img {
                width: 5rem;
                object-fit: contain;

                img {
                    width: 100%;
                    height: 5rem;
                    border-radius: $border-radius-medium;
                    @include transition(0.2s);
                }
            }

            &:hover {
                .irantheme-search-result-post-img {
                    img {
                        opacity: 0.8;
                    }
                }
            }

            // Info
            &-info {
                display: flex;
                flex-direction: column;
                justify-content: center;
                height: auto;
                row-gap: 0.25rem;
            }

            // Options
            &-options {
                display: flex;
                flex-wrap: wrap;
                font-size: 0.7rem;
                column-gap: 1rem;
                row-gap: 0.5rem;

                span {
                    display: flex;
                    align-items: center;
                    column-gap: 0.25rem;

                    i {
                        font-size: 0.7rem;
                    }
                }
            }

            // Heading
            &-heading {
                h3 {
                    font-size: 0.8rem;
                    line-height: 1.4rem;
                    // overflow: hidden;
                    // text-overflow: ellipsis;
                    // white-space: nowrap;
                }
            }

            // Date
            &-date {
                font-size: 0.7rem;
                display: flex;
                align-items: center;
                column-gap: 0.25rem;
            }

            // Woocommerce
            &-woocommerce {
                &-options {
                    display: flex;
                    flex-wrap: wrap;

                    // Price section (Right)
                    &-price {
                        font-size: 0.7rem;
                        // color: $color-gray-800;

                        del {
                            font-size: 0.6rem;
                            // color: $color-gray-600;
                            margin-left: 0.5rem;

                            .woocommerce-Price-currencySymbol {
                                display: none;
                            }
                        }

                        ins {
                            text-decoration: none;
                        }

                        svg {
                            width: 1rem;
                            height: 1rem;

                            position: relative;
                            top: -1px;
                        }
                    }
                }
            }
        }
    }
}

/*
=====================================
Prev results
=====================================
*/
.irantheme-search-results-prev {
    display: flex;
    flex-direction: column;
}

// Categories
.irantheme-search-categories {
    overflow-y: auto;
    overflow-x: hidden;
    width: 100%;
    border-radius: $border-radius-medium;
    padding: 0.5rem;
    max-height: 7.5rem;

    &-holder {
        display: flex;
        flex-wrap: wrap;
        column-gap: 0.5rem;
        row-gap: 0.5rem;
        padding-top: 0.25rem;
    }

    .irantheme-search-category-item {
        display: inline-block;
        align-items: center;
        width: fit-content;
        column-gap: 0.35rem;
        display: flex;
        border-radius: $border-radius-medium;
        padding: 0.5rem;
        @include transition(0.3s);
        line-height: normal;
        text-align: right;
        font-size: 0.7rem;
    }
}

/*
=====================================
Posts suggestion
=====================================
*/

.irantheme-search-suggestions {
    width: 100%;
    border-radius: $border-radius-medium;
    display: flex;
    flex-direction: column;
    padding-top: 0.5rem;

    // Categories suggestions
    &-categories {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        column-gap: 0.5rem;
        row-gap: 0.5rem;

        &-item {
            display: flex;
            align-items: center;
            column-gap: 0.25rem;
            font-size: 0.7rem;
            color: $color-gray-700;
            border-radius: $border-radius-medium;
        }
    }

    // Banner image
    &-banner {
        margin-top: auto;
        padding-top: 1rem;
        display: flex;

        &-img {
            border-radius: $border-radius-medium;
            width: 100%;
            height: auto;
            @include transition(0.2s);

            &:hover {
                opacity: 0.9;
            }
        }
    }
}

/*
=====================================
Search result not found
=====================================
*/

.irantheme-search-results-not-found {
    padding: 2rem .5rem;
    text-align: center;

    i {
        font-size: 1.3rem;
        border-radius: 50%;
        padding: 0.9rem;
    }

    &-title {
        font-size: 1.1rem;
        margin-top: 1.2rem;
    }

    &-desc {
        font-size: .9rem;
        margin-top: 0.7rem;
    }
}

/*
=====================================
Header white mode
=====================================
*/
// White mode
&.irantheme-header-white,
&.irantheme-header-white-important {

    // Search box
    #irantheme-search-box {
        border-color: $color-gray-200;

        // Alignment & container
        .irantheme-search-box-alignment {}
    }

    // Search form
    .irantheme-search-form {
        background-color: $color-gray-100;

        // Search input
        .irantheme-search-input {
            color: $color-gray-600;

            &::placeholder {
                color: $color-gray-600;
            }
        }

        // Search options
        .irantheme-search-case {
            color: $color-gray-700;

            &:hover {
                color: $color-gray-800;
            }

            // Spinner
            .irantheme-animate-rotate {
                border-color: $color-gray-400 $color-gray-400 $color-gray-800 $color-gray-400;
            }
        }

        .irantheme-search-suggestions {
            // background: $color-gray-100;
        }

        .irantheme-search-results-not-found {
            &-title {
                color: $color-gray-800;
            }

            &-desc {
                color: $color-gray-600;
            }
        }

        // Search results
        .irantheme-search-results {
            @extend %box-shadow-white;
            background-color: $color-white;

            // Label
            &-label {
                color: $color-gray-700;
            }

            // Category buttons
            .irantheme-search-categories {
                background: $color-gray-100;

                .irantheme-search-category-item {
                    background: $color-white;
                    color: $color-gray-700;

                    &:hover,
                    &.active {
                        background: $color-gray-200;
                        color: $color-gray-700;
                    }
                }
            }

            // Result posts
            .irantheme-search-result-post {
                @extend %box-shadow-white;

                // Options
                &-options {
                    color: $color-gray-600;
                }

                // Heading
                &-heading {
                    h3 {
                        color: $color-gray-800;
                    }
                }

                // Date
                &-date {
                    color: $color-gray-600;
                }

                // Woocommerce
                &-woocommerce {
                    &-options {

                        // Price section (Right)
                        &-price {
                            color: $color-gray-800;

                            del {
                                color: $color-gray-600;
                            }

                            svg {
                                fill: $color-gray-900;
                            }
                        }
                    }
                }
            }
        }
    }
}

/*
=====================================
Dark mode
=====================================
*/
&.irantheme-header-dark,
&.irantheme-header-dark-important {

    // Search box
    #irantheme-search-box {
        background-color: $color-dark;
        border-color: $color-gray-800;

        // Alignment & container
        .irantheme-search-box-alignment {}
    }

    // Search form
    .irantheme-search-form {
        background-color: $color-gray-900;

        // Search input
        .irantheme-search-input {
            color: $color-gray-400;

            &::placeholder {
                color: $color-gray-400;
            }
        }

        // Search options
        .irantheme-search-case {
            color: $color-gray-300;

            &:hover {
                color: $color-gray-200;
            }

            // Spinner
            .irantheme-animate-rotate {
                border-color: $color-gray-600 $color-gray-600 $color-gray-200 $color-gray-600;
            }
        }

        .irantheme-search-suggestions {
            // background: $color-gray-900;
        }

        .irantheme-search-results-not-found {
            &-title {
                color: $color-gray-200;
            }

            &-desc {
                color: $color-gray-500;
            }
        }

        // Search results
        .irantheme-search-results {
            @extend %box-shadow-dark;
            background-color: $color-gray-900;

            // Label
            &-label {
                color: $color-gray-300;
            }

            // Category buttons
            .irantheme-search-categories {
                background: $color-gray-900;

                .irantheme-search-category-item {
                    background: $color-dark;
                    color: $color-gray-300;

                    &:hover,
                    &.active {
                        background: $color-gray-800;
                        color: $color-gray-300;
                    }
                }
            }

            // Result posts
            .irantheme-search-result-post {
                @extend %box-shadow-dark;

                // Options
                &-options {
                    color: $color-gray-400;
                }

                // Heading
                &-heading {
                    h3 {
                        color: $color-gray-200;
                    }
                }

                // Date
                &-date {
                    color: $color-gray-400;
                }

                // Woocommerce
                &-woocommerce {
                    &-options {

                        // Price
                        &-price {
                            color: $color-gray-200;

                            del {
                                color: $color-gray-400;
                            }

                            svg {
                                fill: $color-gray-100;
                            }
                        }
                    }
                }
            }
        }
    }
}