/*
=====================================
Slider (Derived from showcase)
=====================================
*/
.irantheme-woocommerce-slider-section {
    background-color: transparent;

    .irantheme-woocommerce-slider {

        .row {
            row-gap: 1rem;
        }

        .irantheme-swiper-section-woocommerce-slider {
            height: 100%;
        }

        .irantheme-swiper-section-slider-simple {
            width: 100%;
            height: inherit;
            position: relative;
            overflow: hidden;

            // Image
            &-image {
                overflow: hidden;
                height: 100%;

                &-link {
                    display: flex;
                    width: 100%;
                    height: 100%;
                }

                &-img {
                    width: 100%;
                    height: fit-content;
                    max-height: 100vh;
                    object-fit: cover;
                    object-position: center;
                    height: 100%;
                }
            }

            // Content
            &-content {
                position: absolute;
                top: 0;
                right: 0;
                left: 0;
                height: 100%;
            }

            .irantheme-tinymce-content {
                *::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .irantheme-btn-group {
                *::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .irantheme-showcase-custom-text-link {
                *::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .swiper-wrapper {
                height: inherit;
            }

            .swiper-slide {
                text-align: center;
                font-size: 18px;
                background-color: #fff;
                width: 100% !important;
                height: inherit;
                display: flex;
                overflow: hidden;

                &::selection {
                    background-color: transparent;
                    color: inherit
                }
            }

            .irantheme-showcase-simple-section {
                height: inherit;
                width: 100%;
                display: flex;

                .irantheme-showcase-simple {
                    height: inherit;
                    width: 100%;
                }
            }
        }

        .irantheme-woocommerce-slider-product {
            height: 100%;

            &-holder {
                height: 100%;

                .irantheme-woocommerce-slider-product-item {
                    padding: 2rem;
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    row-gap: 1rem;

                    // Top elements
                    &-top {
                        display: flex;
                        flex-wrap: wrap;
                        align-items: center;
                        justify-content: space-between;

                        &-title {
                            font-size: 0.8rem;
                            font-weight: bold;
                            display: flex;
                            align-items: center;
                            column-gap: 0.5rem;

                            i {
                                font-weight: bold;
                                // color: $color-white;
                            }

                            cite {
                                // color: $color-white;
                                font-style: normal;
                            }
                        }

                        // Rating
                        &-rating {
                            display: flex;
                            align-items: center;
                            flex-wrap: nowrap;

                            &.flex-right {
                                justify-content: flex-start;
                            }

                            &.flex-left {
                                justify-content: flex-end;
                            }

                            &.flex-center {
                                justify-content: center;
                            }

                            &-score {
                                font-size: 0.75rem;
                                // color: $color-white;
                            }

                            i {
                                // color: $color-quinary;
                                font-size: 0.8rem;
                            }

                            span {
                                // color: $color-white;
                                position: relative;
                                top: 1px;
                                margin-left: 0.25rem;
                                font-size: 0.7rem;
                            }
                        }

                        // Schedule
                        .irantheme-woocommerce-products-schedule {
                            width: 100%;
                            display: block;
                            padding-top: 1rem;

                            &-caption {
                                // color: $color-white;
                                font-size: 0.8rem;
                                font-weight: bold;
                            }

                            &-list {
                                gap: 0.25rem;

                                &-item {
                                    display: flex;
                                    flex-direction: column;
                                    align-items: center;
                                    justify-content: center;
                                    line-height: normal;
                                    padding: 0.25rem;
                                    border-radius: $border-radius-medium;

                                    span {
                                        font-size: 0.7rem;
                                        // color: $color-white;
                                        // background: $color-white-transparent-2;
                                    }
                                }
                            }
                        }
                    }

                    // Thumbnail
                    &-thumbnail {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        width: 100%;
                        margin-top: auto;

                        &-holder {}

                        &-img {
                            width: 11rem;
                            height: 11rem;
                            max-width: 13rem;
                            max-height: 13rem;

                            @media only screen and (max-width: 991px) {
                                width: fit-content;
                                height: fit-content;
                                max-width: 10rem;
                                max-height: 10rem;
                            }
                        }
                    }

                    &-heading {
                        font-size: 0.9rem;
                        text-align: center;
                        line-height: normal;

                        a {
                            // color: $color-white;
                        }
                    }

                    // Add to cart
                    .irantheme-woocommerce-products-item-add-to-cart {
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        margin-top: auto;

                        &-button {
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            padding: 0.75rem 1rem !important;
                            border-radius: 50%;
                            width: 3rem;
                            height: 3rem;
                            z-index: 9;
                            @include transition(0.2s);
                            @include transform(scale(0.9));
                            // background: $color-white;

                            &:hover {
                                @include transform(scale(0.95));
                            }

                            &:active {
                                @include transform(scale(1));
                            }

                            i {
                                // color: $color-dark;
                                font-size: 1.2rem;
                                margin: 0 !important;
                                font-weight: bold;
                            }

                            &-success {
                                display: none;
                            }

                            // Spinner hide
                            .irantheme-animate-rotate {
                                width: 1.1rem;
                                height: 1.1rem;
                                border-radius: 50%;
                                border-width: 2px;
                                border-style: solid;
                                transition: 0.3s;
                                transition: all 0.5s linear;
                                display: none;
                                // border-color: $color-gray-300 $color-gray-300 $color-gray-700 $color-gray-300;

                                &.active {
                                    display: flex !important;
                                }
                            }
                        }

                        // Added to cart
                        .added_to_cart {
                            font-size: 0.7rem;
                            margin-top: 0.5rem;
                            // color: $color-gray-700;
                            text-align: center !important;
                            display: none !important;
                        }
                    }

                    // Price
                    &-price {
                        font-size: 0.8rem;
                        line-height: normal;
                        font-weight: bold;
                        display: flex;
                        justify-content: flex-end;
                        align-items: center;
                        text-align: left;
                        margin-right: auto;
                        // color: $color-gray-800;

                        .irantheme-woocommerce-products-holder {
                            display: flex;
                            align-items: center;
                            column-gap: 0.25rem;
                            justify-content: flex-end;
                        }

                        .irantheme-woocommerce-products-discount {
                            padding: 0.25rem;
                            font-size: 0.6rem;
                            border-radius: $border-radius-medium;
                        }

                        del {
                            font-size: 0.7rem;
                            // color: $color-gray-600;
                            display: block;
                            font-weight: normal;

                            .woocommerce-Price-currencySymbol {
                                display: none;
                            }
                        }

                        ins {
                            text-decoration: none;
                            display: block;
                        }

                        svg {
                            width: 1.1rem;
                            height: 1.1rem;

                            position: relative;
                            top: -2px;
                        }
                    }
                }
            }

            // Next button init position
            .swiper-button-next {
                border-radius: 50%;
            }

            // Prev button init position
            .swiper-button-prev {
                border-radius: 50%;
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background: $color-white;
        }

        .irantheme-woocommerce-slider-product.white {
            background: $color-gray-100;

            .irantheme-woocommerce-slider-product-holder {

                .irantheme-woocommerce-slider-product-item {

                    // Top elements
                    &-top {

                        &-title {

                            i {
                                color: $color-dark;
                            }

                            cite {
                                color: $color-dark;
                            }
                        }

                        // Rating
                        &-rating {

                            &-score {
                                color: $color-dark;
                            }

                            i {
                                color: $color-quinary;
                            }

                            span {
                                color: $color-dark;
                            }
                        }

                        // Schedule
                        .irantheme-woocommerce-products-schedule {
                            &-caption {
                                color: $color-dark;
                            }

                            &-list {
                                &-item {
                                    background: $color-white;
                                    color: $color-gray-700;

                                    span {
                                        color: $color-gray-700;
                                    }

                                    cite {
                                        color: $color-gray-700;
                                    }
                                }
                            }
                        }
                    }

                    &-heading {

                        a {
                            color: $color-dark;
                        }
                    }

                    // Add to cart
                    .irantheme-woocommerce-products-item-add-to-cart {
                        &-button {
                            background: $color-dark;

                            i {
                                color: $color-white;
                            }

                            &-success {}

                            // Spinner hide
                            .irantheme-animate-rotate {
                                border-color: $color-gray-300 $color-gray-300 $color-gray-700 $color-gray-300;
                            }
                        }

                        // Added to cart
                        .added_to_cart {
                            color: $color-gray-300;
                        }
                    }

                    // Price
                    &-price {
                        .irantheme-woocommerce-products-discount {
                            color: $color-white;
                            background: $color-dark;

                            i {}

                            span {
                                // color: $color-white;
                            }
                        }

                        .irantheme-woocommerce-products-price {
                            color: $color-dark;

                            .irantheme-woocommerce-products-holder {
                                del {
                                    color: $color-gray-500;
                                }
                            }

                            ins {
                                color: $color-dark;
                            }

                            svg {
                                fill: $color-dark;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background: $color-dark;
        }

        .irantheme-woocommerce-slider-product.dark {
            background: $color-gray-900;

            .irantheme-woocommerce-slider-product-holder {

                .irantheme-woocommerce-slider-product-item {

                    // Top elements
                    &-top {

                        &-title {

                            i {
                                color: $color-white;
                            }

                            cite {
                                color: $color-white;
                            }
                        }

                        // Rating
                        &-rating {

                            &-score {
                                color: $color-white;
                            }

                            i {
                                color: $color-quinary;
                            }

                            span {
                                color: $color-white;
                            }
                        }

                        // Schedule
                        .irantheme-woocommerce-products-schedule {
                            &-caption {
                                color: $color-white;
                            }

                            &-list {
                                &-item {
                                    background: $color-dark;
                                    color: $color-gray-300;

                                    span {
                                        color: $color-gray-300;
                                    }

                                    cite {
                                        color: $color-gray-300;
                                    }
                                }
                            }
                        }
                    }

                    &-heading {

                        a {
                            color: $color-white;
                        }
                    }

                    // Add to cart
                    .irantheme-woocommerce-products-item-add-to-cart {
                        &-button {
                            background: $color-white;

                            i {
                                color: $color-dark;
                            }

                            &-success {}

                            // Spinner hide
                            .irantheme-animate-rotate {
                                border-color: $color-gray-700 $color-gray-700 $color-gray-300 $color-gray-700;
                            }
                        }

                        // Added to cart
                        .added_to_cart {
                            color: $color-gray-700;
                        }
                    }

                    // Price
                    &-price {
                        .irantheme-woocommerce-products-discount {
                            color: $color-dark;
                            background: $color-white;

                            i {}

                            span {
                                // color: $color-dark;
                            }
                        }

                        .irantheme-woocommerce-products-price {
                            color: $color-white;

                            .irantheme-woocommerce-products-holder {
                                del {
                                    color: $color-gray-500;
                                }
                            }

                            ins {
                                color: $color-white;
                            }

                            svg {
                                fill: $color-white;
                            }
                        }
                    }
                }
            }

        }
    }
}