/*
=====================================
Comments list
=====================================
*/

.irantheme-comments {
    .comment-reply-title {
        display: none;
    }

    .text-description {
        font-size: 0.8rem;
        color: $color-gray-700;
        margin: 0.5rem 0;
        // display: none;
    }

    .logged-in-as {
        display: none;
    }

    .comments-list {
        padding: 2rem;

        & li.comment:last-child {
            border-bottom: none;
            margin-bottom: 0;
            padding-bottom: 0;
        }

        .comment {
            border-bottom: 1px solid $color-gray-200;
            margin-bottom: 15px;
            padding-bottom: 1rem;

            .comment-avatar {
                width: 2.5rem;
                float: right;

                img {
                    width: 100%;
                    height: 2.5rem;
                    border-radius: 50%;
                }
            }

            .comment-content {
                margin-right: 3.5rem;
                position: relative;

                .comment-heading {
                    padding-top: 0.5rem;

                    b {
                        font-size: 0.8rem;
                        color: $color-dark;
                        font-weight: normal;
                    }
                }

                .comment-options {
                    // border-bottom: 1px solid $color-gray-100;
                    // padding-bottom: 0.5rem;
                    // margin-bottom: 0.5rem;

                    .date {
                        font-size: 0.6rem;
                        color: $color-gray-500;
                    }
                }

                .comment-reply {
                    display: flex;
                    justify-content: flex-end;
                    font-size: 0.6rem;
                    padding-top: 1rem;

                    a {
                        color: $color-gray-600;
                        margin-right: 0.5rem;
                        background: $color-gray-100;
                        padding: 0 0.5rem;

                        &:hover {
                            color: $color-gray-900;
                        }
                    }
                }

                .comment-body {
                    padding-top: 0.25rem;

                    p {
                        font-size: 0.7rem;
                        color: $color-gray-700;
                        margin-bottom: 0.25rem;
                    }
                }
            }
        }

        &>.children {
            padding-right: 3.5rem;
        }
    }

    /*
    =====================================
    White
    =====================================
    */
    &.white {
        .irantheme-input-form-fields label {
            color: $color-gray-800;
        }

        .irantheme-input-form-fields textarea,
        .irantheme-input-form-fields input {
            border: 1px solid $color-gray-300;
            color: $color-gray-800;
        }

        // .irantheme-input-form-fields input[type="submit"] {
        //     color: $color-gray-200;
        // }

        .text-description {
            color: $color-gray-700;
        }

        .comments-list {

            .comment {
                border-bottom: 1px solid $color-gray-200;

                .comment-content {

                    .comment-heading {

                        b {
                            color: $color-dark;
                        }
                    }

                    .comment-options {

                        .date {
                            color: $color-gray-500;
                        }
                    }

                    .comment-reply {

                        a {
                            color: $color-gray-600;
                            background: $color-gray-100;

                            &:hover {
                                color: $color-gray-900;
                            }
                        }
                    }

                    .comment-body {

                        p {
                            color: $color-gray-700;
                        }
                    }
                }
            }
        }
    }

    /*
    =====================================
    Dark
    =====================================
    */
    &.dark {
        .irantheme-input-form-fields label {
            color: $color-gray-200;
        }

        .irantheme-input-form-fields textarea,
        .irantheme-input-form-fields input {
            border: 1px solid $color-gray-700;
            color: $color-gray-200;
        }

        // .irantheme-input-form-fields input[type="submit"] {
        //     color: $color-gray-800;
        // }

        .text-description {
            color: $color-gray-300;
        }

        .comments-list {

            .comment {
                border-bottom: 1px solid $color-gray-800;

                .comment-content {

                    .comment-heading {

                        b {
                            color: $color-white;
                        }
                    }

                    .comment-options {

                        .date {
                            color: $color-gray-500;
                        }
                    }

                    .comment-reply {

                        a {
                            color: $color-gray-400;
                            background: $color-gray-900;

                            &:hover {
                                color: $color-gray-100;
                            }
                        }
                    }

                    .comment-body {

                        p {
                            color: $color-gray-300;
                        }
                    }
                }
            }
        }
    }
}