/*
=====================================
Communication Contact Section
=====================================
*/
.irantheme-communication-contact-section {
    .irantheme-communication-contact {
        // background-color: $color-white;
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        overflow: hidden;
        z-index: 9;

        &>.irantheme-container-inner>.row>.irantheme-tinymce-content {
            @media only screen and (max-width: 991px) {
                padding-left: 2rem;
                padding-right: 2rem;
            }
        }

        .row {
            row-gap: 2rem;
        }

        .irantheme-object-group {
            display: flex;
            flex-direction: column;
            row-gap: 2rem;
        }

        // All columns
        div[class*="col-"] {
            position: relative;

            .irantheme-tinymce-holder {
                height: 100%;
                display: flex;
                flex-direction: column;
                justify-content: center;
            }
        }

        // Column padding
        .irantheme-holder-padding {
            &.padding-right {
                padding-right: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-right: 0.75rem;
                }
            }

            &.padding-left {
                padding-left: 4rem;

                @media only screen and (max-width: 992px) {
                    padding-left: 0.75rem;
                }
            }

            @media only screen and (max-width: 992px) {
                padding-right: 0.75rem;
                padding-left: 0.75rem;
            }
        }

        .irantheme-service-heading-col {
            height: 100%;


            .irantheme-tinymce-holder {
                padding: 0 2rem;
            }
        }

        // Service holder
        .irantheme-communication-contact-service-holder {
            padding: 3rem;
            height: 100%;
            display: flex;
            align-items: center;
        }

        // Contact wrapper
        .irantheme-communication-contact-wrapper {
            position: relative;
            z-index: 2;
        }

        // Item
        .irantheme-service-item {
            position: relative;
            // overflow: hidden;
            display: flex;
            height: 100%;
            z-index: 1;

            // Wrapper
            .irantheme-service-item-wrapper {
                position: relative;
                border-radius: $border-radius-low;
                background-repeat: no-repeat;
                background-position: center;
                background-size: cover;
                display: flex;
                align-items: flex-start;
                // align-items: center;
                width: 100%;
                height: 100%;

                .irantheme-service-item-wrapper-content {
                    width: 100%;

                    // Icon side
                    &.irantheme-service-item-icon-side {
                        display: flex;
                        column-gap: 1rem;

                        .irantheme-service-item-icon {
                            margin-bottom: auto;
                        }
                    }
                }

                // Double icon
                .irantheme-service-item-double-icon {
                    position: absolute;
                    top: 0;
                    right: 0;
                    font-size: 14rem;
                    // color: $color-gray-200;
                    @include transform(translateY(-2rem) translateX(2rem));
                    z-index: 8;
                }
            }

            // Icon
            &-icon {
                margin-bottom: 2rem;
                position: relative;
                z-index: 9;

                &.icon-box-style {
                    display: inline-flex;
                    justify-content: center;
                    align-items: center;
                    aspect-ratio: 1 /1;

                    &.border-style {
                        background-color: transparent;
                        border-width: 1px;
                        border-style: solid;
                    }
                }

                i {
                    @include transition(0.2s, all, ease-in);
                    font-size: 1.8rem;
                    // color: $color-gray-600;
                }
            }

            // Content
            &-content {
                position: relative;
                display: flex;
                flex-direction: column;
                justify-content: center;
                z-index: 9;

                // Horizontal mode
                &-horizontal {
                    flex-direction: row;
                    align-items: flex-start;
                    justify-content: center;
                    display: flex;

                    .irantheme-service-item-content-desc-horizontal {
                        margin-right: 1rem;
                        margin-left: 1rem;
                    }

                    // Separator
                    .irantheme-service-item-content-separator {
                        width: 2px;
                        height: 2rem;
                        margin-right: 1rem;
                    }
                }

                // Title
                h3 {
                    font-size: 1rem;
                    // color: $color-dark;
                    margin-bottom: 0.25rem;
                    font-weight: bold;
                    line-height: normal;

                    &.irantheme-service-item-content-title-number {
                        font-size: 2.4rem;
                        font-weight: bold;
                    }
                }

                // Description
                p {
                    font-size: 0.8rem;
                    // color: $color-gray-700;

                    &.irantheme-service-item-content-desc-number {
                        font-size: 1rem;
                        line-height: 1.8rem;
                        margin-top: 1rem;
                    }

                    &.irantheme-service-item-content-desc-number-small {
                        font-size: 0.8rem;
                        line-height: 1.4rem;
                    }
                }

                // Button
                &-button {
                    margin-top: 0.5rem;

                    &.irantheme-btn-group {
                        margin-top: 1.5rem;

                        a {
                            &::after {
                                content: none !important;
                            }
                        }
                    }

                    a {
                        font-size: 0.8rem;
                        border-width: 0 0 2px 0;
                        border-style: solid;

                        // border-color: $color-gray-500;
                        // color: $color-gray-600;
                        &:not(.irantheme-btn) {
                            padding: 0.25rem 0;
                        }

                        position: relative;

                        &::after {
                            content: '';
                            position: absolute;
                            top: 100%;
                            right: 0;
                            width: 0;
                            height: 1px;
                            @include transition(0.2s, all, cubic-bezier(.59, .32, .48, 1.01));
                        }

                        &:hover {
                            &::after {
                                width: 100%;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;

            .irantheme-communication-contact-box-shadow {
                box-shadow: 0px 7px 25px 1px rgba(0, 0, 0, 0.08);
            }

            // Box style
            .irantheme-communication-contact-box-style {
                background: $color-gray-100;
            }

            // Border
            .irantheme-communication-contact-border {
                border-color: $color-gray-200;
            }

            // Item
            .irantheme-service-item {

                .irantheme-service-item-wrapper {
                    &.white {
                        background-color: $color-white;
                    }

                    &.irantheme-service-item-box-style {
                        background-color: $color-gray-100;
                    }
                }

                // Icon
                &-icon {

                    &.icon-box-style {
                        &.color-box-style {
                            background-color: $color-gray-100;
                        }

                        &.border-style {
                            border-color: $color-gray-200;
                        }
                    }

                    i {
                        color: $color-gray-600;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-800;
                    }

                    // Description
                    p {
                        color: $color-gray-700;
                    }

                    // Separator service number
                    &-separator {
                        background: $color-gray-800;
                    }

                    // Button
                    &-button {
                        a {
                            &:not(.irantheme-btn) {
                                color: $color-gray-700;
                            }

                            border-color: transparent;

                            &::after {
                                background-color: $color-gray-600;
                            }
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;

            .irantheme-communication-contact-box-shadow {
                box-shadow: 0px 7px 25px 1px rgba(233, 233, 233, 0.08);
            }

            // Box style
            .irantheme-communication-contact-box-style {
                background: $color-gray-900;
            }

            // Border
            .irantheme-communication-contact-border {
                border-color: $color-gray-800;
            }

            // Item
            .irantheme-service-item {

                .irantheme-service-item-wrapper {
                    &.dark {
                        background-color: $color-dark;
                    }

                    &.irantheme-service-item-box-style {
                        background-color: $color-gray-900;
                    }
                }

                // Icon
                &-icon {
                    &.icon-box-style {
                        &.color-box-style {
                            background-color: $color-gray-900;
                        }

                        &.border-style {
                            border-color: $color-gray-800;
                        }
                    }

                    i {
                        color: $color-gray-400;
                    }
                }

                // Content
                &-content {

                    // Title
                    h3 {
                        color: $color-gray-200;
                    }

                    // Description
                    p {
                        color: $color-gray-300;
                    }

                    // Separator service number
                    &-separator {
                        background: $color-gray-200;
                    }

                    // Button
                    &-button {
                        a {
                            &:not(.irantheme-btn) {
                                color: $color-gray-300;
                            }

                            border-color: transparent;

                            &::after {
                                background-color: $color-gray-200;
                            }
                        }
                    }
                }
            }
        }
    }
}