/*
=====================================
Footer technological
=====================================
*/

#footer-technological {
    background: $color-dark;

    // Headline
    .headline {
        padding: 3rem 0;

        // Heading
        .footer-heading {
            font-size: 0.9rem;
            color: $color-white;
            font-weight: bold;
            margin-bottom: 2rem;
        }

        // About
        .footer-about {
            padding-top: 1rem;

            p {
                font-size: 0.8rem;
                color: $color-gray-400;
                margin-bottom: 0.5rem;
            }

            a {
                font-size: 0.7rem;
                font-weight: bold;
                color: $color-white;

                &:hover {
                    i {
                        transform: translateX(-0.25rem);
                    }
                }

                i {
                    margin-right: 0.5rem;
                    transition: 0.3s;
                    font-size: 0.5rem;
                    font-weight: bold;
                }
            }
        }

        // Latest comments
        .footer-latest-comments {
            ul {
                display: flex;
                flex-direction: column;

                li {
                    font-size: 0.8rem;
                    color: $color-gray-500;
                    padding: 1rem 0;

                    &:hover {
                        i {
                            @extend %animation-left-to-right;
                        }
                    }

                    i {
                        color: $color-primary;
                        font-size: 0.5rem;
                    }

                    span {
                        color: $color-white;
                        margin-right: 0.5rem;
                        margin-left: 0.25rem;
                        font-weight: bold;
                    }

                    a {
                        margin-right: 0.25rem;
                        color: $color-primary;
                    }
                }
            }
        }

        // List tag
        .list-tags {
            display: flex;
            flex-direction: row;
            flex-wrap: wrap;
            padding-top: 1rem;

            a {
                font-size: 0.7rem;
                background: $color-darker;
                color: $color-white;
                padding: 0.25rem 0.5rem;
                margin: 0.125rem;
            }
        }
    }

    // Copyright
    .copyright-technological {
        background: $color-gray-900;
        display: flex;
        flex-direction: column;
        justify-content: center;
        text-align: center;
        padding: 2rem 0;

        // Social media
        .irantheme-social-media {
            display: flex;
            flex-direction: row;
            justify-content: center;
            text-align: center;
            margin-bottom: 0.5rem;

            li {
                a {
                    color: $color-white;
                    font-size: 0.75rem;
                    margin: 0.25rem;
                    width: 2rem;
                    height: 2rem;
                    display: block;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    border-radius: 50%;

                    svg,
                    path {
                        color: $color-white;
                        fill: $color-white;
                        width: 0.75rem;
                        height: 0.75rem;
                        position: relative;
                        top: -2px;
                        transition: inherit;
                    }

                    &:hover {
                        background: $color-gray-200;
                        color: $color-dark;

                        svg,
                        path {
                            color: $color-dark;
                            fill: $color-dark;
                        }
                    }
                }
            }
        }

        p {
            color: $color-gray-500;
            font-size: 0.7rem;
            margin-bottom: 1rem;
        }
    }
}