/*
=====================================
Business Plane Service
=====================================
*/
.irantheme-business-plane-service-section {
    .irantheme-business-plane-service {
        background-repeat: no-repeat;
        background-position: center;
        background-size: cover;
        position: relative;
        // background: $color-gray-100;

        // All columns
        div[class*="col"] {
            position: relative;
        }

        .irantheme-object-group {
            row-gap: 1.5rem;
        }

        // Plane service
        .irantheme-business-plane-service-post-wrapper {
            position: relative;
            z-index: 2;

            .irantheme-business-plane-service-post-item {
                background: transparent;
                padding: 4rem 2rem;
                border-radius: $border-radius-low;
                overflow: hidden;
                position: relative;

                // Modes
                &-mode-vip,
                &-mode-special {
                    position: absolute;
                    top: 0;
                    left: 0;
                    z-index: 99;
                    display: flex;
                    justify-content: center;
                    align-items: center;
                    text-align: center;
                    flex-wrap: wrap;
                    font-size: 0.8rem;
                    padding: 0.25rem 7rem;
                    width: 20rem;
                    @include transform(rotate(-45deg) translate(-6rem, -4rem));
                    cursor: default;

                    i {
                        color: $color-dark;
                        margin-left: 0.5rem;
                    }

                    cite {
                        color: $color-dark;
                        font-style: normal;
                    }
                }

                // Box style
                &.irantheme-business-plane-service-post-item-box-style {
                    background: $color-white;
                }

                // Box shadow
                &.irantheme-business-plane-service-post-item-box-shadow {
                    @include box-shadow(0 15px 25px -7px rgba(0, 0, 0, 0.09),
                        0 -12px 10px -10px rgba(0, 0, 0, 0.04));
                    @include transition(0.4s);

                    &:hover {
                        @include box-shadow(none);
                    }
                }

                // Box style
                &.irantheme-business-plane-service-post-item-border {
                    border-width: 2px;
                    border-style: solid;
                }

                // Title
                &-title {
                    font-size: 1.4rem;
                    margin-bottom: 1rem;
                    color: $color-gray-900;
                }

                // Description
                &-desc {
                    font-size: 0.8rem;
                    color: $color-gray-600;
                    margin-bottom: 2rem;
                }

                // Price
                &-price {
                    font-size: 2rem;
                    line-height: 3rem;
                    color: $color-gray-700;
                    display: flex;
                    flex-direction: column;
                    flex-wrap: wrap;
                    justify-content: center;

                    &-main {
                        color: $color-gray-700;
                        width: auto;
                    }

                    &-discount {
                        color: $color-gray-500;
                        font-size: 1.2rem;
                        position: relative;
                        width: auto;

                        &::after {
                            content: '';
                            width: 100%;
                            height: 2px;
                            background: $color-gray-600;
                            @include transform(rotate(-10deg));
                            position: absolute;
                            top: 50%;
                            right: 0;
                        }
                    }
                }

                // Features list
                &-features-list {
                    font-size: 0.9rem;
                    color: $color-gray-700;

                    .irantheme-tinymce-content {
                        font-size: 0.9rem;
                    }
                }

                // Button
                &-button {}
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-gray-100;

            // Plane service
            .irantheme-business-plane-service-post-wrapper {
                .irantheme-business-plane-service-post-item {

                    // Box style
                    &.irantheme-business-plane-service-post-item-box-style {
                        background: $color-white;
                    }

                    // Box shadow
                    &.irantheme-business-plane-service-post-item-box-shadow {
                        @include box-shadow(0 15px 25px -7px rgba(0, 0, 0, 0.09),
                            0 -12px 10px -10px rgba(0, 0, 0, 0.04));
                        @include transition(0.4s);

                        &:hover {
                            @include box-shadow(none);
                        }
                    }

                    // Box style
                    &.irantheme-business-plane-service-post-item-border {
                        border-color: $color-gray-200;
                    }

                    // Title
                    &-title {
                        color: $color-gray-900;
                    }

                    // Price
                    &-price {
                        color: $color-gray-700;

                        &-discount {
                            color: $color-gray-500;

                            &::after {
                                background: $color-gray-600;
                            }
                        }

                        &-main {
                            color: $color-gray-700;
                        }
                    }

                    // Description
                    &-desc {
                        color: $color-gray-600;
                    }

                    // Features list
                    &-features-list {
                        color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-gray-900;

            // Plane service
            .irantheme-business-plane-service-post-wrapper {
                .irantheme-business-plane-service-post-item {

                    // Box style
                    &.irantheme-business-plane-service-post-item-box-style {
                        background: $color-dark;
                    }

                    // Box shadow
                    &.irantheme-business-plane-service-post-item-box-shadow {
                        @include box-shadow(0 15px 25px -7px rgba(233, 233, 233, 0.09),
                            0 -12px 10px -10px rgba(233, 233, 233, 0.04));
                        @include transition(0.4s);

                        &:hover {
                            @include box-shadow(none);
                        }
                    }

                    // Box style
                    &.irantheme-business-plane-service-post-item-border {
                        border-color: $color-gray-800;
                    }

                    // Title
                    &-title {
                        color: $color-gray-100;
                    }

                    // Price
                    &-price {
                        color: $color-gray-300;

                        &-main {
                            color: $color-gray-300;
                        }

                        &-discount {
                            color: $color-gray-500;

                            &::after {
                                background: $color-gray-400;
                            }
                        }
                    }

                    // Description
                    &-desc {
                        color: $color-gray-400;
                    }

                    // Features list
                    &-features-list {
                        color: $color-gray-300;
                    }
                }
            }
        }
    }
}