*,
*::before,
*::after {
	-webkit-box-sizing: border-box;
	box-sizing: border-box;
}

html {
	font-size: 13pt;
	overflow-x: hidden;

	/* Disable smooth scrolling */
	scroll-behavior: auto !important;

	@media only screen and (max-width: 1199px) {
		& {
			font-size: 11pt;
		}
	}
}

#wpadminbar {
	z-index: 999999999;
}

.rtl #wpadminbar * {
	font-family: $font-family-pack;
}

ul,
ol {
	margin: 0;
	padding: 0;
}

a {
	color: $color-dark;
	-webkit-transition: all 0.2s ease-in-out;
	-o-transition: all 0.2s ease-in-out;
	transition: all 0.2s ease-in-out;
	text-decoration: none;

	&:hover {
		text-decoration: none;
		color: $color-gray-700;
	}
}

h1 {
	font-size: 1.8rem;
}

h2 {
	font-size: 1.6rem;
}

h3 {
	font-size: 1.4rem;
}

body {
	background-color: $color-white;
	color: $color-dark;
	// font-family: $font-family-pack;
	font-size: 1rem;
	direction: rtl;
	text-align: right;
	overflow-x: hidden;
	line-height: 1.6rem;
}

.tooltip {
	// font-family: $font-family-pack;
}

hr {
	margin: 1rem 0;
	color: inherit;
	border: 0;
	border-top: 1px $color-gray-500 solid;
	opacity: 0.25;
}

