#wp-admin-bar-irantheme-storeplus-page-builder-icon .ab-icon::before {
	content: '\f5fd';
	font-family: $font-family-icons;
}

#wp-admin-bar-irantheme-storeplus-page-builder-icon-mobile .ab-icon::before {
	content: '\f5fd';
	font-family: $font-family-icons;
}

#wp-admin-bar-irantheme-storeplus-settings-icon .ab-icon::before {
	content: '\f1de';
	font-family: $font-family-icons;
}

.irantheme-section,
.irantheme-object {
	position: relative;
}

// Tinymce slider text
.irantheme-tinymce-slider-text::after {
	content: '|';
	font-size: inherit;
	background: $color-white;
	display: inline-block;
	margin: 0.25rem;
	position: relative;
	width: 0;
	height: auto;
	@extend %animation-fade;
}

// Alignments
.irantheme-text-center {
	text-align: center !important;
}

.irantheme-text-right {
	text-align: right !important;
}

.irantheme-text-left {
	text-align: left !important;
}

// Empty thumbnail
.irantheme-empty-thumbnail {
	width: 100%;
	height: 100%;
	min-height: 20rem;
	padding: 3rem;
	text-align: center;
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	align-self: stretch;
	background: transparent;

	// Icon
	&-icon {
		font-size: 5rem;
		margin-bottom: 1rem;
		color: $color-gray-500;
	}

	&-heading {
		font-size: 0.9rem;
		margin-bottom: 0.5rem;
	}

	// Description
	&-description {
		font-size: 0.8rem;
	}

	// White mode
	&.white {
		.irantheme-empty-thumbnail-heading {
			color: $color-gray-700;
		}

		.irantheme-empty-thumbnail-description {
			color: $color-gray-600;
		}
	}

	// Dark mode
	&.dark {
		.irantheme-empty-thumbnail-heading {
			color: $color-gray-300;
		}

		.irantheme-empty-thumbnail-description {
			color: $color-gray-400;
		}
	}

}

.irantheme-tinymce-holder {
	// padding: 3rem 0;
	position: relative;
	z-index: 2;

	.irantheme-tinymce-style {
		padding: 0.5rem 0;
		display: block;
		width: 100%;

		&-underline {
			width: 3rem;
			height: 5px;
			border-radius: $border-radius-high;
			display: inline-block;
		}

		&-hashur {
			display: inline-block;
			width: 7rem;
			height: 1rem;
			background-color: transparent;
			opacity: 0.8;
		}
	}

	.irantheme-tinymce-style-dotted {
		display: grid;
		grid-template-columns: repeat(3, minmax(0, auto));
		grid-template-rows: repeat(6, auto);
		gap: 0.5rem;
		max-width: 4rem;
		height: fit-content;
		line-height: 0.5rem;
		margin: auto 0;
		cursor: default;

		&-dot {
			border-radius: 50%;
			color: $color-gray-500;
			font-size: 1.5rem;
		}
	}

	.irantheme-tinymce-style-parallel {
		display: flex;
		align-items: center;
		gap: 0.25rem;
		cursor: default;

		&-line {
			width: 0.5rem;
			height: 1.5rem;
			border-radius: $border-radius-low;

			&:first-child {
				height: 1rem;
			}

			&:last-child {
				height: 1.5rem;
			}
		}
	}

	.irantheme-tinymce-style-icon {
		display: flex;
		cursor: default;

		i {
			width: 3rem;
			height: 3rem;
			display: flex;
			align-items: center;
			justify-content: center;
			font-size: 1.6rem;
			border-radius: $border-radius-high;
			color: $color-gray-700;
			background: $color-gray-100;
		}
	}
}

// Tinymce heading
.irantheme-tinymce-content {
	position: relative;
	margin: 0;
	line-height: normal;
	font-size: 14pt;
	// color: $color-gray-700;
	color: $color-gray-300;
	font-weight: normal;

	&>*:not(.irantheme-typed-strings, .irantheme-tinymce-bg-radius, b) {
		display: block;
	}

	&>* {
		margin-top: 0.5rem;
		margin-bottom: 0.5rem;
	}

	p {
		margin-bottom: 1rem;
		font-size: 1em;
		color: $color-gray-300;
		font-weight: normal;
	}

	span,
	del,
	em {
		font-weight: normal;
	}

	h1,
	h2,
	h3,
	h4,
	h5,
	h6 {
		color: $color-gray-200;
		margin: 1rem 0;
		line-height: normal;
		font-weight: normal;
	}

	h1 {
		font-size: 2em;
	}

	h2 {
		font-size: 1.8em;
	}

	h3 {
		font-size: 1.6em;
	}

	h4 {
		font-size: 1.4em;
	}

	h5 {
		font-size: 1.2em;
	}

	h6 {
		font-size: 1em;
	}

	strong {
		font-weight: bold;

		span {
			font-weight: bold;
		}
	}

	em {
		font-style: italic;
	}

	blockquote {
		display: inline-block;
		border-right-width: 5px;
		border-right-style: solid;
		padding: 0.5rem 1rem;
		font-size: 1.2em;
		color: $color-white;
	}

	hr {
		border-color: $color-gray-500;
	}

	.irantheme-tinymce-bg-radius {
		padding: 0.25rem 0.5rem;
		border-radius: $border-radius-medium;
	}

	ul {
		padding: 1rem 0;

		li {
			padding: 0.25rem 0;

			&::before {
				content: "\f00c";
				font-family: $font-family-icons;
				font-size: inherit;
				font-weight: bold;
				padding-left: 1rem;
				color: $color-white;
				padding: 0.25rem 0.35rem;
				border-radius: 50%;
				background: $color-gray-800;
				margin-left: 1rem;
			}
		}
	}

	ol {
		padding: 1rem 0;

		li {
			padding: 0.25rem 0;

			&::before {
				content: "\f00c";
				font-family: $font-family-icons;
				font-size: inherit;
				font-weight: bold;
				padding-left: 1rem;
				padding: calc(0.25rem - 1px) calc(0.35rem - 1px);
				border-radius: 50%;
				border-width: 1px;
				border-style: solid;
				color: $color-gray-800;
				border-color: $color-gray-800;
				margin-left: 1rem;
			}
		}
	}

	.irantheme-tinymce-content-button {
		padding-top: 1rem;

		a {
			font-size: 0.8em;
			padding: 0.75rem 1.5rem;
			border-radius: $border-radius-low;
			background: transparent;
			border-width: 1px;
			border-style: solid;
			display: inline-block;
			// border-color: $color-dark;
			// color: $color-dark;
		}
	}

	// Tinymce heading white
	&.white {
		color: $color-gray-600;

		h1,
		h2,
		h3,
		h4,
		h5,
		h6,
		h1 span,
		h2 span,
		h3 span,
		h4 span,
		h5 span,
		h6 span {
			color: $color-gray-900;
		}

		p,
		span,
		a {
			color: $color-gray-600;
		}

		.irantheme-tinymce-content-button {
			a {
				border-color: $color-gray-800;
				color: $color-dark;

				&:hover {
					background: $color-gray-800;
					color: $color-white;
				}
			}
		}

		.typed-cursor {
			color: $color-gray-800;
		}

		ul {

			li {

				&::before {
					color: $color-white;
					background: $color-gray-800;
				}
			}
		}

		ol {

			li {

				&::before {
					color: $color-gray-800;
					border-color: $color-gray-800;
				}
			}
		}
	}

	// Tinymce heading dark
	&.dark {
		color: $color-gray-400;

		h1,
		h2,
		h3,
		h4,
		h5,
		h6,
		h1 span,
		h2 span,
		h3 span,
		h4 span,
		h5 span,
		h6 span {
			color: $color-gray-100;
		}

		p,
		span,
		a {
			color: $color-gray-400;
		}

		.irantheme-tinymce-content-button {
			a {
				border-color: $color-gray-200;
				color: $color-white;

				&:hover {
					background: $color-gray-200;
					color: $color-dark;
				}
			}
		}
	}

	.typed-cursor {
		color: $color-gray-200;
	}

	ul {

		li {

			&::before {
				color: $color-dark;
				background: $color-gray-200;
			}
		}
	}

	ol {

		li {

			&::before {
				color: $color-gray-200;
				border-color: $color-gray-200;
			}
		}
	}

	@media only screen and (max-width:1199px) {
		font-size: 13pt;
	}

	@media only screen and (max-width:991px) {
		font-size: 12pt;
	}

	@media only screen and (max-width:767px) {
		font-size: 11pt;
	}

	@media only screen and (max-width:575px) {
		font-size: 11pt;
	}

	@media only screen and (max-width:399px) {
		font-size: 11pt;
	}
}

.irantheme-swiper-button-slider {
	position: absolute;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 0;
	z-index: 10;
	@include transform(translateX(50%));
	line-height: normal;
	width: fit-content;
	opacity: 0.8;
	@include transition(0.4s, all, cubic-bezier(0.25, 0.46, 0.45, 0.94));

	&:hover {
		opacity: 1;
	}

	.swiper-button-next,
	.swiper-button-prev {
		@include transform(none !important);
		position: static !important;
		margin: 0.375em !important;
		box-shadow: none !important;
		width: 2em !important;
		height: 2em !important;
		font-size: 0.8em;
		flex-basis: 2em;
		flex-shrink: 0;
		display: flex;
		align-items: center;
		justify-content: center;
		border-radius: 50% !important;

		svg {
			display: none !important;
		}
	}

	.swiper-pagination {
		position: static !important;
		display: flex;
		align-items: center;
		justify-content: center;

		.swiper-pagination-bullet {
			width: 0.4em;
			height: 0.4em;
			background-color: $color-white;
			@include transition(0.2s);
			margin: 0.175em !important;

			&-active {
				width: 1.25em;
				border-radius: $border-radius-high;
				background-color: $color-white;
			}

			&:hover {
				opacity: 1;
			}
		}
	}

	&.white {
		background: $color-white;
		@extend %box-shadow-white;

		.swiper-button-next,
		.swiper-button-prev {
			background: $color-gray-200;
			color: $color-dark !important;

			&:hover {
				background: $color-gray-400;
				color: $color-dark !important;
			}
		}

		.swiper-pagination {
			.swiper-pagination-bullet {
				background-color: $color-dark;

				&-active {
					background-color: $color-dark;
				}
			}
		}
	}

	&.dark {
		background: $color-dark;
		@extend %box-shadow-dark;

		.swiper-button-next,
		.swiper-button-prev {
			background: $color-gray-800;
			color: $color-white !important;

			&:hover {
				background: $color-gray-600;
				color: $color-white !important;
			}
		}

		.swiper-pagination {
			.swiper-pagination-bullet {
				background-color: $color-white;

				&-active {
					background-color: $color-white;
				}
			}
		}
	}
}

// Swiper arrow buttons
.swiper-button-next,
.swiper-button-prev {
	background: $color-white;
	color: $color-dark !important;
	border-radius: $border-radius-low;
	width: 2.25rem !important;
	height: 2.25rem !important;
	box-shadow: 0px 10px 20px rgba(0, 0, 0, 0.3);
	@include transition(0.4s, all, cubic-bezier(0.25, 0.46, 0.45, 0.94));
	font-size: 1rem;
	display: flex;
	align-items: center;
	justify-content: center;
	text-align: center;

	svg {
		width: 0.8rem;
		height: 0.8rem;

		path {
			fill: currentColor !important;
		}
	}

	&.white {
		background: $color-white;
		color: $color-dark !important;

		&:hover {
			background: $color-dark;
			color: $color-white !important;
		}
	}

	&.dark {
		background: $color-dark;
		color: $color-white !important;

		&:hover {
			background: $color-white;
			color: $color-dark !important;
		}
	}

	&:hover {
		background: $color-dark;
		color: $color-white !important;
	}

	&::before,
	&::after {
		font-size: 0.7rem !important;
		font-weight: bolder !important;
		color: inherit !important;
	}
}

.swiper-button-next.swiper-button-disabled,
.swiper-button-prev.swiper-button-disabled {
	pointer-events: auto !important;
}

.swiper {

	// Next button init position
	.swiper-button-next {
		@include transform(translateX(calc(-100% - 2rem)));
	}

	// Prev button init position
	.swiper-button-prev {
		@include transform(translateX(calc(100% + 2rem)));
	}

	// Hover slide wrapper
	&:hover {
		.swiper-button-next {
			@include transform(translateX(0));
		}

		// transition:cubic-bezier(0.25, 0.46, 0.45, 0.94)

		.swiper-button-prev {
			@include transform(translateX(0));
		}
	}
}


// Swiper pagination buttons
.swiper-pagination {

	.swiper-pagination-bullet {
		width: 10px;
		height: 10px;
		background-color: $color-white;
		@include transition(0.2s);

		&-active {
			width: 25px;
			border-radius: $border-radius-high;
			background-color: $color-white;
		}

		&:hover {
			opacity: 1;
		}
	}
}

// Tips holder
.irantheme-tips-holder {
	position: fixed;
	right: 1rem;
	bottom: 1rem;
	z-index: 9999999;

	.irantheme-tip {
		font-size: 0.9rem;
		text-align: right;
		display: flex;
		align-items: center;
		padding: 0.75rem 1rem;
		border-radius: $border-radius-medium;
		overflow: hidden;
		margin-top: 0.5rem;
		background: $color-white;
		color: $color-dark;
		font-weight: bold;
		box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);
		position: relative;

		&::before {
			content: '';
			width: 4px;
			height: 2rem;
			position: absolute;
			right: 0;
			top: 50%;
			@include transform(translateY(-50%));
			border-radius: $border-radius-medium;
		}

		// Icon
		&-icon {
			margin-left: 1rem;
			font-size: 2rem;
		}

		// Note
		&-note {
			margin: 0;
			padding: 0;
		}

		// Success
		&.irantheme-tip-success {
			&::before {
				background: $color-quaternary;
			}

			a,
			.irantheme-tip-icon {
				color: $color-quaternary;
			}

			.irantheme-tip-timer .irantheme-tip-timer-counter {
				background: $color-quaternary;
			}
		}

		// Info
		&.irantheme-tip-info {
			&::before {
				background: $color-primary;
			}

			a,
			.irantheme-tip-icon {
				color: $color-primary;
			}

			.irantheme-tip-timer .irantheme-tip-timer-counter {
				background: $color-primary;
			}
		}

		// Error
		&.irantheme-tip-error {
			&::before {
				background: $color-tertiary;
			}

			a,
			.irantheme-tip-icon {
				color: $color-tertiary;
			}

			.irantheme-tip-timer .irantheme-tip-timer-counter {
				background: $color-tertiary;
			}
		}

		// Warning
		&.irantheme-tip-warning {
			&::before {
				background: $color-quinary;
			}

			a,
			.irantheme-tip-icon {
				color: $color-quinary;
			}

			.irantheme-tip-timer .irantheme-tip-timer-counter {
				background: $color-quinary;
			}
		}

		// Timer
		&-timer {
			position: absolute;
			right: 0;
			bottom: 0;
			width: 100%;
			height: 4px;
			background: transparent;
			border-radius: $border-radius-medium;

			&-counter {
				width: 0;
				height: 3px;
				display: block;
				background: $color-gray-500;
			}
		}
	}
}