// Common style in single-product-physical and single-product-downloadable
.irantheme-single-product {
    padding-bottom: 70px;

    .irantheme-single-product-divider {
        height: 1px;
        width: 100%;
        background: linear-gradient(90deg, rgba(230, 231, 232, 0), $color-gray-300 52.08%, rgba(230, 231, 232, 0));
        margin: 1.5rem 0;

        &.little-m {
            margin: 0.5rem 0;
        }

        &.zero-m {
            margin: 0;
        }
    }

    .irantheme-product-breadcrumb {
        padding-top: 1rem;
        padding-bottom: 0.5rem;

        .irantheme-woocommerce-breadcrumb {
            font-size: 0.7rem;
            color: $color-gray-600;

            .irantheme-woocommerce-breadcrumb-delimiter {
                padding: 0 0.5rem;
            }

            a {
                transition: color 0.2s ease-in-out;
                color: $color-gray-600;

                &:hover {
                    color: $color-dark;
                }
            }
        }
    }

    &-main-content {
        padding-top: 0.5rem;
    }

    &-additional-info {
        @media (max-width: 991.98px) {
            display: none !important;
            opacity: 0 !important;
            visibility: hidden !important;
        }

        margin-top: 3rem;

        @media (max-width: 991.98px) {
            margin-top: 1rem;
        }

        &-list {
            display: flex;
            align-items: center;
            justify-content: space-between;
            column-gap: 3rem;
            width: 100%;
            padding: 1.2rem 0;
            border-top: 1px solid $color-gray-200;
            border-bottom: 1px solid $color-gray-200;


            @media (max-width: 991.98px) {
                overflow-x: auto;
                scroll-snap-type: x mandatory;
                -webkit-overflow-scrolling: touch;
                scrollbar-width: none;
            }

            @media (max-width: 767.98px) {
                column-gap: 2rem;
            }


            &-item {
                display: flex;
                align-items: center;
                justify-content: space-between;
                width: 100%;
                gap: 1rem;

                // max-width: 25%;
                @media (max-width: 991.98px) {
                    width: 25%;
                    scroll-snap-align: center;
                }

                @media (max-width: 767.98px) {
                    width: 45%;
                    min-width: 45%;
                }

                .label {
                    display: flex;
                    flex-direction: column;
                    align-items: flex-start;
                    flex-wrap: wrap;
                    min-width: 85%;

                    @media (max-width: 991.98px) {
                        scroll-snap-align: center;
                    }

                    .title {
                        font-size: 0.75rem;
                        font-weight: 600;
                        color: $color-gray-800;

                        @media (max-width: 991.98px) {
                            scroll-snap-align: center;
                        }
                    }

                    .desc {
                        font-size: 0.7rem;
                        color: $color-gray-600;
                        line-height: normal;

                        @media (max-width: 991.98px) {
                            scroll-snap-align: center;
                        }
                    }
                }

                .icon {
                    font-size: 1.2rem;
                    min-width: 15%;

                    @media (max-width: 991.98px) {
                        scroll-snap-align: center;
                    }
                }
            }
        }
    }

    &-content {
        padding: 3rem 0;

        &.file {
            @media (max-width: 991.98px) {
                flex-direction: column-reverse !important;
            }
        }

        &-tabs {
            &-container {
                width: 100%;
            }

            &-list {
                display: flex;
                align-items: center;
                justify-content: flex-start;
                flex-wrap: wrap;
                border-bottom-width: 1px;
                border-bottom-style: solid;
                border-bottom-color: $color-gray-200;

                @media (max-width: 991.98px) {
                    flex-wrap: nowrap;
                    overflow-x: auto;
                    scroll-snap-type: x mandatory;
                    -webkit-overflow-scrolling: touch;
                    scrollbar-width: none;
                }

                &-item {
                    cursor: pointer;

                    a {
                        display: block;
                        padding: 0.7rem 1.5rem;
                        font-size: 0.7rem;
                        font-weight: 700;
                        white-space: nowrap;
                        color: $color-gray-600;

                        span {
                            display: flex;
                            align-items: center;
                            line-height: normal;

                            .review-count {
                                margin-right: 0.25rem;
                                padding: 2px 7px 0 7px;
                                min-width: 1.2rem;
                                font-size: 0.75rem;
                                display: flex;
                                justify-content: center;
                                align-items: center;
                                text-align: center;
                                vertical-align: middle;
                                background-color: $color-gray-300;
                                color: $color-gray-800;
                                border-radius: $border-radius-little;
                                line-height: normal;
                            }
                        }
                    }

                    &.active {
                        a {
                            border-bottom-width: 4px;
                            border-bottom-style: solid;
                            border-color: $color-red-shine;
                            color: $color-red-shine;
                            border-radius: $border-radius-low;

                            span .review-count {
                                color: $color-dark;
                            }
                        }
                    }
                }
            }

            &-panel {
                color: $color-gray-700;
                position: relative;

                &-inner-wrapper {
                    padding: 2rem 0;
                }

                &-title {
                    margin-bottom: 2rem !important;
                    color: $color-gray-700 !important;
                    font-size: 1.2rem !important;
                    font-weight: 800;
                }

                .irantheme-woocommerce-product-attributes {
                    width: 100%;
                    border-radius: $border-radius-low;
                    overflow: hidden;

                    .irantheme-woocommerce-product-attributes-item {

                        &:nth-child(odd) {
                            background-color: $color-gray-100;
                        }

                        &-label {
                            padding: 0.75rem 0.75rem 0.75rem 6rem;
                            font-size: 0.8rem;
                            color: $color-gray-800;
                        }

                        &-value {
                            font-size: 0.8rem;
                            color: $color-gray-600;

                            p {
                                white-space: normal;
                            }

                        }
                    }
                }

                .irantheme-woocommerce-single-product-reviews {
                    position: relative;
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    align-items: center;

                    .irantheme-woocommerce-single-product-reviews-wrapper {
                        position: relative;
                        width: 100%;

                        .irantheme-woocommerce-single-product-reviews-row {
                            flex-direction: row;

                            .irantheme-woocommerce-single-product-reviews-SummaryBox-col {
                                display: flex;
                                flex-direction: column;
                                gap: 1rem;
                                padding-bottom: 2rem;

                                .irantheme-woocommerce-single-product-reviews-SummaryBox-wrapper {

                                    .irantheme-woocommerce-single-product-reviews-SummaryBox-average {
                                        display: flex;
                                        flex-direction: column;
                                        padding-bottom: 1rem;
                                        // border-bottom: 1px solid $color-gray-200;

                                        &-rate {
                                            display: flex;
                                            flex-direction: column-reverse;
                                            align-items: center;
                                            gap: 0.5rem;
                                            width: 100%;

                                            &-star {
                                                .star-rating {
                                                    font-size: 20px !important;
                                                    padding-right: 0 !important;
                                                    letter-spacing: 0 !important;
                                                    width: 5.6em !important;

                                                    span {
                                                        font-size: 20px !important;
                                                        letter-spacing: 0 !important;
                                                    }
                                                }
                                            }

                                            &-value {
                                                font-size: 1.8rem;
                                                font-weight: 600;
                                                line-height: normal;
                                                position: relative;

                                                // top: 3px;
                                                span {
                                                    font-size: 0.85rem;
                                                    font-weight: 500;
                                                    padding-right: 0.25rem;
                                                }
                                            }
                                        }

                                        &-desc {
                                            font-size: 0.7rem;
                                            padding-top: 0.2rem;
                                            color: $color-gray-600;
                                            text-align: center;
                                        }
                                    }

                                    .irantheme-woocommerce-single-product-reviews-SummaryBox-details {
                                        border: 1px solid $color-gray-200;
                                        border-radius: $border-radius-medium;
                                        padding: 1.2rem;

                                        &-table {
                                            width: 100%;

                                            tbody {
                                                font-size: 0.8rem;
                                                font-weight: 900;

                                                tr {
                                                    td {
                                                        width: auto;
                                                        padding: 0.2rem 0.3rem;

                                                        &.star {
                                                            text-align: right;
                                                        }

                                                        &.bar {
                                                            width: 80%;

                                                            .rate-range {
                                                                height: 10px;
                                                                background: $color-gray-200;
                                                                border-radius: $border-radius-medium;

                                                                &-bar {
                                                                    border-radius: $border-radius-medium;
                                                                    background: #f1c430;
                                                                    height: 100%;
                                                                }
                                                            }
                                                        }

                                                        &.percentage {
                                                            text-align: left;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }

                                .irantheme-woocommerce-single-product-reviews-add-comment {
                                    display: flex;
                                    flex-direction: column;
                                    gap: 1rem;

                                    .open-add-comment-modal-btn {
                                        border-radius: $border-radius-medium;
                                        display: flex;
                                        justify-content: space-between;
                                        align-items: center;
                                        height: 3.5rem;
                                        padding-left: 1rem;
                                        padding-right: 1rem;
                                        width: 100%;
                                        cursor: pointer;
                                        position: relative;
                                        font-size: 0.9rem;
                                        font-weight: 600;
                                        background-color: $color-red-shine;
                                        color: $color-white;
                                        border-width: 1px;
                                        border-style: solid;
                                        border-color: $color-red-shine;
                                        transition: all 0.2s ease-in-out;

                                        i {
                                            font-size: 1.15rem;
                                        }

                                        &:hover {
                                            background-color: $color-white !important;
                                            color: $color-red-shine;
                                        }
                                    }

                                    .add-comment-submit-desc {
                                        font-size: 0.75rem;
                                        color: $color-gray-700;
                                    }
                                }
                            }

                            .irantheme-woocommerce-single-product-reviews-commentlist-col {
                                padding-left: 1rem;
                            }
                        }

                        .irantheme-wc-no-reviews {
                            display: flex;
                            flex-direction: column;
                            align-items: center;
                            justify-content: center;
                            padding: 2rem;

                            i {
                                color: $color-gray-500;
                                font-size: 2.8rem;
                            }

                            .title {
                                color: $color-gray-600;
                                margin-top: 1.8rem;
                                font-size: 1rem;
                            }

                            .desc {
                                display: flex;
                                align-items: center;
                                gap: 0.25rem;
                                color: $color-gray-600;
                                margin-top: 0.25rem;
                                font-size: 0.7rem;
                            }

                            .btn {
                                margin-top: 1.8rem;
                                height: 3rem;
                                padding-left: 1.5rem;
                                padding-right: 1.5rem;
                                font-size: 0.8rem;
                                font-weight: 600;
                                background-color: $color-red-shine;
                                border-width: 1px;
                                border-style: solid;
                                border-color: $color-red-shine;
                                border-radius: 0.5rem;
                                color: $color-white;
                                transition: all 0.2s ease-in-out;

                                &:hover {
                                    background-color: $color-white !important;
                                    color: $color-red-shine;
                                }
                            }
                        }

                        .irantheme-wc-verification-required {
                            display: flex;
                            align-items: center;
                            justify-content: center;

                            p {
                                font-size: 0.8rem;
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                padding: 0.5rem 0.75rem;
                                background-color: $color-tip-warning-background;
                                color: $color-tip-warning-color;
                                border-radius: $border-radius-low;
                                border: 1px solid $color-tip-warning-border;
                            }
                        }

                        .irantheme-woocommerce-single-product-commentlist {
                            display: flex;
                            flex-direction: column;
                            gap: 2rem;

                            .irantheme-woocommerce-single-product-comment-item {
                                width: 100%;

                                &.depth-1 {
                                    padding-bottom: 2rem;
                                    border-bottom: 1px solid $color-gray-200;
                                }

                                .irantheme-woocommerce-single-product-comment-item-wrapper {
                                    position: relative;
                                    width: 100%;

                                    .irantheme-woocommerce-single-product-comment-item-text {
                                        display: flex;
                                        flex-direction: column;

                                        .irantheme-woocommerce-review-awaiting-approval-meta {
                                            .irantheme-woocommerce-review-awaiting-approval {
                                                display: flex;
                                                align-items: center;
                                                margin-top: 0.3rem;
                                                font-size: 0.75rem;
                                                color: $color-gray-600;
                                                font-style: normal;

                                                &::before {
                                                    content: '\e1e4';
                                                    font-family: $font-family-icons;
                                                    display: inline-block;
                                                    margin-left: 0.35rem;
                                                    font-weight: 300;
                                                }
                                            }
                                        }

                                        .irantheme-woocommerce-review-item-head {
                                            display: flex;
                                            justify-content: space-between;

                                            &-info {
                                                display: flex;
                                                align-items: center;
                                                gap: 1rem;

                                                &-holder {
                                                    display: flex;
                                                    flex-direction: column;
                                                    justify-content: center;
                                                    gap: 0.5rem;
                                                }

                                                &-author {
                                                    display: flex;
                                                    align-items: center;
                                                    line-height: normal;

                                                    &-name {
                                                        font-size: 0.75rem;
                                                        color: $color-gray-800;
                                                        font-weight: 500;
                                                    }

                                                    &-verified {
                                                        padding: 0.25rem 0.5rem;
                                                        color: $color-quaternary;
                                                        background-color: #F0FAF5;
                                                        border-radius: $border-radius-high;
                                                        margin-right: 0.75rem;
                                                        font-style: normal;
                                                        font-size: 0.6rem;
                                                        font-weight: 600;
                                                    }
                                                }

                                                &-gravatar {
                                                    width: 2.5rem;
                                                    height: 2.5rem;

                                                    .irantheme-woocommerce-profile-avatar {
                                                        width: 100%;
                                                        height: 100%;

                                                        img {
                                                            height: 100%;
                                                            width: 100%;
                                                            object-fit: cover;
                                                            border-radius: 100%;
                                                        }
                                                    }
                                                }
                                            }

                                            &-meta {
                                                &-published-date {
                                                    font-size: 0.7rem;
                                                    color: $color-gray-600;
                                                }
                                            }
                                        }

                                        .description {
                                            text-align: justify;
                                            font-size: 0.8rem;
                                            color: $color-gray-700;
                                            margin-top: 1rem;
                                        }
                                    }
                                }

                                .children {
                                    display: flex;
                                    flex-direction: column;
                                    margin-top: 0.5rem;

                                    .irantheme-woocommerce-single-product-comment-item-wrapper {
                                        position: relative;
                                        width: 100%;
                                        padding: 1.5rem 3rem;
                                        background-color: $color-gray-100;
                                        border-radius: $border-radius-medium;
                                    }
                                }
                            }
                        }
                    }

                    .irantheme-woocommerce-single-product-review-form-wrapper {
                        position: relative;
                        width: 100%;

                        .irantheme-review_form {
                            position: relative;
                            width: 100%;

                            .comment-reply-title {
                                font-size: 0.8rem;
                                color: $color-gray-900;
                            }
                        }

                        .comment-form {
                            position: relative;
                            width: 100%;
                            display: flex;
                            flex-wrap: wrap;
                            justify-content: space-between;

                            .required {
                                color: $color-tertiary;
                            }

                            label {
                                color: $color-dark;
                                font-weight: 600;
                                font-size: 0.75rem;
                            }

                            .comment-notes {
                                display: flex;
                                flex-direction: column;
                                width: 100%;
                                margin-bottom: 0.75rem;
                                font-size: 0.8rem;
                                color: $color-gray-700;

                                &>span {
                                    position: relative;
                                    display: flex;
                                    align-items: center;

                                    &::before {
                                        font-family: $font-family-icons;
                                        content: '\f30f';
                                        margin-left: 0.5rem;
                                    }
                                }
                            }

                            .irantheme-comment-form-rating {
                                p.stars {
                                    a {
                                        position: relative;
                                        height: 1rem;
                                        width: 0.71rem;
                                        text-indent: -999em;
                                        display: inline-block;
                                        text-decoration: none;
                                        opacity: 0.5;

                                        &::before {
                                            display: block;
                                            position: absolute;
                                            top: 0;
                                            right: 0;
                                            width: 1rem;
                                            height: 1rem;
                                            line-height: 1;
                                            font-family: $font-family-icons;
                                            content: "\f005";
                                            font-weight: bold;
                                            text-indent: 0;
                                            color: #f1c430;
                                            font-size: 0.9rem;
                                        }
                                    }
                                }

                                p.stars>span:hover a,
                                p.stars.selected a {
                                    opacity: 1;
                                }

                                p.stars a:hover~a,
                                p.stars a.active~a {
                                    opacity: 0.5;
                                }
                            }

                            .irantheme-comment-field {
                                position: relative;
                                flex: 0 0 100%;
                                margin-top: 0.5rem;

                                input,
                                textarea {
                                    padding: 10px 15px 10px 15px;
                                    resize: none;
                                }

                                textarea {
                                    margin-bottom: 0.5rem;
                                }

                                &.irantheme-comment-form-author {
                                    flex: 0 0 calc(50% - 13.5px);
                                }

                                &.irantheme-comment-form-email {
                                    flex: 0 0 calc(50% - 13.5px);
                                }
                            }

                            .comment-form-cookies-consent {
                                display: flex;
                                align-items: center;
                                padding: 0.5rem 0;

                                input {
                                    width: 0.9rem;
                                    height: 0.9rem;
                                }
                            }

                            textarea {
                                border-radius: 0.5rem;
                            }

                            .form-submit {
                                padding: 0.5rem 0;
                                width: 100%;

                                .submit {
                                    width: 100%;
                                    height: 3rem;
                                    font-size: 0.8rem;
                                    font-weight: 600;
                                    background-color: $color-red-shine;
                                    border-width: 1px;
                                    border-style: solid;
                                    border-color: $color-red-shine;
                                    border-radius: $border-radius-medium;
                                    color: $color-white;
                                    transition: all 0.2s ease-in-out;

                                    &:hover {
                                        background-color: $color-white !important;
                                        color: $color-red-shine;
                                    }
                                }
                            }
                        }
                    }

                    .product-add-comment-modal {
                        &-wrapper {
                            .add-comment-content {
                                display: flex;
                                flex-direction: column;
                                row-gap: 1.5rem;

                                &-product-desc {
                                    font-size: 0.8rem;
                                    line-height: normal;
                                }

                                &-product-details {
                                    display: flex;
                                    align-items: center;
                                    justify-content: flex-start;
                                    column-gap: 0.75rem;
                                    width: 100%;

                                    &-image {
                                        width: 3rem;
                                        height: auto;
                                        border-radius: $border-radius-medium;
                                        overflow: hidden;

                                        img {
                                            aspect-ratio: 1/1;
                                        }
                                    }

                                    &-name {
                                        display: flex;
                                        flex-direction: column;
                                        row-gap: 0.35rem;
                                        width: 100%;

                                        &-title {
                                            font-size: 0.7rem;
                                            font-weight: 700;
                                            line-height: normal;
                                            text-overflow: ellipsis;
                                            overflow: hidden;
                                            display: -webkit-box;
                                            line-clamp: 1;
                                            -webkit-line-clamp: 1;
                                            -webkit-box-orient: vertical;
                                            max-width: 90%;
                                        }

                                        &-desc {
                                            font-size: 0.7rem;
                                            color: $color-gray-600;
                                            line-height: normal;
                                            text-overflow: ellipsis;
                                            overflow: hidden;
                                            display: -webkit-box;
                                            line-clamp: 1;
                                            -webkit-line-clamp: 1;
                                            -webkit-box-orient: vertical;
                                            max-width: 80%;
                                        }
                                    }
                                }

                                &-attention {
                                    display: flex;
                                    flex-direction: column;
                                    align-items: center;
                                    gap: 0.75rem;

                                    &-label {
                                        font-size: 0.8rem;
                                        font-weight: 600;
                                    }

                                    &-login-btn {
                                        width: 100%;
                                        height: 3rem;
                                        font-size: 0.8rem;
                                        font-weight: 600;
                                        background-color: $color-red-shine;
                                        border-width: 1px;
                                        border-style: solid;
                                        border-color: $color-red-shine;
                                        border-radius: $border-radius-medium;
                                        color: $color-white;
                                        transition: all 0.2s ease-in-out;
                                        display: flex;
                                        align-items: center;
                                        justify-content: center;

                                        &:hover {
                                            background-color: $color-white !important;
                                            color: $color-red-shine;
                                        }
                                    }
                                }

                            }
                        }
                    }
                }

                .irantheme-single-product-tab-product_qa {

                    &-list {
                        display: flex;
                        flex-direction: column;
                        row-gap: 1rem;

                        &-item {
                            display: flex;
                            flex-direction: column;
                            gap: 1.5rem;

                            .user-question {
                                border-bottom: 1px solid $color-gray-200;

                                &-head {
                                    display: flex;
                                    align-items: center;
                                    column-gap: 1.1rem;

                                    &-title {
                                        font-size: 0.85rem;
                                        font-weight: 700;
                                    }

                                    &-icon {
                                        display: flex;
                                        align-items: center;
                                        justify-content: center;
                                        font-size: 0.8rem;
                                        line-height: normal;
                                        background-color: #eef5ff;
                                        color: #346DF9;
                                        width: 2rem;
                                        height: 1.7rem;
                                        border-radius: $border-radius-medium;
                                    }
                                }

                                &-reply {
                                    padding-top: 1.5rem;
                                    padding-bottom: 1.5rem;

                                    &-item {
                                        display: flex;
                                        align-items: flex-start;
                                        column-gap: 1.1rem;

                                        &-icon {
                                            display: flex;
                                            align-items: center;
                                            justify-content: flex-start;
                                            background-color: #F0FAF5;
                                            border-radius: $border-radius-medium;

                                            span {
                                                display: flex;
                                                align-items: center;
                                                justify-content: center;
                                                width: 2rem;
                                                height: 1.7rem;
                                                font-size: 0.7rem;
                                                color: $color-quaternary;
                                                line-height: normal;
                                                font-weight: 600;
                                            }

                                        }

                                        &-content {
                                            font-size: 0.8rem;
                                            color: $color-gray-700;

                                            &-author {
                                                display: flex;
                                                align-items: center;
                                                column-gap: 0.5rem;
                                                font-size: 0.7rem;
                                                color: $color-gray-600;
                                                padding-top: 0.5rem;

                                                span {
                                                    font-size: 0.6rem;
