    /* Style for description content container */
    .description-tab-content-wrapper {
        position: relative;
        transition: max-height 0.5s ease;
    }

    /* Collapsed state - limit height and hide overflow */
    .description-collapsed {
        max-height: 750px;
        overflow: hidden;
        position: relative;
    }

    /* Beautiful subtle gradient overlay */
    .description-tab-read-more-fade {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        height: 50px;
        background: linear-gradient(180deg,
                rgba(255, 255, 255, 0) 0%,
                rgba(255, 255, 255, 0.4) 40%,
                rgba(255, 255, 255, 0.7) 70%,
                rgba(255, 255, 255, 0.95) 100%);
        pointer-events: none;
        transition: all 0.5s ease;
        opacity: 1;
        backdrop-filter: blur(1px);
    }

    /* Smooth fade out when expanded */
    .description-expanded .description-tab-read-more-fade {
        opacity: 0;
        transform: translateY(20px);
    }

    /* Clean modern button */
    .description-tab-read-more-toggle {
        position: relative;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        text-align: center;
        font-size: 0.75rem;
        background-color: $color-red-shine;
        border-width: 1px;
        border-style: solid;
        border-color: $color-red-shine;
        border-radius: $border-radius-medium;
        color: $color-white;
        height: 50px;
        padding-left: 2rem;
        padding-right: 2rem;
        transition: all 0.2s ease-in-out;
        min-width: fit-content;
        margin: 1.5rem auto;
        cursor: pointer;
        position: relative;
        z-index: 10;
        @include transition(0.2s);

        &:hover {
            background-color: $color-white !important;
            color: $color-red-shine;
        }

        &.description-collapsed {
            &::after {
                content: '\f107';
                font-family: $font-family-icons;
            }
        }

        &.description-expanded {
            &::after {
                content: '\f106';
                font-family: $font-family-icons;
            }
        }
    }

