/*
=====================================
Gallery type
=====================================
*/
.irantheme-gallery-type-section {
    .irantheme-gallery-type {
        position: relative;
        background-position: center;
        background-repeat: no-repeat;
        background-size: cover;

        // Wrapper
        &-wrapper {
            position: relative;
            z-index: 2;
        }


        // Item
        &-item {
            display: flex;
            margin-bottom: 0 !important;

            // Animate
            .irantheme-gallery-type-animation {
                width: 100%;
                height: 100%;
                display: flex;
                flex-direction: column;
                overflow: hidden;
            }

            // Link
            &-link {
                width: 100%;
                height: 100%;
                display: flex;
                position: relative;
                overflow: hidden;

                // Image
                &-img {
                    object-fit: fill;
                    width: 100%;
                    height: 100%;
                    @include transition(0.2s);

                    &::selection {
                        background-color: transparent;
                        color: inherit
                    }

                    &:hover {
                        opacity: 0.8;
                    }
                }
            }

            // Content
            &-content {
                padding: 2rem;
                display: flex;
                flex-direction: column;
                height: 100%;
                z-index: 1;

                &-heading {
                    font-size: 1.2rem;
                    // color: $color-dark;
                    line-height: 2rem;
                    width: fit-content;

                    &::selection {
                        background-color: transparent;
                        color: inherit
                    }
                }

                &-desc {
                    padding-top: 1rem;
                    font-size: 0.7rem;
                    margin-top: auto;
                    // color: $color-gray-600;
                    width: fit-content;
                }

                &-link {
                    margin-top: 1rem;
                    font-size: 0.7rem;
                    // color: $color-gray-600;
                    width: fit-content;
                    position: relative;

                    &::after {
                        content: '';
                        width: 100%;
                        height: 1px;
                        position: absolute;
                        top: 100%;
                        right: 0;
                        // background: $color-gray-600;
                        @include transition(0.2s);
                    }

                    &:hover {
                        &::after {
                            width: 0;
                        }

                        // color: $color-gray-700;
                    }
                }
            }
        }

        /*
        =====================================
        White
        =====================================
        */
        &.white {
            background-color: $color-white;
        }

        // Item
        &-item {
            &.white {
                .irantheme-gallery-type-animation {
                    background-color: $color-gray-100;
                }

                // Content
                .irantheme-gallery-type-item-content {

                    &-heading {
                        color: $color-dark;
                    }

                    &-desc {
                        color: $color-gray-600;
                    }

                    &-link {
                        color: $color-gray-600;

                        &::after {
                            background: $color-gray-600;
                        }

                        &:hover {

                            color: $color-gray-700;
                        }
                    }
                }
            }
        }

        /*
        =====================================
        Dark
        =====================================
        */
        &.dark {
            background-color: $color-dark;
        }

        // Item
        &-item {
            &.dark {
                .irantheme-gallery-type-animation {
                    background-color: $color-gray-900;
                }

                // Content
                .irantheme-gallery-type-item-content {

                    &-heading {
                        color: $color-white;
                    }

                    &-desc {
                        color: $color-gray-400;
                    }

                    &-link {
                        color: $color-gray-400;

                        &::after {
                            background: $color-gray-400;
                        }

                        &:hover {

                            color: $color-gray-300;
                        }
                    }
                }
            }
        }
    }
}