.irantheme-wc-cart {
    background-color: $color-gray-100;

    &-wrapper {
        padding: 4rem;

        @media only screen and (max-width: 767.98px) {
            padding: 2.5rem;
        }

        @media only screen and (max-width: 575.98px) {
            padding: 1rem;
        }
    }

    &-title {
        display: flex;
        align-items: center;
        justify-content: center;
        background-color: $color-white;
        padding: 1.5rem 0.5rem;
        margin-bottom: 1rem;
        border-radius: $border-radius-medium;

        ul {
            display: flex;

            li {
                display: flex;
                align-items: center;

                span {
                    display: flex;
                    align-items: center;
                    padding: 1rem 0.75rem;
                    color: $color-gray-500 !important;

                    i {
                        font-size: 1.3rem;
                        padding-left: 0.5rem;
                    }

                    strong {
                        font-size: 0.9rem;
                    }

                }

                &::after {
                    content: '';
                    width: 94px;
                    height: 1px;
                    margin: 0.75rem;
                    background: $color-gray-500;
                    position: relative;
                    top: 1px;
                }

                &.active {
                    span {
                        color: $color-dark !important;
                        transform: scale(1.1);
                    }
                }

                &.done {
                    span {
                        color: $color-quaternary !important;
                    }
                }

                &.success {
                    &::after {
                        content: none;
                    }
                }

                @media only screen and (max-width: 767.98px) {
                    &:not(.active) {
                        display: none;
                    }

                    &::after {
                        content: none;
                    }
                }
            }
        }
    }

    &-holder {
        background-color: $color-white;
        border-radius: $border-radius-medium;
        padding: 0.35rem;
    }

    // Empty card
    .wp-block-woocommerce-empty-cart-block {
        padding: 1rem;
        font-size: 0.9rem;
        color: $color-gray-700;

        .wp-block-heading.wc-block-cart__empty-cart__title {
            display: flex;
            flex-direction: column;
            font-size: 0.9rem;
            color: $color-gray-700;

            &::before {
                display: none;
            }

            &::before {
                display: block;
                content: '\e3f2';
                font-family: $font-family-icons;
                font-size: 3.5rem;
                margin-bottom: 1.5rem !important;
                // Reset
                background-color: unset !important;
                height: unset !important;
                mask-image: none !important;
                mask-position: unset !important;
                mask-repeat: unset !important;
                mask-size: unset !important;
                width: unset !important;
            }
        }

        .wp-block-separator {
            &::before {
                font-size: 2rem;
                color: $color-gray-700;
            }
        }

        .wp-block-heading {
            padding: 2rem;
            font-size: 1.6rem;
            color: $color-gray-800;
        }

        .wc-block-grid__product {
            margin-top: 1rem;
            padding: 0 0.75rem;

            .wc-block-grid__product-link {
                .wc-block-grid__product-title {
                    font-size: 0.8rem;
                    color: $color-gray-900;
                    font-weight: normal;
                    line-height: normal;
                }

                .wc-block-grid__product-onsale {
                    border: none;
                    background-color: $color-tertiary;
                    border-radius: $border-radius-low;
                    color: $color-white;
                    right: unset;
                    left: auto;
                }

                .wc-block-grid__product-image {
                    img {
                        height: 200px;
                    }
                }
            }

            .wc-block-grid__product-price {
                font-size: 0.75rem;
            }

            .wc-block-grid__product-rating {
                display: none;
            }

            .wc-block-grid__product-add-to-cart {
                display: none;
            }
        }

    }

    // Main default wrapper
    .wc-block-cart {
        margin: 0 !important;
        overflow-x: auto;

        // Main column
        .wc-block-components-main {
            display: flex;
            flex-direction: column;
            padding: 2rem !important;

            // Cart item table
            table.wc-block-cart-items {
                thead {
                    font-size: 0.9rem;
                    color: $color-gray-700;
                    font-weight: normal;

                    .wc-block-cart-items__header,
                    th {
                        font-size: 0.85rem;
                        font-weight: normal;
                    }

                    .wc-block-cart-items__header-product {
                        visibility: hidden !important;
                        opacity: 0 !important;
                    }
                }

                tbody {
                    font-size: 0.85rem;
                    color: $color-gray-600;

                    .wc-block-cart-items__row {
                        @media only screen and (max-width: 520px) {
                            display: flex;
                            align-items: center;
                            flex-direction: column;
                            border-bottom: 1px solid $color-gray-200;
                        }
                    }

                    .wc-block-cart-items__row:last-child {
                        border-bottom: none !important;
                    }

                    // Cart item table image
                    .wc-block-cart-item__image {
                        width: 5rem;

                        img {
                            width: 5rem;
                            height: 5rem;
                            max-width: 5rem;
                            border-radius: $border-radius-low;
                        }
                    }

                    // Cart item table info
                    .wc-block-cart-item__product {
                        @media only screen and (max-width: 520px) {
                            text-align: center;
                        }

                        .wc-block-cart-item__wrap {
                            display: flex;
                            flex-wrap: wrap;

                            @media only screen and (max-width: 520px) {
                                align-items: center;
                                justify-content: center;
                            }

                            @media only screen and (max-width: 1120px) {
                                flex-direction: column;
                            }

                            @media only screen and (max-width: 843.98px) {
                                flex-direction: row;
                            }

                            &>* {
                                flex: 100%;
                            }

                            .wc-block-components-product-name {
                                order: 1;
                                flex: 1 1 auto;
                                min-width: 60%;
                                width: 60%;
                                line-height: normal;
                                color: $color-gray-900;

                                @media only screen and (max-width: 520px) {
                                    margin-top: 0.5rem;
                                }

                                @media only screen and (max-width: 1120px) {
                                    width: auto;
                                }
                            }

                            .wc-block-cart-item__prices {
                                order: 3;

                                .price {
                                    display: flex;
                                    align-items: center;

                                    @media only screen and (max-width: 520px) {
                                        justify-content: center;
                                        flex-direction: column;
                                    }
                                }

                                .wc-block-components-product-price__regular {
                                    font-size: 0.75rem;
                                }

                                .wc-block-components-product-price__value {
                                    color: $color-gray-700 !important;
                                    font-size: 0.86rem !important;

                                    @media only screen and (max-width: 520px) {
                                        margin-right: 0;
                                        margin-top: 0.25rem;
                                    }
                                }
                            }

                            .wc-block-components-product-metadata {
                                order: 2;

                                @media only screen and (max-width: 520px) {
                                    order: 2;
                                }

                                @media only screen and (max-width: 1120px) {
                                    order: 1;
                                }

                                .wc-block-components-product-metadata__description {
                                    display: none;
                                }

                                .wc-block-components-product-details {
                                    color: $color-gray-600 !important;
                                    display: flex;
                                    align-items: center;
                                    flex-wrap: wrap;
                                    font-size: 0.7rem !important;

                                    @media only screen and (max-width: 520px) {
                                        justify-content: center;
                                    }

                                    li {
                                        padding-left: 0.5rem;

                                        &:not(:first-child) {
                                            padding-right: 0.5rem;
                                        }

                                        &:not(:last-child) {
                                            border-left-width: 1px;
                                            border-left-style: solid;
                                            border-left-color: $color-gray-400;
                                        }
                                    }
                                }
                            }


                            .wc-block-components-sale-badge {
                                order: 4;

                                @media only screen and (max-width: 520px) {
                                    order: 3;
                                }

                                display: flex;
                                align-items: center;
                                border: none !important;
                                background-color: $color-tip-success-background !important;
                                color: $color-tip-success-color !important;
                                max-width: fit-content;
                                font-weight: normal;
                                padding: 0.15rem 0.7rem;

                                .wc-block-formatted-money-amount {
                                    padding-right: 0.2rem;
                                }

                                &::before {
                                    content: '\f81d';
                                    font-family: $font-family-icons;
                                    margin-left: 0.35rem;
                                    font-weight: 300;
                                    font-size: 0.9rem;
                                }
                            }

                            .wc-block-cart-item__quantity {
                                order: 1;
                                flex: 1 1 auto;
                                min-width: 40%;
                                width: 40%;
                                display: flex;
                                flex-direction: row;
                                align-items: center;
                                margin: 1rem 0;

                                @media only screen and (max-width: 1120px) {
                                    align-items: flex-start;
                                }

                                @media only screen and (max-width: 520px) {
                                    align-items: center;
                                    padding: 0 !important;
                                    order: 4;
                                    flex: 100% !important;
                                }

                                .wc-block-components-quantity-selector {
                                    color: $color-dark !important;
                                    width: fit-content !important;
                                    height: 2rem;

                                    .wc-block-components-quantity-selector__input {
                                        z-index: 1;
                                        text-align: center;
                                        border: none;
                                        margin: 0;
                                        min-width: 3rem;
                                        font-weight: normal;
                                        font-size: 0.75rem !important;
                                        padding: 0.5rem;
                                        font-size: 0.9rem;

                                        &:focus {
                                            border: none !important;
                                            box-shadow: none !important;
                                        }
                                    }

                                    .wc-block-components-quantity-selector__button {
                                        font-size: 1rem;
                                        opacity: 1 !important;
                                        z-index: 1;
                                        @include transition(0.2s);

                                        &:hover {
                                            color: $color-gray-600;
                                        }

                                        &:focus {
                                            border: none !important;
                                            box-shadow: none !important;
                                        }
                                    }

                                    &::after {
                                        border: none !important;
                                        background-color: $color-gray-100 !important;
                                        border-radius: $border-radius-low !important;
                                    }
                                }

                                .wc-block-cart-item__remove-link {
                                    font-style: normal;
                                    text-decoration: none !important;
                                    font-size: 0.7rem !important;
                                    color: $color-gray-800;
                                    @include transition(0.2s);
                                    width: fit-content;
                                    padding: 0.25rem 0.75rem;
                                    display: flex;
                                    align-items: center;

                                    @media only screen and (max-width: 1120px) {
                                        padding-right: 0;
                                        margin-bottom: 1rem;
                                    }

                                    @media only screen and (max-width: 520px) {
                                        padding-left: 0;
                                        padding-right: 0;
                                    }

                                    &::before {
                                        content: '\e2b4';
                                        font-family: $font-family-icons;
                                        margin-left: 0.25rem;
                                        font-size: 1rem !important;
                                    }

                                    svg {
                                        display: none !important;
                                    }

                                    &:hover {
                                        color: $color-gray-600;
                                    }
                                }
                            }
                        }
                    }

                    // Cart item table total
                    .wc-block-cart-item__total {
                        color: $color-gray-900;

                        .wc-block-cart-item__total-price-and-sale-badge-wrapper {
                            @media only screen and (max-width: 520px) {
                                align-items: center;
                            }
                        }

                        .wc-block-components-product-badge {
                            border: none !important;
                            color: $color-tip-success-color !important;
                            padding: 0 !important;
                            display: flex;
                            align-items: center;


                            .wc-block-formatted-money-amount {
                                padding-right: 0.2rem;
                            }

                            &::after {
                                content: '\f555';
                                font-family: $font-family-icons;
                                margin-right: 0.35rem;
                                font-weight: 400;
                                font-size: 0.9rem;
                            }
                        }
                    }
                }
            }
        }

        // Sidebar column
        .wc-block-components-sidebar {
            display: flex;
            flex-direction: column;
            align-items: stretch;
            padding: 2rem !important;
            background-color: $color-gray-100;
            border-radius: $border-radius-low;
            color: $color-gray-700;

            .wp-block-woocommerce-cart-order-summary-block {
                font-size: 0.85rem;
                padding: 0 !important;

                .wp-block-woocommerce-cart-order-summary-heading-block {
                    font-size: 0.85rem;
                    font-weight: normal;
                    padding-left: 0 !important;
                    padding-right: 0 !important;
                }

                .wp-block-woocommerce-cart-order-summary-coupon-form-block {
                    .wc-block-components-totals-coupon {
                        .wc-block-components-panel__button {
                            display: flex;
                            align-items: center;

                            &::before {
                                content: '\25';
                                font-family: $font-family-icons;
                                margin-left: 0.5rem;
                                font-weight: 300;
                            }
                        }
                    }
                }

                .wc-block-components-totals-shipping {
                    .wc-block-components-totals-shipping__change-address__link {
                        text-decoration: none !important;
                        display: flex;
                        align-items: center;
                        margin-top: 0.5rem;
                        @include transition(0.2s);

                        &:hover {
                            color: $color-gray-600;
                        }

                        &::before {
                            content: '\e60a';
                            font-family: $font-family-icons;
                            margin-left: 0.25rem;
                            font-weight: 300;
                        }
                    }
                }

                .wc-block-components-totals-footer-item {
                    .wc-block-components-totals-item__label {
                        font-size: 0.85rem !important;
                    }

                    .wc-block-components-totals-item__value {
                        font-size: 0.85rem !important;
                    }

                    .wc-block-components-totals-item__description {
                        font-size: 0.85rem !important;
                    }
                }
            }
        }

    }

    // Input and button
    .wc-block-components-text-input input[type=text] {
        border-color: $color-gray-300 !important;
        box-shadow: none !important;
        font-size: 0.85rem;
        color: $color-gray-800;

        &:focus {
            border-color: $color-dark !important;
        }
    }

    .wc-block-components-text-input input[type=tel] {
        border-color: $color-gray-300 !important;
        box-shadow: none !important;
        font-size: 0.85rem;
        color: $color-gray-800;

        &:focus {
            border-color: $color-dark !important;
        }
    }

    .wc-block-components-text-input input,
    .wc-block-components-text-input textarea,
    .wc-block-checkout__add-note .wc-block-components-textarea,
    .wc-block-components-combobox .wc-block-components-combobox-control input.components-combobox-control__input:focus,
    .wc-block-components-combobox .wc-block-components-combobox-control input.components-combobox-control__input[aria-expanded=true],
    .wc-block-components-combobox .wc-block-components-combobox-control input.components-combobox-control__input,
    .wc-blocks-components-select select {
        font-size: 0.85rem;
        color: $color-gray-800;
        border-color: $color-gray-300 !important;
        box-shadow: none !important;

        &:focus {
            border-color: $color-dark !important;
        }

    }

    .wc-blocks-components-select select {
        border: 1px solid;
    }

    .wc-blocks-components-select .wc-blocks-components-select__container {
        border: none !important;
    }

    .wc-block-components-validation-error>p {
        font-size: 0.7rem;
        color: $color-tertiary;
    }

    .wc-block-components-text-input label,
    .wc-blocks-components-select label {
        font-size: 0.85rem !important;
        color: $color-gray-700 !important;
    }

    .wc-block-components-text-input.has-error label,
    .wc-block-components-validation-error {
        color: $color-gray-700 !important;
    }

    .wc-block-components-text-input.has-error input {
        border-color: $color-tertiary !important;
    }

    // Buttons
    body:not(.woocommerce-block-theme-has-button-styles) .wc-block-components-button:not(.is-link) {
        @extend %button-dark-style;
        margin: 0;
    }

    .wc-block-components-button {
        background-color: $color-gray-200 !important;
        font-size: 0.9rem !important;
        border-radius: $border-radius-low;
        border: none !important;
        color: $color-gray-700 !important;
        transition: all 0.2s ease-in-out !important;
        box-shadow: none !important;

        &:hover {
            background-color: $color-gray-300 !important;
            color: $color-gray-700 !important;
        }

        &:focus {
            box-shadow: none !important;
            outline: none !important;
        }
    }

    // Radio control
    .wc-block-components-radio-control {
        font-size: 0.85rem !important;
    }

    .wc-block-components-radio-control .wc-block-components-radio-control__input {
        min-height: 12px !important;
        min-width: 12px !important;
        height: 12px !important;
        width: 12px !important;
        margin-top: 0 !important;

        &:focus {
            outline: none !important;
            outline-offset: unset !important;
        }
    }

    .wc-block-components-radio-control .wc-block-components-radio-control__input:checked:before {
        min-height: 6px !important;
        min-width: 6px !important;
        height: 6px !important;
        width: 6px !important;
    }
}