.irantheme-woocommerce-payment {

    // Global style for all used table
    &-table {
        width: 100%;

        thead {
            background-color: $color-gray-100;
            border-radius: $border-radius-low;
            color: $color-gray-700;
            font-size: 0.9rem;

            &.irantheme-woocommerce-payment-table-radius {
                th:first-child {
                    border-radius: 0 $border-radius-low $border-radius-low 0;
                }

                th:last-child {
                    border-radius: $border-radius-low 0 0 $border-radius-low;
                }
            }
        }

        tbody {
            color: $color-gray-600;
            font-size: 0.85rem;
        }

        tr {
            &:not(:last-child) {
                border-bottom: 1px solid $color-gray-200;
            }
        }

        td {
            padding: 0.75rem 1rem;
            white-space: normal;
        }

        th {
            padding: 0.75rem 1rem;
            white-space: normal;
            font-weight: normal;
        }

        tfoot {
            font-size: 0.85rem;
            background-color: $color-gray-100;

            tr {
                border: none !important;
            }
        }
    }

    .irantheme-woocommerce-payment-methods-wrapper {
        padding: 1rem;
        background-color: $color-gray-100;
        border-radius: $border-radius-low;
    }

    .irantheme-woocommerce-payment-invoice-wrapper {
        @media only screen and (max-width: 339.98px) {
            overflow-x: scroll;
        }

        @media only screen and (max-width: 991.98px) {
            margin-bottom: 1rem;
        }
    }

    &-methods {

        &-title {
            margin-bottom: 1rem;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.9rem;

            i {
                line-height: normal;
                margin-left: 0.5rem;
            }
        }

        li {
            box-shadow: none !important;
            border-radius: $border-radius-low !important;
            background-color: $color-white !important;
            padding: 0.5rem 1rem;
            font-size: 0.85rem;
            color: $color-gray-900;

            .payment_box {
                margin-top: 0.25rem;
                padding: 0.5rem 0.75rem;
                background-color: $color-tip-info-background;
                color: $color-tip-info-color;
                border-radius: $border-radius-low;
                display: flex;
                align-items: center;
                font-size: 0.75rem;

                i {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    font-size: 1.1rem;
                    margin-left: 0.5rem;
                    font-weight: 300;
                }
            }
        }
    }

    &-term {
        p::before {
            content: "\f772";
            font-family: $font-family-icons;
            margin-left: 0.5rem;
            font-weight: 300;
            line-height: normal;
        }

        font-size: 0.85rem !important;
        color: $color-gray-800 !important;
        display: flex;
        align-items: center;
        margin-top: 1rem;
        text-align: justify;

        a {
            color: $color-primary;
            transition: all 0.2s ease-in-out;

            &:hover {
                color: $color-primary-hover;
            }
        }
    }

    &-submit {
        display: flex;

        button {
            background-color: $color-gray-200 !important;
            font-size: 0.9rem !important;
            border-radius: $border-radius-low;
            border: none;
            color: $color-gray-700;
            transition: all 0.2s ease-in-out;
            width: 100%;
            min-height: 3rem;
            margin-top: 1rem;

            &:hover {
                background-color: $color-gray-300 !important;
            }
        }
    }
}